      if (Array.isArray(seals.sixth.leverOrder)) replaceArrayContents(SIXTH_SEAL_LEVER_ORDER, seals.sixth.leverOrder);
      if (seals.sixth.leverSprite) Object.assign(SIXTH_SEAL_LEVER_SPRITE, seals.sixth.leverSprite);
