    if (taintedSouls.battleRoomId) EKATRIX_BATTLE_ROOM_ID = taintedSouls.battleRoomId;
    if (taintedSouls.battleDisplayName) EKATRIX_BATTLE_DISPLAY_NAME = taintedSouls.battleDisplayName;
