async function loadQuestDialogueAssets() {
  if (
    questDialogueReady &&
    questMissionsDialogue &&
    questNpcsDialogue &&
    questBattlesConfig &&
    questItemsConfigData &&
    questToastsConfigData &&
    questRoomsConfigData &&
    questConfigData
  ) {
    return {
      missions: questMissionsDialogue,
      npcs: questNpcsDialogue,
      battles: questBattlesConfig,
      items: questItemsConfigData,
      toasts: questToastsConfigData,
      rooms: questRoomsConfigData,
      config: questConfigData
    };
  }
  if (!questDialogueLoadPromise) {
    questDialogueLoadPromise = (async () => {
      const [missionsData, npcsData, battlesData, itemsData, toastsData, roomsData, configData] = await Promise.all([
        fetchQuestJsonAsset('missions.json'),
        fetchQuestJsonAsset('npcs.json'),
        fetchQuestJsonAsset('battles.json'),
        fetchQuestJsonAsset('items.json'),
        fetchQuestJsonAsset('toasts.json'),
        fetchQuestJsonAsset('rooms.json'),
        fetchQuestJsonAsset('config.json')
      ]);
      applyQuestConfigFromAssets(configData);
      applyQuestDialogueFromAssets(missionsData, npcsData);
      applyQuestBattlesFromAssets(battlesData);
      applyQuestItemsFromAssets(itemsData);
      applyQuestToastsFromAssets(toastsData);
      applyQuestRoomsFromAssets(roomsData);
      if (typeof patchBoardNpcChatFromDialogue === 'function') {
        patchBoardNpcChatFromDialogue();
      }
      console.log('[Quests Mod] Loaded quest config, dialogue, battles, items, toasts, and rooms from assets/quests');
      return {
        missions: missionsData,
        npcs: npcsData,
        battles: battlesData,
        items: itemsData,
        toasts: toastsData,
        rooms: roomsData,
        config: configData
      };
    })().catch((error) => {
      questDialogueLoadPromise = null;
      console.error('[Quests Mod] Failed to load quest dialogue assets:', error);
      throw error;
    });
  }
  return questDialogueLoadPromise;
}

function getKingTibianusKeywordResponses() {
  const keywords = { ...NPC_SHARED_KEYWORDS, ...(questNpcsDialogue?.['king-tibianus']?.keywords || {}) };
  if (KING_LETTER_MISSION?.prompt) {
    keywords.letter = KING_LETTER_MISSION.prompt;
    keywords.scroll = KING_LETTER_MISSION.prompt;
  }
  if (KING_HONEYFLOWER_MISSION?.prompt) {
    keywords.honeyflower = KING_HONEYFLOWER_MISSION.prompt;
    keywords['honey flower'] = KING_HONEYFLOWER_MISSION.prompt;
    keywords.honey = KING_HONEYFLOWER_MISSION.prompt;
  }
  return keywords;
}

async function ensureQuestDialogueLoaded() {
  try {
    await loadQuestDialogueAssets();
  } catch (_) { /* fallback to empty shells */ }
}

function sanitizeDialogueText(value, fallback = '') {
  const text = String(value ?? '').trim();
  if (!text) return fallback;
  const lower = text.toLowerCase();
  if (lower === 'undefined' || lower === 'null' || lower === 'nan') return fallback;
  return text;
}

async function ensureNpcDialogueAssetsReady(logPrefix = '[Quests Mod][NPC]') {
  try {
    await loadQuestDialogueAssets();
    return true;
  } catch (error) {
    console.warn(`${logPrefix} Dialogue assets not ready, using safe fallback copy.`, error);
    return false;
  }
}



