// Quest item chat keywords — filled from assets/quests/items.json
const QUEST_ITEM_CHAT_ENTRIES = [];

function matchQuestItemInChatMessage(message) {
  const lower = String(message ?? '').toLowerCase();
  let bestEntry = null;
  let bestKeywordLength = 0;

  for (const entry of QUEST_ITEM_CHAT_ENTRIES) {
    for (const keyword of entry.keywords) {
      if (lower.includes(keyword) && keyword.length > bestKeywordLength) {
        bestEntry = entry;
        bestKeywordLength = keyword.length;
      }
    }
  }

  return bestEntry;
}

function formatQuestItemChatLine(line, playerName = 'Player') {
  if (typeof line !== 'string') return line;
  return line.includes('Player') ? line.replace(/Player/g, playerName) : line;
}

function getNpcQuestItemUninvolvedResponse(npcId, productName, playerName = 'Player') {
  const template = NPC_QUEST_ITEM_UNINVOLVED_TEMPLATES[npcId];
  const line = template
    ? template.replace(/\{item\}/g, productName)
    : `I don't know anything about ${productName}.`;
  return formatQuestItemChatLine(line, playerName);
}

function getNpcQuestItemChatResponse(npcId, message, playerName = 'Player') {
  const entry = matchQuestItemInChatMessage(message);
  if (!entry) return null;

  const npcResponses = NPC_QUEST_ITEM_CHAT_RESPONSES[npcId];
  const line = npcResponses ? npcResponses[entry.id] : null;
  if (line == null) {
    return getNpcQuestItemUninvolvedResponse(npcId, entry.productName, playerName);
  }

  return formatQuestItemChatLine(line, playerName);
}

// Early, greedy-logic-proof intercept for "hintOnly" quest items — ones with no
// hand-in / mechanic on any NPC, only a "here's who wants it" line. Handlers whose
// own mission-keyword logic would otherwise swallow the phrase (e.g. King Tibianus
// treats any message containing "key" as a mission query) call this near the top
// and return early. Only NPCs that actually have a questItems line for the item
// respond; everyone else falls through to their normal flow.
function getNpcQuestItemHintResponse(npcId, message, playerName = 'Player') {
  const entry = matchQuestItemInChatMessage(message);
  if (!entry || !entry.hintOnly) return null;
  const npcResponses = NPC_QUEST_ITEM_CHAT_RESPONSES[npcId];
  const line = npcResponses ? npcResponses[entry.id] : null;
  if (line == null) return null;
  return formatQuestItemChatLine(line, playerName);
}

function getRandomNpcConfusionResponse(responses, playerName = 'Player') {
  if (!Array.isArray(responses) || responses.length === 0) {
    return 'I do not understand.';
  }
  const line = responses[Math.floor(Math.random() * responses.length)];
  if (typeof line !== 'string') return line;
  return line.includes('Player') ? line.replace(/Player/g, playerName) : line;
}

/**
 * Longest-keyword-first includes match over a response map (sync).
 * @param {Record<string, any>} map
 * @param {string} message
 * @param {string} [playerName='Player']
 * @param {{ defaultResponse: any, lowercaseKeys?: boolean }} options
 */
function matchKeywordResponsesSync(map, message, playerName = 'Player', options = {}) {
  const {
    defaultResponse,
    lowercaseKeys = false
  } = options;
  const lowerMessage = String(message ?? '').toLowerCase().trim();
  const sortedKeys = Object.keys(map).sort((a, b) => b.length - a.length);

  for (const keyword of sortedKeys) {
    const needle = lowercaseKeys ? keyword.toLowerCase() : keyword;
    if (!lowerMessage.includes(needle)) continue;

    let response = map[keyword];

    if (Array.isArray(response)) {
      return response.map((line) =>
        String(line).includes('Player') ? String(line).replace(/Player/g, playerName) : line
      );
    }
    if (typeof response === 'string' && response.includes('Player')) {
      return response.replace(/Player/g, playerName);
    }
    if (response && response.includes && response.includes('Player')) {
      return response.replace(/Player/g, playerName);
    }
    return response;
  }

  if (typeof defaultResponse === 'string' && defaultResponse.includes('Player')) {
    return defaultResponse.replace(/Player/g, playerName);
  }
  return defaultResponse;
}

/**
 * Longest-keyword-first includes match over a response map.
 * @param {Record<string, any>} map
 * @param {string} message
 * @param {string} [playerName='Player']
 * @param {{ defaultResponse: any, resolveAsync?: boolean, lowercaseKeys?: boolean, asyncErrorFallback?: any }} options
 */
async function matchKeywordResponses(map, message, playerName = 'Player', options = {}) {
  const {
    defaultResponse,
    resolveAsync = false,
    lowercaseKeys = false
  } = options;
  const lowerMessage = String(message ?? '').toLowerCase().trim();
  const sortedKeys = Object.keys(map).sort((a, b) => b.length - a.length);

  for (const keyword of sortedKeys) {
    const needle = lowercaseKeys ? keyword.toLowerCase() : keyword;
    if (!lowerMessage.includes(needle)) continue;

    let response = map[keyword];
    if (resolveAsync && typeof response === 'function') {
      try {
        response = await response();
      } catch (err) {
        console.error('[Quests Mod] Error getting dynamic response:', err);
        response = options.asyncErrorFallback ?? defaultResponse;
      }
    }

    if (Array.isArray(response)) {
      return response.map((line) =>
        String(line).includes('Player') ? String(line).replace(/Player/g, playerName) : line
      );
    }
    if (typeof response === 'string' && response.includes('Player')) {
      return response.replace(/Player/g, playerName);
    }
    if (response && response.includes && response.includes('Player')) {
      return response.replace(/Player/g, playerName);
    }
    return response;
  }

  if (typeof defaultResponse === 'string' && defaultResponse.includes('Player')) {
    return defaultResponse.replace(/Player/g, playerName);
  }
  return defaultResponse;
}

function getNpcKeywordResponse(responses, message, playerName = 'Player', options = {}) {
  return matchKeywordResponsesSync(responses, message, playerName, {
    defaultResponse: null,
    lowercaseKeys: true,
    ...options
  });
}

function getTeshaResponse(message, playerName = 'Player') {
  const result = getNpcKeywordResponse(TESHA_RESPONSES, message, playerName);
  if (result == null) return null;
  return Array.isArray(result) ? result : [result];
}

function getWydaResponse(message, playerName = 'Player') {
  return getNpcKeywordResponse(WYDA_RESPONSES, message, playerName);
}

function getCostelloResponse(message, playerName = 'Player') {
  const lowerMessage = message.toLowerCase().trim();

  // Prefer the longest matching seal phrase ("Seal VII" must not match "seal v").
  let bestMatch = null;
  for (const [phrase, sealIndex] of COSTELLO_SEAL_PATTERNS) {
    const p = phrase.trim();
    if (!p) continue;
    if (lowerMessage === p || lowerMessage.includes(p)) {
      if (!bestMatch || p.length > bestMatch.phrase.length) {
        bestMatch = { phrase: p, sealIndex };
      }
    }
  }
  if (bestMatch && typeof getSealCompleted === 'function' && SEAL_TRANSCRIPTS && SEAL_TRANSCRIPTS[bestMatch.sealIndex]) {
    const transcript = SEAL_TRANSCRIPTS[bestMatch.sealIndex];
    return getSealCompleted(bestMatch.sealIndex) ? transcript.complete : transcript.incomplete;
  }
  if (lowerMessage.includes('seals') || lowerMessage === 'seal') {
    return COSTELLO_SEAL_GUIDANCE_FALLBACK || "The seven seals of Ghostlands must be completed one by one.";
  }

  return getNpcKeywordResponse(COSTELLO_RESPONSES, message, playerName);
}

function getAlDeeResponse(message, playerName = 'Player') {
  return getNpcKeywordResponse(AL_DEE_RESPONSES, message, playerName);
}

function isNpcFarewellMessage(message) {
  const lower = String(message ?? '').toLowerCase().trim();
  if (!lower) return false;
  if (lower.includes('goodbye') || lower.includes('good bye') || lower.includes('farewell') || lower.includes('see you')) {
    return true;
  }
  return /\bbye\b/.test(lower);
}

function messageContainsNpcSwear(message, swearWords = KING_TIBIANUS_SWEAR_WORDS) {
  const lower = String(message ?? '').toLowerCase();
  if (!lower || !Array.isArray(swearWords) || swearWords.length === 0) return false;
  return swearWords.some((word) => {
    const w = String(word ?? '').toLowerCase().trim();
    if (!w) return false;
    if (w.includes(' ')) return lower.includes(w);
    const escaped = w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return new RegExp(`\\b${escaped}\\b`, 'i').test(lower);
  });
}

