function resolveQuestProductName(productId) {
  const product = questItemsConfigData?.products?.[productId];
  if (product?.productName) return product.productName;
  if (productId === 'costelloDiary') {
    return COSTELLO_QUEEN_BANSHEES_MISSION.diaryItemName || "Costello's diary";
  }
  if (productId === 'blessedAnkh') {
    return COSTELLO_QUEEN_BANSHEES_MISSION.rewardItemName || 'Blessed Ankh';
  }
  if (productId === 'spoolOfYarn') {
    return MOTHER_OF_ALL_SPIDERS_MISSION.rewardItemName || 'Spool of Yarn';
  }
  if (productId === 'stuffedToad') {
    return JAKUNDAF_DESERT_MISSION.rewardItemName || 'Stuffed Toad';
  }
  if (productId === 'goldenMug') {
    return DRAGONMOTHER_MISSION.rewardItemName || 'Demodras Soul Core';
  }
  if (productId === 'oldWidowSoulCore') {
    return MOTHER_OF_ALL_SPIDERS_MISSION.soulCoreItemName || 'The Old Widow Soul Core';
  }
  if (productId === 'ekatrixSoulCore' || productId === 'witchSoulCore') {
    return TAINTED_SOULS_MISSION.soulCoreItemName || TAINTED_SOULS_MISSION.rewardItemName || 'Ekatrix Soul Core';
  }
  if (productId === 'bosstiary') {
    return 'Bosstiary';
  }
  if (productId === 'dragonClaw') {
    return getMissionRewardItemName(KING_RED_DRAGON_MISSION, 'dragonClaw');
  }
  if (productId === 'scorpionSceptre') {
    return SCORPION_SCEPTRE_CONFIG.productName || 'Compass';
  }
  if (productId === 'minotaurTrophy') {
    return MINOTAUR_TROPHY_CONFIG.productName || 'Wooden Plank';
  }
  if (productId === 'luminousOrb') {
    return LUMINOUS_ORB_CONFIG.productName || 'Luminous Orb';
  }
  if (productId === 'spectralStone') {
    return SPECTRAL_STONE_CONFIG.productName || 'Spectral Stone';
  }
  return productId;
}

