  function inferStarterCoinThankedFromProgress(progress) {
    if (!progress || progress.__isEmpty) return false;
    if (progress.starterCoinThanked) return true;
    for (const firebaseKey of Object.values(MISSION_FIREBASE_KEY_MAP)) {
      const entry = progress[firebaseKey];
      if (entry?.accepted || entry?.completed) return true;
    }
    if (progress.costelloVisited) return true;
    if (progress.mornenion?.defeated) return true;
    if (progress.ironOre?.completed || progress.ironOre?.active || progress.ironOre?.startTime) return true;
    return false;
  }

  async function grantStarterSilverTokenIfNeeded(progress, playerName) {
    try {
      if (!progress || !progress.__isEmpty || !playerName) {
        return;
      }
      if (progress.starterCoinThanked || kingChatState.starterCoinThanked) {
        return;
      }
      if (!missionProgressHydratedFromFirebase) {
        console.warn('[Quests Mod] Skipping starter Silver Token until Firebase progress is hydrated');
        return;
      }
      const hasToken = await hasSilverToken();
      if (hasToken) {
        return;
      }
      await addQuestItem(SILVER_TOKEN_CONFIG.productName, 1);
      // Persist current hydrated progress (defaults for a new player) — never a partial wipe.
      await saveKingTibianusProgress(playerName, getAllMissionProgress());
      console.log('[Quests Mod] Granted starter Silver Token to new player (no King progress)');
    } catch (error) {
      console.error('[Quests Mod] Error granting starter Silver Token:', error);
    }
  }

  // =======================
  // Deterministic Drop Calculation
  // =======================

  // Deterministic random function using seed (produces consistent results)
  // This makes drops verifiable and prevents manipulation
  function deterministicRandom(seed, creatureGameId, productIndex) {
    // Combine seed with creature and product identifiers for uniqueness
    const combined = seed + creatureGameId * 1000 + productIndex;
    
    // Simple hash function to create pseudo-random value
    let hash = 0;
    const str = combined.toString();
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    
    // Normalize to 0-1 range
    return Math.abs(hash) % 10000 / 10000;
  }

  // =======================
  // Creature Detection (serverResults ONLY)
  // =======================

  // Get creature gameId from serverResults (from monsterDrop)
  function getCreatureGameId(serverResults) {
    if (!serverResults || !serverResults.rewardScreen) {
      return null;
    }

    const rewardScreen = serverResults.rewardScreen;

    // Check monsterDrop.gameId in rewardScreen
    if (rewardScreen.monsterDrop && typeof rewardScreen.monsterDrop.gameId === 'number') {
      return rewardScreen.monsterDrop.gameId;
    }

    // Also check serverResults.monsterDrop (might be at top level)
    if (serverResults.monsterDrop && typeof serverResults.monsterDrop.gameId === 'number') {
      return serverResults.monsterDrop.gameId;
    }

    return null;
  }

  function getCreatureDisplayNameByGameId(gameId) {
    if (gameId == null) return null;
    try {
      if (window.creatureDatabase?.findMonsterByGameId) {
        const monster = window.creatureDatabase.findMonsterByGameId(Number(gameId));
        return monster?.metadata?.name || monster?.name || null;
      }
    } catch (e) {
      console.error('[Quests Mod][Wishlist] Error resolving creature name:', e);
    }
    return null;
  }

  function isGoblinCreatureName(name) {
    return typeof name === 'string' && /goblin/i.test(name);
  }

  // Get stamina spent from serverResults (based on Hunt Analyzer implementation)
  function getStaminaSpent(serverResults) {
    if (!serverResults) {
      return 0;
    }

    // Use the same method as Hunt Analyzer: serverResults.next.playerExpDiff
    // This represents the experience/stamina cost of the battle
    if (serverResults.next && typeof serverResults.next.playerExpDiff === 'number') {
      return serverResults.next.playerExpDiff;
    }

    // Fallback to other possible locations if the main one doesn't work
    if (typeof serverResults.staminaSpent === 'number') {
      return serverResults.staminaSpent;
    }

    if (serverResults.rewardScreen && typeof serverResults.rewardScreen.staminaSpent === 'number') {
      return serverResults.rewardScreen.staminaSpent;
    }

    if (serverResults.battleData && typeof serverResults.battleData.staminaSpent === 'number') {
      return serverResults.battleData.staminaSpent;
    }

    // Default to 0 if not found
    return 0;
  }

  /** Drop chance scales with stamina spent: baseDropChance per 3 stamina, capped at 100%. */
  function getStaminaScaledDropChance(staminaSpent, baseDropChance) {
    const scaled = (staminaSpent / 3) * baseDropChance;
    return Math.min(scaled, 1.0);
  }

  function formatStaminaDropChanceLog(staminaSpent, baseDropChance, actualDropChance) {
    const perThreeStaminaPercent = (baseDropChance * 100).toFixed(1);
    return `${staminaSpent} stamina → ${(actualDropChance * 100).toFixed(1)}% (${perThreeStaminaPercent}% per 3 stamina)`;
  }

  // Check if defeated creature has quest item drops configured
  function getQuestItemsConfig(creatureGameId) {
    if (!creatureGameId || !QUEST_ITEMS_CONFIG[creatureGameId]) {
      return null;
    }
    return QUEST_ITEMS_CONFIG[creatureGameId];
  }

  // =======================
  // Drop System
  // =======================

  function setupQuestItemsDropSystem() {
    if (questItemsBoardSubscription) {
      return; // Already set up
    }
    
    if (typeof globalThis !== 'undefined' && globalThis.state && globalThis.state.board && globalThis.state.board.subscribe) {
      console.log('[Quests Mod] Setting up quest items drop system...');
      questItemsBoardSubscription = globalThis.state.board.subscribe(({ context }) => {
        const serverResults = context.serverResults;
        if (!serverResults || !serverResults.rewardScreen || typeof serverResults.seed === 'undefined') {
          return;
        }
        
        // Only drop on victories
        if (!serverResults.rewardScreen.victory) {
          return;
        }
        
        const seed = serverResults.seed;
        
        // Skip duplicate seeds
        if (seed === lastProcessedQuestItemsSeed) {
          return;
        }
        
        lastProcessedQuestItemsSeed = seed;
        
        // Get creature gameId from serverResults (from monsterDrop)
        const creatureGameId = getCreatureGameId(serverResults);
        
        if (!creatureGameId) {
          console.log('[Quests Mod][Quest Items] Victory detected but no creature gameId found, seed:', seed);
          return;
        }
        
        // Get creature config (may be null if no specific quest items)
        const creatureConfig = getQuestItemsConfig(creatureGameId);

        // Get stamina spent for dynamic drop chance calculation
        const staminaSpent = getStaminaSpent(serverResults);

        // Always run drop logic async (even for creatures with no specific quest items)
        (async () => {
          // If this is the red dragon loot source, require the mission to be active
          const isDragonLoot = creatureGameId === 26;
          if (isDragonLoot) {
            const dragonActive = await isRedDragonMissionActive();
            if (!dragonActive) {
              console.log('[Quests Mod][Quest Items] Red dragon loot skipped; mission not active');
              return;
            }
          }

          // If this is a dwarf loot source for Al Dee fishing, require the mission to be active
          const alDeeDwarfGameIds = await getAlDeeDwarfGameIds();
          const isAlDeeDwarfLoot = alDeeDwarfGameIds.includes(creatureGameId);
          if (isAlDeeDwarfLoot) {
            const alDeeFishingActive = await isAlDeeFishingMissionActive();
            if (!alDeeFishingActive) {
              console.log('[Quests Mod][Quest Items] Al Dee dwarf loot skipped; mission not active');
              return;
            }
          }

          // Get creature name for logging (fallback if no config)
          const creatureName = creatureConfig ? creatureConfig.creatureName : `Creature ${creatureGameId}`;
          console.log(`[Quests Mod][Quest Items] ${creatureName} victory detected (gameId: ${creatureGameId}), seed:`, seed, `, stamina spent: ${staminaSpent}`);

          // Process creature-specific drops (if any)
          if (creatureConfig && creatureConfig.products.length > 0) {
            console.log(`[Quests Mod][Quest Items] Processing ${creatureConfig.products.length} creature-specific drops`);
            for (let productIndex = 0; productIndex < creatureConfig.products.length; productIndex++) {
              const product = creatureConfig.products[productIndex];
              const actualDropChance = getStaminaScaledDropChance(staminaSpent, product.dropChance);
              const roll = deterministicRandom(seed, creatureGameId, productIndex);
              console.log(`[Quests Mod][Quest Items] ${product.name} roll: ${(roll * 100).toFixed(1)}% (need ≤ ${(actualDropChance * 100).toFixed(1)}% | ${formatStaminaDropChanceLog(staminaSpent, product.dropChance, actualDropChance)})`);
              if (roll <= actualDropChance) {
                try {
                  await addQuestItem(product.name, 1);
                  showQuestItemNotification(product.name, 1);
                  console.log(`[Quests Mod][Quest Items] ${product.name} awarded from ${creatureConfig.creatureName}`);
                } catch (error) {
                  console.error(`[Quests Mod][Quest Items] Error adding ${product.name}:`, error);
                }
              }
            }
          } else {
            console.log(`[Quests Mod][Quest Items] No creature-specific drops configured for ${creatureName}`);
          }

          // Process Al Dee fishing Iron Ore drops from dwarves
          if (isAlDeeDwarfLoot) {
            const currentPlayer = getCurrentPlayerName();
            if (!(await canAwardIronOreDrop(currentPlayer))) {
              console.log('[Quests Mod][Quest Items] Iron Ore dwarf drop skipped (received, owned, concluded, or letter not obtained)');
            } else {
              console.log(`[Quests Mod][Quest Items] Processing Al Dee fishing Iron Ore drop from ${creatureName} (gameId: ${creatureGameId}), seed:`, seed);

              const ironOreBaseChance = ROOKGAARD_GLOBAL_POOL_DROP_CHANCE;
              const actualDropChance = getStaminaScaledDropChance(staminaSpent, ironOreBaseChance);
              const roll = deterministicRandom(seed, creatureGameId, 9999);
              console.log(`[Quests Mod][Quest Items] Iron Ore roll: ${(roll * 100).toFixed(1)}% (need ≤ ${(actualDropChance * 100).toFixed(1)}% | ${formatStaminaDropChanceLog(staminaSpent, ironOreBaseChance, actualDropChance)} | creature: ${creatureName})`);
              if (roll <= actualDropChance) {
                try {
                  await addQuestItem('Iron Ore', 1);
                  showQuestItemNotification('Iron Ore', 1);
                  console.log(`[Quests Mod][Quest Items] Iron Ore awarded from ${creatureName} (Al Dee fishing mission)`);

                  await markIronOreReceived(currentPlayer);
                } catch (error) {
                  console.error(`[Quests Mod][Quest Items] Error adding Iron Ore:`, error);
                }
              }
            }
          }

          // Wishlist: stamina-scaled from any Goblin-named creature, once-ever
          {
            const goblinName = getCreatureDisplayNameByGameId(creatureGameId) || creatureName;
            if (isGoblinCreatureName(goblinName)) {
              const currentPlayer = getCurrentPlayerName();
              if (!(await canAwardWishlistDrop(currentPlayer))) {
                console.log('[Quests Mod][Wishlist] Already received, owned, or quest concluded — skip drop');
              } else {
                const actualDropChance = getStaminaScaledDropChance(staminaSpent, WISHLIST_CONFIG.dropChance);
                const roll = deterministicRandom(seed, creatureGameId, 8801);
                console.log(`[Quests Mod][Wishlist] roll: ${(roll * 100).toFixed(1)}% (need ≤ ${(actualDropChance * 100).toFixed(1)}% | ${formatStaminaDropChanceLog(staminaSpent, WISHLIST_CONFIG.dropChance, actualDropChance)} | ${goblinName})`);
                if (roll <= actualDropChance) {
                  try {
                    await addQuestItem(WISHLIST_CONFIG.productName, 1);
                    showQuestItemNotification(WISHLIST_CONFIG.productName, 1);
                    await markWishlistReceived(currentPlayer);
                    await acceptChristmasMiracleMission({ showToast: true });
                    if (typeof updateAllBoardNpcStates === 'function') {
                      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
                    }
                    console.log(`[Quests Mod][Wishlist] Awarded from ${goblinName}`);
                  } catch (error) {
                    console.error('[Quests Mod][Wishlist] Error awarding Wishlist:', error);
                  }
                }
              }
            }
          }

          // Process global Rookgaard drops — one stamina-scaled roll; letter before iron ore
          if (isInRookgaard()) {
            console.log('[Quests Mod][Quest Items] Checking global Rookgaard drops');
            const currentPlayer = getCurrentPlayerName();
            const letterDrop = ROOKGAARD_GLOBAL_DROPS.find((drop) => drop.name === 'Letter from Al Dee');
            const ironOreDrop = ROOKGAARD_GLOBAL_DROPS.find((drop) => drop.name === 'Iron Ore');

            const canAwardLetter = await canAwardLetterFromAlDeeDrop(currentPlayer);
            const canAwardIronOre = await canAwardIronOreDrop(currentPlayer);

            if (!canAwardLetter && !canAwardIronOre) {
              console.log('[Quests Mod][Quest Items] Rookgaard global drops complete for this account, skipping');
            } else {
              const actualDropChance = getStaminaScaledDropChance(staminaSpent, ROOKGAARD_GLOBAL_POOL_DROP_CHANCE);
              const roll = deterministicRandom(seed, 999, 0);
              console.log(`[Quests Mod][Quest Items] Rookgaard global drop roll: ${(roll * 100).toFixed(1)}% (need ≤ ${(actualDropChance * 100).toFixed(1)}% | ${formatStaminaDropChanceLog(staminaSpent, ROOKGAARD_GLOBAL_POOL_DROP_CHANCE, actualDropChance)})`);

              if (roll <= actualDropChance) {
                try {
                  if (canAwardLetter) {
                    await addQuestItem(letterDrop.name, 1);
                    showQuestItemNotification(letterDrop.name, 1);
                    await markLetterFromAlDeeReceived(currentPlayer);
                    console.log(`[Quests Mod][Quest Items] ${letterDrop.name} awarded from ${creatureName} (Rookgaard global drop)`);
                  } else if (canAwardIronOre) {
                    await addQuestItem(ironOreDrop.name, 1);
                    showQuestItemNotification(ironOreDrop.name, 1);
                    await markIronOreReceived(currentPlayer);
                    console.log(`[Quests Mod][Quest Items] ${ironOreDrop.name} awarded from ${creatureName} (Rookgaard global drop)`);
                  } else {
                    console.log('[Quests Mod][Quest Items] Rookgaard global drop roll won but nothing left to award');
                  }
                } catch (error) {
                  console.error('[Quests Mod][Quest Items] Error adding Rookgaard global drop:', error);
                }
              }
            }
          }
        })();
      });
    }
  }

  // =======================
  // Copper Key Board Tracking & Verification
  // =======================

  // Track boardConfig before battle starts
  async function trackBoardConfigForCopperKey() {
    try {
      // Check if on Mine Hub
      if (!isOnMineHub()) {
        trackedBoardConfig = null;
        return;
      }
      
      // Check if player can still be awarded the Copper Key
      const currentPlayer = getCurrentPlayerName();
      if (currentPlayer) {
        if (!(await canAwardCopperKeyDrop(currentPlayer))) {
          console.log('[Quests Mod][Copper Key] Player already owns Copper Key or quest concluded, skipping tracking');
          trackedBoardConfig = null;
          return;
        }
      }
      
      // Get current boardConfig
      const boardContext = globalThis.state?.board?.getSnapshot?.()?.context;
      if (!boardContext || !boardContext.boardConfig) {
        trackedBoardConfig = null;
        return;
      }
      
      // Check if Corym Charlatan is on tile 69
      if (hasCorymCharlatanOnTile69(boardContext.boardConfig)) {
        // Store a deep copy of boardConfig for verification
        trackedBoardConfig = JSON.parse(JSON.stringify(boardContext.boardConfig));
      } else {
        trackedBoardConfig = null;
      }
    } catch (error) {
      console.error('[Quests Mod][Copper Key] Error tracking boardConfig:', error);
      trackedBoardConfig = null;
    }
  }

  // Clean up Copper Key subscriptions
  function cleanupCopperKeySystem() {
    if (copperKeyBoardSubscription) {
      copperKeyBoardSubscription.unsubscribe();
      copperKeyBoardSubscription = null;
    }
    if (equipmentSlotObserver) {
      equipmentSlotObserver.unsubscribe();
      equipmentSlotObserver = null;
    }
    removeCopperKeyCorymSuccessEffects();
  }

  function shouldEnableCopperKeyCorymSuccessEffects() {
    try {
      const copperMissionProgress = kingChatState.progressCopper || { accepted: false, completed: false };
      if (!copperMissionProgress.accepted || copperMissionProgress.completed) return false;
      return isOnMineHub();
    } catch (error) {
      return false;
    }
  }

  function removeCopperKeyCorymSuccessEffects() {
    removeQuestTileSuccessEffects(COPPER_KEY_CORYM_SUCCESS_EFFECT_CLASS);
  }

  function updateCopperKeyCorymSuccessEffects(boardContext = null) {
    const ctx = boardContext || globalThis.state?.board?.getSnapshot()?.context;
    if (
      !shouldEnableCopperKeyCorymSuccessEffects() ||
      isBoardBattleActive(ctx) ||
      !!ctx?.gameStarted
    ) {
      removeCopperKeyCorymSuccessEffects();
      return;
    }

    const tileIndex = COPPER_KEY_CONFIG.targetTileIndex;
    const tile = getTileElement(tileIndex);
    if (!tile?.isConnected) {
      removeCopperKeyCorymSuccessEffects();
      return;
    }

    const boardConfig = ctx?.boardConfig || [];
    const existing = tile.querySelector(`.${COPPER_KEY_CORYM_SUCCESS_EFFECT_CLASS}`);
    if (hasCorymCharlatanOnTile69(boardConfig)) {
      if (!existing) placeQuestTileSuccessEffect(tile, COPPER_KEY_CORYM_SUCCESS_EFFECT_CLASS);
    } else if (existing) {
      existing.remove();
    }
  }

  // Setup Copper Key verification system (only when mission is active)
  function setupCopperKeySystem() {
    // Only set up if Copper Key mission is active or completed
    const copperMissionProgress = kingChatState.progressCopper || { accepted: false, completed: false };
    if (!copperMissionProgress.accepted && !copperMissionProgress.completed) {
      // Mission not active - cleanup if subscriptions exist
      if (copperKeyBoardSubscription) {
        cleanupCopperKeySystem();
      }
      return;
    }

    if (copperKeyBoardSubscription) {
      return; // Already set up
    }
    
    if (typeof globalThis !== 'undefined' && globalThis.state && globalThis.state.board && globalThis.state.board.subscribe) {
      console.log('[Quests Mod][Copper Key] Setting up Copper Key system...');
      
      // Single subscription for both tracking and verification
      copperKeyBoardSubscription = globalThis.state.board.subscribe(async ({ context }) => {
        // Check if mission is still active, cleanup if not
        const copperMissionProgress = kingChatState.progressCopper || { accepted: false, completed: false };
        if (!copperMissionProgress.accepted && !copperMissionProgress.completed) {
          cleanupCopperKeySystem();
          return;
        }
        // Track boardConfig before battle starts
        if (context.boardConfig && !context.serverResults) {
          await trackBoardConfigForCopperKey();
          updateCopperKeyCorymSuccessEffects(context);
          return;
        }

        updateCopperKeyCorymSuccessEffects(context);
        
        // Monitor serverResults for victory verification
        const serverResults = context.serverResults;
        if (!serverResults || !serverResults.rewardScreen || typeof serverResults.seed === 'undefined') {
          return;
        }
        
        // Only process on victories
        if (!serverResults.rewardScreen.victory) {
          return;
        }
        
        const seed = serverResults.seed;
        
        // Skip duplicate seeds
        if (seed === lastProcessedCopperKeySeed) {
          return;
        }
        
        lastProcessedCopperKeySeed = seed;
        
        try {
          console.log('[Quests Mod][Copper Key] Victory detected, checking conditions, seed:', seed);
          
          // Verify conditions
          // 1. Check if on Mine Hub
          const roomId = serverResults.rewardScreen?.roomId;
          const mineHubRoomId = getMineHubRoomId();
          // Room check
          if (!mineHubRoomId || roomId !== mineHubRoomId) {
            return; // Not on Mine Hub
          }
          
          // 2. Verify Corym Charlatan was on tile 69
          // Use tracked boardConfig if available, otherwise check current boardConfig
          let boardConfigToCheck = trackedBoardConfig;
          if (!boardConfigToCheck) {
            const boardContext = globalThis.state?.board?.getSnapshot?.()?.context;
            boardConfigToCheck = boardContext?.boardConfig;
            // Using current boardConfig
          } else {
            // Using tracked boardConfig
          }
          
          // Debug: Check what pieces are on tile 69
          if (boardConfigToCheck && Array.isArray(boardConfigToCheck)) {
            // minimal debug: presence check is enough
          }
          
          const hasCorymOnTile69 = hasCorymCharlatanOnTile69(boardConfigToCheck, serverResults);
          if (!hasCorymOnTile69) {
            return; // Corym Charlatan was not on tile 69
          }
          
          // 3. Check unique-item eligibility (received flag, ownership, or quest concluded)
          const currentPlayer = getCurrentPlayerName();
          if (!currentPlayer) {
            logCopper('[Quests Mod][Copper Key] Player name not available, skipping');
            return;
          }
          
          if (!(await canAwardCopperKeyDrop(currentPlayer))) {
            return; // Already received, owned, or quest concluded
          }
          
          // All conditions met! Award the key
          console.log('[Quests Mod][Copper Key] Awarding Copper Key');
          
          await addQuestItem(COPPER_KEY_CONFIG.productName, 1);
          await markCopperKeyReceived(currentPlayer);
          
          // Show special "Found Copper Key!" toast
          NotificationService.showImportant(TOAST_MESSAGES.copperKeyFound, '[Quests Mod][Copper Key]');
          
          // Animate the key sprite with funky animation, then explode it, then remove
          setTimeout(() => {
            const tileElement = getTileElement(COPPER_KEY_CONFIG.targetTileIndex);
            const animatedSprite = animateCopperKey(COPPER_KEY_CONFIG.targetTileIndex);
            
            if (animatedSprite && tileElement) {
              // After funky animation completes (2 seconds), trigger explosion
              setTimeout(() => {
                explodeCopperKey(animatedSprite, tileElement);
                
                // After explosion completes (0.5 seconds), remove the sprite
                setTimeout(() => {
                  removeKeyFromElement(tileElement, COPPER_KEY_CONFIG.targetTileIndex, true); // removeSprite = true
                }, 600); // 0.5s explosion + 100ms buffer
              }, 2000); // Wait for funky animation to complete
            } else {
              // If animation failed, just remove it normally
              if (tileElement) {
                removeKeyFromElement(tileElement, COPPER_KEY_CONFIG.targetTileIndex, true);
              }
            }
          }, 100);
          
          console.log('[Quests Mod][Copper Key] Copper Key awarded');
        } catch (error) {
          console.error('[Quests Mod][Copper Key] Error processing Copper Key:', error);
        }
      });
      updateCopperKeyCorymSuccessEffects(globalThis.state?.board?.getSnapshot()?.context);
      
      console.log('[Quests Mod][Copper Key] Copper Key system set up');
    }
  }

  // =======================
  // Notification Service
  // =======================

  const TOAST_MESSAGE_VARIANTS = {};

  function rebuildToastMessageVariantsMap() {
    for (const key of Object.keys(TOAST_MESSAGE_VARIANTS)) {
      delete TOAST_MESSAGE_VARIANTS[key];
    }
    for (const [key, variant] of Object.entries(TOAST_VARIANT_BY_KEY)) {
      if (key === 'mornenionDefeated') {
        TOAST_MESSAGE_VARIANTS[MORNENION_DEFEATED_MESSAGE] = variant;
        continue;
      }
      const message = TOAST_MESSAGES[key];
      if (typeof message === 'string' && message) {
        TOAST_MESSAGE_VARIANTS[message] = variant;
      }
    }
  }

  rebuildToastMessageVariants = rebuildToastMessageVariantsMap;
  rebuildToastMessageVariantsMap();

  function resolveToastVariant(message) {
    if (!message || typeof message !== 'string') return 'info';

    if (TOAST_MESSAGE_VARIANTS[message]) {
      return TOAST_MESSAGE_VARIANTS[message];
    }

    if (message.startsWith('New quest discovered:') || message.startsWith('New quest:')) return 'quest';
    if (message.startsWith('Mission completed:')) return 'completed';
    if (message.includes(' task is complete.')) return 'completed';
    if (message.endsWith(' seal completed')) return 'completed';
    if (message.startsWith('Received ') || message.startsWith('Found ')) return 'found';
    if (message.startsWith('Removed ')) return 'found';
    if (message.startsWith('Delivered to ') || message.startsWith('Returned to ')) return 'found';
    if (message.startsWith('Navigated to ')) return 'found';
    if (/ obtained! \(\+/.test(message) || / obtido! \(\+/.test(message)) return 'found';
    if (message.startsWith('Battling ')) return 'info';
    if (message.includes('can only be placed on tiles')) return 'warning';

    return 'info';
  }

  function resolveToastDuration(message, variant) {
    const resolvedVariant = variant || resolveToastVariant(message);
    return TOAST_VARIANT_DURATIONS[resolvedVariant] ?? TOAST_DURATION_DEFAULT;
  }

  const QUEST_TOAST_ITEM_CLASS = 'quest-toast-item';
  const QUEST_TOAST_GAP = 6;
  const QUEST_TOAST_ITEM_STYLE = 'left:0;right:0;display:flex;position:absolute;transition:230ms cubic-bezier(0.21,1.02,0.73,1);bottom:0;justify-content:flex-end;';

  function relayoutQuestToasts(container) {
    if (!container) return;
    const items = Array.from(container.querySelectorAll(`.${QUEST_TOAST_ITEM_CLASS}`));
    const persistent = items.filter((item) => item.dataset.toastKind === 'persistent');
    const transient = items.filter((item) => item.dataset.toastKind !== 'persistent');
    const ordered = [...persistent, ...transient];

    let offset = 0;
    ordered.forEach((item) => {
      item.style.transform = `translateY(-${offset}px)`;
      const height = Math.ceil(item.getBoundingClientRect().height);
      offset += (height > 0 ? height : 46) + QUEST_TOAST_GAP;
    });
  }

  function createQuestToastShell({ message, variant, productName, dismissable = true }) {
    const flexContainer = document.createElement('div');
    flexContainer.className = QUEST_TOAST_ITEM_CLASS;
    flexContainer.style.cssText = QUEST_TOAST_ITEM_STYLE;

    const toast = document.createElement(dismissable ? 'button' : 'div');
    toast.className = 'non-dismissable-dialogs shadow-lg animate-in fade-in zoom-in-95 slide-in-from-top lg:slide-in-from-bottom';
    if (!dismissable) {
      toast.setAttribute('role', 'presentation');
    }

    const widgetTop = document.createElement('div');
    widgetTop.className = 'widget-top h-2.5';

    const widgetBottom = document.createElement('div');
    widgetBottom.className = 'widget-bottom pixel-font-16 flex items-center gap-2 px-2 py-1 text-whiteHighlight';

    if (productName) {
      const productDef = buildProductDefinitions().find((p) => p.name === productName);
      if (productDef) {
        widgetBottom.appendChild(createProductIcon(productDef, 16));
      }
    }

    const messageDiv = document.createElement('div');
    messageDiv.className = 'text-left';
    if (typeof message === 'string' && message.indexOf('\n') !== -1) {
      messageDiv.style.whiteSpace = 'pre-line';
    }
    messageDiv.style.color = TOAST_VARIANT_COLORS[variant] || TOAST_VARIANT_COLORS.info;
    messageDiv.textContent = message;
    widgetBottom.appendChild(messageDiv);

    toast.appendChild(widgetTop);
    toast.appendChild(widgetBottom);
    flexContainer.appendChild(toast);

    return { flexContainer, toast, messageDiv };
  }
  
  const NotificationService = {
    getContainer() {
      let mainContainer = document.getElementById('quest-items-toast-container');
      if (!mainContainer) {
        mainContainer = document.createElement('div');
        mainContainer.id = 'quest-items-toast-container';
        mainContainer.style.cssText = `
          position: fixed;
          z-index: 9999;
          inset: 16px 16px 64px;
          pointer-events: none;
        `;
        document.body.appendChild(mainContainer);
      }
      return mainContainer;
    },

    updatePositions(container) {
      relayoutQuestToasts(container || this.getContainer());
    },

    show({ productName, message, duration, logPrefix = '[Quests Mod]', variant }) {
      try {
        const mainContainer = this.getContainer();
        const resolvedVariant = variant || resolveToastVariant(message);
        const resolvedDuration = duration ?? resolveToastDuration(message, resolvedVariant);

        const { flexContainer, toast } = createQuestToastShell({
          message,
          variant: resolvedVariant,
          productName,
          dismissable: true
        });
        flexContainer.dataset.toastKind = 'transient';

        mainContainer.appendChild(flexContainer);
        requestAnimationFrame(() => relayoutQuestToasts(mainContainer));

        console.log(`${logPrefix} Toast shown: ${message}`);

        const dismissToast = () => {
          if (flexContainer && flexContainer.parentNode) {
            flexContainer.parentNode.removeChild(flexContainer);
            relayoutQuestToasts(mainContainer);
          }
        };

        toast.addEventListener('click', dismissToast);

        setTimeout(dismissToast, resolvedDuration);

      } catch (error) {
        console.error(`${logPrefix} Error showing toast:`, error);
      }
    },

    showImportant(message, logPrefix = '[Quests Mod]', productName, variant) {
      this.show({ productName, message, logPrefix, variant });
    },

    showQuestDiscovered(mission, logPrefix = '[Quests Mod]') {
      const title = typeof mission === 'string' ? mission : mission.title;
      this.showImportant(TOAST_MESSAGES.questDiscovered(title), logPrefix);
    },

    showQuestAccepted(mission, logPrefix = '[Quests Mod]') {
      this.showImportant(TOAST_MESSAGES.questAccepted(mission.title), logPrefix);
    },

    showQuestCompleted(mission, logPrefix = '[Quests Mod]', { rewardCoins, productName, message } = {}) {
      let resolvedMessage = message;
      if (!resolvedMessage) {
        resolvedMessage = rewardCoins != null
          ? TOAST_MESSAGES.questCompletedWithCoins(mission.title, rewardCoins)
          : TOAST_MESSAGES.questCompleted(mission.title);
      }
      // Pin the gold "completed" styling explicitly so it survives copy edits in toasts.json
      // (resolveToastVariant's English-prefix fallback would otherwise be the only thing keeping it).
      this.show({ productName, message: resolvedMessage, logPrefix, variant: 'completed' });
    },

    showTaskCompletedWithCoins(mission, logPrefix = '[Quests Mod]') {
      this.showImportant(
        TOAST_MESSAGES.taskCompletedWithCoins(mission.title, mission.rewardCoins),
        logPrefix,
        undefined,
        'completed'
      );
    },

    showItemReceived(productName, logPrefix = '[Quests Mod]', message) {
      this.show({
        productName,
        message: message || TOAST_MESSAGES.itemReceived(productName),
        logPrefix
      });
    },

    showItemRemoved(productName, logPrefix = '[Quests Mod]', message) {
      this.show({
        productName,
        message: message || TOAST_MESSAGES.itemRemoved(productName),
        logPrefix
      });
    },

    showSealCompleted(ordinal, logPrefix = '[Quests Mod]') {
      this.showImportant(TOAST_MESSAGES.sealCompleted(ordinal), logPrefix, undefined, 'completed');
    },

    showBattleToast(toastData, logPrefix = '[Quests Mod]') {
      this.show({
        message: toastData.message,
        duration: toastData.duration,
        logPrefix
      });
    },

    createBattleToastCallback(logPrefix) {
      return (toastData) => this.showBattleToast(toastData, logPrefix);
    },

    showQuestItem(productName, amount) {
      this.show({
        productName,
        message: tReplace('mods.quests.productObtained', { productName, amount })
      });
    }
  };

  // =======================
  // Notification System
  // =======================

  function showToast({ productName, message, duration, logPrefix = '[Quests Mod]', variant }) {
    NotificationService.show({ productName, message, duration, logPrefix, variant });
  }

  function showQuestItemNotification(productName, amount) {
    NotificationService.showQuestItem(productName, amount);
  }

  function showSealCompletedToast(ordinal, logPrefix) {
    NotificationService.showSealCompleted(ordinal, logPrefix);
  }

  function showQueenBansheesCompletionToasts() {
    NotificationService.showQuestCompleted(COSTELLO_QUEEN_BANSHEES_MISSION, '[Quests Mod][Costello]');
    NotificationService.showItemReceived(
      COSTELLO_QUEEN_BANSHEES_MISSION.rewardItemName,
      '[Quests Mod][Costello]'
    );
    NotificationService.showImportant(TOAST_MESSAGES.diaryReturned, '[Quests Mod][Costello]');
  }

  let customBattleStatusToastHandle = null;
  let customBattleStatusToastBoardUnsub = null;
  let customBattleStatusToastState = null;

  function countPlayerPlacedAlliesForStatusToast(battle) {
    try {
      if (battle && typeof battle.countPlayerAllyCreatures === 'function') {
        return battle.countPlayerAllyCreatures();
      }
      const boardConfig = globalThis.state?.board?.getSnapshot()?.context?.boardConfig || [];
      return boardConfig.filter((piece) => {
        if (piece?.customForcedAlly) return false;
        if (battle && typeof battle.isForcedAllyEntity === 'function' && battle.isForcedAllyEntity(piece)) {
          return false;
        }
        return piece?.type === 'player' || (piece?.type === 'custom' && piece?.villain === false);
      }).length;
    } catch (error) {
      console.error('[Quests Mod][Battle] Error counting placed allies for status toast:', error);
      return 0;
    }
  }

  function buildCustomBattleStatusToastText({ battleName, allyLimit, battle }) {
    if (typeof allyLimit === 'number') {
      const placed = countPlayerPlacedAlliesForStatusToast(battle);
      return `Battling ${battleName}\nCreatures allowed: ${placed}/${allyLimit}`;
    }
    return `Battling ${battleName}\nCreatures allowed: N/A`;
  }

  function stopCustomBattleStatusToastBoardWatch() {
    if (!customBattleStatusToastBoardUnsub) return;
    try {
      if (typeof customBattleStatusToastBoardUnsub.unsubscribe === 'function') {
        customBattleStatusToastBoardUnsub.unsubscribe();
      } else if (typeof customBattleStatusToastBoardUnsub === 'function') {
        customBattleStatusToastBoardUnsub();
      }
    } catch (error) {
      console.warn('[Quests Mod][Battle] Error unsubscribing status toast board watch:', error);
    }
    customBattleStatusToastBoardUnsub = null;
  }

  function ensureCustomBattleStatusToastBoardWatch() {
    if (customBattleStatusToastBoardUnsub) return;
    if (!globalThis.state?.board?.subscribe) return;
    customBattleStatusToastBoardUnsub = globalThis.state.board.subscribe(() => {
      if (!customBattleStatusToastHandle || !customBattleStatusToastState) return;
      if (typeof customBattleStatusToastHandle.updateMessage !== 'function') return;
      customBattleStatusToastHandle.updateMessage(
        buildCustomBattleStatusToastText(customBattleStatusToastState)
      );
    });
  }

  function removeCustomBattleStatusToast() {
    stopCustomBattleStatusToastBoardWatch();
    customBattleStatusToastState = null;
    if (customBattleStatusToastHandle && typeof customBattleStatusToastHandle.remove === 'function') {
      customBattleStatusToastHandle.remove();
    }
    customBattleStatusToastHandle = null;
    NotificationService.updatePositions();
  }

  function showCustomBattleStatusToast({ battleName, allyLimit, battle = null, logPrefix = '[Quests Mod][Battle]' }) {
    if (!battleName) return;
    const mainContainer = NotificationService.getContainer();
    if (!mainContainer) return;

    customBattleStatusToastState = { battleName, allyLimit, battle, logPrefix };
    const text = buildCustomBattleStatusToastText(customBattleStatusToastState);
    const variant = resolveToastVariant(text);

    if (customBattleStatusToastHandle && typeof customBattleStatusToastHandle.updateMessage === 'function') {
      customBattleStatusToastHandle.updateMessage(text);
      ensureCustomBattleStatusToastBoardWatch();
      requestAnimationFrame(() => NotificationService.updatePositions(mainContainer));
      return;
    }

    const { flexContainer, messageDiv } = createQuestToastShell({
      message: text,
      variant,
      dismissable: false
    });
    flexContainer.dataset.toastKind = 'persistent';
    mainContainer.appendChild(flexContainer);

    customBattleStatusToastHandle = {
      updateMessage(newText) {
        messageDiv.textContent = newText || '';
        requestAnimationFrame(() => NotificationService.updatePositions(mainContainer));
      },
      remove() {
        if (flexContainer && flexContainer.parentNode) {
          flexContainer.parentNode.removeChild(flexContainer);
        }
      }
    };

    ensureCustomBattleStatusToastBoardWatch();
    requestAnimationFrame(() => NotificationService.updatePositions(mainContainer));
    console.log(`${logPrefix} Battle status toast shown: ${text}`);
  }

  function clearAllTimeouts() {
    clearTimeoutOrInterval(buttonCheckInterval);
    clearTimeoutOrInterval(buttonRetryTimeout);
    clearTimeoutOrInterval(observerDebounceTimeout);
    clearTimeoutOrInterval(modalTimeout);
    clearTimeoutOrInterval(dialogTimeout);
    // clearAllToastTimers(); - removed, no longer needed
    buttonCheckInterval = null;
    buttonRetryTimeout = null;
    observerDebounceTimeout = null;
    modalTimeout = null;
    dialogTimeout = null;
  }

  function scheduleQuestItemsButtonRetry() {
    if (buttonRetryTimeout) {
      clearTimeout(buttonRetryTimeout);
      buttonRetryTimeout = null;
    }
    clearCachesAndAddButton(0);
  }

  function inventoryNodeLooksRelevant(node) {
    if (!node || node.nodeType !== Node.ELEMENT_NODE) return false;
    if (node.classList?.contains('container-inventory-4')) return true;
    if (node.classList?.contains('quest-items-inventory-button')) return true;
    if (!node.querySelector) return false;
    return !!(
      node.querySelector('.container-inventory-4') ||
      node.querySelector('.quest-items-inventory-button') ||
      node.querySelector('button.focus-style-visible') ||
      node.querySelector('img[alt="equipments"]')
    );
  }

  // =======================
  // Event Manager
  // =======================
  
  const EventManager = {
    // Track all event listeners for cleanup
    _listeners: new Map(), // Map<element, Map<event, Set<handler>>>

    /**
     * Add event listener with tracking
     * @param {HTMLElement|Document|Window} element - Element to attach listener to
     * @param {string} event - Event name
     * @param {Function} handler - Event handler function
     * @param {Object|boolean} [options] - Event options (useCapture, etc.)
     * @returns {Function} Cleanup function to remove listener
     */
    addEventListener(element, event, handler, options = false) {
      if (!element || !event || !handler) {
        console.warn('[Quests Mod][EventManager] Invalid parameters for addEventListener');
        return () => {};
      }

      // Initialize tracking structure
      if (!this._listeners.has(element)) {
        this._listeners.set(element, new Map());
      }
      const elementListeners = this._listeners.get(element);
      
      if (!elementListeners.has(event)) {
        elementListeners.set(event, new Set());
      }
      const eventHandlers = elementListeners.get(event);

      // Add handler if not already tracked
      if (!eventHandlers.has(handler)) {
        element.addEventListener(event, handler, options);
        eventHandlers.add(handler);
      }

      // Return cleanup function
      return () => this.removeEventListener(element, event, handler);
    },

    /**
     * Remove tracked event listener
     * @param {HTMLElement|Document|Window} element - Element to remove listener from
     * @param {string} event - Event name
     * @param {Function} handler - Event handler function
     */
    removeEventListener(element, event, handler) {
      if (!element || !event || !handler) return;

      const elementListeners = this._listeners.get(element);
      if (!elementListeners) return;

      const eventHandlers = elementListeners.get(event);
      if (!eventHandlers || !eventHandlers.has(handler)) return;

      try {
        element.removeEventListener(event, handler);
        eventHandlers.delete(handler);

        // Clean up empty sets/maps
        if (eventHandlers.size === 0) {
          elementListeners.delete(event);
        }
        if (elementListeners.size === 0) {
          this._listeners.delete(element);
        }
      } catch (e) {
        console.warn('[Quests Mod][EventManager] Error removing event listener:', e);
      }
    },

    /**
     * Remove all tracked listeners
     */
    cleanupAll() {
      for (const [element, elementListeners] of this._listeners.entries()) {
        for (const [event, eventHandlers] of elementListeners.entries()) {
          for (const handler of eventHandlers) {
            try {
              element.removeEventListener(event, handler);
            } catch (e) {
              console.warn('[Quests Mod][EventManager] Error cleaning up listener:', e);
            }
          }
        }
      }
      this._listeners.clear();
    }
  };

  // =======================
  // Error Handler
  // =======================
  
  const ErrorHandler = {
    /**
     * Handle error with standardized logging and optional user message
     * @param {Error} error - Error object
     * @param {string} context - Context where error occurred
     * @param {string} [userMessage] - Optional user-friendly message
     */
    handleError(error, context, userMessage = null) {
      this.logError(error, context);
      
      if (userMessage && typeof api !== 'undefined' && api.ui && api.ui.components && api.ui.components.createModal) {
        try {
          api.ui.components.createModal({
            title: 'Error',
            content: `<p>${userMessage}</p>`,
            buttons: [{ text: 'OK', primary: true }]
          });
        } catch (modalError) {
          console.error('[Quests Mod][ErrorHandler] Error showing error modal:', modalError);
        }
      }
    },

    /**
     * Log error with consistent format
     * @param {Error} error - Error object
     * @param {string} context - Context where error occurred
     */
    logError(error, context) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      const errorStack = error instanceof Error ? error.stack : undefined;
      
      console.error(`[Quests Mod] Error in ${context}:`, errorMessage);
      if (errorStack) {
        console.error('[Quests Mod] Stack trace:', errorStack);
      }
    }
  };

  // =======================
  // Context Menu Helper
  // =======================
  
  /**
   * Create a generic game-styled context menu
   * @param {Object} options - Context menu options
   * @param {number} options.x - X position (client)
   * @param {number} options.y - Y position (client)
   * @param {Array<Object>} options.buttons - Array of button configs: {text, onClick, style?, hoverStyle?}
   * @param {Function} [options.onClose] - Callback when menu closes
   * @param {string} [options.logPrefix='[Quests Mod]'] - Log prefix
   * @param {Element|null} [options.anchorElement] - Optional element to keep the menu pinned to on resize
   * @returns {Object} Menu object with {overlay, menu, closeMenu}
   */
  function createContextMenu({
    x,
    y,
    buttons,
    onClose = null,
    logPrefix = '[Quests Mod]',
    minWidth = '120px',
    layout = 'column', // 'column' | 'center'
    gap = '4px',
    anchorElement = null
  }) {
    const MENU_Z_OVERLAY = '200000';
    const MENU_Z_PANEL = '200001';
    let closed = false;

    // Full-screen overlay above game modals so any click closes the menu
    const overlay = document.createElement('div');
    overlay.style.position = 'fixed';
    overlay.style.top = '0';
    overlay.style.left = '0';
    overlay.style.width = '100%';
    overlay.style.height = '100%';
    overlay.style.zIndex = MENU_Z_OVERLAY;
    overlay.style.backgroundColor = 'transparent';
    overlay.style.pointerEvents = 'auto';
    overlay.style.cursor = 'default';

    // Create menu container (game pixel font)
    const menu = document.createElement('div');
    menu.className = 'pixel-font-14';
    menu.style.position = 'fixed';
    menu.style.left = `${x}px`;
    menu.style.top = `${y}px`;
    menu.style.zIndex = MENU_Z_PANEL;
    menu.style.minWidth = minWidth;
    menu.style.background = "url('https://bestiaryarena.com/_next/static/media/background-dark.95edca67.png') repeat";
    menu.style.border = '4px solid transparent';
    menu.style.borderImage = `url("https://bestiaryarena.com/_next/static/media/4-frame.a58d0c39.png") 6 fill stretch`;
    menu.style.borderRadius = '6px';
    menu.style.padding = '8px';
    menu.style.boxShadow = '0 4px 12px rgba(0, 0, 0, 0.5)';

    // Button container
    const buttonContainer = document.createElement('div');
    buttonContainer.style.display = 'flex';
    if (layout === 'center') {
      buttonContainer.style.justifyContent = 'center';
    } else {
      buttonContainer.style.flexDirection = 'column';
      buttonContainer.style.gap = gap;
    }

    // Create buttons
    buttons.forEach((buttonConfig) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'pixel-font-14';
      button.textContent = buttonConfig.text;
      button.style.width = buttonConfig.width || '140px';
      button.style.height = buttonConfig.height || '30px';
      button.style.fontSize = buttonConfig.fontSize || '14px';
      button.style.lineHeight = '1.2';
      button.style.backgroundColor = buttonConfig.backgroundColor || '#2a4a7a';
      button.style.color = buttonConfig.color || '#E8F4FC';
      button.style.border = buttonConfig.border || '1px solid #4FC3F7';
      button.style.borderRadius = '4px';
      button.style.cursor = 'pointer';
      button.style.textShadow = '1px 1px 0px rgba(0,0,0,0.8)';
      button.style.fontWeight = 'normal';
      button.style.padding = '0 8px';
      button.style.whiteSpace = 'nowrap';

      // Add hover effects
      const hoverBg = buttonConfig.hoverBackgroundColor || '#1a2a4a';
      const hoverBorder = buttonConfig.hoverBorderColor || '#81D4FA';
      const defaultBg = button.style.backgroundColor;
      const defaultBorder = button.style.borderColor;

      button.addEventListener('mouseenter', () => {
        button.style.backgroundColor = hoverBg;
        button.style.borderColor = hoverBorder;
      });
      button.addEventListener('mouseleave', () => {
        button.style.backgroundColor = defaultBg;
        button.style.borderColor = defaultBorder;
      });

      // Add click handler
      button.addEventListener('click', (event) => {
        event.stopPropagation();
        if (buttonConfig.onClick) {
          buttonConfig.onClick();
        }
      });

      buttonContainer.appendChild(button);
    });

    menu.appendChild(buttonContainer);

    // Pin to clicked tile/element on resize when possible; otherwise keep viewport-relative spot
    let useAnchor = false;
    let anchorOffsetX = 0;
    let anchorOffsetY = 0;
    if (anchorElement && typeof anchorElement.getBoundingClientRect === 'function') {
      const ar = anchorElement.getBoundingClientRect();
      if (ar.width > 0 || ar.height > 0) {
        anchorOffsetX = x - ar.left;
        anchorOffsetY = y - ar.top;
        useAnchor = true;
      }
    }
    const viewportRatioX = window.innerWidth > 0 ? x / window.innerWidth : 0;
    const viewportRatioY = window.innerHeight > 0 ? y / window.innerHeight : 0;

    const clampMenuToViewport = () => {
      const rect = menu.getBoundingClientRect();
      let left = parseFloat(menu.style.left) || 0;
      let top = parseFloat(menu.style.top) || 0;
      if (rect.right > window.innerWidth - 8) {
        left = Math.max(8, window.innerWidth - rect.width - 8);
      }
      if (rect.bottom > window.innerHeight - 8) {
        top = Math.max(8, window.innerHeight - rect.height - 8);
      }
      if (left < 8) left = 8;
      if (top < 8) top = 8;
      menu.style.left = `${left}px`;
      menu.style.top = `${top}px`;
    };

    const repositionMenu = () => {
      if (closed) return;
      let nextX;
      let nextY;
      if (useAnchor && anchorElement?.isConnected) {
        const ar = anchorElement.getBoundingClientRect();
        nextX = ar.left + anchorOffsetX;
        nextY = ar.top + anchorOffsetY;
      } else {
        nextX = viewportRatioX * window.innerWidth;
        nextY = viewportRatioY * window.innerHeight;
      }
      menu.style.left = `${nextX}px`;
      menu.style.top = `${nextY}px`;
      clampMenuToViewport();
    };

    const cleanupListeners = () => {
      document.removeEventListener('keydown', escHandler, true);
      document.removeEventListener('pointerdown', outsidePointerHandler, true);
      document.removeEventListener('mousedown', outsidePointerHandler, true);
      document.removeEventListener('contextmenu', outsidePointerHandler, true);
      window.removeEventListener('resize', repositionMenu);
      if (window.visualViewport) {
        window.visualViewport.removeEventListener('resize', repositionMenu);
        window.visualViewport.removeEventListener('scroll', repositionMenu);
      }
    };

    // Close menu function
    const closeMenu = () => {
      if (closed) return;
      closed = true;
      cleanupListeners();
      if (overlay.parentNode) {
        overlay.parentNode.removeChild(overlay);
      }
      if (menu.parentNode) {
        menu.parentNode.removeChild(menu);
      }
      if (onClose) {
        onClose();
      }
    };

    const outsidePointerHandler = (event) => {
      if (menu.contains(event.target)) return;
      closeMenu();
    };

    const escHandler = (e) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        closeMenu();
      }
    };

    overlay.addEventListener('pointerdown', closeMenu);
    overlay.addEventListener('mousedown', closeMenu);
    overlay.addEventListener('click', closeMenu);
    // Capture on document so clicks on high z-index modals still dismiss the menu
    document.addEventListener('pointerdown', outsidePointerHandler, true);
    document.addEventListener('mousedown', outsidePointerHandler, true);
    document.addEventListener('contextmenu', outsidePointerHandler, true);
    document.addEventListener('keydown', escHandler, true);
    window.addEventListener('resize', repositionMenu);
    if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', repositionMenu);
      window.visualViewport.addEventListener('scroll', repositionMenu);
    }

    // Keep menu inside viewport
    document.body.appendChild(overlay);
    document.body.appendChild(menu);
    clampMenuToViewport();

    // Return menu object with cleanup
    return {
      overlay,
      menu,
      closeMenu
    };
  }

  // =======================
  // Mission Manager
  // =======================
  
  const MissionManager = {
    /**
     * Get mission progress
     * @param {Object} mission - Mission object with id property
     * @returns {Object} Progress object {accepted: boolean, completed: boolean}
     */
    getProgress(mission) {
      if (!mission) return { accepted: false, completed: false };
      const stateKey = MISSION_STATE_MAP[mission.id];
      if (stateKey) {
        // Return from state if exists, otherwise return default (future-proof)
        return kingChatState[stateKey] || { accepted: false, completed: false };
      }
      // Mission not in registry - return default
      return { accepted: false, completed: false };
    },

    /**
     * Set mission progress
     * @param {Object} mission - Mission object with id property
     * @param {Object} progress - Progress object {accepted: boolean, completed: boolean}
     */
    setProgress(mission, progress) {
      if (!mission) return;
      const stateKey = MISSION_STATE_MAP[mission.id];
      if (stateKey) {
        kingChatState[stateKey] = progress;
      }
    },

    /**
     * Check if mission is active (accepted but not completed)
     * @param {Object} mission - Mission object
     * @returns {boolean}
     */
    isActive(mission) {
      const progress = this.getProgress(mission);
      return progress.accepted && !progress.completed;
    },

    /**
     * Check if mission is completed
     * @param {Object} mission - Mission object
     * @returns {boolean}
     */
    isCompleted(mission) {
      const progress = this.getProgress(mission);
      return progress.completed;
    },

    /**
     * Get current (next available) mission from a list
     * @param {Array<Object>} missions - Array of mission objects
     * @returns {Object|null} First incomplete mission or null
     */
    getCurrentMission(missions) {
      for (const mission of missions) {
        if (!this.isCompleted(mission)) {
          return mission;
        }
      }
      return null;
    }
  };

  // Legacy function wrappers for backward compatibility
  function getMissionProgress(mission) {
    return MissionManager.getProgress(mission);
  }

  function setMissionProgress(mission, progress) {
    MissionManager.setProgress(mission, progress);
    if (questDialogueReady && progress?.accepted && !progress?.completed) {
      setupProgressAwareQuestObservers();
      refreshSystemsAfterMissionProgressLoaded();
    }
    if (progress?.completed) {
      refreshBoardNpcsAfterQuestItemsChange();
    }
  }

  /**
   * Set mission progress and persist it for the current player in one step.
   * @param {Object} mission - Mission object with id property
   * @param {Object} progress - Progress object {accepted: boolean, completed: boolean}
   * @param {Object} [options]
   * @param {string} [options.playerName] - Override for the current player name
   */
  async function persistMissionProgress(mission, progress, { playerName } = {}) {
    setMissionProgress(mission, progress);
    const name = playerName || getCurrentPlayerName();
    if (!name) return;
    await saveKingTibianusProgress(name, getAllMissionProgress());
  }

  // =======================
  // Modal Helpers
  // =======================
  
  const ModalHelpers = {
    /**
     * Create a modal row container
     * @param {string} [justifyContent='flex-start'] - CSS justify-content value
     * @param {string} [gap='8px'] - Gap between items
     * @returns {HTMLElement} Row container element
     */
    createRow(justifyContent = 'flex-start', gap = '8px') {
      const row = document.createElement('div');
      row.style.cssText = `display: flex; flex-direction: row; justify-content: ${justifyContent}; gap: ${gap}; align-items: center; width: 100%;`;
      return row;
    },

    /**
     * Create a modal column container
     * @param {string} [alignItems='flex-start'] - CSS align-items value
     * @param {string} [gap='8px'] - Gap between items
     * @returns {HTMLElement} Column container element
     */
    createColumn(alignItems = 'flex-start', gap = '8px') {
      const column = document.createElement('div');
      column.style.cssText = `display: flex; flex-direction: column; align-items: ${alignItems}; gap: ${gap}; width: 100%;`;
      return column;
    },

    /**
     * Create a framed box element (common game UI pattern)
     * @param {Object} [options] - Options object
     * @param {string} [options.background] - Background image URL
     * @param {string} [options.borderImage] - Border image URL
     * @param {string} [options.padding] - Padding value
     * @param {string} [options.minHeight] - Minimum height
     * @returns {HTMLElement} Framed box element
     */
    createFramedBox({ 
      background = "url('https://bestiaryarena.com/_next/static/media/background-regular.b0337118.png') repeat",
      borderImage = "url('https://bestiaryarena.com/_next/static/media/4-frame.a58d0c39.png') 6 fill stretch",
      padding = '2px 4px',
      minHeight = '80px'
    } = {}) {
      const frame = document.createElement('div');
      frame.style.cssText = `
        min-height: ${minHeight};
        padding: ${padding};
        width: 100%;
        box-sizing: border-box;
        background: ${background};
        border: 4px solid transparent;
        border-image: ${borderImage};
      `;
      return frame;
    },

    /**
     * Create a chat input textarea with auto-resize
     * @param {Function} onSend - Callback when message is sent
     * @param {Function} [onKeyDown] - Optional keydown handler
     * @returns {Object} Object with {textarea, sendButton, container}
     */
    createChatInput(onSend, onKeyDown = null) {
      const container = this.createRow('flex-start', '4px');
      
      const textarea = document.createElement('textarea');
      textarea.placeholder = 'Type your message...';
      textarea.style.cssText = `
        flex: 1;
        min-height: 27px;
        max-height: 100px;
        resize: none;
        padding: 4px 8px;
        font-size: 12px;
        font-family: inherit;
        background: url('https://bestiaryarena.com/_next/static/media/background-dark.95edca67.png') repeat;
        border: 2px solid transparent;
        border-image: url('https://bestiaryarena.com/_next/static/media/4-frame.a58d0c39.png') 6 fill stretch;
        color: rgb(230, 215, 176);
        overflow-y: auto;
      `;
      
      // Auto-resize textarea
      textarea.addEventListener('input', () => {
        textarea.style.height = '27px';
        textarea.style.height = `${Math.min(textarea.scrollHeight, 100)}px`;
      });
      
      // Handle Enter key (send) and Shift+Enter (new line)
      textarea.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          if (onSend) {
            onSend();
          }
        }
        if (onKeyDown) {
          onKeyDown(e);
        }
      });
      
      const sendButton = document.createElement('button');
      sendButton.textContent = 'Send';
      sendButton.className = 'pixel-font-14';
      sendButton.style.cssText = `
        padding: 4px 12px;
        height: 27px;
        font-size: 12px;
        background: url('https://bestiaryarena.com/_next/static/media/background-green.be515334.png') repeat;
        border: 2px solid transparent;
        border-image: url('https://bestiaryarena.com/_next/static/media/4-frame.a58d0c39.png') 6 fill stretch;
        color: rgb(230, 215, 176);
        cursor: pointer;
      `;
      
      sendButton.addEventListener('click', () => {
        if (onSend) {
          onSend();
        }
      });
      
      container.appendChild(textarea);
      container.appendChild(sendButton);
      
      return { textarea, sendButton, container };
    },

    /**
     * Close a modal dialog by finding and clicking the close button
     * @param {number} [delay=0] - Delay before closing (ms)
     */
    closeModal(delay = 0) {
      setTimeout(() => {
        const dialog = document.querySelector('div[role="dialog"][data-state="open"]');
        if (dialog) {
          const buttons = dialog.querySelectorAll('button');
          let closeButton = null;
          for (const btn of buttons) {
            if (btn.textContent && btn.textContent.trim().toLowerCase() === 'close') {
              closeButton = btn;
              break;
            }
          }
          
          if (closeButton) {
            closeButton.click();
          } else {
            // Fallback: dispatch ESC key events
            for (let i = 0; i < 3; i++) {
              setTimeout(() => {
                document.dispatchEvent(new KeyboardEvent('keydown', { 
                  key: 'Escape', 
                  keyCode: 27, 
                  which: 27, 
                  bubbles: true,
                  cancelable: true
                }));
              }, i * 50);
            }
          }
        }
      }, delay);
    },

    /**
     * Returns an onResponse callback that closes the modal after a farewell message.
     * @param {string} message - Player message text
     * @returns {Function|null}
     */
    getFarewellCloseCallback(message) {
      if (!isNpcFarewellMessage(message)) return null;
      return () => this.closeModal(NPC_MODAL_CLOSE_DELAY_MS);
    }
  };

  /**
   * Open a Quests-mod modal with standard timeout clearing, Escape handling,
   * dimension resolution, and responsive layout setup.
   * @param {Object} options
   * @param {string} options.title - Modal title
   * @param {HTMLElement} options.content - Modal content element
   * @param {number} options.maxWidth - Max width passed to dimension/layout helpers
   * @param {number} options.maxHeight - Max height passed to dimension/layout helpers
   * @param {number} options.minHeight - Min height passed to dimension/layout helpers
   * @param {Array} [options.buttons] - Modal footer buttons
   * @param {number} [options.delayMs=50] - Delay before creating the modal
   * @param {Function} [options.onAfterLayout] - Called with the dialog element after first layout
   * @param {Function} [options.onModalCreated] - Called with the modal ref immediately after creation
   * @param {boolean} [options.clearExistingEscapes=true] - Dispatch 2 Escape keydowns before opening
   */
  function openQuestsModal({
    title,
    content,
    maxWidth,
    maxHeight,
    minHeight,
    buttons = [],
    delayMs = 50,
    onAfterLayout = null,
    onModalCreated = null,
    clearExistingEscapes = true
  }) {
    clearTimeoutOrInterval(modalTimeout);
    clearTimeoutOrInterval(dialogTimeout);
    if (clearExistingEscapes) {
      for (let i = 0; i < 2; i++) {
        document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true }));
      }
    }

    function openNow() {
      const api = (typeof globalThis !== 'undefined' && globalThis.BestiaryModAPI)
        || (typeof window !== 'undefined' && window.BestiaryModAPI);
      if (api?.ui?.components?.createModal) {
        const dims = getQuestsModalDimensions(maxWidth, maxHeight, minHeight);
        const modal = api.ui.components.createModal({
          title,
          width: dims.width,
          height: dims.height,
          content,
          buttons
        });
        if (typeof onModalCreated === 'function') {
          onModalCreated(modal);
        }
        setupQuestsModalResponsiveLayout(
          modal,
          content,
          maxWidth,
          maxHeight,
          minHeight,
          (dialog) => {
            if (typeof onAfterLayout === 'function') onAfterLayout(dialog);
          }
        );
      }
    }

    if (delayMs === 0) {
      openNow();
      modalTimeout = null;
    } else {
      modalTimeout = setTimeout(() => {
        openNow();
        modalTimeout = null;
      }, delayMs);
    }
  }

  // Helper to remove event listener from button
  function removeButtonEventListener(button) {
    if (!button) return;
    const listener = buttonEventListeners.get(button);
    if (listener) {
      try {
        button.removeEventListener('click', listener);
      } catch (e) {
        // Silently ignore if button is already removed
      }
      buttonEventListeners.delete(button);
    }
  }

  // =======================
  // 5. DOM, Inventory & Buttons
  // =======================

  function observeInventory() {
    if (inventoryObserver) {
      try { inventoryObserver.disconnect(); } catch (e) {}
      inventoryObserver = null;
    }
    
    clearTimeoutOrInterval(buttonCheckInterval);
    clearTimeoutOrInterval(buttonRetryTimeout);
    clearTimeoutOrInterval(observerDebounceTimeout);
    buttonCheckInterval = null;
    buttonRetryTimeout = null;
    observerDebounceTimeout = null;

    // Keep a cheap poll while inventory can remount (React rebuilds wipe injected buttons).
    buttonCheckInterval = setInterval(() => {
      if (document.querySelector('.container-inventory-4')) {
        addQuestItemsButton();
      }
    }, BUTTON_CHECK_INTERVAL);
    
    inventoryObserver = new MutationObserver((mutations) => {
      let shouldCheck = false;
      for (const mutation of mutations) {
        for (const node of mutation.addedNodes) {
          if (inventoryNodeLooksRelevant(node)) {
            shouldCheck = true;
            break;
          }
        }
        if (shouldCheck) break;
        // Inventory rebuilds sometimes replace children without a fresh container node.
        if (
          mutation.target?.nodeType === Node.ELEMENT_NODE &&
          (mutation.target.classList?.contains('container-inventory-4') ||
            mutation.target.closest?.('.container-inventory-4'))
        ) {
          shouldCheck = true;
          break;
        }
      }

      if (!shouldCheck) return;

      if (observerDebounceTimeout) {
        clearTimeout(observerDebounceTimeout);
      }
      // Always re-scan current DOM — do not process the stale mutations snapshot.
      observerDebounceTimeout = setTimeout(() => {
        observerDebounceTimeout = null;
        scheduleQuestItemsButtonRetry();
      }, OBSERVER_DEBOUNCE_DELAY);
    });
    
    inventoryObserver.observe(document.body, { 
      childList: true, 
      subtree: true,
      attributes: false,
      characterData: false
    });
    
    addQuestItemsButton();
  }

  // Centralized cache clearing and button adding
  function clearCachesAndAddButton(retry = 0) {
    if (buttonRetryTimeout) {
      clearTimeout(buttonRetryTimeout);
      buttonRetryTimeout = null;
    }
    const added = addQuestItemsButton();
    if (!added && retry < BUTTON_RETRY_MAX) {
      buttonRetryTimeout = setTimeout(() => {
        clearCachesAndAddButton(retry + 1);
      }, BUTTON_RETRY_DELAY);
    }
  }

  // =======================
  // Button Management
  // =======================

  function removeQuestItemsButtonNode(button) {
    if (!button) return;
    try {
      removeButtonEventListener(button);
    } catch (_) {}
    try {
      if (button.isConnected) button.remove();
    } catch (_) {}
  }

  function ensureQuestItemsButtonListener(button) {
    if (!button || buttonEventListeners.has(button)) return;
    const clickHandler = () => {
      showQuestItemsModal();
    };
    button.addEventListener('click', clickHandler);
    buttonEventListeners.set(button, clickHandler);
  }

  function addQuestItemsButton() {
    // Clean up listeners for buttons React already removed
    for (const [button] of buttonEventListeners.entries()) {
      if (!document.contains(button)) {
        buttonEventListeners.delete(button);
      }
    }

    const inventoryContainer = document.querySelector('.container-inventory-4');
    if (!inventoryContainer) {
      // Drop orphan backpacks left behind from a previous inventory mount.
      document.querySelectorAll('.quest-items-inventory-button').forEach(removeQuestItemsButtonNode);
      return false;
    }

    const existingInContainer = inventoryContainer.querySelector('.quest-items-inventory-button');
    if (existingInContainer) {
      // Remove duplicates / orphans outside the live inventory grid
      document.querySelectorAll('.quest-items-inventory-button').forEach((btn) => {
        if (btn !== existingInContainer) removeQuestItemsButtonNode(btn);
      });
      ensureQuestItemsButtonListener(existingInContainer);
      failedAttempts = 0;
      return true;
    }

    // Orphan button still in DOM but not in the live inventory → remove and re-add below
    document.querySelectorAll('.quest-items-inventory-button').forEach(removeQuestItemsButtonNode);
    
    // Find the equipment container button
    const allButtons = Array.from(inventoryContainer.querySelectorAll('button.focus-style-visible.active\\:opacity-70'));
    const equipmentContainerButton = allButtons.find(button => {
      const equipmentImg = button.querySelector('img[alt="equipments"][src*="/assets/icons/equipment-container.png"]');
      return equipmentImg !== null && !button.classList.contains('quest-items-inventory-button');
    });

    if (!equipmentContainerButton) {
      failedAttempts++;
      return false;
    }

    // Check if equipment container button is still connected to DOM
    if (!isInDOM(equipmentContainerButton)) {
      return false;
    }
    
    const questItemsButton = document.createElement('button');
    questItemsButton.className = 'focus-style-visible active:opacity-70 quest-items-inventory-button';
    
    const inventoryBorderStyle = window.betterUIConfig?.inventoryBorderStyle || 'Original';
    const borderDiv = window.getInventoryBorderStyle ? window.getInventoryBorderStyle(inventoryBorderStyle) : '';
    
    questItemsButton.innerHTML = `
      <div data-hoverable="true" data-highlighted="false" data-disabled="false" class="container-slot surface-darker data-[disabled='true']:dithered data-[highlighted='true']:unset-border-image data-[hoverable='true']:hover:unset-border-image">
        <div class="relative grid h-full place-items-center">
          ${borderDiv}
          <div class="sprite item relative id-3253" style="width:32px;height:32px;overflow:hidden;"><div class="viewport" style="width:100%;height:100%;overflow:hidden;"><img alt="quest items" data-cropped="false" class="spritesheet" style="--cropX: 0; --cropY: 0;"></div></div>
        </div>
      </div>
    `;
    
    ensureQuestItemsButtonListener(questItemsButton);
    
    try {
      // Double-check target is still in DOM before inserting
      if (isInDOM(equipmentContainerButton) && inventoryContainer.contains(equipmentContainerButton)) {
        equipmentContainerButton.insertAdjacentElement('afterend', questItemsButton);
        failedAttempts = 0;
        // Do NOT clear the inventory poller here — React may remount the grid after we insert.
      } else {
        removeQuestItemsButtonNode(questItemsButton);
        return false;
      }
    } catch (error) {
      console.error('[Quests Mod] Error adding quest items button:', error);
      removeQuestItemsButtonNode(questItemsButton);
      return false;
    }
    
    return true;
  }

  // =======================
  // 6. NPC & King Modals
  // =======================

  function applyDialogStyles(dialog, width, height, contentRoot, minHeight) {
    applyQuestsModalLayoutToDialog(dialog, contentRoot, width, height, minHeight);
  }

  function createBox({title, content}) {
    const box = document.createElement('div');
    box.style.flex = '1 1 0';
    box.style.display = 'flex';
    box.style.flexDirection = 'column';
    box.style.margin = '0';
    box.style.padding = '0';
    box.style.minHeight = '0';
    box.style.height = '100%';
    box.style.background = "url('https://bestiaryarena.com/_next/static/media/background-dark.95edca67.png') repeat";
    box.style.border = '4px solid transparent';
    box.style.borderImage = `url("https://bestiaryarena.com/_next/static/media/4-frame.a58d0c39.png") 6 fill stretch`;
    box.style.borderRadius = '6px';
    box.style.overflow = 'hidden';
    
    const titleEl = document.createElement('h2');
    titleEl.className = 'widget-top widget-top-text pixel-font-16';
    titleEl.style.margin = '0';
    titleEl.style.padding = '2px 8px';
    titleEl.style.textAlign = 'center';
    titleEl.style.color = 'rgb(255, 255, 255)';
    
    const p = document.createElement('p');
    p.textContent = title;
    p.className = 'pixel-font-16';
    p.style.margin = '0';
    p.style.padding = '0';
    p.style.textAlign = 'center';
    p.style.color = 'rgb(255, 255, 255)';
    titleEl.appendChild(p);
    box.appendChild(titleEl);
    
    const contentWrapper = document.createElement('div');
    contentWrapper.className = 'column-content-wrapper';
    contentWrapper.style.flex = '1 1 0';
    contentWrapper.style.height = '100%';
    contentWrapper.style.minHeight = '0';
    contentWrapper.style.overflowY = 'auto';
    contentWrapper.style.display = 'flex';
    contentWrapper.style.flexDirection = 'column';
    contentWrapper.style.alignItems = 'stretch';
    contentWrapper.style.justifyContent = 'flex-start';
    contentWrapper.style.padding = '8px';
    
    if (typeof content === 'string') {
      contentWrapper.innerHTML = content;
    } else if (content instanceof HTMLElement) {
      contentWrapper.appendChild(content);
    }
    box.appendChild(contentWrapper);
    return box;
  }

  async function refreshQuestItemsModal() {
    // Only refresh when Quest Items is already open. Rebuild via showQuestItemsModal —
    // the old in-place rebuild dropped click handlers / Close wiring and left the UI inert.
    const titleEl = document.querySelector('div[role="dialog"][data-state="open"] h2.widget-top-text p');
    if (titleEl && titleEl.textContent === 'Quest Items') {
      showQuestItemsModal();
    }
  }

  async function showQuestItemsModal() {
    // Clear any pending modal timeouts
    clearTimeoutOrInterval(modalTimeout);
    clearTimeoutOrInterval(dialogTimeout);
    
    // Close any existing modals first (like Autoscroller does)
    for (let i = 0; i < 2; i++) {
      document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true }));
    }
    
    modalTimeout = setTimeout(async () => {
      const contentDiv = document.createElement('div');
      applyModalContentStyles(contentDiv, QUEST_ITEMS_MODAL_WIDTH, QUEST_ITEMS_MODAL_HEIGHT);
      
      // Show loading state
      const loadingDiv = document.createElement('div');
      loadingDiv.textContent = t('mods.quests.loading');
      loadingDiv.style.cssText = 'width: 100%; text-align: center; padding: 20px; color: rgb(230, 215, 176);';
      contentDiv.appendChild(loadingDiv);
      
      const questItemsDims = getQuestsModalDimensions(
        QUEST_ITEMS_MODAL_WIDTH,
        QUEST_ITEMS_MODAL_HEIGHT,
        QUESTS_MODAL_CONFIG.questItems.minHeight
      );
      const questItemsModal = api.ui.components.createModal({
        title: 'Quest Items',
        width: questItemsDims.width,
        height: questItemsDims.height,
        content: contentDiv,
        buttons: [{
          text: 'Close',
          primary: true,
          onClick: () => clearQuestsModalLayoutCleanup()
        }]
      });

      setupQuestsModalResponsiveLayout(
        questItemsModal,
        contentDiv,
        QUEST_ITEMS_MODAL_WIDTH,
        QUEST_ITEMS_MODAL_HEIGHT,
        QUESTS_MODAL_CONFIG.questItems.minHeight
      );
      
      // Fetch and display quest items (always fetch fresh from Firebase)
      try {
        // Clear cache before fetching to ensure we get the latest data
        clearQuestItemsCache();
          const products = await getQuestItems(false); // Force fresh fetch, don't use cache
          const hideCopperKey = await isCopperKeyMissionCompleted();
          const redDragonActive = await isRedDragonMissionActive();
          const redDragonCompleted = await isRedDragonMissionCompleted();
          const displayProducts = { ...products };
          console.log('[Quests Mod][Quest Items] Display products:', displayProducts);
          if (hideCopperKey) {
            delete displayProducts[COPPER_KEY_CONFIG.productName];
            delete displayProducts[MAP_COLOUR_CONFIG.productName];
          }
          // Obsidian Knife is now awarded when accepting the mission, so it will be in displayProducts if owned
          if (redDragonCompleted) {
            delete displayProducts['Red Dragon Leather'];
            delete displayProducts['Red Dragon Scale'];
            delete displayProducts['Obsidian Knife'];
          }
        
        // Clear loading message
        contentDiv.innerHTML = '';
        applyModalContentStyles(contentDiv, QUEST_ITEMS_MODAL_WIDTH, QUEST_ITEMS_MODAL_HEIGHT);
        
        // Build product definitions from configuration
          const productDefinitions = buildProductDefinitions({
            includeCopperKey: !hideCopperKey,
            includeObsidianKnife: redDragonActive,
            includeDragonClaw: redDragonCompleted || (displayProducts[getDragonClawProductName()] > 0)
          });
        const { soulCoreDefs, backpackDefs } = splitQuestItemDefinitions(productDefinitions);
        syncBosstiaryInDisplay(displayProducts);
        const bosstiaryDef = backpackDefs.find((def) => isBosstiaryProduct(def));
        
        // Left column: Product list container
        const productsListContainer = document.createElement('div');
        productsListContainer.style.cssText = `
          display: grid;
          grid-template-columns: repeat(auto-fill, 34px);
          gap: 2px;
          overflow-y: auto;
          overflow-x: hidden;
          height: 100%;
          align-content: start;
        `;
        
        // Right column: Product details container
        const detailsContainer = document.createElement('div');
        detailsContainer.style.cssText = `
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: flex-start;
          padding: 8px;
          overflow-y: auto;
          height: 100%;
        `;
        
        let selectedProduct = null;
        let selectedProductElement = null;
        let detailsBox = null;

        const setDetailsTitle = (title) => {
          const titleP = detailsBox?.querySelector('h2 p');
          if (titleP) titleP.textContent = title;
        };

        const showBosstiaryDetails = () => {
          renderBosstiaryDetails(detailsContainer, {
            bookDef: bosstiaryDef,
            soulCoreDefs,
            displayProducts,
            setTitle: setDetailsTitle
          });
        };
        
        // Function to show placeholder
        const showPlaceholder = () => {
          setDetailsTitle('Details');
          detailsContainer.innerHTML = '';
          
          // Icon and name in horizontal layout (same structure as selected product)
          const iconNameContainer = document.createElement('div');
          iconNameContainer.style.cssText = 'display: flex; align-items: center; gap: 8px; margin-bottom: 8px; width: 100%;';
          
          // Empty placeholder slot on the left
          const placeholderSlot = createEmptyPlaceholderSlot();
          iconNameContainer.appendChild(placeholderSlot);
          
          // Empty space on the right (to match layout)
          const emptySpace = document.createElement('div');
          emptySpace.style.cssText = 'flex: 1;';
          iconNameContainer.appendChild(emptySpace);
          
          detailsContainer.appendChild(iconNameContainer);
          detailsContainer.appendChild(createQuestItemDescFrame());
        };

        // Function to update details panel
        const updateDetailsPanel = (productDef) => {
          if (isBosstiaryProduct(productDef)) {
            showBosstiaryDetails();
            return;
          }
          setDetailsTitle('Details');
          const count = displayProducts[productDef.name] || 0;
          
          detailsContainer.innerHTML = '';
          
          // Icon and name in horizontal layout
          const iconNameContainer = document.createElement('div');
          iconNameContainer.style.cssText = 'display: flex; align-items: center; gap: 8px; margin-bottom: 8px; width: 100%;';

          // Make the container clickable for navigation if it's the map
          if (productDef.name === MAP_COLOUR_CONFIG.productName) {
            iconNameContainer.style.cursor = 'pointer';
            iconNameContainer.title = 'Click to navigate to the mines';

            // Add navigation function
            const navigateToMineHub = () => {
              const roomNames = globalThis.state?.utils?.ROOM_NAME;
              if (!roomNames) return false;

              // Try to find Mine Hub or Kazordoon in the room names
              const targetNames = ['Mine Hub', 'Kazordoon'];
              let targetRoomId = null;

              for (const targetName of targetNames) {
                for (const [roomId, displayName] of Object.entries(roomNames)) {
                  if (displayName === targetName) {
                    targetRoomId = roomId;
                    break;
                  }
                }
                if (targetRoomId) break;
              }

              if (targetRoomId && globalThis.state?.board) {
                // Close modal first by finding and clicking the close button
                const dialog = document.querySelector('div[role="dialog"][data-state="open"]');
                if (dialog) {
                  const closeButton = Array.from(dialog.querySelectorAll('button')).find(
                    btn => btn.textContent.trim() === 'Close'
                  );
                  if (closeButton) {
                    closeButton.click();
                  }
                }

                // Navigate after modal is closed
                setTimeout(() => {
                  globalThis.state.board.send({
                    type: 'selectRoomById',
                    roomId: targetRoomId
                  });

                  // Set floor to 0 after navigation
                  try {
                    globalThis.state.board.trigger.setState({ fn: (prev) => ({ ...prev, floor: 0 }) });
                  } catch (error) {
                    console.warn('[Quests Mod][Map Navigation] Error setting floor to 0:', error);
                  }

                  // Show navigation toast
                  NotificationService.showItemReceived(MAP_COLOUR_CONFIG.productName, '[Quests Mod][Map Navigation]', TOAST_MESSAGES.navigatedToMines);
                }, 200);

                return true;
              }
              return false;
            };

            iconNameContainer.addEventListener('click', (e) => {
              e.stopPropagation();
              navigateToMineHub();
            });
          }

          // Icon on the left
          const productSlot = createProductSlot(productDef, count, false, productDef.rarity != null ? productDef.rarity : 5);
          iconNameContainer.appendChild(productSlot);

          // Name on the right
          const nameDiv = document.createElement('div');
          nameDiv.textContent = productDef.name;
          nameDiv.style.cssText = 'font-size: 14px; font-weight: bold; color: rgb(230, 215, 176); flex: 1;';
          iconNameContainer.appendChild(nameDiv);

          detailsContainer.appendChild(iconNameContainer);
          
          // Description in frame
          const descFrame = createQuestItemDescFrame();
          const descDiv = document.createElement('div');
          if (productDef.name === (COSTELLO_QUEEN_BANSHEES_MISSION.diaryItemName || 'Costello\'s diary')
            || productDef.name === 'Castello\'s diary') {
            descDiv.style.cssText = 'font-size: 11px; font-style: italic; text-align: center;';
            SEVEN_SEALS_GHOSTLANDS_ROOM_NAMES.forEach((label, i) => {
              const done = getSealCompleted(i);
              const line = document.createElement('div');
              line.textContent = label;
              line.style.color = done ? '#4CAF50' : '#f44336';
              descDiv.appendChild(line);
            });
          } else {
            descDiv.textContent = productDef.description || '';
            descDiv.style.cssText = 'font-size: 11px; color: rgb(150, 150, 150); font-style: italic; text-align: center;';
            if (productDef.description && productDef.description.includes('\n')) {
              descDiv.style.whiteSpace = 'pre-line';
            }
          }
          descFrame.appendChild(descDiv);

          // Add toggle button for Fishing Rod or Light Shovel inside the description frame
          if (productDef.name === 'Fishing Rod' || productDef.name === 'Light Shovel') {
            // Create the toggle button
            const toggleButton = document.createElement('button');
            toggleButton.type = 'button';
            toggleButton.className = 'focus-style-visible flex items-center justify-center tracking-wide text-whiteRegular disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1 active:frame-pressed-1 surface-regular gap-1 px-3 py-1 pixel-font-12';
            toggleButton.style.cssText = 'cursor: pointer; white-space: nowrap; box-sizing: border-box; height: 28px; font-size: 12px; margin-top: 8px; display: block; margin-left: auto; margin-right: auto;';

            // Function to update button appearance based on state
            const updateButtonState = () => {
              const isEnabled = productDef.name === 'Fishing Rod' ? fishingState.enabled : miningState.enabled;
              const itemName = productDef.name === 'Fishing Rod' ? 'Fishing' : 'Shovel';

              if (isEnabled) {
                toggleButton.textContent = `${itemName} Enabled`;
                toggleButton.style.setProperty('background-image', 'url("https://bestiaryarena.com/_next/static/media/background-green.be515334.png")', 'important');
                toggleButton.style.setProperty('background-repeat', 'repeat', 'important');
                toggleButton.style.setProperty('border-color', '#4CAF50', 'important'); // Green border
              } else {
                toggleButton.textContent = `Enable ${itemName}`;
                toggleButton.style.setProperty('background-image', 'url("https://bestiaryarena.com/_next/static/media/background-red.21d3f4bd.png")', 'important');
                toggleButton.style.setProperty('background-repeat', 'repeat', 'important');
                toggleButton.style.setProperty('border-color', '#f44336', 'important'); // Red border
              }
            };

            // Initialize button state
            updateButtonState();

            // Add click handler to toggle
            toggleButton.addEventListener('click', () => {
              let toastMessage = null;
              if (productDef.name === 'Fishing Rod') {
                fishingState.enabled = !fishingState.enabled;
                fishingState.manuallyDisabled = !fishingState.enabled;
                updateButtonState();
                updateWaterFishingState(true);
                toastMessage = fishingState.enabled ? TOAST_MESSAGES.fishingEnabled : TOAST_MESSAGES.fishingDisabled;
              } else if (productDef.name === 'Light Shovel') {
                miningState.enabled = !miningState.enabled;
                miningState.manuallyDisabled = !miningState.enabled;
                updateButtonState();
                updateMiningState(true);
                // Tile highlights otherwise only refresh on the next board-state change
                // or game-timer tick, so toggling the shovel while already standing on
                // the diggable tile wouldn't show the "Dig" highlight until one of those
                // happened to fire. Refresh immediately so it appears right away.
                if (typeof refreshQuestTileHighlights === 'function') {
                  refreshQuestTileHighlights();
                }
                toastMessage = miningState.enabled ? TOAST_MESSAGES.shovelEnabled : TOAST_MESSAGES.shovelDisabled;
              }

              if (toastMessage) {
                showToast({ message: toastMessage, logPrefix: '[Quests Mod][Tools]' });
              }
            });

            // Add the button to the description frame
            descFrame.appendChild(toggleButton);
          }

          if (productDef.name === PRESENT_CONFIG.productName) {
            const openButton = document.createElement('button');
            openButton.type = 'button';
            openButton.className = 'focus-style-visible flex items-center justify-center tracking-wide text-whiteRegular disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1 active:frame-pressed-1 surface-regular gap-1 px-3 py-1 pixel-font-12';
            openButton.style.cssText = 'cursor: pointer; white-space: nowrap; box-sizing: border-box; height: 28px; font-size: 12px; margin-top: 8px; display: block; margin-left: auto; margin-right: auto;';
            openButton.textContent = 'Open Present';
            openButton.style.setProperty('background-image', 'url("https://bestiaryarena.com/_next/static/media/background-red.21d3f4bd.png")', 'important');
            openButton.style.setProperty('background-repeat', 'repeat', 'important');
            openButton.style.setProperty('border-color', '#f44336', 'important');
            openButton.addEventListener('click', async () => {
              openButton.disabled = true;
              try {
                await openPresentFromInventory();
              } catch (error) {
                console.error('[Quests Mod][Present] Error opening present:', error);
                openButton.disabled = false;
              }
            });
            descFrame.appendChild(openButton);
          }

          // Drop chance removed from display
          detailsContainer.appendChild(descFrame);
        };
        
        const renderProductGrid = () => {
          productsListContainer.innerHTML = '';
          selectedProduct = null;
          selectedProductElement = null;

          for (const productDef of backpackDefs) {
            const count = displayProducts[productDef.name] || 0;
            if (count <= 0) continue;

            const { productItem, containerSlot } = createQuestItemSlotButton(productDef, count);

            productItem.addEventListener('click', () => {
              if (selectedProductElement === productItem) {
                setQuestItemSlotHighlighted(containerSlot, false);
                selectedProduct = null;
                selectedProductElement = null;
                showPlaceholder();
                return;
              }

              if (selectedProductElement) {
                setQuestItemSlotHighlighted(selectedProductElement.querySelector('[data-highlighted]'), false);
              }

              selectedProduct = productDef;
              selectedProductElement = productItem;
              setQuestItemSlotHighlighted(containerSlot, true);
              updateDetailsPanel(productDef);
            });

            productItem.addEventListener('mouseenter', () => {
              if (productItem !== selectedProductElement) {
                containerSlot.setAttribute('data-hoverable', 'true');
              }
            });

            productsListContainer.appendChild(productItem);
          }
        };

        const productsBox = createBox({
          title: 'Quest Items',
          content: productsListContainer
        });
        productsBox.style.width = '180px';
        productsBox.style.flexShrink = '0';

        detailsBox = createBox({
          title: 'Details',
          content: detailsContainer
        });
        detailsBox.style.width = '280px';
        detailsBox.style.flexShrink = '0';

        contentDiv.appendChild(productsBox);
        contentDiv.appendChild(detailsBox);

        renderProductGrid();
        showPlaceholder();
        
      } catch (error) {
        console.error('[Quests Mod] Error loading quest items:', error);
        contentDiv.innerHTML = '';
        const errorBox = createBox({
          title: 'Quest Items',
          content: `<div style="text-align: center; padding: 20px; color: rgb(255, 100, 100);">${t('mods.quests.errorLoading')}</div>`
        });
        errorBox.style.width = '100%';
        contentDiv.appendChild(errorBox);
      }
      
      modalTimeout = null;
    }, 50);
  }

  // =======================
  // King Tibianus Modal
  // =======================

  // King keyword lines load from npcs.json; only the dynamic iron ore handler stays here.
  const KING_TIBIANUS_RESPONSES = {
    'iron ore': async () => {
    try {
      const currentPlayer = getCurrentPlayerName();
      if (!currentPlayer) {
        return getKingIronOreLine('default', 'Yes.. Iron Ore! Let me know if you find one!');
      }

      const currentProducts = await getQuestItems(false);
      const ironOreCount = currentProducts['Iron Ore'] || 0;

      // Check if Al Dee fishing mission is completed - if so, Iron Ore quests shouldn't be claimable
      if (kingChatState.progressAlDeeFishing.completed || fishingState.ironOreQuestCompleted) {
        try {
          await consumeAllOfQuestItem('Iron Ore');
          await refreshQuestItemsModal();
        } catch (err) {
          console.error('[Quests Mod][King Tibianus] Error removing leftover Iron Ore:', err);
        }
        return getKingIronOreLine('missionConcluded', 'I appreciate your continued interest, but our business with iron ore is concluded.');
      }

      // Check if quest timer has expired and reward is ready to be claimed
      if (fishingState.ironOreQuestExpired && !fishingState.ironOreQuestCompleted) {
        // Quest timer expired - award Magnet reward now that player is talking to us
        console.log('[Quests Mod][King Tibianus] Awarding Magnet reward for expired Iron Ore quest');
        try {
          console.log('[Quests Mod][King Tibianus] Calling addQuestItem for Magnet...');
          const result = await addQuestItem('Magnet', 1);
          console.log('[Quests Mod][King Tibianus] addQuestItem result:', result);
          showQuestItemNotification('Magnet', 1);
          fishingState.ironOreQuestExpired = false;
          fishingState.ironOreQuestCompleted = true;
          console.log('[Quests Mod][King Tibianus] Magnet reward awarded successfully');

          // Refresh quest items modal if it's open
          setTimeout(() => {
            refreshQuestItemsModal();
            console.log('[Quests Mod][King Tibianus] Refreshed quest items modal');
          }, 500);

          // Save completed quest progress to Firebase (merge preserves other missions)
          const currentPlayer = getCurrentPlayerName();
          if (currentPlayer) {
            await saveKingTibianusProgress(currentPlayer, {
              ironOre: {
                active: false,
                startTime: null,
                completed: true
              }
            });
          }

          await cleanupInvalidQuestItems(getAllMissionProgress());

          return getKingIronOreLine('rewardGiven', 'Thank you for giving me an Iron Ore! Here\'s a small gift for you.');
        } catch (err) {
          console.error('[Quests Mod][King Tibianus] Error awarding Magnet:', err);
          return getKingIronOreLine('rewardGiven', 'Thank you for giving me an Iron Ore! Here\'s a small gift for you.');
        }
      }

      // Check if quest is active and timer is still running
      if (fishingState.ironOreQuestActive && fishingState.ironOreQuestStartTime) {
        // Quest active but timer not expired
        return getKingIronOreLine('comeBackLater', 'Come back in a minute.');
      }

      // Check inventory for Iron Ore - this takes precedence over completion status
      if (ironOreCount > 0) {
        // Check if Al Dee fishing mission is active and not completed - only take Iron Ore if mission is accepted but not finished
        if (!kingChatState.progressAlDeeFishing.accepted) {
          return getKingIronOreLine('fineRockNoMission', 'That\'s a fine looking rock you have there.');
        }
        if (kingChatState.progressAlDeeFishing.completed) {
          // Business concluded — strip leftover ore so it cannot be turned in again.
          try {
            await consumeAllOfQuestItem('Iron Ore');
            await refreshQuestItemsModal();
          } catch (err) {
            console.error('[Quests Mod][King Tibianus] Error removing leftover Iron Ore:', err);
          }
          return getKingIronOreLine('fineRockMissionDone', 'I appreciate the rock, but I have no further use for iron ore now that our business is concluded.');
        }

        // Player has Iron Ore and mission is active - take it and start timer
        try {
          await consumeQuestItem('Iron Ore', 1);
          fishingState.ironOreQuestActive = true;
          fishingState.ironOreQuestExpired = false; // Reset expired flag when starting new quest
          fishingState.ironOreQuestStartTime = Date.now();

          // Save quest progress to Firebase (merge preserves other missions)
          await saveKingTibianusProgress(currentPlayer, {
            ironOre: {
              active: true,
              startTime: fishingState.ironOreQuestStartTime,
              completed: false
            }
          });

          return getKingIronOreLine('oreAccepted', 'Thank you! I\'ll give this to my guard... come back in a minute and I\'ll have something for you.');
        } catch (err) {
          console.error('[Quests Mod][King Tibianus] Error consuming Iron Ore:', err);
          return getKingIronOreLine('default', 'Yes.. Iron Ore! Let me know if you find one!');
        }
      } else {
        // Player has no Iron Ore - check if quest was ever completed
        if (fishingState.ironOreQuestCompleted) {
          return getKingIronOreLine('repeatThankYou', 'Another thank you for this ore, hope you enjoy the small gift I gave you!');
        } else {
          return getKingIronOreLine('default', 'Yes.. Iron Ore! Let me know if you find one!');
        }
      }
    } catch (err) {
      console.error('[Quests Mod][King Tibianus] Error in iron ore response:', err);
      return getKingIronOreLine('default', 'Yes.. Iron Ore! Let me know if you find one!');
    }
  }
  };

  async function getKingTibianusResponse(message, playerName = 'Player') {
    const kingResponses = {
      ...KING_TIBIANUS_RESPONSES,
      ...getKingTibianusKeywordResponses()
    };
    return matchKeywordResponses(kingResponses, message, playerName, {
      defaultResponse: null,
      resolveAsync: true,
      lowercaseKeys: true,
      asyncErrorFallback: 'I greet thee, my loyal subject Player.'
    });
  }

  async function showKingTibianusModal() {
    await ensureQuestDialogueLoaded();
    // Clear any pending modal timeouts
    clearTimeoutOrInterval(modalTimeout);
    clearTimeoutOrInterval(dialogTimeout);

    // Fresh modal = fresh conversation; drop stale yes/no or accept prompts
    kingChatState.awaitingKeyConfirm = false;
    kingChatState.missionOffered = false;
    kingChatState.offeredMission = null;
    let awaitingLostOracleOrbConfirm = false;
    let awaitingIsleConfirm = false; // Isle of Solitude easter egg — pending "yes" to teleport
    
    // Close any existing modals first (like Autoscroller does)
    for (let i = 0; i < 2; i++) {
      document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true }));
    }
    
    modalTimeout = setTimeout(() => {
      const contentDiv = document.createElement('div');
      applyModalContentStyles(contentDiv, KING_TIBI_MODAL_WIDTH, KING_TIBI_MODAL_HEIGHT);
      contentDiv.classList.add('quests-king-chat-content');
      
      const kingTibianusIconUrl = getQuestItemsAssetUrl('King_Tibianus.gif');
      
      // Create modal content with 3 rows
      const modalContent = document.createElement('div');
      modalContent.className = 'quests-king-chat-body';
      modalContent.style.cssText = 'display: flex; flex-direction: column; gap: 12px; padding: 0; width: 100%; min-width: 0; height: 100%; box-sizing: border-box;';
      
      // Row 1: Top row with image and message
      const row1 = document.createElement('div');
      row1.className = 'quests-king-chat-row';
      row1.style.cssText = 'display: flex; flex-direction: row; align-items: stretch; width: 100%; min-width: 0; gap: 12px; align-self: stretch;';
      
      const imageContainer = document.createElement('div');
      imageContainer.className = 'container-slot surface-darker grid place-items-center overflow-hidden quests-king-chat-image';
      imageContainer.style.cssText = 'width: 110px; min-width: 110px; max-width: 110px; flex: 0 0 110px; height: 90px; padding: 0; align-self: stretch;';
      
      const kingImgWrapper = document.createElement('div');
      kingImgWrapper.style.cssText = 'width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; padding: 0; box-sizing: border-box;';
      
      const kingImg = document.createElement('img');
      kingImg.src = kingTibianusIconUrl;
      kingImg.alt = 'King Tibianus';
      kingImg.className = 'pixelated';
      kingImg.style.cssText = 'width: 106px; height: 64px; object-fit: contain; image-rendering: pixelated;';
      kingImgWrapper.appendChild(kingImg);
      imageContainer.appendChild(kingImgWrapper);
      
      const messageContainer = document.createElement('div');
      messageContainer.className = 'tooltip-prose pixel-font-16 frame-pressed-1 surface-dark flex w-full flex-col gap-1 p-2 text-whiteRegular quests-king-chat-messages';
      messageContainer.style.cssText = 'flex: 1 1 0; min-width: 0; width: auto; height: 90px; max-height: 90px; overflow-y: auto; box-sizing: border-box;';
      messageContainer.id = 'king-tibianus-messages';
      
      // Function to add message to conversation
      let pendingKingChunkTimeouts = [];
      function addMessageToConversation(sender, text, isKing = false, noChunk = false) {
        const appendOne = (chunkText) => {
          const messageP = document.createElement('p');
          messageP.className = 'inline text-monster';
          // King Tibianus messages use the same style as initial greeting;
          // player messages use a lavender/purple color instead.
          messageP.style.color = isKing ? 'rgb(135, 206, 250)' : 'rgb(200, 180, 255)';
          messageP.textContent = sender + ': ' + chunkText;

          messageContainer.appendChild(messageP);

          // Scroll to bottom
          setTimeout(() => {
            messageContainer.scrollTop = messageContainer.scrollHeight;
          }, 0);
        };

        // A newer message (the player's reply, or the next queued NPC line) supersedes
        // whatever this modal was still mid-way through printing — cancel any chunk of
        // a previous long message that hasn't appeared yet, so it can't land in the
        // transcript after a reply that already moved the conversation past it.
        pendingKingChunkTimeouts.forEach((id) => clearTimeout(id));
        pendingKingChunkTimeouts = [];

        if (isKing && !noChunk) {
          pendingKingChunkTimeouts = scheduleChunkedDialogue(appendOne, text);
        } else {
          appendOne(text);
        }
      }

      // Grey, italic hint line — distinct from King/player dialogue —
      // used when the King is deliberately not responding (e.g. awaiting a proper greeting).
      function addHintToConversation(text) {
        const hintP = document.createElement('p');
        hintP.className = 'inline text-monster';
        hintP.style.cssText = 'color: rgb(150, 150, 150); font-style: italic;';
        hintP.textContent = text;

        messageContainer.appendChild(hintP);

        setTimeout(() => {
          messageContainer.scrollTop = messageContainer.scrollHeight;
        }, 0);
      }

      // If the starter coin was already spent (no token in inventory), greet normally
      (async () => {
        try {
          const hasToken = await hasSilverToken();
          if (!hasToken) {
            addMessageToConversation('King Tibianus', applyPlayerNameSubstitution('I greet thee, my loyal subject Player.'), true, true);
          }
        } catch (err) {
          console.warn('[Quests Mod] Could not check token for initial greeting:', err);
          addMessageToConversation('King Tibianus', applyPlayerNameSubstitution('I greet thee, my loyal subject Player.'), true);
        }
      })();
      
      row1.appendChild(imageContainer);
      row1.appendChild(messageContainer);
      
      // Row 2: Middle row split into 2 columns
      const row2 = document.createElement('div');
      row2.className = 'quests-king-chat-main';
      row2.style.cssText = 'width: 100%; max-width: 100%; min-width: 0; height: 300px; display: flex; gap: 12px; margin: auto 0; align-self: stretch; box-sizing: border-box;';
      
      // Column 1: First column (150px wide) using same background/frame as row1
      const col1 = document.createElement('div');
      col1.style.cssText = `
        width: 170px;
        min-width: 170px;
        max-width: 170px;
        height: 100%;
        display: flex;
        flex-direction: column;
        gap: 8px;
        box-sizing: border-box;
      `;
      
      // Column 2: Plain container (Mission Log will provide its own frame)
      const col2 = document.createElement('div');
      col2.style.cssText = `
        flex: 1;
        height: 100%;
        display: flex;
        flex-direction: column;
        gap: 0;
        padding: 0;
        box-sizing: border-box;
      `;
      
      row2.appendChild(col1);
      row2.appendChild(col2);

      function setRow2Disabled(disabled) {
        if (!row2) return;
        row2.style.pointerEvents = disabled ? 'none' : 'auto';
        row2.style.filter = disabled ? 'grayscale(1) brightness(0.6)' : 'none';
        row2.style.opacity = disabled ? '0.6' : '1';
      }

      // kingChatState is now defined globally
      // All missions (Al Dee missions are shown but can only be accepted through Al Dee). Order = QUEST_LOG_MISSIONS.
      const MISSIONS = QUEST_LOG_MISSIONS;

      // Uses module Mission Registry MISSION_STATE_MAP / MISSION_FIREBASE_KEY_MAP

      // Random responses when Tibianus doesn't understand the player's input
      function getRandomConfusionResponse() {
        return getRandomNpcConfusionResponse(KING_TIBIANUS_CONFUSION_RESPONSES, getCurrentPlayerName() || 'Player');
      }

      function getMissionById(id) {
        return MISSIONS.find(m => m.id === id);
      }

      // getMissionProgress and setMissionProgress are defined globally for Tile 79 functionality

      function getKingMissionChain() {
        const hasHolyTible = (cachedQuestItems && (cachedQuestItems['The Holy Tible'] || 0) > 0);
        const kingMissions = [KING_COPPER_KEY_MISSION, KING_RED_DRAGON_MISSION, KING_LETTER_MISSION];
        if (hasHolyTible) kingMissions.push(KING_MONKS_STUDY_MISSION);
        kingMissions.push(KING_SCARAB_COIN_MISSION);
        return kingMissions;
      }

      function getHoneyflowerMissionProgress() {
        return getMissionProgress(KING_HONEYFLOWER_MISSION);
      }

      function canOfferHoneyflowerMission() {
        return !getHoneyflowerMissionProgress().completed;
      }

      function getCrossingTheLineMissionProgress() {
        return getMissionProgress(KING_CROSSING_THE_LINE_MISSION);
      }

      function canOfferCrossingTheLineMission() {
        return getHoneyflowerMissionProgress().completed && !getCrossingTheLineMissionProgress().completed;
      }

      function canOfferCopperKeyMission() {
        const progress = getMissionProgress(KING_COPPER_KEY_MISSION);
        if (progress.completed || progress.accepted) return false;
        return isMineHubUnlocked();
      }

      function hasHoneyflowerInInventory() {
        return (cachedQuestItems?.[HONEYFLOWER_CONFIG.productName] || 0) > 0;
      }

      function getKingMissionKeywordCandidates() {
        return [
          KING_HONEYFLOWER_MISSION,
          KING_CROSSING_THE_LINE_MISSION,
          ...getKingMissionChain()
        ];
      }

      function getActiveKingMissions() {
        return getKingMissionKeywordCandidates().filter((mission) => {
          const progress = getMissionProgress(mission);
          return !!progress.accepted && !progress.completed;
        });
      }

      async function isKingMissionReadyForHandIn(mission) {
        if (!mission) return false;
        const progress = getMissionProgress(mission);
        if (!progress.accepted || progress.completed) return false;

        if (mission.id === KING_COPPER_KEY_MISSION.id) {
          return await hasCopperKeyInInventory();
        }
        if (mission.id === KING_HONEYFLOWER_MISSION.id) {
          return hasHoneyflowerInInventory();
        }
        if (mission.id === KING_CROSSING_THE_LINE_MISSION.id) {
          return hasCrossingTheLineObjectiveComplete();
        }
        if (mission.id === KING_RED_DRAGON_MISSION.id) {
          return await hasRedDragonMaterials();
        }
        if (mission.id === KING_SCARAB_COIN_MISSION.id) {
          return await hasScarabCoinInInventory();
        }
        if (mission.id === KING_MONKS_STUDY_MISSION.id) {
          return !!kingChatState.costelloVisited;
        }
        return false;
      }

      function canKingStampAlDeeLetter(products = cachedQuestItems) {
        const letterProgress = getMissionProgress(KING_LETTER_MISSION);
        if (!letterProgress.accepted || letterProgress.completed) return false;
        const { letterCount, stampedLetterCount } = getLetterMissionItemCounts(products);
        return letterCount > 0 && stampedLetterCount === 0;
      }

      // Mid-mission step (stamp) or hand-in ready — used by "mission" / topic keywords.
      async function getKingMissionProgressKind(mission) {
        if (!mission) return null;
        const progress = getMissionProgress(mission);
        if (!progress.accepted || progress.completed) return null;

        if (mission.id === KING_LETTER_MISSION.id) {
          try {
            const products = await getQuestItems(false);
            if (canKingStampAlDeeLetter(products)) return 'stamp-letter';
          } catch (error) {
            console.error('[Quests Mod][King Tibianus] Error checking letter for progress:', error);
          }
          return null;
        }

        if (await isKingMissionReadyForHandIn(mission)) return 'hand-in';
        return null;
      }

      // hasKingTibianusQuestAction() is defined at module scope (shared with the Quest Log tab badge).
      async function refreshKingTibianusPendingBadge() {
        try {
          const isPending = await hasKingTibianusQuestAction();
          setNpcModalPendingBadge(imageContainer, isPending);
        } catch (error) {
          console.error('[Quests Mod][King Tibianus] Error refreshing pending quest badge:', error);
        }
      }

      async function stampAlDeeLetterForKing(reason = 'stamp Letter from Al Dee') {
        const playerName = getCurrentPlayerName();
        if (!playerName) return false;

        const currentProducts = await getQuestItems(false);
        if (!canKingStampAlDeeLetter(currentProducts)) return false;

        const { letterCount } = getLetterMissionItemCounts(currentProducts);
        const updatedProducts = {
          ...currentProducts,
          'Letter from Al Dee': Math.max(0, letterCount - 1),
          'Stamped Letter': (currentProducts['Stamped Letter'] || 0) + 1
        };

        const encrypted = await encryptQuestItems(updatedProducts, playerName);
        const hashedPlayer = await hashUsername(playerName);
        await FirebaseService.put(
          `${getQuestItemsApiUrl()}/${hashedPlayer}`,
          { encrypted },
          reason
        );

        cachedQuestItems = updatedProducts;
        NotificationService.showItemReceived('Stamped Letter', '[Quests Mod][King Tibianus]');
        console.log('[Quests Mod][King Tibianus] Exchanged Letter from Al Dee for Stamped Letter');

        if (typeof updateTile79RightClickState === 'function') {
          updateTile79RightClickState();
        }
        refreshBoardNpcsAfterQuestItemsChange();
        renderKingQuestUI();
        return true;
      }

      // Returns true if the king already replied / advanced the mission.
      async function tryProgressKingMission(mission) {
        const kind = await getKingMissionProgressKind(mission);
        if (!kind) return false;

        if (kind === 'stamp-letter') {
          try {
            const stamped = await stampAlDeeLetterForKing('exchange Letter from Al Dee for Stamped Letter (mission progress)');
            if (!stamped) return false;
            const stampMsg = KING_LETTER_MISSION.stampLetter
              || 'Ah, you found the letter! I\'ve stamped it for you. Now take it to Al Dee in Rookgaard.';
            queueKingReply(stampMsg, { onDone: () => { clearTextarea(); } });
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
            kingChatState.awaitingKeyConfirm = false;
            return true;
          } catch (error) {
            console.error('[Quests Mod][King Tibianus] Error stamping letter:', error);
            return false;
          }
        }

        if (kind === 'hand-in') {
          setKingAwaitingKeyConfirm(mission);
          queueKingReply(buildStrings(mission).keyQuestion);
          clearTextarea();
          return true;
        }

        return false;
      }

      async function tryProgressAnyActiveKingMission() {
        for (const mission of getActiveKingMissions()) {
          if (await tryProgressKingMission(mission)) return true;
        }
        return false;
      }

      async function findProgressableActiveKingMission() {
        for (const mission of getActiveKingMissions()) {
          if (await getKingMissionProgressKind(mission)) {
            return mission;
          }
        }
        return null;
      }

      function areAllMissionsCompleted() {
        return getKingMissionChain().every(mission => getMissionProgress(mission).completed);
      }

      function currentMission() {
        for (const mission of getKingMissionChain()) {
          if (!getMissionProgress(mission).completed) {
            return mission;
          }
        }
        return null;
      }

      let activeMission = currentMission();
      let selectedMissionId = null; // none selected by default
      let kingMissionListTab = 'missions';
      const kingMissionListScrollTops = { missions: 0, completed: 0 };
      let kingQuestDetailsVisible = false;
      let kingQuestDescEl = null;
      let kingQuestDescBody = null;
      let customFooter = null;
      let customSeparator = null;
      let modalRef = null;

      // Create cooldown manager for Tibianus conversation
      const tibianusCooldown = createNPCCooldownManager();

      function buildStrings(mission) {
        // Handle case where all missions are completed (mission is null)
        if (!mission) {
          return {
            missionPrompt: 'All missions have been completed. Come back later for more tasks.',
            thankYou: 'All missions have been completed.',
            keyQuestion: 'All missions have been completed.',
            keyComplete: 'All missions have been completed.',
            keyScoldNoKey: 'All missions have been completed.',
            keyKeepSearching: 'All missions have been completed.',
            keyAnswerYesNo: 'All missions have been completed.',
            missionCompleted: 'All missions have been completed.',
            missionActive: 'All missions have been completed.'
          };
        }

        return {
          missionPrompt: mission.prompt,
          missionPromptWithLetter: mission.promptWithLetter || mission.prompt,
          thankYou: mission.accept,
          thankYouNoLetter: mission.acceptNoLetter || mission.accept,
          keyQuestion: mission.askForKey || mission.askForItems || mission.askForItem || mission.askForLetter || 'Have you found what I asked for?',
          keyComplete: getMissionCompleteLine(mission),
          keyScoldNoKey: mission.missingKey || mission.missingItems || mission.missingItem || mission.missingLetter || 'You claim yes but lack what I asked for.',
          keyKeepSearching: mission.keepSearching,
          keyAnswerYesNo: mission.answerYesNo,
          missionCompleted: mission.alreadyCompleted,
          missionActive: mission.id === KING_LETTER_MISSION.id
            ? getLetterMissionAlreadyActiveReply(mission)
            : mission.alreadyActive
        };
      }
      let kingStrings = buildStrings(activeMission);
      let kingModalProgressLoading = false;

      function closeDialogWithFallback(delayMs = 0) {
        ModalHelpers.closeModal(delayMs);
      }

      function removeDefaultModalFooter(dialog) {
        try {
          if (!dialog) return;
          const separators = dialog.querySelectorAll('.separator');
          separators.forEach(el => {
            if (el !== customSeparator) {
              el.remove();
            }
          });
          const buttonRows = dialog.querySelectorAll('.flex.justify-end.gap-2');
          buttonRows.forEach(row => {
            if (row !== customFooter && !row.querySelector('.guild-coins-display')) {
              row.remove();
            }
          });
        } catch (error) {
          console.warn('[Quests Mod][King Tibianus] Could not remove default modal footer:', error);
        }
      }

      function queueKingReply(text, { onDone = null, closeAfterMs = null } = {}) {
        setTimeout(() => {
          addMessageToConversation('King Tibianus', text, true);
          if (onDone) onDone();
          if (typeof closeAfterMs === 'number') {
            closeDialogWithFallback(closeAfterMs);
          }
        }, 1000);
      }

      async function awardGuildCoins(amount) {
        try {
          const coinsAdder =
            globalThis.addGuildCoins ||
            (globalThis.Guilds && globalThis.Guilds.addGuildCoins) ||
            (globalThis.BestiaryModAPI &&
             globalThis.BestiaryModAPI.guilds &&
             globalThis.BestiaryModAPI.guilds.addGuildCoins) ||
            (typeof addGuildCoins === 'function' ? addGuildCoins : null);

          if (!coinsAdder) {
            console.warn('[Quests Mod][King Tibianus] addGuildCoins not available, skipping guild coin reward');
            return;
          }

          await coinsAdder(amount);
          console.log('[Quests Mod][King Tibianus] Awarded guild coins:', amount);
        } catch (error) {
          console.error('[Quests Mod][King Tibianus] Error awarding guild coins:', error);
        }
      }

      // Guild coin display
      const guildCoinIconUrl = cachedExtensionBaseUrl ? constructUrl(cachedExtensionBaseUrl, '/assets/ot/Guild_Coin.png') : '/assets/ot/Guild_Coin.png';
      let guildCoinAmountSpan = null;

      async function updateGuildCoinDisplay() {
        if (!guildCoinAmountSpan) return;
        guildCoinAmountSpan.textContent = '...';
        try {
          const coinsGetter =
            globalThis.getGuildCoins ||
            (globalThis.Guilds && globalThis.Guilds.getGuildCoins) ||
            (globalThis.BestiaryModAPI &&
             globalThis.BestiaryModAPI.guilds &&
             globalThis.BestiaryModAPI.guilds.getGuildCoins) ||
            (typeof getGuildCoins === 'function' ? getGuildCoins : null);
          if (!coinsGetter) {
            console.error('[Quests Mod][King Tibianus] getGuildCoins not available; cannot show guild coins.');
            guildCoinAmountSpan.textContent = '?';
            return;
          }
          const amount = await coinsGetter();
          guildCoinAmountSpan.textContent = Number.isFinite(amount) ? amount.toLocaleString('en-US') : '?';
        } catch (error) {
          console.error('[Quests Mod][King Tibianus] Error updating guild coins display:', error);
          guildCoinAmountSpan.textContent = '?';
        }
      }

      function renderKingQuestUI() {
        if (!col1 || !col2) return;

        refreshKingTibianusPendingBadge();

        const existingMissionListScroll = col1.querySelector('.king-mission-list-scroll-body');
        if (existingMissionListScroll) {
          kingMissionListScrollTops[kingMissionListTab] = existingMissionListScroll.scrollTop;
        }

        col1.innerHTML = '';
        col2.innerHTML = '';

        const missionStates = MISSIONS.map(mission => ({
          mission,
          progress: getMissionProgress(mission)
        }));

        // Keep selection valid; allow no selection (null)
        const selectedMission = selectedMissionId ? getMissionById(selectedMissionId) : null;
        const selectedProgress = selectedMission ? getMissionProgress(selectedMission) : { accepted: false, completed: false };

        const handleMissionClick = (missionId) => {
          if (selectedMissionId === missionId) {
            // Deselect
            selectedMissionId = null;
            kingQuestDetailsVisible = false;
          } else {
            kingQuestDetailsVisible = true;
            selectedMissionId = missionId;
          }
          renderKingQuestUI();
        };

        function createFramedBox(titleText, bodyContent) {
          const box = document.createElement('div');
          box.style.display = 'flex';
          box.style.flexDirection = 'column';
          box.style.margin = '0';
          box.style.padding = '0';
          box.style.minHeight = '0';
          box.style.height = '100%';
          box.style.background = 'url("https://bestiaryarena.com/_next/static/media/background-dark.95edca67.png") repeat';
          box.style.border = '4px solid transparent';
          box.style.borderImage = 'url("https://bestiaryarena.com/_next/static/media/4-frame.a58d0c39.png") 6 fill stretch';
          box.style.borderRadius = '6px';
          box.style.overflow = 'hidden';

          const header = document.createElement('h2');
          header.className = 'widget-top widget-top-text pixel-font-16';
          header.style.margin = '0';
          header.style.padding = '2px 8px';
          header.style.textAlign = 'center';
          header.style.color = 'rgb(255, 255, 255)';
          const p = document.createElement('p');
          p.className = 'pixel-font-16';
          p.style.margin = '0';
          p.style.padding = '0';
          p.style.textAlign = 'center';
          p.style.color = 'rgb(255, 255, 255)';
          p.textContent = titleText;
          header.appendChild(p);
          box.appendChild(header);

          const body = document.createElement('div');
          body.style.flex = '1 1 0';
          body.style.minHeight = '0';
          body.style.overflowY = 'auto';
          body.style.padding = '8px';
          if (bodyContent instanceof HTMLElement) {
            body.appendChild(bodyContent);
          }
          box.appendChild(body);
          return box;
        }

        function createTabbedMissionListBox(activeTab, missionsContent, completedContent) {
          const box = document.createElement('div');
          box.style.display = 'flex';
          box.style.flexDirection = 'column';
          box.style.margin = '0';
          box.style.padding = '0';
          box.style.minHeight = '0';
          box.style.height = '100%';
          box.style.background = 'url("https://bestiaryarena.com/_next/static/media/background-dark.95edca67.png") repeat';
          box.style.border = '4px solid transparent';
          box.style.borderImage = 'url("https://bestiaryarena.com/_next/static/media/4-frame.a58d0c39.png") 6 fill stretch';
          box.style.borderRadius = '6px';
          box.style.overflow = 'hidden';

          const tabBar = document.createElement('div');
          tabBar.style.cssText = 'display:flex;gap:4px;padding:4px 8px 0;box-sizing:border-box;';

          const tabs = [
            { id: 'missions', label: 'Missions' },
            { id: 'completed', label: 'Completed' }
          ];

          tabs.forEach(({ id, label }) => {
            const isActive = activeTab === id;
            const tabButton = document.createElement('button');
            tabButton.type = 'button';
            tabButton.textContent = label;
            tabButton.className = isActive
              ? 'focus-style-visible flex items-center justify-center tracking-wide text-whiteHighlight frame-1-blue active:frame-pressed-1-blue surface-blue gap-1 px-2 py-0.5 pb-[3px] pixel-font-14'
              : 'focus-style-visible flex items-center justify-center tracking-wide text-whiteRegular frame-1 active:frame-pressed-1 surface-regular gap-1 px-2 py-0.5 pb-[3px] pixel-font-14';
            tabButton.style.cssText = 'flex:1 1 0;cursor:pointer;white-space:nowrap;box-sizing:border-box;max-height:21px;height:21px;font-size:14px;';
            tabButton.addEventListener('click', () => {
              if (kingMissionListTab === id) return;
              kingMissionListTab = id;
              renderKingQuestUI();
            });
            tabBar.appendChild(tabButton);
          });

          box.appendChild(tabBar);

          const body = document.createElement('div');
          body.className = 'king-mission-list-scroll-body';
          body.style.flex = '1 1 0';
          body.style.minHeight = '0';
          body.style.overflowY = 'auto';
          body.style.padding = '8px';
          body.appendChild(activeTab === 'completed' ? completedContent : missionsContent);
          box.appendChild(body);
          return box;
        }

        const missionsBody = document.createElement('div');
        missionsBody.style.display = 'flex';
        missionsBody.style.flexDirection = 'column';
        missionsBody.style.gap = '6px';

        const completedBody = document.createElement('div');
        completedBody.style.display = 'flex';
        completedBody.style.flexDirection = 'column';
        completedBody.style.gap = '6px';

        if (kingModalProgressLoading) {
          missionsBody.appendChild(createKingPanelPlaceholder('Loading...'));
          completedBody.appendChild(createKingPanelPlaceholder('Loading...'));
        } else {
        const currentMissions = missionStates.filter(ms => ms.progress.accepted && !ms.progress.completed);
        if (currentMissions.length > 0) {
          currentMissions.forEach(({ mission }) => {
            const missionEntry = document.createElement('p');
            missionEntry.className = 'text-whiteHighlight';
            missionEntry.textContent = getMissionListDisplayTitle(mission);
            missionEntry.style.cursor = 'pointer';
            missionEntry.style.userSelect = 'none';
            missionEntry.style.margin = '0';
            missionEntry.style.color = selectedMissionId === mission.id
              ? '#e6d7b0'
              : (getMissionNpcColor(mission) || '#ffffff');
            missionEntry.addEventListener('click', () => handleMissionClick(mission.id));
            missionsBody.appendChild(missionEntry);
          });
        } else {
          const noneEntry = document.createElement('p');
          noneEntry.style.margin = '0';
          noneEntry.style.color = '#888';
          noneEntry.style.fontStyle = 'italic';
          noneEntry.textContent = 'No active mission';
          missionsBody.appendChild(noneEntry);
          kingQuestDetailsVisible = false;
        }

        const completedMissions = missionStates.filter(ms => ms.progress.completed);
        if (completedMissions.length > 0) {
          completedMissions.forEach(({ mission }) => {
            const completedItem = document.createElement('p');
            completedItem.style.margin = '0';
            completedItem.textContent = getMissionListDisplayTitle(mission);
            completedItem.style.color = selectedMissionId === mission.id
              ? '#e6d7b0'
              : (getMissionNpcColor(mission) || '#ffffff');
            completedItem.style.fontStyle = 'normal';
            completedItem.style.cursor = 'pointer';
            completedItem.style.userSelect = 'none';
            completedItem.style.textDecoration = 'none';
            completedItem.addEventListener('click', () => handleMissionClick(mission.id));
            completedBody.appendChild(completedItem);
          });
        } else {
          const noneItem = document.createElement('p');
          noneItem.style.margin = '0';
          noneItem.textContent = 'No completed missions';
          noneItem.style.color = '#888';
          noneItem.style.fontStyle = 'italic';
          completedBody.appendChild(noneItem);
        }
        }

        const missionListBox = createTabbedMissionListBox(kingMissionListTab, missionsBody, completedBody);
        missionListBox.style.flex = '1 1 0';
        missionListBox.style.minHeight = '0';
        missionListBox.style.height = '100%';

        col1.appendChild(missionListBox);

        const descContent = document.createElement('div');
        descContent.className = 'flex flex-col gap-1';
        descContent.style.padding = '0';

        const descBlock = document.createElement('div');
        descBlock.className = 'flex flex-col gap-1';
        const hintBlock = document.createElement('div');
        hintBlock.className = 'flex flex-col gap-1';

        if (kingModalProgressLoading) {
          const line1 = document.createElement('p');
          line1.textContent = 'Loading...';
          line1.style.color = '#888';
          line1.style.fontStyle = 'italic';
          descBlock.appendChild(line1);
        } else if (!selectedMission) {
          const line1 = document.createElement('p');
          line1.textContent = 'No mission selected.';
          line1.style.color = '#888';
          line1.style.fontStyle = 'italic';
          descBlock.appendChild(line1);
        } else if (!selectedProgress.accepted) {
          const line1 = document.createElement('p');
          line1.textContent = 'No active mission.';
          line1.style.color = '#888';
          line1.style.fontStyle = 'italic';
          descBlock.appendChild(line1);
        } else if (selectedProgress.completed) {
          const line1 = document.createElement('p');
          line1.textContent = getMissionCompletionSummary(selectedMission);
          line1.style.margin = '0';
          line1.style.color = 'rgb(255, 255, 255)';
          descBlock.appendChild(line1);

          const rewardText = getMissionCompletionRewardText(selectedMission);
          if (rewardText) {
            const line2 = document.createElement('p');
            line2.textContent = rewardText;
            line2.style.margin = '0';
            line2.style.marginTop = '6px';
            line2.style.color = 'rgb(230, 215, 176)';
            descBlock.appendChild(line2);
          }
        } else {
          // For letter mission, show the current stage objective
          if (selectedMission.id === KING_LETTER_MISSION.id) {
            const objectiveText = getLetterMissionObjectiveText(selectedMission);
            const line1 = document.createElement('p');
            line1.textContent = objectiveText;
            descBlock.appendChild(line1);

            const line3 = document.createElement('p');
            line3.style.color = '#b0b0b0';
            line3.style.fontStyle = 'italic';
            line3.style.marginTop = '6px';
            const { stampedLetterCount } = getLetterMissionItemCounts();
            line3.textContent = stampedLetterCount > 0
              ? 'Take the stamped letter to Al Dee in Rookgaard to complete the mission.'
              : selectedMission.hint;
            hintBlock.appendChild(line3);
          } else if (selectedMission.id === KING_SCARAB_COIN_MISSION.id) {
            let hasScarabCoin = false;
            if (cachedQuestItems !== null) {
              hasScarabCoin = (cachedQuestItems[SCARAB_COIN_CONFIG.productName] || 0) > 0;
            }

            if (hasScarabCoin) {
              const line1 = document.createElement('p');
              line1.textContent = selectedMission.objectiveLine1;
              line1.style.textDecoration = 'line-through';
              line1.style.opacity = '0.7';
              descBlock.appendChild(line1);

              const line2 = document.createElement('p');
              line2.textContent = selectedMission.objectiveLine2;
              descBlock.appendChild(line2);

              const line3 = document.createElement('p');
              line3.style.color = '#b0b0b0';
              line3.style.fontStyle = 'italic';
              line3.style.marginTop = '6px';
              line3.textContent = 'Tesha is rumoured to know the meaning of scarab coins.';
              hintBlock.appendChild(line3);
            } else {
              const line1 = document.createElement('p');
              line1.textContent = selectedMission.objectiveLine1;
              descBlock.appendChild(line1);

              (async () => {
                try {
                  const currentProducts = await getQuestItems(false);
                  const hasScarabCoinAsync = (currentProducts[SCARAB_COIN_CONFIG.productName] || 0) > 0;
                  if (hasScarabCoinAsync) {
                    descBlock.innerHTML = '';
                    const doneLine = document.createElement('p');
                    doneLine.textContent = selectedMission.objectiveLine1;
                    doneLine.style.textDecoration = 'line-through';
                    doneLine.style.opacity = '0.7';
                    descBlock.appendChild(doneLine);

                    const nextLine = document.createElement('p');
                    nextLine.textContent = selectedMission.objectiveLine2;
                    descBlock.appendChild(nextLine);

                    hintBlock.innerHTML = '';
                    const hintLine = document.createElement('p');
                    hintLine.style.color = '#b0b0b0';
                    hintLine.style.fontStyle = 'italic';
                    hintLine.style.marginTop = '6px';
                    hintLine.textContent = 'Tesha is rumoured to know the meaning of scarab coins.';
                    hintBlock.appendChild(hintLine);
                  }
                } catch (error) {
                  console.error('[Quests Mod][King Tibianus] Error checking for Scarab Coin in objectives:', error);
                }
              })();

              const line3 = document.createElement('p');
              line3.style.color = '#b0b0b0';
              line3.style.fontStyle = 'italic';
              line3.style.marginTop = '6px';
              line3.textContent = selectedMission.hint;
              hintBlock.appendChild(line3);
            }
          } else if (selectedMission.id === SERPENTINE_TOWER_MISSION.id) {
            const serpentineProgress = getMissionProgress(SERPENTINE_TOWER_MISSION);
            const line1 = document.createElement('p');
            if (serpentineProgress.putridChamberComplete) {
              line1.textContent = selectedMission.putridChamberReturnObjective;
              descBlock.appendChild(line1);
            } else if (hasSerpentineDestroyFieldRune()) {
              const doneLine = document.createElement('p');
              doneLine.textContent = selectedMission.objectiveLine1;
              doneLine.style.textDecoration = 'line-through';
              doneLine.style.opacity = '0.7';
              descBlock.appendChild(doneLine);

              line1.textContent = selectedMission.objectiveLine2;
              descBlock.appendChild(line1);
            } else {
              line1.textContent = selectedMission.objectiveLine1;
              descBlock.appendChild(line1);
              const line2 = document.createElement('p');
              line2.textContent = selectedMission.objectiveLine2;
              line2.style.opacity = '0.7';
              descBlock.appendChild(line2);
            }

            const line3 = document.createElement('p');
            line3.style.color = '#b0b0b0';
            line3.style.fontStyle = 'italic';
            line3.style.marginTop = '6px';
            line3.textContent = serpentineProgress.putridChamberComplete
              ? SCORPION_SCEPTRE_CONFIG.description
              : (hasSerpentineDestroyFieldRune()
                ? (selectedMission.hintBasement || selectedMission.hint)
                : selectedMission.hint);
            hintBlock.appendChild(line3);
          } else if (selectedMission.id === CHRISTMAS_MIRACLE_MISSION.id) {
            let hasPresent = false;
            if (cachedQuestItems !== null) {
              hasPresent = (cachedQuestItems[PRESENT_CONFIG.productName] || 0) > 0;
            }

            if (hasPresent) {
              const doneLine = document.createElement('p');
              doneLine.textContent = selectedMission.objectiveLine1;
              doneLine.style.textDecoration = 'line-through';
              doneLine.style.opacity = '0.7';
              descBlock.appendChild(doneLine);

              const nextLine = document.createElement('p');
              nextLine.textContent = selectedMission.objectiveLine2;
              descBlock.appendChild(nextLine);

              const hintLine = document.createElement('p');
              hintLine.style.color = '#b0b0b0';
              hintLine.style.fontStyle = 'italic';
              hintLine.style.marginTop = '6px';
              hintLine.textContent = 'Perhaps it is meant to be opened.';
              hintBlock.appendChild(hintLine);
            } else {
              const line1 = document.createElement('p');
              line1.textContent = selectedMission.objectiveLine1;
              descBlock.appendChild(line1);
            }
          } else if (selectedMission.id === SVENSON_LOVE_STORY_MISSION.id) {
            const line1 = document.createElement('p');
            line1.textContent = getActiveMissionObjectiveLine(selectedMission);
            descBlock.appendChild(line1);

            const hintText = getActiveMissionHintLine(selectedMission);
            if (hintText) {
              const line3 = document.createElement('p');
              line3.style.color = '#b0b0b0';
              line3.style.fontStyle = 'italic';
              line3.style.marginTop = '6px';
              line3.textContent = hintText;
              hintBlock.appendChild(line3);
            }
          } else if (selectedMission.id === LOST_ORACLE_MISSION.id) {
            const lostProgress = getMissionProgress(LOST_ORACLE_MISSION) || {};
            const stages = [
              {
                done: !!(lostProgress.kingInformed || lostProgress.orbExchanged || lostProgress.spectralStoneReceived || lostProgress.oracleEnraged || lostProgress.battleCompleted || lostProgress.completed || lostProgress.oracleDismissed),
                text: selectedMission.objectiveLine1
              },
              {
                done: !!(lostProgress.orbExchanged || lostProgress.spectralStoneReceived || lostProgress.oracleEnraged || lostProgress.battleCompleted || lostProgress.completed || lostProgress.oracleDismissed),
                text: selectedMission.objectiveLine2
              },
              {
                done: !!(lostProgress.spectralStoneReceived || lostProgress.oracleEnraged || lostProgress.battleCompleted || lostProgress.completed || lostProgress.oracleDismissed),
                text: selectedMission.objectiveLine3
              },
              {
                done: !!(lostProgress.oracleEnraged || lostProgress.battleCompleted || lostProgress.completed || lostProgress.oracleDismissed),
                text: selectedMission.objectiveLine4
              },
              {
                done: !!(lostProgress.battleCompleted || lostProgress.completed || lostProgress.oracleDismissed),
                text: selectedMission.objectiveLine5
              },
              {
                done: !!(lostProgress.completed || lostProgress.oracleDismissed),
                text: selectedMission.objectiveLine6
              }
            ].filter((stage) => !!stage.text);

            let shownCurrent = false;
            for (const stage of stages) {
              if (stage.done) {
                const doneLine = document.createElement('p');
                doneLine.textContent = stage.text;
                doneLine.style.textDecoration = 'line-through';
                doneLine.style.opacity = '0.7';
                descBlock.appendChild(doneLine);
                continue;
              }
              if (!shownCurrent) {
                const line1 = document.createElement('p');
                line1.textContent = getActiveMissionObjectiveLine(selectedMission) || stage.text;
                descBlock.appendChild(line1);
                shownCurrent = true;
              }
            }

            const hintText = getActiveMissionHintLine(selectedMission) || selectedMission.hint;
            if (hintText) {
              const line3 = document.createElement('p');
              line3.style.color = '#b0b0b0';
              line3.style.fontStyle = 'italic';
              line3.style.marginTop = '6px';
              line3.textContent = hintText;
              hintBlock.appendChild(line3);
            }
          } else {
            // For other missions, always show both objectives
            const line1 = document.createElement('p');
            line1.textContent = selectedMission.objectiveLine1;
            descBlock.appendChild(line1);

            if (selectedMission.objectiveLine2) {
              const line2 = document.createElement('p');
              line2.textContent = selectedMission.objectiveLine2;
              descBlock.appendChild(line2);
            }

            const line3 = document.createElement('p');
            line3.style.color = '#b0b0b0';
            line3.style.fontStyle = 'italic';
            line3.style.marginTop = '6px';
            line3.textContent = selectedMission.hint;
            hintBlock.appendChild(line3);
          }
        }

        const descBodyWrapper = document.createElement('div');
        descBodyWrapper.className = 'flex flex-col gap-1';
        descBodyWrapper.style.padding = '0';
        descBodyWrapper.appendChild(descBlock);
        descBodyWrapper.appendChild(hintBlock);

        // Start hidden until a mission is clicked
        // Always show details when a mission is selected; hide only when none selected
        descBodyWrapper.style.display = (kingModalProgressLoading || selectedMission) ? 'block' : 'none';

        const missionLogBox = createFramedBox('Mission Log', descBodyWrapper);
        missionLogBox.style.flex = '1 1 0';
        missionLogBox.style.minHeight = '0';

        col2.appendChild(missionLogBox);
        kingQuestDescEl = missionLogBox;
        kingQuestDescBody = descBodyWrapper;

        const missionListScroll = col1.querySelector('.king-mission-list-scroll-body');
        if (missionListScroll) {
          const savedScrollTop = kingMissionListScrollTops[kingMissionListTab] || 0;
          requestAnimationFrame(() => {
            missionListScroll.scrollTop = savedScrollTop;
          });
        }
      }

      function createKingPanelPlaceholder(text) {
        const placeholder = document.createElement('p');
        placeholder.style.margin = '0';
        placeholder.style.color = '#888';
        placeholder.style.fontStyle = 'italic';
        placeholder.textContent = text;
        return placeholder;
      }

      async function applyKingModalSideEffects() {
        try {
          const goldenRopeProgress = kingChatState.progressAlDeeGoldenRope;
          if (!goldenRopeProgress.accepted && !goldenRopeProgress.completed) {
            const questItems = await getQuestItems(false);
            if (questItems && questItems['Elvenhair Rope'] && questItems['Elvenhair Rope'] > 0) {
              console.log('[Quests Mod][King Tibianus] Auto-accepting Al Dee golden rope mission - player has Elvenhair Rope');
              kingChatState.progressAlDeeGoldenRope.accepted = true;
              const playerName = getCurrentPlayerName();
              if (playerName) {
                await saveKingTibianusProgress(playerName, {
                  alDeeGoldenRope: {
                    accepted: true,
                    completed: false
                  }
                });
              }
            }
          }
        } catch (error) {
          console.warn('[Quests Mod][King Tibianus] Error auto-accepting golden rope mission:', error);
        }

        try {
          const tokenHeld = await hasSilverToken();
          setRow2Disabled(tokenHeld && !kingChatState.starterCoinThanked);
        } catch (err) {
          console.warn('[Quests Mod] Could not set row2 disabled state:', err);
        }
      }

      function refreshKingModalMissionState() {
        activeMission = currentMission();
        kingStrings = buildStrings(activeMission);
        renderKingQuestUI();
      }

      function applyKingProgressToState(progress) {
        if (progress && progress.accepted !== undefined) {
          kingChatState.progressCopper = {
            accepted: progress.accepted,
            completed: progress.completed
          };
        }
        if (progress) {
          for (const [missionId, firebaseKey] of Object.entries(MISSION_FIREBASE_KEY_MAP)) {
            const stateKey = MISSION_STATE_MAP[missionId];
            if (stateKey && progress[firebaseKey]) {
              kingChatState[stateKey] = buildMissionProgressFromFirebaseEntry(firebaseKey, progress[firebaseKey]);
            }
          }
          kingChatState.mornenionDefeated = !!(progress.mornenion && progress.mornenion.defeated);
          if (progress.starterCoinThanked !== undefined) {
            kingChatState.starterCoinThanked = !!progress.starterCoinThanked;
          } else if (inferStarterCoinThankedFromProgress(progress)) {
            kingChatState.starterCoinThanked = true;
          }
        }
      }

      async function loadKingTibianusProgress() {
        kingModalProgressLoading = !missionProgressHydratedFromFirebase;
        if (!missionProgressHydratedFromFirebase) {
          renderKingQuestUI();
        }

        try {
          if (!missionProgressHydratedFromFirebase) {
            await loadMissionProgressOnInit();
          }
          await getQuestItems(false);
          if (!missionProgressHydratedFromFirebase) {
            const playerName = getCurrentPlayerName();
            const progress = await getKingTibianusProgress(playerName);
            await grantStarterSilverTokenIfNeeded(progress, playerName);
            applyKingProgressToState(progress);
          }
          await applyKingModalSideEffects();
          selectedMissionId = null;
          activeMission = currentMission();
          kingStrings = buildStrings(activeMission);
          refreshKingModalMissionState();
        } catch (error) {
          console.error('[Quests Mod][King Tibianus] Error loading progress:', error);
        } finally {
          kingModalProgressLoading = false;
          renderKingQuestUI();
        }
      }

      async function startKingTibianusQuestForMission(mission) {
        try {
          const playerName = getCurrentPlayerName();
          if (!playerName) {
            console.warn('[Quests Mod][King Tibianus] Player name not available, cannot start quest');
            return;
          }
          if (!mission) {
            console.warn('[Quests Mod][King Tibianus] No mission specified');
            return;
          }
          const currentProgress = getMissionProgress(mission);
          const nextProgress = {
            accepted: true,
            completed: !!currentProgress.completed
          };
          setMissionProgress(mission, nextProgress);
          // Update the corresponding progress state
          if (mission.id === KING_COPPER_KEY_MISSION.id) {
            kingChatState.progressCopper.accepted = true;
          } else if (mission.id === KING_HONEYFLOWER_MISSION.id) {
            kingChatState.progressHoneyflower.accepted = true;
            if (typeof updateHoneyflowerTileRightClickState === 'function') {
              updateHoneyflowerTileRightClickState();
            }
          } else if (mission.id === KING_CROSSING_THE_LINE_MISSION.id) {
            const crossingProgress = buildCrossingTheLineProgress({ accepted: true });
            setMissionProgress(mission, crossingProgress);
            kingChatState.progressCrossingTheLine = { ...crossingProgress };
            if (typeof setupCrossingTheLineSystem === 'function') {
              setupCrossingTheLineSystem();
            }
            if (typeof refreshQuestTileHighlights === 'function') {
              refreshQuestTileHighlights();
            }
            NotificationService.showQuestAccepted(KING_CROSSING_THE_LINE_MISSION, '[Quests Mod][King Tibianus]');
          } else if (mission.id === KING_RED_DRAGON_MISSION.id) {
            kingChatState.progressDragon.accepted = true;
          } else if (mission.id === KING_LETTER_MISSION.id) {
            kingChatState.progressLetter.accepted = true;
          } else if (mission.id === KING_MONKS_STUDY_MISSION.id) {
            kingChatState.progressMonksStudy.accepted = true;
          } else if (mission.id === KING_SCARAB_COIN_MISSION.id) {
            kingChatState.progressScarabHunt.accepted = true;
          } else if (mission.id === FOLLOWER_OF_ZATHROTH_MISSION.id) {
            kingChatState.progressFollowerOfZathroth.accepted = true;
            if (typeof updateTile83WydaRightClickState === 'function') updateTile83WydaRightClickState();
          } else if (mission.id === MOTHER_OF_ALL_SPIDERS_MISSION.id) {
            kingChatState.progressMotherOfAllSpiders.accepted = true;
          }
          activeMission = currentMission();
          selectedMissionId = null;
          kingStrings = buildStrings(activeMission);
          // Use registry to get all mission progress (future-proof)
          const allProgress = getAllMissionProgress();
          // Include ironOre if it exists in fishingState
          if (fishingState.ironOreQuestActive !== undefined || fishingState.ironOreQuestCompleted) {
            allProgress.ironOre = {
              active: fishingState.ironOreQuestActive || false,
              startTime: fishingState.ironOreQuestStartTime || null,
              completed: fishingState.ironOreQuestCompleted || false
            };
          }
          await saveKingTibianusProgress(playerName, allProgress);

          // Add map to inventory when copper key mission is accepted
          if (mission.id === KING_COPPER_KEY_MISSION.id) {
            try {
              await addQuestItem(MAP_COLOUR_CONFIG.productName, 1);
              NotificationService.showImportant(TOAST_MESSAGES.mapReceived, '[Quests Mod][King Tibianus]', MAP_COLOUR_CONFIG.productName);
              console.log('[Quests Mod][King Tibianus] Awarded Map (Colour) for copper key mission');
              // Set up Copper Key system now that mission is accepted
              setupCopperKeySystem();
            } catch (err) {
              console.error('[Quests Mod][King Tibianus] Error awarding Map (Colour):', err);
            }
          }

          // Add Obsidian Knife to inventory when red dragon mission is accepted
          if (mission.id === KING_RED_DRAGON_MISSION.id) {
            try {
              await addQuestItem('Obsidian Knife', 1);
              NotificationService.showItemReceived('Obsidian Knife', '[Quests Mod][King Tibianus]');
              console.log('[Quests Mod][King Tibianus] Awarded Obsidian Knife for red dragon mission');
            } catch (err) {
              console.error('[Quests Mod][King Tibianus] Error awarding Obsidian Knife:', err);
            }
          }

          if (mission.id === KING_MONKS_STUDY_MISSION.id && typeof updateTile53CostelloRightClickState === 'function') {
            updateTile53CostelloRightClickState();
          }

          if (mission.id === KING_SCARAB_COIN_MISSION.id) {
            NotificationService.showQuestAccepted(KING_SCARAB_COIN_MISSION, '[Quests Mod][King Tibianus]');
          }

          // Exchange Letter from Al Dee for Stamped Letter when letter mission is accepted with the letter
          if (mission.id === KING_LETTER_MISSION.id) {
            try {
              const stamped = await stampAlDeeLetterForKing('exchange Letter from Al Dee for Stamped Letter');
              if (!stamped) {
                console.log('[Quests Mod][King Tibianus] Letter mission accepted — seek Al Dee / recover letter in Rookgaard');
                if (typeof updateTile79RightClickState === 'function') {
                  updateTile79RightClickState();
                }
              }
            } catch (err) {
              console.error('[Quests Mod][King Tibianus] Error exchanging letter:', err);
            }
          } else {
            // Mission accepted but not KING_LETTER_MISSION - still update tile 79 state in case it's relevant
            if (typeof updateTile79RightClickState === 'function') {
              updateTile79RightClickState();
            }
          }

          renderKingQuestUI();
        } catch (error) {
          console.error('[Quests Mod][King Tibianus] Error starting quest:', error);
        }
      }

      async function completeKingTibianusQuest(missionToComplete) {
        try {
          const playerName = getCurrentPlayerName();
          if (!playerName) return;
          const mission = missionToComplete || activeMission;
          if (!mission) {
            console.warn('[Quests Mod][King Tibianus] No active mission to complete');
            return;
          }
          const currentProgress = getMissionProgress(mission);
          const shouldAwardDragonClaw =
            mission.id === KING_RED_DRAGON_MISSION.id && !currentProgress.completed;
          if (!currentProgress.completed) {
            await consumeKingMissionHandInItems(mission);
          }
          const nextProgress = mission.id === KING_HONEYFLOWER_MISSION.id
            ? buildHoneyflowerProgress({ accepted: true, completed: true })
            : mission.id === KING_CROSSING_THE_LINE_MISSION.id
              ? buildCrossingTheLineProgress({ accepted: true, completed: true, crossingObjectiveComplete: true })
              : { accepted: true, completed: true };
          setMissionProgress(mission, nextProgress);
          activeMission = currentMission();
          selectedMissionId = null;
          kingStrings = buildStrings(activeMission);
          // Use registry to get all mission progress (future-proof)
          const allProgress = getAllMissionProgress();
          // Include ironOre if it exists in fishingState
          if (fishingState.ironOreQuestActive !== undefined || fishingState.ironOreQuestCompleted) {
            allProgress.ironOre = {
              active: fishingState.ironOreQuestActive || false,
              startTime: fishingState.ironOreQuestStartTime || null,
              completed: fishingState.ironOreQuestCompleted || false
            };
          }
          await saveKingTibianusProgress(playerName, allProgress);
          if (shouldAwardDragonClaw) {
            try {
              const clawName = getDragonClawProductName();
              await addQuestItem(clawName, 1);
              NotificationService.showItemReceived(clawName, '[Quests Mod][King Tibianus]');
              console.log(`[Quests Mod][King Tibianus] Awarded ${clawName} for dragon mission completion`);
            } catch (err) {
              console.error('[Quests Mod][King Tibianus] Error awarding Dragon Claw:', err);
            }
          }
          renderKingQuestUI();
          console.log('[Quests Mod][King Tibianus] Quest marked as completed');

          if (!currentProgress.completed) {
            NotificationService.showQuestCompleted(
              mission,
              '[Quests Mod][King Tibianus]',
              mission.rewardCoins > 0 ? { rewardCoins: mission.rewardCoins } : undefined
            );
          }

          // Update rank display after quest completion
          scheduleArenaRankDisplayUpdate(100);
        } catch (error) {
          console.error('[Quests Mod][King Tibianus] Error completing quest:', error);
        }
      }

      async function hasCopperKeyInInventory() {
        try {
          const items = await getQuestItems(false);
          return (items && items[COPPER_KEY_CONFIG.productName] > 0);
        } catch (error) {
          console.error('[Quests Mod][King Tibianus] Error checking Copper Key in inventory:', error);
          return false;
        }
      }

      async function hasRedDragonMaterials() {
        try {
          const items = await getQuestItems(false);
          const scales = (items && items['Red Dragon Scale']) || 0;
          const leathers = (items && items['Red Dragon Leather']) || 0;
          return scales >= 30 && leathers >= 30;
        } catch (error) {
          console.error('[Quests Mod][King Tibianus] Error checking red dragon materials:', error);
          return false;
        }
      }

      // Row 3: Chat input area
      const row3 = document.createElement('div');
      row3.style.cssText = `
        padding: 0;
        border-top: 0;
        margin: 0;
        background: rgba(255, 255, 255, 0.05);
        display: flex;
        flex-direction: column;
        gap: 2px;
        flex-shrink: 0;
      `;
      
      const inputRow = document.createElement('div');
      inputRow.style.cssText = 'display: flex; gap: 6px; align-items: center;';
      
      const textarea = document.createElement('textarea');
      textarea.className = 'king-tibianus-chat-input';
      textarea.setAttribute('wrap', 'off');
      textarea.placeholder = 'Type your message to King Tibianus...';
      textarea.style.cssText = `
        flex: 1;
        height: 28px;
        max-height: 28px;
        min-height: 28px;
        padding: 4px 6px;
        background-color: #333;
        border: 4px solid transparent;
        border-image: url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill;
        color: rgb(255, 255, 255);
        font-family: inherit;
        font-size: 13px;
        line-height: 18px;
        resize: none;
        box-sizing: border-box;
        line-height: 1.2;
        white-space: nowrap;
        overflow-x: hidden;
        overflow-y: hidden;
        outline: none;
      `;
      
      // Handle Enter key
      textarea.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          sendMessageToKing();
        }
      });
      
      // Remove focus outline/border
      textarea.addEventListener('focus', () => {
        textarea.style.outline = 'none';
        textarea.style.borderImage = 'url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill';
      });
      
      textarea.addEventListener('blur', () => {
        textarea.style.outline = 'none';
        textarea.style.borderImage = 'url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill';
      });
      
      const sendButton = document.createElement('button');
      sendButton.textContent = 'Send';
      sendButton.className = 'primary';
      sendButton.style.cssText = `
        height: 28px;
        padding: 4px 10px;
        white-space: nowrap;
        font-size: 13px;
        line-height: 16px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: url('https://bestiaryarena.com/_next/static/media/background-blue.7259c4ed.png') center center / cover;
        border: 4px solid transparent;
        border-image: url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill;
        color: rgb(255, 255, 255);
        cursor: pointer;
        font-family: inherit;
      `;
      
      // Track pending response timeout
      let pendingResponseTimeout = null;
      let latestMessage = null;
      const thankYouText = kingStrings.thankYou;

      // Helper function to check if text is a valid hail phrase (case-insensitive)
      function isValidHailPhrase(text) {
        const trimmed = text.trim().toLowerCase();
        return trimmed === 'hail' || trimmed === 'hail king' || trimmed === 'hail the king';
      }

      function isAffirmativeReply(text) {
        return /\byes\b/i.test(text.trim());
      }

      function isNegativeReply(text) {
        return /\bno\b/i.test(text.trim());
      }

      function setKingAwaitingKeyConfirm(mission) {
        kingChatState.missionOffered = false;
        kingChatState.awaitingKeyConfirm = true;
        kingChatState.offeredMission = mission;
      }

      function setKingMissionOffered(mission) {
        kingChatState.awaitingKeyConfirm = false;
        kingChatState.missionOffered = true;
        kingChatState.offeredMission = mission;
      }

      async function maybeHandleStarterCoin(lowerText) {
        if (kingChatState.starterCoinThanked) {
          return null;
        }
        if (!isValidHailPhrase(lowerText)) {
          return null;
        }
        let hasToken = await hasSilverToken();
        if (!hasToken) {
          // Edge case: user sent hail before starter token grant completed; grant now if eligible
          try {
            const playerName = getCurrentPlayerName();
            const progress = await getKingTibianusProgress(playerName);
            await grantStarterSilverTokenIfNeeded(progress, playerName);
            hasToken = await hasSilverToken();
          } catch (err) {
            console.warn('[Quests Mod] Could not grant starter token during hail:', err);
          }
        }
        if (!hasToken) {
          return null;
        }
        const consumed = await consumeQuestItem(SILVER_TOKEN_CONFIG.productName, 1);
        if (consumed) {
          kingChatState.starterCoinThanked = true;
          setRow2Disabled(false);
          const playerName = getCurrentPlayerName();
          if (playerName) {
            try {
              await saveKingTibianusProgress(playerName, getAllMissionProgress());
            } catch (err) {
              console.error('[Quests Mod][King Tibianus] Error saving starter coin thank-you:', err);
            }
          }
          return 'I thank thee for the coin.';
        }
        return null;
      }

      // Helper: Clear textarea input
      function clearTextarea() {
        textarea.value = '';
        textarea.style.height = '27px';
      }

      // Helper: Determine target mission based on message content
      function determineTargetMission(lowerText, activeMission) {
        const mentionsKey = lowerText.includes('key') || lowerText.includes('copper key');
        const mentionsDragon = lowerText.includes('dragon') || lowerText.includes('scale') || lowerText.includes('leather');
        const mentionsLetter = lowerText.includes('letter') || lowerText.includes('scroll');
        const mentionsMonks = lowerText.includes('costello') || lowerText.includes('monastery') || lowerText.includes('monks') || lowerText.includes('white raven');
        const mentionsScarab = lowerText.includes('scarab') || lowerText.includes('desert') || lowerText.includes('darama') || lowerText.includes('valuable') || lowerText.includes('sands');
        const mentionsHoneyflower = lowerText.includes('honeyflower') || lowerText.includes('honey flower') || lowerText.includes('honey');
        const mentionsCrossing = lowerText.includes('crossing') || lowerText.includes('bishop') || lowerText.includes('chess') || lowerText.includes('carlin') || lowerText.includes('boardgame') || lowerText.includes('board game') || lowerText.includes('city boardgames') || lowerText.includes('mage');
        const hasHolyTible = (cachedQuestItems && (cachedQuestItems['The Holy Tible'] || 0) > 0);

        if (mentionsHoneyflower && canOfferHoneyflowerMission()) {
          return MISSIONS.find(m => m.id === KING_HONEYFLOWER_MISSION.id) || activeMission;
        }

        if (mentionsCrossing && canOfferCrossingTheLineMission()) {
          return MISSIONS.find(m => m.id === KING_CROSSING_THE_LINE_MISSION.id) || activeMission;
        }

        if (areAllMissionsCompleted()) {
          return activeMission;
        }

        if (mentionsHoneyflower) {
          return MISSIONS.find(m => m.id === KING_HONEYFLOWER_MISSION.id) || activeMission;
        } else if (mentionsCrossing && getHoneyflowerMissionProgress().completed) {
          return MISSIONS.find(m => m.id === KING_CROSSING_THE_LINE_MISSION.id) || activeMission;
        } else if (mentionsLetter) {
          return MISSIONS.find(m => m.id === KING_LETTER_MISSION.id) || activeMission;
        } else if (mentionsKey) {
          return MISSIONS.find(m => m.id === KING_COPPER_KEY_MISSION.id) || activeMission;
        } else if (mentionsDragon) {
          return MISSIONS.find(m => m.id === KING_RED_DRAGON_MISSION.id) || activeMission;
        } else if (mentionsMonks && hasHolyTible) {
          return MISSIONS.find(m => m.id === KING_MONKS_STUDY_MISSION.id) || activeMission;
        } else if (mentionsScarab) {
          return MISSIONS.find(m => m.id === KING_SCARAB_COIN_MISSION.id) || activeMission;
        }
        return activeMission;
      }

      // Helper: Handle key confirmation response (yes/no after "Have you found my key?")
      async function handleKeyConfirmation(lowerText) {
        if (!kingChatState.awaitingKeyConfirm) {
          return false;
        }

        const confirmMission = kingChatState.offeredMission;
        if (!confirmMission) {
          kingChatState.awaitingKeyConfirm = false;
          return false;
        }

        const confirmStrings = buildStrings(confirmMission);
        const currentProgress = getMissionProgress(confirmMission);
        if (!currentProgress.accepted || currentProgress.completed) {
          kingChatState.awaitingKeyConfirm = false;
          kingChatState.offeredMission = null;
          return false;
        }

        if (isAffirmativeReply(lowerText)) {
          const hasItems = await isKingMissionReadyForHandIn(confirmMission);

          if (hasItems) {
            const missionToComplete = confirmMission;
            const completingScarabHunt = confirmMission.id === KING_SCARAB_COIN_MISSION.id;
            queueKingReply(confirmStrings.keyComplete, { onDone: async () => {
              if (completingScarabHunt) {
                updateTeshaArrowState();
                renderKingQuestUI();
              } else {
                if (missionToComplete.id === KING_HONEYFLOWER_MISSION.id) {
                  if (typeof updateHoneyflowerTileRightClickState === 'function') {
                    updateHoneyflowerTileRightClickState();
                  }
                }
                if (missionToComplete.id === KING_CROSSING_THE_LINE_MISSION.id) {
                  if (typeof refreshQuestTileHighlights === 'function') {
                    refreshQuestTileHighlights();
                  }
                }
                if (missionToComplete.rewardCoins > 0) {
                  await awardGuildCoins(missionToComplete.rewardCoins);
                  await updateGuildCoinDisplay();
                }
                await completeKingTibianusQuest(missionToComplete);
              }
            } });
          } else {
            queueKingReply(confirmStrings.keyScoldNoKey, { closeAfterMs: 2000 });
          }
          kingChatState.awaitingKeyConfirm = false;
          kingChatState.offeredMission = null;
          clearTextarea();
          return true;
        }

        if (isNegativeReply(lowerText)) {
          queueKingReply(confirmStrings.keyKeepSearching);
          kingChatState.awaitingKeyConfirm = false;
          kingChatState.offeredMission = null;
          clearTextarea();
          return true;
        }

        queueKingReply(confirmStrings.keyAnswerYesNo);
        clearTextarea();
        return true;
      }

      // Helper: Handle mission acceptance
      async function handleMissionAcceptance(lowerText) {
        if (!kingChatState.missionOffered || !kingChatState.offeredMission || !isAffirmativeReply(lowerText)) {
          return false;
        }

        const offeredProgress = getMissionProgress(kingChatState.offeredMission);
        if (offeredProgress.accepted || offeredProgress.completed) {
          return false;
        }

        // Prevent King Tibianus from accepting Al Dee missions
        const offeredMissionToStart = kingChatState.offeredMission;
        if (offeredMissionToStart.id === AL_DEE_FISHING_MISSION.id || offeredMissionToStart.id === AL_DEE_GOLDEN_ROPE_MISSION.id) {
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
          queueKingReply('That mission belongs to Al Dee, the rope merchant in Rookgaard. You must speak with him to accept it.', { onDone: () => {
            clearTextarea();
          } });
          tibianusCooldown.reset();
          return true;
        }

        if (offeredMissionToStart.id === KING_COPPER_KEY_MISSION.id && !canOfferCopperKeyMission()) {
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
          queueKingReply(KING_COPPER_KEY_MISSION.notExperiencedEnough, { onDone: () => {
            clearTextarea();
          } });
          tibianusCooldown.reset();
          return true;
        }

        if (offeredMissionToStart.id === KING_SCARAB_COIN_MISSION.id && !(await hasLightShovelInInventory())) {
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
          queueKingReply(
            KING_SCARAB_COIN_MISSION.requiresLightShovel
              || 'I have no task for thee at present. Come back later.',
            { onDone: () => { clearTextarea(); } }
          );
          tibianusCooldown.reset();
          return true;
        }

        kingChatState.missionOffered = false;
        const offeredStrings = buildStrings(offeredMissionToStart);
        
        // Check if this is the letter mission and player doesn't have the letter
        let acceptanceMessage = offeredStrings.thankYou;
        if (offeredMissionToStart.id === KING_LETTER_MISSION.id) {
          try {
            const currentProducts = await getQuestItems(false);
            const currentLetterCount = currentProducts['Letter from Al Dee'] || 0;
            if (currentLetterCount === 0) {
              acceptanceMessage = offeredStrings.thankYouNoLetter;
            }
          } catch (error) {
            console.error('[Quests Mod][King Tibianus] Error checking for letter:', error);
            // Fall back to default message if check fails
          }
        }
        
        queueKingReply(acceptanceMessage, { onDone: async () => {
          await startKingTibianusQuestForMission(offeredMissionToStart);
          kingChatState.offeredMission = null;
        } });
        tibianusCooldown.reset();
        clearTextarea();
        return true;
      }

      // Send message function
      async function sendMessageToKing() {
        const text = textarea.value.trim();
        if (!text || text.length === 0) {
          return;
        }
        
        // Get player name
        const playerName = getCurrentPlayerName() || 'Player';
        const lowerText = text.toLowerCase();
        
        // Add player message to conversation
        addMessageToConversation(playerName, text, false);
        
        // Clear any pending response timeout
        tibianusCooldown.clearPendingResponse();

        // Swearing at the king ends the audience angrily
        if (messageContainsNpcSwear(lowerText)) {
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
          kingChatState.awaitingKeyConfirm = false;
          tibianusCooldown.queueResponse(
            text,
            KING_TIBIANUS_SWEAR_RESPONSE,
            addMessageToConversation,
            'King Tibianus',
            () => ModalHelpers.closeModal(KING_TIBIANUS_SWEAR_CLOSE_DELAY_MS)
          );
          clearTextarea();
          return;
        }
        
        // If the king has not received the starter coin yet, only accept valid hail phrases
        const tokenHeld = await hasSilverToken();
        if (tokenHeld && !kingChatState.starterCoinThanked) {
          if (!isValidHailPhrase(lowerText)) {
            addHintToConversation('King Tibianus is ignoring you. Perhaps a proper greeting would get his attention.');
            clearTextarea();
            return;
          }
        }

        // Easter egg: ask the King about the "Isle of Solitude" / "GM Island". He offers
        // passage and only teleports you (enterIsleOfSolitude) once you answer "yes".
        if (awaitingIsleConfirm) {
          if (isAffirmativeReply(lowerText)) {
            awaitingIsleConfirm = false;
            clearTextarea();
            tibianusCooldown.queueResponse(
              text,
              'So be it. Do not speak of what you see there.',
              addMessageToConversation,
              'King Tibianus',
              () => {
                setTimeout(() => {
                  ModalHelpers.closeModal(0);
                  enterIsleOfSolitude();
                }, 2000);
              }
            );
            return;
          }
          if (isNegativeReply(lowerText)) {
            awaitingIsleConfirm = false;
            clearTextarea();
            tibianusCooldown.queueResponse(
              text,
              'Wise. The isle keeps its secrets.',
              addMessageToConversation,
              'King Tibianus',
              ModalHelpers.getFarewellCloseCallback(text)
            );
            return;
          }
          // Any other reply: drop the pending offer and fall through to normal handling.
          awaitingIsleConfirm = false;
        }
        if (lowerText.includes('isle of solitude') || lowerText.includes('gm island')) {
          clearTextarea();
          const isleLine = getKingTibianusKeywordResponses()['isle of solitude']
            || getKingTibianusKeywordResponses()['gm island']
            || 'The Isle of Solitude does not officially exist.';
          awaitingIsleConfirm = true;
          tibianusCooldown.queueResponse(
            text,
            `${isleLine} Do you wish passage there now?`,
            addMessageToConversation,
            'King Tibianus'
          );
          return;
        }

        // Quest items that only have a generic "take it to <NPC>" hint (e.g. the
        // Key to Magic → Tesha) must answer before the mission-keyword logic below,
        // which would otherwise treat "key to magic" as a copper-key query.
        const kingItemHint = getNpcQuestItemHintResponse('king-tibianus', text, playerName);
        if (kingItemHint) {
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
          tibianusCooldown.queueResponse(
            text,
            kingItemHint,
            addMessageToConversation,
            'King Tibianus',
            ModalHelpers.getFarewellCloseCallback(text)
          );
          clearTextarea();
          return;
        }

        // Refresh mission context (in case first mission just completed)
        activeMission = currentMission();
        kingStrings = buildStrings(activeMission);
        const currentProgress = getMissionProgress(activeMission);

        // Check for mission-related keywords
        const mentionsKey = lowerText.includes('key') || lowerText.includes('copper key');
        const mentionsDragon = lowerText.includes('dragon') || lowerText.includes('scale') || lowerText.includes('leather');
        const mentionsLetter = lowerText.includes('letter') || lowerText.includes('scroll');
        const mentionsMonks = lowerText.includes('costello') || lowerText.includes('monastery') || lowerText.includes('monks') || lowerText.includes('white raven');
        const mentionsScarab = lowerText.includes('scarab') || lowerText.includes('desert') || lowerText.includes('darama') || lowerText.includes('valuable') || lowerText.includes('sands');
        const mentionsHoneyflower = lowerText.includes('honeyflower') || lowerText.includes('honey flower') || lowerText.includes('honey');
        const mentionsCrossing = lowerText.includes('crossing') || lowerText.includes('bishop') || lowerText.includes('chess') || lowerText.includes('carlin') || lowerText.includes('boardgame') || lowerText.includes('board game') || lowerText.includes('city boardgames') || lowerText.includes('mage');
        const mentionsMissionKeyword = lowerText.includes('mission') || lowerText.includes('quest') || lowerText.includes('task');

        // Determine target mission based on what player mentioned
        const targetMission = determineTargetMission(lowerText, activeMission);
        const targetStrings = buildStrings(targetMission);
        const targetProgress = getMissionProgress(targetMission);

        // Handle pending key confirmation (yes/no after "Have you found my key?")
        if (await handleKeyConfirmation(lowerText)) {
          return;
        }

        // The Lost Oracle — ask about oracle / exchange Orb for Luminous Orb
        const lostOracleProgress = getMissionProgress(LOST_ORACLE_MISSION) || {};
        const mentionsOracle = lowerText.includes('oracle');
        const mentionsOrb = /\borb\b/.test(lowerText) && !lowerText.includes('luminous');
        if ((lostOracleProgress.completed || lostOracleProgress.oracleDismissed) && mentionsOracle) {
          clearTextarea();
          queueKingReply(
            getLostOracleNpcRestoredLine('king', getCurrentPlayerName() || 'Player')
          );
          return;
        }
        if (lostOracleProgress.accepted && !lostOracleProgress.completed) {
          if (awaitingLostOracleOrbConfirm) {
            if (isAffirmativeReply(lowerText)) {
              awaitingLostOracleOrbConfirm = false;
              clearTextarea();
              try {
                const ok = await exchangeOrbForLuminousOrb();
                queueKingReply(
                  ok
                    ? getMissionDialogueLine(LOST_ORACLE_MISSION, 'kingOracleExchanged', 'Behold — a Luminous Orb. Guard it well; destiny is seldom gentle.')
                    : getMissionDialogueLine(LOST_ORACLE_MISSION, 'kingOracleNoOrb', 'Return when you have an Orb to offer.')
                );
              } catch (error) {
                console.error('[Quests Mod][King Tibianus] Error exchanging Orb for Luminous Orb:', error);
                queueKingReply(getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'));
              }
              return;
            }
            if (isNegativeReply(lowerText)) {
              awaitingLostOracleOrbConfirm = false;
              clearTextarea();
              queueKingReply(
                getMissionDialogueLine(LOST_ORACLE_MISSION, 'kingOracleDecline', 'Very well. Return when you are prepared to offer the Orb.')
              );
              return;
            }
          }

          if (mentionsOracle || mentionsOrb) {
            clearTextarea();
            try {
              await noteLostOracleInquiry({ fromKing: true });
              const freshProgress = getMissionProgress(LOST_ORACLE_MISSION) || {};
              if (freshProgress.oracleEnraged || freshProgress.battleCompleted) {
                queueKingReply(
                  getMissionDialogueLine(
                    LOST_ORACLE_MISSION,
                    'kingOracleReturnStone',
                    'The Spectral Stone belongs with The Oracle. Return it whence such light was born.'
                  )
                );
                return;
              }
              if (freshProgress.spectralStoneReceived || hasSpectralStoneInInventory()) {
                queueKingReply(
                  getMissionDialogueLine(
                    LOST_ORACLE_MISSION,
                    'kingOracleReturnStone',
                    'The Spectral Stone belongs with The Oracle. Return it whence such light was born.'
                  )
                );
                return;
              }
              if (freshProgress.orbExchanged || hasLuminousOrbInInventory()) {
                queueKingReply(
                  getMissionDialogueLine(LOST_ORACLE_MISSION, 'kingOracleAlreadyExchanged', 'You already hold the Luminous Orb I fashioned. Take it to Wyda in the Venore swamps.')
                );
                return;
              }
              const hasOrb = hasOrbInInventory() || ((await getQuestItems(false))?.[ORB_CONFIG.productName] || 0) > 0;
              if (hasOrb && (mentionsOrb || mentionsOracle)) {
                if (mentionsOrb || isAffirmativeReply(lowerText)) {
                  // Asking with orb in inventory — prompt confirm, or exchange on orb keyword
                  if (mentionsOrb && !mentionsOracle) {
                    awaitingLostOracleOrbConfirm = false;
                    const ok = await exchangeOrbForLuminousOrb();
                    queueKingReply(
                      ok
                        ? getMissionDialogueLine(LOST_ORACLE_MISSION, 'kingOracleExchanged', 'Behold — a Luminous Orb. Guard it well; destiny is seldom gentle.')
                        : getMissionDialogueLine(LOST_ORACLE_MISSION, 'kingOracleNoOrb', 'Return when you have an Orb to offer.')
                    );
                    return;
                  }
                  awaitingLostOracleOrbConfirm = true;
                  queueKingReply(
                    getMissionDialogueLine(LOST_ORACLE_MISSION, 'kingOracleHasOrb', 'You carry an Orb. Shall I transform it into a Luminous Orb?')
                  );
                  return;
                }
              }
              queueKingReply(
                getMissionDialogueLine(LOST_ORACLE_MISSION, 'kingOracleAsk', 'An Oracle? Strange visions haunt my dreams of such a being. Bring me an Orb — I may yet unveil its true light.')
              );
              return;
            } catch (error) {
              console.error('[Quests Mod][King Tibianus] Error handling Lost Oracle dialogue:', error);
            }
          }
        }

        // Mission acceptance handler
        if (await handleMissionAcceptance(lowerText)) {
          return;
        }

        let kingResponse = '';
        
        const starterCoinResponse = await maybeHandleStarterCoin(lowerText);

        if (starterCoinResponse) {
          kingResponse = starterCoinResponse;
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
          NotificationService.showItemReceived(SILVER_TOKEN_CONFIG.productName, '[Quests Mod][King Tibianus]', TOAST_MESSAGES.kingTookCoin);
        } else if (areAllMissionsCompleted() && !canOfferHoneyflowerMission() && !canOfferCrossingTheLineMission() && (mentionsKey || mentionsDragon || mentionsMonks || mentionsHoneyflower || mentionsCrossing || mentionsMissionKeyword)) {
          // All missions completed, tell player to come back later
          kingResponse = 'All missions have been completed. Come back later for more tasks.';
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
        } else if (mentionsCrossing && !getHoneyflowerMissionProgress().completed) {
          kingResponse = 'Complete your current task for me first, then we may speak of further drills.';
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
        } else if (mentionsKey || mentionsDragon || mentionsLetter || mentionsMonks || mentionsScarab || mentionsHoneyflower || mentionsCrossing) {
          const hasHolyTibleForMonks = (cachedQuestItems && (cachedQuestItems['The Holy Tible'] || 0) > 0);
          if (mentionsMonks && !hasHolyTibleForMonks) {
            kingResponse = 'You must first complete the search for the Light and possess the Holy Tible before I can entrust you with that task.';
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else if (targetMission.id === AL_DEE_FISHING_MISSION.id || targetMission.id === AL_DEE_GOLDEN_ROPE_MISSION.id) {
            kingResponse = 'That mission belongs to Al Dee, the rope merchant in Rookgaard. You must speak with him to accept it.';
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else if (targetProgress.completed) {
            kingResponse = targetStrings.missionCompleted;
            kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
            kingChatState.offeredMission = null;
          } else if (targetProgress.accepted) {
            // Prefer mid-mission progress (e.g. stamp letter) or hand-in prompt.
            if (await tryProgressKingMission(targetMission)) {
              return;
            }

            setKingAwaitingKeyConfirm(targetMission);
            queueKingReply(targetStrings.keyQuestion);
            clearTextarea();
            return;
          } else if (targetMission.id === KING_COPPER_KEY_MISSION.id && !canOfferCopperKeyMission()) {
            kingResponse = KING_COPPER_KEY_MISSION.notExperiencedEnough;
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else if (targetMission.id === KING_SCARAB_COIN_MISSION.id && !(await hasLightShovelInInventory())) {
            kingResponse = KING_SCARAB_COIN_MISSION.requiresLightShovel
              || 'I have no task for thee at present. Come back later.';
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else {
            if (targetMission.id === KING_LETTER_MISSION.id) {
              const products = await getQuestItems(false);
              kingResponse = getLetterMissionOfferPrompt(targetMission, products);
            } else {
              kingResponse = targetStrings.missionPrompt;
            }
            setKingMissionOffered(targetMission);
          }
        } else if (mentionsMissionKeyword) {
          const honeyProgress = getHoneyflowerMissionProgress();
          const honeyStrings = buildStrings(KING_HONEYFLOWER_MISSION);
          const crossingProgress = getCrossingTheLineMissionProgress();
          const crossingStrings = buildStrings(KING_CROSSING_THE_LINE_MISSION);

          // Prefer any already-accepted mission that can progress (stamp letter, hand-in, etc.).
          if (await tryProgressAnyActiveKingMission()) {
            return;
          }

          if (canOfferHoneyflowerMission()) {
            if (honeyProgress.accepted) {
              kingResponse = honeyStrings.missionActive;
              kingChatState.missionOffered = false;
              kingChatState.offeredMission = null;
            } else {
              kingResponse = KING_HONEYFLOWER_MISSION.prompt;
              setKingMissionOffered(KING_HONEYFLOWER_MISSION);
            }
          } else if (canOfferCrossingTheLineMission()) {
            if (crossingProgress.accepted) {
              kingResponse = crossingStrings.missionActive;
              kingChatState.missionOffered = false;
              kingChatState.offeredMission = null;
            } else {
              kingResponse = KING_CROSSING_THE_LINE_MISSION.prompt;
              setKingMissionOffered(KING_CROSSING_THE_LINE_MISSION);
            }
          } else if (areAllMissionsCompleted() && !canOfferHoneyflowerMission() && !canOfferCrossingTheLineMission()) {
            kingResponse = 'All missions have been completed. Come back later for more tasks.';
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else if (currentProgress.completed) {
            kingResponse = kingStrings.missionCompleted;
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else if (currentProgress.accepted) {
            kingResponse = kingStrings.missionActive;
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else if (activeMission?.id === KING_COPPER_KEY_MISSION.id && !canOfferCopperKeyMission()) {
            kingResponse = KING_COPPER_KEY_MISSION.notExperiencedEnough;
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else if (activeMission?.id === KING_SCARAB_COIN_MISSION.id && !(await hasLightShovelInInventory())) {
            kingResponse = KING_SCARAB_COIN_MISSION.requiresLightShovel
              || 'I have no task for thee at present. Come back later.';
            kingChatState.missionOffered = false;
            kingChatState.offeredMission = null;
          } else {
            if (activeMission?.id === KING_LETTER_MISSION.id) {
              const products = await getQuestItems(false);
              kingResponse = getLetterMissionOfferPrompt(activeMission, products);
            } else {
              kingResponse = kingStrings.missionPrompt;
            }
            setKingMissionOffered(activeMission);
          }
        } else if (/\b(hi|hello|hey|greetings|good day)\b/.test(lowerText)) {
          kingResponse = applyPlayerNameSubstitution('I greet thee, my loyal subject Player.');
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
        } else {
          // Check transcript responses before falling back to confusion
          const transcriptResponse = await getKingTibianusResponse(text, playerName);
          if (transcriptResponse !== null) {
            // If we got a meaningful transcript response, use it
            kingResponse = transcriptResponse;
          } else {
            const questItemResponse = getNpcQuestItemChatResponse('king-tibianus', text, playerName);
            kingResponse = questItemResponse ?? getRandomConfusionResponse();
          }
          kingChatState.missionOffered = false;
          kingChatState.offeredMission = null;
        }
        
        // Queue response with cooldown
        tibianusCooldown.queueResponse(
          text,
          kingResponse,
          addMessageToConversation,
          'King Tibianus',
          ModalHelpers.getFarewellCloseCallback(text)
        );
        
        // Clear input
        clearTextarea();
        
      }
      
      sendButton.addEventListener('click', sendMessageToKing);
      
      inputRow.appendChild(textarea);
      inputRow.appendChild(sendButton);
      row3.appendChild(inputRow);
      
      // Footer with guild coins display
      const footer = document.createElement('div');
      footer.className = 'flex justify-end gap-2 items-center';
      footer.style.cssText = 'width: 100%;';
      customFooter = footer;

      const coinDisplay = document.createElement('div');
      coinDisplay.className = 'pixel-font-16 frame-pressed-1 surface-darker flex items-center justify-end gap-1 px-1.5 pb-px text-right text-whiteRegular mr-auto guild-coins-display';
      coinDisplay.style.cssText = 'box-sizing: border-box;';

      const coinImg = document.createElement('img');
      coinImg.src = guildCoinIconUrl;
      coinImg.alt = 'Guild Coins';
      coinImg.style.cssText = 'width: 16px; height: 16px;';

      guildCoinAmountSpan = document.createElement('span');
      guildCoinAmountSpan.className = 'guild-coins-amount';
      guildCoinAmountSpan.textContent = '...';

      coinDisplay.appendChild(coinImg);
      coinDisplay.appendChild(guildCoinAmountSpan);
      footer.appendChild(coinDisplay);

      const footerCloseBtn = document.createElement('button');
      footerCloseBtn.type = 'button';
      footerCloseBtn.textContent = 'Close';
      footerCloseBtn.className = 'focus-style-visible flex items-center justify-center tracking-wide text-whiteRegular disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1 active:frame-pressed-1 surface-regular gap-1 px-2 py-0.5 pb-[3px] pixel-font-14 [&_svg]:size-[11px] [&_svg]:mb-[1px] [&_svg]:mt-[2px]';
      footerCloseBtn.style.cssText = 'cursor: pointer; white-space: nowrap; box-sizing: border-box; max-height: 21px; height: 21px; font-size: 14px;';
      footerCloseBtn.addEventListener('click', () => {
        clearQuestsModalLayoutCleanup();
        if (modalRef?.close) {
          modalRef.close();
        } else {
          const dialog = document.querySelector('div[role="dialog"][data-state="open"]');
          if (dialog && dialog.parentNode) {
            dialog.parentNode.removeChild(dialog);
          } else {
            closeDialogWithFallback(0);
          }
        }
      });
      footer.appendChild(footerCloseBtn);

      modalContent.appendChild(row1);
      modalContent.appendChild(row2);
      modalContent.appendChild(row3);

      const footerContainer = document.createElement('div');
      footerContainer.style.cssText = 'display: flex; flex-direction: column; gap: 0; width: 100%;';

      const separator = document.createElement('div');
      separator.className = 'separator my-2.5';
      separator.setAttribute('role', 'none');
      customSeparator = separator;
      footerContainer.appendChild(separator);

      footerContainer.appendChild(footer);
      modalContent.appendChild(footerContainer);

      renderKingQuestUI();
      updateGuildCoinDisplay();

      contentDiv.appendChild(modalContent);
      
      const kingDims = getQuestsModalDimensions(
        KING_TIBI_MODAL_WIDTH,
        KING_TIBI_MODAL_HEIGHT,
        QUESTS_MODAL_CONFIG.kingTibianus.minHeight
      );
      const modal = api.ui.components.createModal({
        title: 'King Tibianus',
        width: kingDims.width,
        height: kingDims.height,
        content: contentDiv,
        buttons: []
      });
      modalRef = modal;

      setupQuestsModalResponsiveLayout(
        modal,
        contentDiv,
        KING_TIBI_MODAL_WIDTH,
        KING_TIBI_MODAL_HEIGHT,
        QUESTS_MODAL_CONFIG.kingTibianus.minHeight,
        (dialog) => removeDefaultModalFooter(dialog)
      );

      loadKingTibianusProgress().then(() => {
        updateGuildCoinDisplay();
      }).catch((error) => {
        console.error('[Quests Mod][King Tibianus] Error loading progress after modal open:', error);
      });
      
      modalTimeout = null;
    }, 50);
  }

  // Shared inventory check functions for both King Tibianus and Al Dee handlers
  async function hasLightShovelInInventory() {
    try {
      const items = await getQuestItems(false);
      return (items && items['Light Shovel'] > 0);
    } catch (error) {
      console.error('[Quests Mod] Error checking Light Shovel in inventory:', error);
      return false;
    }
  }

  async function hasElvenhairRopeInInventory() {
    try {
      const items = await getQuestItems(false);
      return (items && items['Elvenhair Rope'] > 0);
    } catch (error) {
      console.error('[Quests Mod] Error checking Elvenhair Rope in inventory:', error);
      return false;
    }
  }

  // Migration function to convert old Dwarven Pickaxe to Light Shovel
  async function migrateDwarvenPickaxeToLightShovel() {
    try {
      console.log('[Quests Mod] Checking for Dwarven Pickaxe migration...');
      const items = await getQuestItems(false);

      if (items && items['Dwarven Pickaxe'] > 0) {
        console.log('[Quests Mod] Found Dwarven Pickaxe, migrating to Light Shovel...');

        // Consume the old Dwarven Pickaxe
        await consumeQuestItem('Dwarven Pickaxe', items['Dwarven Pickaxe']);

        // Add the new Light Shovel
        await addQuestItem('Light Shovel', items['Dwarven Pickaxe']);

        console.log('[Quests Mod] Successfully migrated', items['Dwarven Pickaxe'], 'Dwarven Pickaxe to Light Shovel');
      } else {
        console.log('[Quests Mod] No Dwarven Pickaxe found, no migration needed');
      }
    } catch (error) {
      console.error('[Quests Mod] Error during Dwarven Pickaxe migration:', error);
    }
  }

  // Al Dee Modal (similar to King Tibianus modal)
  async function showAlDeeModal() {
    await ensureQuestDialogueLoaded();
    // Clear any pending modal timeouts
    clearTimeoutOrInterval(modalTimeout);
    clearTimeoutOrInterval(dialogTimeout);

    // Close any existing modals first
    for (let i = 0; i < 2; i++) {
      document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true }));
    }

    modalTimeout = setTimeout(() => {
      const contentDiv = document.createElement('div');
      applyModalContentStyles(contentDiv, KING_TIBI_MODAL_WIDTH, KING_TIBI_MODAL_HEIGHT);
      contentDiv.classList.add('quests-king-chat-content');

      const alDeeIconUrl = getQuestItemsAssetUrl('Al_Dee.gif');

      // Create modal content with greeting message
      const modalContent = document.createElement('div');
      modalContent.className = 'quests-king-chat-body';
      modalContent.style.cssText = 'display: flex; flex-direction: column; gap: 12px; padding: 0; width: 100%; min-width: 0; height: 100%; box-sizing: border-box;';

      // Row 1: Top row with image and message
      const row1 = document.createElement('div');
      row1.className = 'quests-king-chat-row';
      row1.style.cssText = 'display: flex; flex-direction: row; align-items: stretch; width: 100%; min-width: 0; gap: 12px; align-self: stretch;';

      const imageContainer = document.createElement('div');
      imageContainer.className = 'container-slot surface-darker grid place-items-center overflow-hidden quests-king-chat-image';
      imageContainer.style.cssText = 'width: 110px; min-width: 110px; max-width: 110px; flex: 0 0 110px; height: 90px; padding: 0; align-self: stretch;';

      const alDeeImgWrapper = document.createElement('div');
      alDeeImgWrapper.style.cssText = 'width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; padding: 10px; box-sizing: border-box;';

      const alDeeImg = document.createElement('img');
      alDeeImg.src = alDeeIconUrl;
      alDeeImg.alt = 'Al Dee';
      alDeeImg.className = 'pixelated';
      alDeeImg.style.cssText = 'max-width: 100%; max-height: 100%; width: auto; height: auto; object-fit: contain; image-rendering: pixelated;';
      alDeeImgWrapper.appendChild(alDeeImg);
      imageContainer.appendChild(alDeeImgWrapper);
      setNpcModalPendingBadge(imageContainer, hasAlDeeQuestAction());

      const messageContainer = document.createElement('div');
      messageContainer.className = 'tooltip-prose pixel-font-16 frame-pressed-1 surface-dark flex w-full flex-col gap-1 p-2 text-whiteRegular quests-king-chat-messages';
      messageContainer.style.cssText = 'flex: 1 1 0; min-width: 0; width: auto; height: 90px; max-height: 90px; overflow-y: auto; box-sizing: border-box;';
      messageContainer.id = 'al-dee-messages';

      // Confusion responses for Al Dee (merchant style)
      function getRandomAlDeeConfusionResponse() {
        return getRandomNpcConfusionResponse(AL_DEE_CONFUSION_RESPONSES, getCurrentPlayerName() || 'Player');
      }

      // Al Dee mission chat state
      const alDeeChatState = {
        offeringFishingMission: false,
        awaitingAxeConfirm: false,
        offeringRopeMission: false,
        awaitingRopeConfirm: false,
        offeringRookieGuardMission: false,
        awaitingRookieGuardConfirm: false
      };

      function isAlDeeLetterMissionCompleted() {
        return !!getMissionProgress(KING_LETTER_MISSION).completed;
      }

      let fishingRodBuyButtonUpdater = null;
      function refreshFishingRodShopAvailability() {
        if (typeof fishingRodBuyButtonUpdater === 'function') {
          fishingRodBuyButtonUpdater();
        }
      }

      // Create cooldown manager for Al Dee conversation
      const alDeeCooldown = createNPCCooldownManager();

      // Function to add message to conversation
      let pendingAlDeeChunkTimeouts = [];
      function addMessageToConversation(sender, text, isAlDee = false, noChunk = false) {
        const appendOne = (chunkText) => {
          const messageP = document.createElement('p');
          messageP.className = 'inline text-monster';
          // Al Dee messages use the same style as initial greeting;
          // player messages use a lavender/purple color instead.
          messageP.style.color = isAlDee ? 'rgb(135, 206, 250)' : 'rgb(200, 180, 255)';
          messageP.textContent = sender + ': ' + chunkText;

          messageContainer.appendChild(messageP);

          // Scroll to bottom
          setTimeout(() => {
            messageContainer.scrollTop = messageContainer.scrollHeight;
          }, 0);
        };

        // See King Tibianus' addMessageToConversation above for why this matters: cancel
        // any not-yet-delivered chunk of a previous long message before scheduling new
        // ones, so a stale trailing sentence can't appear after a reply that already
        // moved the conversation past it.
        pendingAlDeeChunkTimeouts.forEach((id) => clearTimeout(id));
        pendingAlDeeChunkTimeouts = [];

        if (isAlDee && !noChunk) {
          pendingAlDeeChunkTimeouts = scheduleChunkedDialogue(appendOne, text);
        } else {
          appendOne(text);
        }
      }

      // Add welcome message
      const playerName = getCurrentPlayerName() || 'Player';
      const welcomeMessage = 'Hello, hello, ' + playerName + '! Please come in, look, and buy! I\'m a specialist for all sorts of tools. Just ask me for a trade to see my offers!';
      addMessageToConversation('Al Dee', welcomeMessage, true, true);

      row1.appendChild(imageContainer);
      row1.appendChild(messageContainer);

      // Row 2: Shop interface
      const row2 = document.createElement('div');
      row2.className = 'quests-king-chat-main';
      row2.style.cssText = 'display: grid; grid-template-rows: repeat(auto-fill, 60px); align-items: start; gap: 8px; padding: 8px; background: rgba(0, 0, 0, 0.3); border-radius: 4px; flex: 1 1 0; min-height: 0; min-width: 0; width: 100%; max-width: 100%; overflow-y: auto; box-sizing: border-box;';

      // Function to create a shop item
      function createShopItem(iconName, itemName, price, displayName, itemId) {
        const shopItem = document.createElement('div');
        shopItem.style.cssText = 'display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 4px; background: rgba(255, 255, 255, 0.05); border-radius: 2px; height: 60px; box-sizing: border-box;';

        // Item icon container
        const itemIconContainer = document.createElement('div');
        itemIconContainer.className = 'container-slot surface-darker grid place-items-center overflow-hidden';
        itemIconContainer.style.cssText = 'width: 34px; height: 34px; flex-shrink: 0;';

        // iconName may be a board sprite id (number) or a quests asset filename.
        const shopSpriteId = (typeof iconName === 'number' || /^\d+$/.test(String(iconName))) ? Number(iconName) : null;
        let itemIcon;
        if (shopSpriteId != null) {
          itemIcon = document.createElement('div');
          itemIcon.className = `sprite item relative id-${shopSpriteId}`;
          itemIcon.style.cssText = 'width: 32px; height: 32px; overflow: hidden; flex-shrink: 0;';
          itemIcon.innerHTML = `<div class="viewport" style="width:100%;height:100%;overflow:hidden;"><img alt="${shopSpriteId}" data-cropped="false" class="spritesheet" style="--cropX: 0; --cropY: 0;"></div>`;
        } else {
          itemIcon = document.createElement('img');
          itemIcon.src = getQuestItemsAssetUrl(iconName);
          itemIcon.alt = itemName;
          itemIcon.className = 'pixelated';
          itemIcon.style.cssText = 'width: 32px; height: 32px; object-fit: contain; image-rendering: pixelated;';
        }
        itemIconContainer.appendChild(itemIcon);

        // Item name and price container
        const infoContainer = document.createElement('div');
        infoContainer.style.cssText = 'display: flex; flex-direction: column; flex: 1; min-width: 0;';

        const itemNameDisplay = document.createElement('div');
        itemNameDisplay.className = 'pixel-font-12 text-whiteRegular';
        itemNameDisplay.textContent = displayName;
        itemNameDisplay.style.cssText = 'font-weight: bold; margin-bottom: 2px;';

        const priceDisplay = document.createElement('div');
        priceDisplay.className = 'pixel-font-12 text-whiteRegular';
        priceDisplay.textContent = price + ' guild coins';
        priceDisplay.style.cssText = 'display: flex; align-items: center; gap: 2px;';

        // Guild coin icon for price
        const coinIcon = document.createElement('img');
        coinIcon.src = cachedExtensionBaseUrl ? constructUrl(cachedExtensionBaseUrl, '/assets/ot/Guild_Coin.png') : '/assets/ot/Guild_Coin.png';
        coinIcon.alt = 'Guild Coin';
        coinIcon.className = 'pixelated';
        coinIcon.style.cssText = 'width: 12px; height: 12px; object-fit: contain; image-rendering: pixelated;';
        priceDisplay.insertBefore(coinIcon, priceDisplay.firstChild);

        infoContainer.appendChild(itemNameDisplay);
        infoContainer.appendChild(priceDisplay);

        // Buy button
        const buyButton = document.createElement('button');
        buyButton.type = 'button';
        buyButton.className = 'focus-style-visible flex items-center justify-center tracking-wide text-whiteRegular disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1 active:frame-pressed-1 surface-regular gap-1 px-2 py-0.5 pixel-font-12';
        buyButton.style.cssText = 'cursor: pointer; white-space: nowrap; box-sizing: border-box; height: 24px; font-size: 12px; flex-shrink: 0;';

        // Check if item has been purchased. Every Al Dee shop item is a unique one-time
        // buy (Fishing Rod etc.), so already OWNING one — from any source — must also block
        // the purchase. When we detect that, back-fill the Firebase "bought" flag so it
        // sticks even if the player later drops the item.
        const playerName = getCurrentPlayerName();
        const ownsShopItem = () => getCachedQuestItemCount(displayName) > 0;
        let isPurchased = ownsShopItem();
        if (playerName) {
          Promise.all([
            getAlDeeShopPurchases(playerName).catch(() => ({})),
            getQuestItems(false).catch(() => null)
          ]).then(([purchases, freshItems]) => {
            const owns = ownsShopItem() || !!(freshItems && (freshItems[displayName] || 0) > 0);
            const flagged = purchases[itemId] === true;
            isPurchased = flagged || owns;
            if (owns && !flagged) {
              saveAlDeeShopPurchase(playerName, itemId, true).catch((err) =>
                console.warn('[Quests Mod][Al Dee Shop] Could not back-fill purchase flag:', err));
            }
            updateButtonState();
          }).catch(() => {
            updateButtonState();
          });
        }

        const requiresLetterComplete = itemId === 'fishing_rod';

        function updateButtonState() {
          if (isPurchased) {
            buyButton.textContent = 'Bought';
            buyButton.disabled = true;
            buyButton.style.filter = 'grayscale(100%)';
            buyButton.style.opacity = '0.6';
            return;
          }
          if (requiresLetterComplete && !isAlDeeLetterMissionCompleted()) {
            buyButton.textContent = 'Locked';
            buyButton.disabled = true;
            buyButton.style.filter = 'grayscale(100%)';
            buyButton.style.opacity = '0.6';
            return;
          }
          buyButton.textContent = 'Buy';
          buyButton.disabled = false;
          buyButton.style.filter = '';
          buyButton.style.opacity = '';
        }

        // Initialize button state
        updateButtonState();
        if (requiresLetterComplete) {
          fishingRodBuyButtonUpdater = updateButtonState;
        }

        // Buy button click handler
        buyButton.addEventListener('click', async () => {
          try {
            if (requiresLetterComplete && !isAlDeeLetterMissionCompleted()) {
              addMessageToConversation(
                'Al Dee',
                AL_DEE_FISHING_MISSION.requiresLetterForFishingRod
                  || 'I only sell fishing rods to those who\'ve finished delivering the king\'s stamped letter to me.',
                true
              );
              return;
            }

            // Unique item — refuse (and heal the flag) if the player already owns one.
            const ownedNow = await getQuestItems(false).catch(() => null);
            if (isPurchased || ownsShopItem() || (ownedNow && (ownedNow[displayName] || 0) > 0)) {
              isPurchased = true;
              updateButtonState();
              if (playerName) {
                saveAlDeeShopPurchase(playerName, itemId, true).catch(() => {});
              }
              addMessageToConversation(
                'Al Dee',
                (itemId === 'fishing_rod' && AL_DEE_FISHING_MISSION.alreadyOwnsFishingRod)
                  || `You already have a ${displayName.toLowerCase()} — I only sell one to a customer.`,
                true
              );
              return;
            }

            // Check if player has enough guild coins
            const coinsGetter = globalThis.getGuildCoins ||
              (globalThis.Guilds && globalThis.Guilds.getGuildCoins) ||
              (globalThis.BestiaryModAPI && globalThis.BestiaryModAPI.guilds && globalThis.BestiaryModAPI.guilds.getGuildCoins) ||
              (typeof getGuildCoins === 'function' ? getGuildCoins : null);

            if (!coinsGetter) {
              addMessageToConversation('Al Dee', 'Sorry, I cannot check your guild coins right now.', true);
              return;
            }

            const currentCoins = await coinsGetter();
            if (currentCoins < price) {
              addMessageToConversation('Al Dee', `You don't have enough guild coins! You need ${price} guild coins to buy ${displayName.toLowerCase()}.`, true);
              return;
            }

            // Deduct coins and give item
            const coinsDeduct = globalThis.deductGuildCoins ||
              (globalThis.Guilds && globalThis.Guilds.deductGuildCoins) ||
              (globalThis.BestiaryModAPI && globalThis.BestiaryModAPI.guilds && globalThis.BestiaryModAPI.guilds.deductGuildCoins) ||
              (typeof deductGuildCoins === 'function' ? deductGuildCoins : null);

            if (coinsDeduct) {
              await coinsDeduct(price); // Deduct coins

              // Add item to quest items inventory
              try {
                await addQuestItem(displayName, 1);
                console.log('[Al Dee Shop] Added', displayName, 'to quest items inventory');
              } catch (inventoryError) {
                console.error('[Al Dee Shop] Error adding item to inventory:', inventoryError);
              }

              // Mark as purchased in Firebase
              await saveAlDeeShopPurchase(playerName, itemId, true);

              // Update button state
              isPurchased = true;
              updateButtonState();

              addMessageToConversation('Al Dee', `Thank you for your business! Here's your ${displayName.toLowerCase()}.`, true);

              // Update guild coin display
              updateGuildCoinDisplay();

              // Refresh quest items modal if it's open
              refreshQuestItemsModal();
            } else {
              addMessageToConversation('Al Dee', 'Sorry, there seems to be an issue with deducting guild coins.', true);
            }
          } catch (error) {
            console.error('[Al Dee Shop] Error processing purchase:', error);
            addMessageToConversation('Al Dee', 'Sorry, something went wrong with the purchase.', true);
          }
        });

        // Assemble the shop item
        shopItem.appendChild(itemIconContainer);
        shopItem.appendChild(infoContainer);
        shopItem.appendChild(buyButton);

        return shopItem;
      }

      // Add shop items to the grid
      row2.appendChild(createShopItem(3483, 'Fishing Rod', 100, 'Fishing Rod', 'fishing_rod'));

      // Row 3: Chat input area (matches King Tibianus exactly)
      const row3 = document.createElement('div');
      row3.style.cssText = `
        padding: 0;
        border-top: 0;
        margin: 0;
        background: rgba(255, 255, 255, 0.05);
        display: flex;
        flex-direction: column;
        gap: 2px;
        flex-shrink: 0;
      `;

      const inputRow = document.createElement('div');
      inputRow.style.cssText = 'display: flex; gap: 6px; align-items: center;';

      const textarea = document.createElement('textarea');
      textarea.className = 'king-tibianus-chat-input';
      textarea.setAttribute('wrap', 'off');
      textarea.placeholder = 'Type your message to Al Dee...';
      textarea.style.cssText = `
        flex: 1;
        height: 28px;
        max-height: 28px;
        min-height: 28px;
        padding: 4px 6px;
        background-color: #333;
        border: 4px solid transparent;
        border-image: url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill;
        color: rgb(255, 255, 255);
        font-family: inherit;
        font-size: 13px;
        line-height: 18px;
        resize: none;
        box-sizing: border-box;
        line-height: 1.2;
        white-space: nowrap;
        overflow-x: hidden;
        overflow-y: hidden;
        outline: none;
      `;

      // Handle Enter key and focus/blur events like King Tibianus
      textarea.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          sendMessageToAlDee();
        }
      });

      // Remove focus outline/border
      textarea.addEventListener('focus', () => {
        textarea.style.outline = 'none';
        textarea.style.borderImage = 'url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill';
      });

      textarea.addEventListener('blur', () => {
        textarea.style.outline = 'none';
        textarea.style.borderImage = 'url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill';
      });
      // Handle Enter key
      textarea.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          sendMessageToAlDee();
        }
      });

      const sendButton = document.createElement('button');
      sendButton.textContent = 'Send';
      sendButton.className = 'primary';
      sendButton.style.cssText = `
        height: 28px;
        padding: 4px 10px;
        white-space: nowrap;
        font-size: 13px;
        line-height: 16px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: url('https://bestiaryarena.com/_next/static/media/background-blue.7259c4ed.png') center center / cover;
        border: 4px solid transparent;
        border-image: url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill;
        color: rgb(255, 255, 255);
        cursor: pointer;
        font-family: inherit;
      `;

      async function sendMessageToAlDee() {
        const text = textarea.value.trim();
        if (!text || text.length === 0) {
          return;
        }

        // Get player name
        const playerName = getCurrentPlayerName() || 'Player';
        const lowerText = text.toLowerCase();

        // Add player message to conversation
        addMessageToConversation(playerName, text, false);

        // Clear any pending response timeout
        alDeeCooldown.clearPendingResponse();

        // Clear input
        textarea.value = '';

        if (lowerText.includes('magnet')) {
          try {
            const currentProducts = await getQuestItems();
            const hasMagnet = (currentProducts['Magnet'] || 0) > 0;
            const fishingProgress = getMissionProgress(AL_DEE_FISHING_MISSION);
            const onFishingMission = fishingProgress.accepted && !fishingProgress.completed;

            let magnetResponse;
            if (hasMagnet) {
              magnetResponse = onFishingMission
                ? 'You already have a magnet! Try your fishing rod in the cave waters where goblins roam — it may pull my Small Axe from the depths.'
                : 'A magnet is handy for pulling metal from water. I do not sell them myself.';
            } else {
              magnetResponse = onFishingMission
                ? 'You will need a magnet to fish my Small Axe out of those waters. King Tibianus may give you one if you help him with a task in Rookgaard.'
                : 'I do not sell magnets. King Tibianus might reward you with one if you bring him iron ore from Rookgaard.';
            }

            alDeeCooldown.queueResponse(
              text,
              magnetResponse,
              addMessageToConversation,
              'Al Dee'
            );
            return;
          } catch (error) {
            console.error('[Quests Mod][Al Dee] Error handling magnet keyword:', error);
          }
        }

        // Prefer handing in the stamped letter before any other Al Dee progress.
        async function tryDeliverStampedLetterToAlDee(playerNameForMsg, sourceText) {
          try {
            if (isAlDeeLetterMissionCompleted()) return false;
            const currentProducts = await getQuestItems();
            const hasStampedLetter = (currentProducts['Stamped Letter'] || 0) > 0;
            if (!hasStampedLetter) return false;

            await consumeQuestItem('Stamped Letter', 1);
            console.log('[Quests Mod][Al Dee] Stamped Letter delivered, consuming from inventory');
            NotificationService.showItemReceived('Stamped Letter', '[Quests Mod][Al Dee]', TOAST_MESSAGES.deliveredTo('Al Dee'));

            const coinsAdder = globalThis.addGuildCoins ||
              (globalThis.Guilds && globalThis.Guilds.addGuildCoins) ||
              (globalThis.BestiaryModAPI && globalThis.BestiaryModAPI.guilds && globalThis.BestiaryModAPI.guilds.addGuildCoins) ||
              (typeof addGuildCoins === 'function' ? addGuildCoins : null);

            if (coinsAdder && KING_LETTER_MISSION.rewardCoins > 0) {
              await coinsAdder(KING_LETTER_MISSION.rewardCoins);
              console.log(`[Quests Mod][Al Dee] Awarded ${KING_LETTER_MISSION.rewardCoins} guild coins for letter delivery`);
            } else {
              console.warn('[Quests Mod][Al Dee] addGuildCoins not available, skipping guild coin reward');
            }

            setMissionProgress(KING_LETTER_MISSION, { accepted: true, completed: true });
            console.log('[Quests Mod][Al Dee] Letter delivery mission completed');
            NotificationService.showQuestCompleted(
              KING_LETTER_MISSION,
              '[Quests Mod][Al Dee]',
              KING_LETTER_MISSION.rewardCoins > 0 ? { rewardCoins: KING_LETTER_MISSION.rewardCoins } : undefined
            );

            try {
              const afterProducts = await getQuestItems(false);
              const letterCount = afterProducts['Letter from Al Dee'] || 0;
              if (letterCount > 0) {
                await consumeQuestItem('Letter from Al Dee', letterCount);
                console.log('[Quests Mod][Al Dee] Removed Letter from Al Dee from inventory (unique item, quest completed)');
              }
            } catch (error) {
              console.error('[Quests Mod][Al Dee] Error removing Letter from Al Dee:', error);
            }

            const saveName = getCurrentPlayerName();
            if (saveName) {
              await saveKingTibianusProgress(saveName, getAllMissionProgress());
              console.log('[Quests Mod][Al Dee] Letter mission progress saved to Firebase');
            }

            if (typeof updateTile79RightClickState === 'function') {
              updateTile79RightClickState();
              console.log('[Quests Mod][Al Dee] Tile 79 state updated after mission completion');
            }

            updateGuildCoinDisplay();
            refreshFishingRodShopAvailability();
            refreshBoardNpcsAfterQuestItemsChange();

            alDeeCooldown.queueResponse(
              sourceText,
              'Ah, finally! The king\'s stamped letter. Thank you for delivering it, ' + playerNameForMsg + '. Here\'s 50 guild coins as a reward for your service.',
              addMessageToConversation,
              'Al Dee'
            );
            return true;
          } catch (error) {
            console.error('[Quests Mod][Al Dee] Error checking/delivering stamped letter:', error);
            return false;
          }
        }

        // Check for stamped letter delivery mission
        if (lowerText.includes('letter') || lowerText.includes('deliver') || lowerText.includes('king') || lowerText.includes('tibianus')) {
          if (await tryDeliverStampedLetterToAlDee(playerName, text)) {
            return;
          }
        }

        // Check for fishing mission keywords and Small Axe return
        // Mission acceptance ("yes" to a new offer) must win over a stale axe hand-in confirm.
        const acceptingNewAlDeeMission = lowerText.includes('yes')
          && (alDeeChatState.offeringFishingMission || alDeeChatState.offeringRopeMission);
        if (!acceptingNewAlDeeMission && (
            lowerText.includes('small axe') || lowerText.includes('axe') ||
            (lowerText.includes('yes') && alDeeChatState.awaitingAxeConfirm))) {
          try {
            const currentProducts = await getQuestItems();
            const hasSmallAxe = (currentProducts['Small Axe'] || 0) > 0;

            if (hasSmallAxe) {
              // Remove the Small Axe from inventory
              await consumeQuestItem('Small Axe', 1);
              NotificationService.showItemReceived('Small Axe', '[Quests Mod][Al Dee]', TOAST_MESSAGES.returnedTo('Al Dee'));
              console.log('[Quests Mod][Al Dee] Small Axe returned, consuming from inventory');
              alDeeChatState.awaitingAxeConfirm = false;

              // Award Light Shovel
              try {
                await addQuestItem('Light Shovel', 1);
                showQuestItemNotification('Light Shovel', 1);
                console.log('[Quests Mod][Al Dee] Awarded Light Shovel for axe return');
              } catch (error) {
                console.error('[Quests Mod][Al Dee] Error awarding Light Shovel:', error);
              }

              // Mark mission as completed
              setMissionProgress(AL_DEE_FISHING_MISSION, { accepted: true, completed: true });
              NotificationService.showQuestCompleted(AL_DEE_FISHING_MISSION, '[Quests Mod][Al Dee]');
              fishingState.ironOreQuestActive = false;
              fishingState.ironOreQuestExpired = false;
              fishingState.ironOreQuestCompleted = true;
              fishingState.ironOreQuestStartTime = null;
              console.log('[Quests Mod][Al Dee] Fishing mission completed');

              // Save progress to Firebase
              if (playerName) {
                await saveKingTibianusProgress(playerName, getAllMissionProgress());
                console.log('[Quests Mod][Al Dee] Fishing mission progress saved to Firebase');
              }

              await cleanupInvalidQuestItems(getAllMissionProgress());
              await refreshQuestItemsModal();

              // Update guild coin display
              updateGuildCoinDisplay();

              // Queue response with cooldown
              alDeeCooldown.queueResponse(
                text,
                getMissionCompleteLine(AL_DEE_FISHING_MISSION),
                addMessageToConversation,
                'Al Dee'
              );

              return; // Exit early, don't show regular transcript response
            } else if (alDeeChatState.awaitingAxeConfirm) {
              // Player said yes but has no Small Axe
              alDeeCooldown.queueResponse(
                text,
                AL_DEE_FISHING_MISSION.missingItem,
                addMessageToConversation,
                'Al Dee'
              );

              alDeeChatState.awaitingAxeConfirm = false;
              return;
            }
          } catch (error) {
            console.error('[Quests Mod][Al Dee] Error handling fishing mission:', error);
          }
        }

        // Handle golden rope mission completion
          // Check for "yes" when awaiting rope confirmation (must be checked before other "yes" handlers)
          if (lowerText.includes('yes') && alDeeChatState.awaitingRopeConfirm) {
            try {
              // Player claims to have the elvenhair rope
              const currentProducts = await getQuestItems();
              const hasRope = (currentProducts['Elvenhair Rope'] || 0) > 0;

              if (hasRope) {
                // Verify that Mornenion was defeated before allowing completion
                const mornenionDefeated = await isMornenionDefeated();
                if (!mornenionDefeated) {
                  console.log('[Quests Mod][Al Dee] Player has rope but Mornenion not defeated');
                  alDeeCooldown.queueResponse(
                    text,
                    'You have the rope, but you must first defeat Mornenion in the depths below!',
                    addMessageToConversation,
                    'Al Dee'
                  );
                  alDeeChatState.awaitingRopeConfirm = false;
                  return;
                }

                console.log('[Quests Mod][Al Dee] Elvenhair rope returned, consuming from inventory');

                // Consume elvenhair rope from inventory
                try {
                  await consumeQuestItem('Elvenhair Rope', 1);
                  console.log('[Quests Mod][Al Dee] Elvenhair rope consumed from inventory');
                } catch (error) {
                  console.error('[Quests Mod][Al Dee] Error consuming elvenhair rope:', error);
                }

                // Award The Holy Tible as reward
                try {
                  await addQuestItem('The Holy Tible', 1);
                  showQuestItemNotification('The Holy Tible', 1);
                  console.log('[Quests Mod][Al Dee] Awarded The Holy Tible for golden rope mission completion');
                } catch (error) {
                  console.error('[Quests Mod][Al Dee] Error awarding The Holy Tible:', error);
                }

                // Mark mission as completed
                setMissionProgress(AL_DEE_GOLDEN_ROPE_MISSION, { accepted: true, completed: true });
                NotificationService.showQuestCompleted(AL_DEE_GOLDEN_ROPE_MISSION, '[Quests Mod][Al Dee]');
                console.log('[Quests Mod][Al Dee] Golden rope mission completed');

                // Save progress to Firebase using registry (future-proof)
                if (playerName) {
                  // Fetch existing progress to preserve mornenion field
                  const existingProgress = await getKingTibianusProgress(playerName);
                  const allProgress = getAllMissionProgress();
                  
                  // Include ironOre if it exists in fishingState
                  if (fishingState.ironOreQuestActive !== undefined || fishingState.ironOreQuestCompleted) {
                    allProgress.ironOre = {
                      active: fishingState.ironOreQuestActive || false,
                      startTime: fishingState.ironOreQuestStartTime || null,
                      completed: fishingState.ironOreQuestCompleted || false
                    };
                  }
                  
                  // Set Mornenion as defeated when golden rope mission is completed
                  // (completing this mission means Mornenion was defeated to obtain the rope)
                  kingChatState.mornenionDefeated = true;
                  allProgress.mornenion = { defeated: true };
                  console.log('[Quests Mod][Al Dee] Mornenion marked as defeated - golden rope mission completed');
                  
                  await saveKingTibianusProgress(playerName, allProgress);
                  console.log('[Quests Mod][Al Dee] Golden rope mission progress saved to Firebase');
                }

                // Update guild coin display
                updateGuildCoinDisplay();

                // Queue response with cooldown
                alDeeCooldown.queueResponse(
                  text,
                  getMissionCompleteLine(AL_DEE_GOLDEN_ROPE_MISSION),
                  addMessageToConversation,
                  'Al Dee'
                );

                alDeeChatState.awaitingRopeConfirm = false;
                return; // Exit early, don't show regular transcript response
              } else {
                // Player said yes but has no elvenhair rope
                alDeeCooldown.queueResponse(
                  text,
                  AL_DEE_GOLDEN_ROPE_MISSION.missingItem,
                  addMessageToConversation,
                  'Al Dee'
                );

                alDeeChatState.awaitingRopeConfirm = false;
                return;
              }
            } catch (error) {
              console.error('[Quests Mod][Al Dee] Error handling golden rope mission:', error);
            }
          }

        // Handle Rookie Guard mission report-in (must be checked before other "yes" handlers)
        if (lowerText.includes('yes') && alDeeChatState.awaitingRookieGuardConfirm) {
          try {
            const rookieGuardProgress = getMissionProgress(AL_DEE_ROOKIE_GUARD_MISSION);
            if (rookieGuardProgress.battleCompleted) {
              try {
                await addQuestItem('Knarknaknork Soul Core', 1);
                showQuestItemNotification('Knarknaknork Soul Core', 1);
                console.log('[Quests Mod][Al Dee] Awarded Knarknaknork Soul Core for Rookie Guard mission completion');
              } catch (error) {
                console.error('[Quests Mod][Al Dee] Error awarding Knarknaknork Soul Core:', error);
              }

              setMissionProgress(AL_DEE_ROOKIE_GUARD_MISSION, { accepted: true, completed: true, battleCompleted: true });
              NotificationService.showQuestCompleted(AL_DEE_ROOKIE_GUARD_MISSION, '[Quests Mod][Al Dee]');
              console.log('[Quests Mod][Al Dee] Rookie Guard mission completed');

              if (playerName) {
                await saveKingTibianusProgress(playerName, getAllMissionProgress());
                console.log('[Quests Mod][Al Dee] Rookie Guard mission progress saved to Firebase');
              }

              alDeeCooldown.queueResponse(
                text,
                getMissionCompleteLine(AL_DEE_ROOKIE_GUARD_MISSION),
                addMessageToConversation,
                'Al Dee'
              );

              alDeeChatState.awaitingRookieGuardConfirm = false;
              return; // Exit early, don't show regular transcript response
            } else {
              // Player said yes but hasn't defeated Knarknaknork yet
              alDeeCooldown.queueResponse(
                text,
                AL_DEE_ROOKIE_GUARD_MISSION.missingItem,
                addMessageToConversation,
                'Al Dee'
              );

              alDeeChatState.awaitingRookieGuardConfirm = false;
              return;
            }
          } catch (error) {
            console.error('[Quests Mod][Al Dee] Error handling Rookie Guard mission:', error);
          }
        }

        // Check for mission acceptance
        if (lowerText.includes('yes') && alDeeChatState.offeringFishingMission) {
          if (!isAlDeeLetterMissionCompleted()) {
            alDeeChatState.offeringFishingMission = false;
            alDeeCooldown.queueResponse(
              text,
              AL_DEE_FISHING_MISSION.requiresLetterComplete
                || 'Before I set you another task, bring me the king\'s stamped letter. Deliver that first, then we can talk.',
              addMessageToConversation,
              'Al Dee'
            );
            return;
          }

          // Start the fishing mission
          setMissionProgress(AL_DEE_FISHING_MISSION, { accepted: true, completed: false });
          
          // Queue response with cooldown
          alDeeCooldown.queueResponse(
            text,
            AL_DEE_FISHING_MISSION.accept,
            addMessageToConversation,
            'Al Dee'
          );

          alDeeChatState.offeringFishingMission = false;

          // Save progress
          if (playerName) {
            await saveKingTibianusProgress(playerName, getAllMissionProgress());
            console.log('[Quests Mod][Al Dee] Fishing mission accepted, progress saved to Firebase');
          }

          return;
        }

        // Check for golden rope mission acceptance
        if (lowerText.includes('yes') && alDeeChatState.offeringRopeMission) {
          // Start the golden rope mission
          setMissionProgress(AL_DEE_GOLDEN_ROPE_MISSION, { accepted: true, completed: false });
          
          // Queue response with cooldown
          alDeeCooldown.queueResponse(
            text,
            AL_DEE_GOLDEN_ROPE_MISSION.accept,
            addMessageToConversation,
            'Al Dee'
          );

          alDeeChatState.offeringRopeMission = false;
          alDeeChatState.awaitingAxeConfirm = false;
          alDeeChatState.awaitingRopeConfirm = false;

          // Save progress — always persist the full local snapshot
          if (playerName) {
            try {
              await saveKingTibianusProgress(playerName, getAllMissionProgress());
              console.log('[Quests Mod][Al Dee] Golden rope mission accepted, progress saved to Firebase', {
                alDeeGoldenRope: kingChatState.progressAlDeeGoldenRope
              });
            } catch (error) {
              console.error('[Quests Mod][Al Dee] Error saving golden rope mission progress:', error);
            }
          }

          return;
        }

        // Check for Rookie Guard mission acceptance
        if (lowerText.includes('yes') && alDeeChatState.offeringRookieGuardMission) {
          // Start the Rookie Guard mission
          setMissionProgress(AL_DEE_ROOKIE_GUARD_MISSION, { accepted: true, completed: false, battleCompleted: false });

          // Queue response with cooldown
          alDeeCooldown.queueResponse(
            text,
            AL_DEE_ROOKIE_GUARD_MISSION.accept,
            addMessageToConversation,
            'Al Dee'
          );

          alDeeChatState.offeringRookieGuardMission = false;
          alDeeChatState.awaitingRookieGuardConfirm = false;

          if (playerName) {
            try {
              await saveKingTibianusProgress(playerName, getAllMissionProgress());
              console.log('[Quests Mod][Al Dee] Rookie Guard mission accepted, progress saved to Firebase');
            } catch (error) {
              console.error('[Quests Mod][Al Dee] Error saving Rookie Guard mission progress:', error);
            }
          }

          if (typeof updateSewersPortalState === 'function') updateSewersPortalState();

          return;
        }

        // Check for golden rope mission keywords (rope/elvenhair rope)
        // If mission is active, player has rope, and Mornenion is defeated, ask if they want to return it
        if ((lowerText.includes('elvenhair rope') || lowerText.includes('rope')) && 
            !lowerText.includes('yes') && !alDeeChatState.awaitingRopeConfirm) {
          try {
            const missionProgress = getMissionProgress(AL_DEE_GOLDEN_ROPE_MISSION);
            // Only handle if mission is accepted but not completed
            if (missionProgress.accepted && !missionProgress.completed) {
              const currentProducts = await getQuestItems();
              const hasRope = (currentProducts['Elvenhair Rope'] || 0) > 0;
              
              if (hasRope) {
                const mornenionDefeated = await isMornenionDefeated();
                // If player has the rope, they must have defeated Mornenion (rope is only obtained from victory)
                // So we can proceed to ask if they want to return it
                // However, we still verify the flag is set for proper quest tracking
                if (mornenionDefeated) {
                  // Ask if they want to return the rope
                  alDeeChatState.awaitingRopeConfirm = true;
                  alDeeCooldown.queueResponse(
                    text,
                    AL_DEE_GOLDEN_ROPE_MISSION.askForItem.replace('Player', playerName),
                    addMessageToConversation,
                    'Al Dee'
                  );
                  return; // Exit early, don't show regular transcript response
                } else {
                  // Player has rope but flag not set - this shouldn't happen normally
                  // But if it does (e.g., dev command), set the flag and proceed
                  console.warn('[Quests Mod][Al Dee] Player has rope but Mornenion flag not set - setting flag and proceeding');
                  const playerNameForFlag = getCurrentPlayerName();
                  if (playerNameForFlag) {
                    try {
                      const existingProgress = await getKingTibianusProgress(playerNameForFlag);
                      const mergedProgress = {
                        ...existingProgress,
                        mornenion: {
                          defeated: true
                        }
                      };
                      await saveKingTibianusProgress(playerNameForFlag, mergedProgress);
                      console.log('[Quests Mod][Al Dee] Mornenion defeated flag set retroactively');
                    } catch (error) {
                      console.error('[Quests Mod][Al Dee] Error setting Mornenion flag:', error);
                    }
                  }
                  // Now ask if they want to return the rope
                  alDeeChatState.awaitingRopeConfirm = true;
                  alDeeCooldown.queueResponse(
                    text,
                    AL_DEE_GOLDEN_ROPE_MISSION.askForItem.replace('Player', playerName),
                    addMessageToConversation,
                    'Al Dee'
                  );
                  return; // Exit early, don't show regular transcript response
                }
              }
            }
          } catch (error) {
            console.error('[Quests Mod][Al Dee] Error handling rope keyword:', error);
          }
        }

        // Check for mission offer trigger
        if (lowerText.includes('mission') || lowerText.includes('missions') ||
            lowerText.includes('task') || lowerText.includes('quest') || lowerText.includes('help')) {
          // Deliver stamped letter first if the player still has it.
          if (await tryDeliverStampedLetterToAlDee(playerName, text)) {
            return;
          }

          if (!isAlDeeLetterMissionCompleted()) {
            alDeeCooldown.queueResponse(
              text,
              AL_DEE_FISHING_MISSION.requiresLetterComplete
                || 'Before I set you another task, bring me the king\'s stamped letter. Deliver that first, then we can talk.',
              addMessageToConversation,
              'Al Dee'
            );
            return;
          }

          // Al Dee's missions only (can be expanded in the future)
          const AL_DEE_MISSIONS = [AL_DEE_FISHING_MISSION, AL_DEE_GOLDEN_ROPE_MISSION, AL_DEE_ROOKIE_GUARD_MISSION];

          async function currentAlDeeMission() {
            // Return the first incomplete mission, or null if all are completed
            for (const mission of AL_DEE_MISSIONS) {
              // Check prerequisites for golden rope mission
              if (mission.id === AL_DEE_GOLDEN_ROPE_MISSION.id) {
                // Must have completed fishing mission AND have Light Shovel
                if (!kingChatState.progressAlDeeFishing.completed) {
                  continue; // Skip this mission if fishing mission not completed
                }
                const hasShovel = await hasLightShovelInInventory();
                if (!hasShovel) {
                  continue; // Skip this mission if no Light Shovel
                }
              }

              // Rookie Guard only opens up once the golden rope task is done
              if (mission.id === AL_DEE_ROOKIE_GUARD_MISSION.id && !kingChatState.progressAlDeeGoldenRope.completed) {
                continue;
              }

              if (!getMissionProgress(mission).completed) {
                return mission;
              }
            }
            // All missions completed, no more missions available
            return null;
          }

          function buildAlDeeStrings(mission) {
            // Handle case where all missions are completed (mission is null)
            if (!mission) {
              return {
                missionPrompt: 'All my tasks have been completed. Come back later for more tasks!',
                thankYou: 'All my tasks have been completed.',
                keyQuestion: 'All my tasks have been completed.',
                keyComplete: 'All my tasks have been completed.',
                keyScoldNoKey: 'All my tasks have been completed.',
                keyKeepSearching: 'All my tasks have been completed.',
                keyAnswerYesNo: 'All my tasks have been completed.',
                missionCompleted: 'All my tasks have been completed.',
                missionActive: 'All my tasks have been completed.'
              };
            }

            return {
              missionPrompt: mission.prompt,
              thankYou: mission.accept,
              keyQuestion: mission.askForItem || 'Have you found what I asked for?',
              keyComplete: getMissionCompleteLine(mission),
              keyScoldNoKey: mission.missingItem || 'You claim yes but lack what I asked for.',
              keyKeepSearching: mission.keepSearching,
              keyAnswerYesNo: mission.answerYesNo,
              missionCompleted: mission.alreadyCompleted,
              missionActive: mission.alreadyActive
            };
          }

          const activeMission = await currentAlDeeMission();
          const strings = buildAlDeeStrings(activeMission);

          let responseText = '';
          if (!activeMission) {
            // All Al Dee missions completed
            responseText = strings.missionPrompt;
          } else {
            const missionProgress = getMissionProgress(activeMission);

            if (missionProgress.accepted) {
              // Prefer continuing progress when the player already holds the turn-in item.
              let readyToHandIn = false;
              try {
                const products = await getQuestItems(false);
                if (activeMission.id === AL_DEE_FISHING_MISSION.id && (products['Small Axe'] || 0) > 0) {
                  alDeeChatState.awaitingAxeConfirm = true;
                  alDeeChatState.awaitingRopeConfirm = false;
                  alDeeChatState.offeringFishingMission = false;
                  alDeeChatState.offeringRopeMission = false;
                  readyToHandIn = true;
                } else if (activeMission.id === AL_DEE_GOLDEN_ROPE_MISSION.id && (products['Elvenhair Rope'] || 0) > 0) {
                  const mornenionDefeated = await isMornenionDefeated();
                  if (mornenionDefeated) {
                    alDeeChatState.awaitingRopeConfirm = true;
                    alDeeChatState.awaitingAxeConfirm = false;
                    alDeeChatState.offeringFishingMission = false;
                    alDeeChatState.offeringRopeMission = false;
                    readyToHandIn = true;
                  }
                } else if (activeMission.id === AL_DEE_ROOKIE_GUARD_MISSION.id) {
                  const rookieGuardProgress = getMissionProgress(AL_DEE_ROOKIE_GUARD_MISSION);
                  if (rookieGuardProgress.battleCompleted) {
                    alDeeChatState.awaitingRookieGuardConfirm = true;
                    alDeeChatState.awaitingAxeConfirm = false;
                    alDeeChatState.awaitingRopeConfirm = false;
                    alDeeChatState.offeringFishingMission = false;
                    alDeeChatState.offeringRopeMission = false;
                    alDeeChatState.offeringRookieGuardMission = false;
                    readyToHandIn = true;
                  }
                }
              } catch (error) {
                console.error('[Quests Mod][Al Dee] Error checking mission hand-in items:', error);
              }

              responseText = readyToHandIn ? strings.keyQuestion : strings.missionActive;
            } else {
              // Offer the mission
              responseText = strings.missionPrompt;
              alDeeChatState.awaitingAxeConfirm = false;
              alDeeChatState.awaitingRopeConfirm = false;
              alDeeChatState.awaitingRookieGuardConfirm = false;

              // Set appropriate offering flag based on mission
              if (activeMission.id === AL_DEE_FISHING_MISSION.id) {
                alDeeChatState.offeringFishingMission = true;
                alDeeChatState.offeringRopeMission = false;
                alDeeChatState.offeringRookieGuardMission = false;
              } else if (activeMission.id === AL_DEE_GOLDEN_ROPE_MISSION.id) {
                alDeeChatState.offeringRopeMission = true;
                alDeeChatState.offeringFishingMission = false;
                alDeeChatState.offeringRookieGuardMission = false;
              } else if (activeMission.id === AL_DEE_ROOKIE_GUARD_MISSION.id) {
                alDeeChatState.offeringRookieGuardMission = true;
                alDeeChatState.offeringFishingMission = false;
                alDeeChatState.offeringRopeMission = false;
              }
            }
          }

          // Queue response with cooldown
          alDeeCooldown.queueResponse(
            text,
            responseText,
            addMessageToConversation,
            'Al Dee'
          );

          return;
        }

        const lostOracleWonder = tryLostOracleNpcWonderResponse(text, playerName, 'al-dee', 'Al Dee');
        if (lostOracleWonder != null) {
          alDeeCooldown.queueResponse(
            text,
            lostOracleWonder,
            addMessageToConversation,
            'Al Dee',
            ModalHelpers.getFarewellCloseCallback(text)
          );
          return;
        }

        // Get transcript response (handles all standard Al Dee dialogue)
        let alDeeResponse = getAlDeeResponse(text, playerName);
        if (alDeeResponse == null) {
          alDeeResponse = getNpcQuestItemChatResponse('al-dee', text, playerName);
        }
        if (alDeeResponse == null) {
          alDeeResponse = getRandomAlDeeConfusionResponse();
        }

        alDeeCooldown.queueResponse(
          text,
          alDeeResponse,
          addMessageToConversation,
          'Al Dee',
          ModalHelpers.getFarewellCloseCallback(text)
        );
      }

      sendButton.addEventListener('click', sendMessageToAlDee);

      inputRow.appendChild(textarea);
      inputRow.appendChild(sendButton);
      row3.appendChild(inputRow);

      modalContent.appendChild(row1);
      modalContent.appendChild(row2);
      modalContent.appendChild(row3);

      // Footer with guild coins display and close button (same structure as King Tibianus)
      let customFooter = null;
      let customSeparator = null;
      let guildCoinAmountSpan = null;

      function closeDialogWithFallback(delayMs = 0) {
        ModalHelpers.closeModal(delayMs);
      }

      function removeDefaultModalFooter(dialog) {
        try {
          if (!dialog) return;
          const separators = dialog.querySelectorAll('.separator');
          separators.forEach(el => {
            if (el !== customSeparator) {
              el.remove();
            }
          });
          const buttonRows = dialog.querySelectorAll('.flex.justify-end.gap-2');
          buttonRows.forEach(row => {
            if (row !== customFooter && !row.querySelector('.guild-coins-display')) {
              row.remove();
            }
          });
        } catch (error) {
          console.warn('[Quests Mod][Al Dee] Could not remove default modal footer:', error);
        }
      }

      const footer = document.createElement('div');
      footer.className = 'flex justify-end gap-2 items-center';
      footer.style.cssText = 'width: 100%;';
      customFooter = footer;

      // Guild coin display
      const guildCoinIconUrl = cachedExtensionBaseUrl ? constructUrl(cachedExtensionBaseUrl, '/assets/ot/Guild_Coin.png') : '/assets/ot/Guild_Coin.png';
      const coinDisplay = document.createElement('div');
      coinDisplay.className = 'pixel-font-16 frame-pressed-1 surface-darker flex items-center justify-end gap-1 px-1.5 pb-px text-right text-whiteRegular mr-auto guild-coins-display';
      coinDisplay.style.cssText = 'box-sizing: border-box;';

      const coinImg = document.createElement('img');
      coinImg.src = guildCoinIconUrl;
      coinImg.alt = 'Guild Coins';
      coinImg.style.cssText = 'width: 16px; height: 16px;';

      guildCoinAmountSpan = document.createElement('span');
      guildCoinAmountSpan.className = 'guild-coins-amount';
      guildCoinAmountSpan.textContent = '...';

      coinDisplay.appendChild(coinImg);
      coinDisplay.appendChild(guildCoinAmountSpan);
      footer.appendChild(coinDisplay);

      const footerCloseBtn = document.createElement('button');
      footerCloseBtn.type = 'button';
      footerCloseBtn.textContent = 'Close';
      footerCloseBtn.className = 'focus-style-visible flex items-center justify-center tracking-wide text-whiteRegular disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1 active:frame-pressed-1 surface-regular gap-1 px-2 py-0.5 pb-[3px] pixel-font-14 [&_svg]:size-[11px] [&_svg]:mb-[1px] [&_svg]:mt-[2px]';
      footerCloseBtn.style.cssText = 'cursor: pointer; white-space: nowrap; box-sizing: border-box; max-height: 21px; height: 21px; font-size: 14px;';
      footerCloseBtn.addEventListener('click', () => {
        clearQuestsModalLayoutCleanup();
        if (modalRef?.close) {
          modalRef.close();
        } else {
          const dialog = document.querySelector('div[role="dialog"][data-state="open"]');
          if (dialog && dialog.parentNode) {
            dialog.parentNode.removeChild(dialog);
          } else {
            closeDialogWithFallback(0);
          }
        }
      });
      footer.appendChild(footerCloseBtn);

      const footerContainer = document.createElement('div');
      footerContainer.style.cssText = 'display: flex; flex-direction: column; gap: 0; width: 100%;';

      const separator = document.createElement('div');
      separator.className = 'separator my-2.5';
      separator.setAttribute('role', 'none');
      customSeparator = separator;
      footerContainer.appendChild(separator);

      footerContainer.appendChild(footer);
      modalContent.appendChild(footerContainer);

      // Function to update guild coin display
      async function updateGuildCoinDisplay() {
        if (!guildCoinAmountSpan) return;
        guildCoinAmountSpan.textContent = '...';
        try {
          const coinsGetter =
            globalThis.getGuildCoins ||
            (globalThis.Guilds && globalThis.Guilds.getGuildCoins) ||
            (globalThis.BestiaryModAPI &&
             globalThis.BestiaryModAPI.guilds &&
             globalThis.BestiaryModAPI.guilds.getGuildCoins) ||
            (typeof getGuildCoins === 'function' ? getGuildCoins : null);
          if (!coinsGetter) {
            console.error('[Quests Mod][Al Dee] getGuildCoins not available; cannot show guild coins.');
            guildCoinAmountSpan.textContent = '?';
            return;
          }
          const amount = await coinsGetter();
          guildCoinAmountSpan.textContent = Number.isFinite(amount) ? amount.toLocaleString('en-US') : '?';
        } catch (error) {
          console.error('[Quests Mod][Al Dee] Error updating guild coins display:', error);
          guildCoinAmountSpan.textContent = '?';
        }
      }

      contentDiv.appendChild(modalContent);

      // Update guild coin display
      updateGuildCoinDisplay();

      const alDeeDims = getQuestsModalDimensions(
        KING_TIBI_MODAL_WIDTH,
        KING_TIBI_MODAL_HEIGHT,
        QUESTS_MODAL_CONFIG.kingTibianus.minHeight
      );
      const modal = api.ui.components.createModal({
        title: 'Al Dee',
        width: alDeeDims.width,
        height: alDeeDims.height,
        content: contentDiv,
        buttons: []
      });

      modalRef = modal;

      setupQuestsModalResponsiveLayout(
        modal,
        contentDiv,
        KING_TIBI_MODAL_WIDTH,
        KING_TIBI_MODAL_HEIGHT,
        QUESTS_MODAL_CONFIG.kingTibianus.minHeight,
        (dialog) => removeDefaultModalFooter(dialog)
      );

      modalTimeout = null;
    }, 50);
  }

  // Shared NPC chat modal content (image + messages + input). Used by Costello and Wyda.
  function createOutfitPortraitSlot({
    outfitSpriteId,
    outfitFacing = 'south',
    outfitShiny = false,
    outfitPortraitTranslate = '-12px -12px',
    outfitName = ''
  }) {
    const container = document.createElement('div');
    container.className = 'relative flex h-full w-full flex-col items-center justify-center overflow-hidden p-1';
    container.style.cssText = 'width:100%;height:100%;box-sizing:border-box;gap:0;';

    if (outfitName) {
      const nameLabel = document.createElement('div');
      nameLabel.className = 'pixel-font-16 text-whiteHighlight relative z-3 text-center';
      nameLabel.style.cssText = 'color:rgb(96, 192, 96);text-shadow:-1px 0 #000,1px 0 #000,0 -1px #000,0 1px #000;line-height:1;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-bottom:0;';
      nameLabel.textContent = outfitName;
      container.appendChild(nameLabel);
    }

    const spriteContainer = document.createElement('div');
    spriteContainer.className = 'relative z-3 mx-auto flex h-12 w-sprite-2x items-center justify-center';
    spriteContainer.style.cssText = 'margin-top:-2px;';

    const spriteOutfit = document.createElement('div');
    spriteOutfit.className = `sprite outfit pointer-events-none id-${outfitSpriteId} idle ${outfitFacing}`;
    spriteOutfit.style.cssText = `translate:${outfitPortraitTranslate};`;

    const viewport = document.createElement('div');
    viewport.className = 'viewport';
    const outfitImg = document.createElement('img');
    outfitImg.alt = outfitFacing;
    outfitImg.className = 'actor spritesheet';
    outfitImg.setAttribute('data-shiny', outfitShiny ? 'true' : 'false');
    outfitImg.style.cssText = 'animation-play-state:running;';
    viewport.appendChild(outfitImg);
    spriteOutfit.appendChild(viewport);
    spriteContainer.appendChild(spriteOutfit);
    container.appendChild(spriteContainer);
    return container;
  }

  function createNPCChatModalContent(options) {
    const {
      npcName,
      playerName,
      imageUrl,
      imageAlt,
      outfitSpriteId,
      outfitFacing = 'south',
      outfitShiny = false,
      outfitPortraitTranslate = '-12px -12px',
      itemSpriteId,
      welcomeMessage,
      placeholder,
      modalWidth,
      modalHeight,
      messageContainerId
    } = options;

    const contentDiv = document.createElement('div');
    applyModalContentStyles(contentDiv, modalWidth, modalHeight, true);

    const modalContent = document.createElement('div');
    modalContent.className = 'quests-npc-chat-body';
    modalContent.style.cssText = 'display: flex; flex-direction: column; gap: 12px; padding: 0; width: 100%; min-width: 0; height: 100%; min-height: 0; flex: 1 1 auto; box-sizing: border-box;';

    const row1 = document.createElement('div');
    row1.className = 'quests-npc-chat-row';
    row1.style.cssText = 'display: flex; flex-direction: row; align-items: stretch; align-self: stretch; width: 100%; min-width: 0; gap: 12px; flex: 1 1 0; min-height: 0;';

    const imageContainer = document.createElement('div');
    imageContainer.className = 'container-slot surface-darker relative grid place-items-center overflow-hidden quests-npc-chat-image';
    imageContainer.style.cssText = 'width: 110px; min-width: 110px; max-width: 110px; flex: 0 0 110px; height: 150px; min-height: 150px; padding: 0; align-self: stretch;';

    if (outfitSpriteId) {
      imageContainer.appendChild(createOutfitPortraitSlot({
        outfitSpriteId,
        outfitFacing,
        outfitShiny,
        outfitPortraitTranslate,
        outfitName: npcName
      }));
    } else if (itemSpriteId) {
      const itemPortrait = document.createElement('div');
      itemPortrait.style.cssText = 'width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:10px;box-sizing:border-box;gap:6px;';
      if (npcName) {
        const nameLabel = document.createElement('div');
        nameLabel.className = 'pixel-font-16 text-whiteHighlight relative z-3 text-center';
        nameLabel.style.cssText = 'color:rgb(96, 192, 96);text-shadow:-1px 0 #000,1px 0 #000,0 -1px #000,0 1px #000;line-height:1;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
        nameLabel.textContent = npcName;
        itemPortrait.appendChild(nameLabel);
      }
      const spriteWrap = document.createElement('div');
      spriteWrap.className = `sprite item relative id-${itemSpriteId}`;
      spriteWrap.style.cssText = 'z-index:1000;transform:scale(2);transform-origin:center center;';
      spriteWrap.innerHTML = `<div class="viewport"><img alt="${itemSpriteId}" data-cropped="false" class="spritesheet" style="--cropX: 0; --cropY: 0;"></div>`;
      itemPortrait.appendChild(spriteWrap);
      imageContainer.appendChild(itemPortrait);
    } else {
      const imgWrapper = document.createElement('div');
      imgWrapper.style.cssText = 'width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; padding: 10px; box-sizing: border-box;';

      const img = document.createElement('img');
      img.src = imageUrl;
      img.alt = imageAlt || npcName;
      img.className = 'pixelated';
      img.style.cssText = 'max-width: 100%; max-height: 100%; width: auto; height: auto; object-fit: contain; image-rendering: pixelated;';
      imgWrapper.appendChild(img);
      imageContainer.appendChild(imgWrapper);
    }

    const messageContainer = document.createElement('div');
    messageContainer.className = 'tooltip-prose pixel-font-16 frame-pressed-1 surface-dark flex w-full flex-col gap-1 p-2 text-whiteRegular quests-npc-chat-messages';
    messageContainer.style.cssText = 'flex: 1 1 0; min-width: 0; width: auto; height: 150px; min-height: 150px; max-height: 150px; overflow-y: auto; box-sizing: border-box;';
    if (messageContainerId) messageContainer.id = messageContainerId;

    let pendingNpcChunkTimeouts = [];
    function addMessage(sender, text, isNpc, noChunk = false) {
      const appendOne = (chunkText) => {
        const messageP = document.createElement('p');
        messageP.className = 'inline text-monster';
        messageP.style.color = isNpc ? 'rgb(135, 206, 250)' : 'rgb(200, 180, 255)';
        messageP.textContent = sender + ': ' + chunkText;
        messageContainer.appendChild(messageP);
        setTimeout(() => { messageContainer.scrollTop = messageContainer.scrollHeight; }, 0);
      };

      // A newer message supersedes whatever this modal was still mid-way through
      // printing — cancel any not-yet-delivered chunk of a previous long message so it
      // can't land in the transcript after a reply that already moved past it.
      pendingNpcChunkTimeouts.forEach((id) => clearTimeout(id));
      pendingNpcChunkTimeouts = [];

      if (isNpc && !noChunk) {
        pendingNpcChunkTimeouts = scheduleChunkedDialogue(appendOne, text);
      } else {
        appendOne(text);
      }
    }

    // Greetings/welcome lines are always delivered as a single message, never
    // split into 2-3 sentence chunks.
    addMessage(npcName, welcomeMessage, true, true);

    row1.appendChild(imageContainer);
    row1.appendChild(messageContainer);
    modalContent.appendChild(row1);

    const inputRow = document.createElement('div');
    inputRow.className = 'quests-npc-chat-input';
    inputRow.style.cssText = 'display: flex; gap: 6px; align-items: center; flex-shrink: 0; width: 100%; min-width: 0; box-sizing: border-box;';
    const textarea = document.createElement('textarea');
    textarea.setAttribute('wrap', 'off');
    textarea.placeholder = placeholder;
    textarea.style.cssText = 'flex:1 1 0;min-width:0;height:28px;max-height:28px;min-height:28px;padding:4px 6px;background-color:#333;border:4px solid transparent;border-image:url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill;color:rgb(255,255,255);font-size:13px;resize:none;box-sizing:border-box;outline:none;';

    const sendBtn = document.createElement('button');
    sendBtn.textContent = 'Send';
    sendBtn.className = 'primary';
    sendBtn.style.cssText = `
      height: 28px;
      padding: 4px 10px;
      white-space: nowrap;
      font-size: 13px;
      line-height: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      background: url('https://bestiaryarena.com/_next/static/media/background-blue.7259c4ed.png') center center / cover;
      border: 4px solid transparent;
      border-image: url("https://bestiaryarena.com/_next/static/media/1-frame.f1ab7b00.png") 4 fill;
      color: rgb(255, 255, 255);
      cursor: pointer;
      font-family: inherit;
    `;

    inputRow.appendChild(textarea);
    inputRow.appendChild(sendBtn);
    modalContent.appendChild(inputRow);
    contentDiv.appendChild(modalContent);

    return { contentDiv, addMessage, messageContainer, imageContainer, textarea, sendBtn };
  }

  // Costello Modal (Isle of Kings, Carlin) – uses shared NPC chat layout
  async function showCostelloModal() {
    await ensureQuestDialogueLoaded();
    kingChatState.costelloVisited = true;
    const playerName = getCurrentPlayerName();
    if (playerName) {
      getKingTibianusProgress(playerName).then((currentProgress) => {
        const merged = { ...currentProgress, costelloVisited: true };
        saveKingTibianusProgress(playerName, merged).catch((err) => console.error('[Quests Mod][Costello] Error saving costelloVisited:', err));
      }).catch((err) => console.error('[Quests Mod][Costello] Error loading progress for costelloVisited:', err));
    }

    const costelloPlayerName = getCurrentPlayerName() || 'Player';
    const costelloIconUrl = getQuestItemsAssetUrl('Costello.gif');
    const { contentDiv, addMessage: addMessageToConversation, imageContainer: costelloImageContainer, textarea: costelloTextarea, sendBtn: costelloSendBtn } = createNPCChatModalContent({
      npcName: 'Costello',
      playerName: costelloPlayerName,
      imageUrl: costelloIconUrl,
      imageAlt: 'Costello',
      welcomeMessage: 'Welcome, ' + costelloPlayerName + '! Feel free to tell me what brings you here.',
      placeholder: 'Type your message to Costello...',
      modalWidth: KING_TIBI_MODAL_WIDTH,
      modalHeight: COSTELLO_MODAL_HEIGHT,
      messageContainerId: 'costello-messages'
    });
    setNpcModalPendingBadge(costelloImageContainer, hasCostelloQuestAction());

    costelloTextarea.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendMessageToCostello();
      }
    });
    costelloSendBtn.addEventListener('click', sendMessageToCostello);

    const costelloCooldown = createNPCCooldownManager();
    let costelloAwaitingHolyTible = false;
    let costelloOfferingQueenBanshees = false;
    let costelloOfferingBloodProtector = false;

    async function sendMessageToCostello() {
        const text = (costelloTextarea.value || '').trim();
        if (!text) return;
        addMessageToConversation(costelloPlayerName, text, false);
        costelloTextarea.value = '';
        costelloCooldown.clearPendingResponse();
        const lowerText = text.toLowerCase();

        // Complete Queen Banshees when all seven seals are done and player says they are done (even without saying "mission")
        const queenBansheesProgress = getMissionProgress(COSTELLO_QUEEN_BANSHEES_MISSION);
        const completionKeywords = ['done', 'task', 'finished', 'completed', 'return', 'yes', 'complete', 'ready'];
        if (queenBansheesProgress.accepted && !queenBansheesProgress.completed && areAllSevenSealsCompleted() && completionKeywords.some(kw => lowerText.includes(kw))) {
          try {
            await addQuestItem(COSTELLO_QUEEN_BANSHEES_MISSION.rewardItemName, 1);
            await consumeQuestItem(COSTELLO_QUEEN_BANSHEES_MISSION.diaryItemName, 1);
            await persistMissionProgress(COSTELLO_QUEEN_BANSHEES_MISSION, { accepted: true, completed: true }, { playerName: costelloPlayerName });
            showQueenBansheesCompletionToasts();
            costelloCooldown.queueResponse(text, getMissionDialogueLine(COSTELLO_QUEEN_BANSHEES_MISSION, 'complete', 'You have completed the seven seals of Ghostlands. The Queen Of The Banshees task is complete. You have received the Blessed Ankh. My thanks.'), addMessageToConversation, 'Costello');
          } catch (err) {
            console.error('[Quests Mod][Costello] Error completing Queen Banshees:', err);
            costelloCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessageToConversation, 'Costello');
          }
          return;
        }

        if (lowerText.includes('mission') || lowerText.includes('quest')) {
          const monksProgress = getMissionProgress(KING_MONKS_STUDY_MISSION);
          const queenBansheesProgress = getMissionProgress(COSTELLO_QUEEN_BANSHEES_MISSION);
          const followerOfZathrothProgress = getMissionProgress(FOLLOWER_OF_ZATHROTH_MISSION);
          if (monksProgress.accepted && !monksProgress.completed) {
            costelloAwaitingHolyTible = true;
            costelloCooldown.queueResponse(text, getMissionDialogueLine(KING_MONKS_STUDY_MISSION, 'costelloHolyTibleAsk', 'The King has sent you. Do you have the Holy Tible with you? I need to see it to complete your study here.'), addMessageToConversation, 'Costello');
          } else if (monksProgress.completed && !queenBansheesProgress.accepted) {
            costelloOfferingQueenBanshees = true;
            costelloCooldown.queueResponse(text, COSTELLO_QUEEN_BANSHEES_MISSION.prompt, addMessageToConversation, 'Costello');
          } else if (queenBansheesProgress.accepted && !queenBansheesProgress.completed) {
            const hasAllSeven = areAllSevenSealsCompleted();
            if (hasAllSeven) {
              // Player is already with Costello and reporting the mission — finish the hand-in now.
              try {
                await addQuestItem(COSTELLO_QUEEN_BANSHEES_MISSION.rewardItemName, 1);
                await consumeQuestItem(COSTELLO_QUEEN_BANSHEES_MISSION.diaryItemName, 1);
                await persistMissionProgress(COSTELLO_QUEEN_BANSHEES_MISSION, { accepted: true, completed: true }, { playerName: costelloPlayerName });
                showQueenBansheesCompletionToasts();
                costelloCooldown.queueResponse(text, getMissionDialogueLine(COSTELLO_QUEEN_BANSHEES_MISSION, 'complete', 'You have completed the seven seals of Ghostlands. The Queen Of The Banshees task is complete. You have received the Blessed Ankh. My thanks.'), addMessageToConversation, 'Costello');
              } catch (err) {
                console.error('[Quests Mod][Costello] Error completing Queen Banshees:', err);
                costelloCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessageToConversation, 'Costello');
              }
            } else {
              costelloCooldown.queueResponse(text, COSTELLO_QUEEN_BANSHEES_MISSION.alreadyActive, addMessageToConversation, 'Costello');
            }
          } else if (queenBansheesProgress.completed && !followerOfZathrothProgress.accepted) {
            costelloOfferingBloodProtector = true;
            costelloCooldown.queueResponse(text, FOLLOWER_OF_ZATHROTH_MISSION.prompt, addMessageToConversation, 'Costello');
          } else if (followerOfZathrothProgress.accepted && !followerOfZathrothProgress.completed) {
            costelloCooldown.queueResponse(text, FOLLOWER_OF_ZATHROTH_MISSION.alreadyActive, addMessageToConversation, 'Costello');
          } else if (followerOfZathrothProgress.completed) {
            costelloCooldown.queueResponse(text, FOLLOWER_OF_ZATHROTH_MISSION.alreadyCompleted, addMessageToConversation, 'Costello');
          } else {
            costelloCooldown.queueResponse(text, getMissionCommonLine('costelloNoFurtherMissions', 'I have no further mission for you. Perhaps the King has work for you.'), addMessageToConversation, 'Costello');
          }
          return;
        }

        if (costelloOfferingQueenBanshees && lowerText.includes('yes')) {
          costelloOfferingQueenBanshees = false;
          try {
            await addQuestItem(COSTELLO_QUEEN_BANSHEES_MISSION.diaryItemName, 1);
            setMissionProgress(COSTELLO_QUEEN_BANSHEES_MISSION, { accepted: true, completed: false });
            kingChatState.progressQueenBanshees.accepted = true;
            kingChatState.progressQueenBanshees.completed = false;
            setMissionProgress(KING_MONKS_STUDY_MISSION, { accepted: true, completed: true });
            kingChatState.progressMonksStudy.accepted = true;
            kingChatState.progressMonksStudy.completed = true;
            const allProgress = getAllMissionProgress();
            await saveKingTibianusProgress(costelloPlayerName, allProgress);
            costelloCooldown.queueResponse(text, COSTELLO_QUEEN_BANSHEES_MISSION.accept + getMissionDialogueLine(COSTELLO_QUEEN_BANSHEES_MISSION, 'acceptDiarySuffix', ' You have received my diary.'), addMessageToConversation, 'Costello');
          } catch (err) {
            console.error('[Quests Mod][Costello] Error accepting Queen Banshees:', err);
            costelloCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessageToConversation, 'Costello');
          }
          return;
        }
        if (costelloOfferingQueenBanshees && (lowerText.includes('no') || lowerText.includes('not'))) {
          costelloOfferingQueenBanshees = false;
          costelloCooldown.queueResponse(text, getMissionCommonLine('notReady', 'Return when you are ready for this task.'), addMessageToConversation, 'Costello');
          return;
        }

        if (costelloOfferingBloodProtector && lowerText.includes('yes')) {
          costelloOfferingBloodProtector = false;
          try {
            await persistMissionProgress(FOLLOWER_OF_ZATHROTH_MISSION, { accepted: true, completed: false }, { playerName: costelloPlayerName });
            if (typeof updateTile83WydaRightClickState === 'function') updateTile83WydaRightClickState();
            costelloCooldown.queueResponse(text, FOLLOWER_OF_ZATHROTH_MISSION.accept, addMessageToConversation, 'Costello');
          } catch (err) {
            console.error('[Quests Mod][Costello] Error accepting Follower of Zathroth:', err);
            costelloCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessageToConversation, 'Costello');
          }
          return;
        }
        if (costelloOfferingBloodProtector && (lowerText.includes('no') || lowerText.includes('not'))) {
          costelloOfferingBloodProtector = false;
          costelloCooldown.queueResponse(text, getMissionDialogueLine(FOLLOWER_OF_ZATHROTH_MISSION, 'notReadyDecline', 'Return when you are ready to bring the Blessed Ankh to Wyda.'), addMessageToConversation, 'Costello');
          return;
        }

        if (costelloAwaitingHolyTible && lowerText.includes('yes')) {
          try {
            const questItems = await getQuestItems(false);
            const hasTible = (questItems['The Holy Tible'] || 0) >= 1;
            if (hasTible) {
              await consumeQuestItem('The Holy Tible', 1);
              await persistMissionProgress(KING_MONKS_STUDY_MISSION, { accepted: true, completed: true }, { playerName: costelloPlayerName });
              const coinsAdder = globalThis.addGuildCoins ||
                (globalThis.Guilds && globalThis.Guilds.addGuildCoins) ||
                (globalThis.BestiaryModAPI && globalThis.BestiaryModAPI.guilds && globalThis.BestiaryModAPI.guilds.addGuildCoins) ||
                (typeof addGuildCoins === 'function' ? addGuildCoins : null);
              const monksStudyCoins = KING_MONKS_STUDY_MISSION.rewardCoins || 0;
              if (coinsAdder && monksStudyCoins > 0) {
                await coinsAdder(monksStudyCoins);
              }
              costelloAwaitingHolyTible = false;
              NotificationService.showQuestCompleted(
                KING_MONKS_STUDY_MISSION,
                '[Quests Mod][Costello]',
                monksStudyCoins > 0 ? { rewardCoins: monksStudyCoins } : undefined
              );
              costelloCooldown.queueResponse(text, formatDialogueLine(getMissionDialogueLine(KING_MONKS_STUDY_MISSION, 'costelloStudyComplete', 'Thank you. Your study here is complete. Here are {coins} guild coins as a reward.'), { coins: monksStudyCoins }), addMessageToConversation, 'Costello');
            } else {
              costelloCooldown.queueResponse(text, getMissionDialogueLine(KING_MONKS_STUDY_MISSION, 'costelloHolyTibleMissing', 'You do not have the Holy Tible. Return when you have it.'), addMessageToConversation, 'Costello');
            }
          } catch (err) {
            console.error('[Quests Mod][Costello] Error completing Monks Study:', err);
            costelloCooldown.queueResponse(text, getMissionDialogueLine(KING_MONKS_STUDY_MISSION, 'costelloHolyTibleError', 'Something went wrong. Return when you have the Holy Tible.'), addMessageToConversation, 'Costello');
          }
          return;
        }

        if (costelloAwaitingHolyTible && lowerText.includes('no')) {
          costelloAwaitingHolyTible = false;
          costelloCooldown.queueResponse(text, getMissionDialogueLine(KING_MONKS_STUDY_MISSION, 'costelloHolyTibleReturn', 'Return when you have the Holy Tible.'), addMessageToConversation, 'Costello');
          return;
        }

        const lostOracleWonder = tryLostOracleNpcWonderResponse(text, costelloPlayerName, 'costello', 'Costello');
        if (lostOracleWonder != null) {
          costelloCooldown.queueResponse(
            text,
            lostOracleWonder,
            addMessageToConversation,
            'Costello',
            ModalHelpers.getFarewellCloseCallback(text)
          );
          return;
        }

        let response = getCostelloResponse(text, costelloPlayerName);
        if (response == null) {
          response = getNpcQuestItemChatResponse('costello', text, costelloPlayerName);
        }
        if (response == null) {
          response = getRandomNpcConfusionResponse(COSTELLO_CONFUSION_RESPONSES, costelloPlayerName);
        }
        costelloCooldown.queueResponse(
          text,
          response,
          addMessageToConversation,
          'Costello',
          ModalHelpers.getFarewellCloseCallback(text)
        );
    }

    openQuestsModal({
      title: 'Costello',
      content: contentDiv,
      maxWidth: KING_TIBI_MODAL_WIDTH,
      maxHeight: COSTELLO_MODAL_HEIGHT,
      minHeight: QUESTS_MODAL_CONFIG.npcChat.minHeight,
      onAfterLayout: (dialog) => {
        if (typeof removeDefaultModalFooter === 'function') {
          removeDefaultModalFooter(dialog);
        }
      }
    });
  }

  // Wyda Modal (Wyda's House, swamps of Venore) – uses shared NPC chat layout and transcript
  async function showWydaModal() {
    await ensureQuestDialogueLoaded();
    const wydaPlayerName = getCurrentPlayerName() || 'Player';
    const wydaIconUrl = getQuestItemsAssetUrl('Wyda.gif');
    const { contentDiv, addMessage, imageContainer: wydaImageContainer, textarea, sendBtn } = createNPCChatModalContent({
      npcName: 'Wyda',
      playerName: wydaPlayerName,
      imageUrl: wydaIconUrl,
      imageAlt: 'Wyda',
      welcomeMessage: "What? Talking to me, " + wydaPlayerName + "? I'm bored! Bored bored bored! Nothing ever happens here!",
      placeholder: 'Type your message to Wyda...',
      modalWidth: KING_TIBI_MODAL_WIDTH,
      modalHeight: COSTELLO_MODAL_HEIGHT,
      messageContainerId: 'wyda-messages'
    });
    setNpcModalPendingBadge(wydaImageContainer, hasWydaQuestAction());

    const wydaCooldown = createNPCCooldownManager();
    let wydaOfferingMotherOfAllSpiders = false;
    let wydaOfferingJakundafDesert = false;
    let wydaOfferingTaintedSouls = false;
    let awaitingLostOracleLuminousConfirm = false;

    async function sendMessageToWyda() {
      const text = (textarea.value || '').trim();
      if (!text) return;
      addMessage(wydaPlayerName, text, false);
      textarea.value = '';
      wydaCooldown.clearPendingResponse();
      const lowerText = text.toLowerCase();

      const followerOfZathrothProgress = getMissionProgress(FOLLOWER_OF_ZATHROTH_MISSION);
      const motherProgress = getMissionProgress(MOTHER_OF_ALL_SPIDERS_MISSION);
      const jakundafProgress = getMissionProgress(JAKUNDAF_DESERT_MISSION);
      const taintedSoulsProgress = getMissionProgress(TAINTED_SOULS_MISSION);
      const lostOracleProgress = getMissionProgress(LOST_ORACLE_MISSION) || {};

      // Quest items with only a generic "take it to <NPC>" hint (Key to Magic →
      // Tesha) answer before Wyda's own "magic"/"key" keyword lines.
      const wydaItemHint = getNpcQuestItemHintResponse('wyda', text, wydaPlayerName);
      if (wydaItemHint) {
        wydaCooldown.queueResponse(text, wydaItemHint, addMessage, 'Wyda', ModalHelpers.getFarewellCloseCallback(text));
        return;
      }

      // The Lost Oracle: Luminous Orb → Spectral Stone
      const mentionsLuminous = lowerText.includes('luminous') || lowerText.includes('orb');
      const mentionsSpectral = lowerText.includes('spectral');
      const giveLuminousKeywords = ['luminous', 'orb', 'spectral', 'give', 'here', 'take', 'offer', 'mission', 'quest'];
      const wantsToGiveLuminous = giveLuminousKeywords.some(kw => lowerText.includes(kw));

      if (awaitingLostOracleLuminousConfirm) {
        if (/\byes\b/i.test(text.trim())) {
          awaitingLostOracleLuminousConfirm = false;
          try {
            const ok = await exchangeLuminousOrbForSpectralStone();
            wydaCooldown.queueResponse(
              text,
              ok
                ? getMissionDialogueLine(LOST_ORACLE_MISSION, 'wydaLuminousExchanged', 'There. A Spectral Stone — pulsating with spectral energy. Do not lose it.')
                : getMissionDialogueLine(LOST_ORACLE_MISSION, 'wydaLuminousMissing', 'You do not have a Luminous Orb. Ask the King to unveil an Orb first.'),
              addMessage,
              'Wyda'
            );
          } catch (err) {
            console.error('[Quests Mod][Wyda] Error exchanging Luminous Orb:', err);
            wydaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Wyda');
          }
          return;
        }
        if (/\bno\b/i.test(text.trim())) {
          awaitingLostOracleLuminousConfirm = false;
          wydaCooldown.queueResponse(
            text,
            getMissionDialogueLine(LOST_ORACLE_MISSION, 'wydaLuminousDecline', 'Then keep your glowing toy. Return when you are ready.'),
            addMessage,
            'Wyda'
          );
          return;
        }
      }

      if (
        lostOracleProgress.accepted
        && !lostOracleProgress.completed
        && lostOracleProgress.orbExchanged
        && (mentionsLuminous || mentionsSpectral || wantsToGiveLuminous || messageMentionsOracle(text))
      ) {
        try {
          if (lostOracleProgress.spectralStoneReceived || hasSpectralStoneInInventory()) {
            wydaCooldown.queueResponse(
              text,
              getMissionDialogueLine(LOST_ORACLE_MISSION, 'wydaLuminousAlready', 'You already carry the Spectral Stone I forged. Keep it close.'),
              addMessage,
              'Wyda'
            );
            return;
          }
          const items = await getQuestItems(false);
          const luminousName = LUMINOUS_ORB_CONFIG.productName || 'Luminous Orb';
          const hasLuminous = (items?.[luminousName] || 0) >= 1 || hasLuminousOrbInInventory();
          if (!hasLuminous) {
            wydaCooldown.queueResponse(
              text,
              getMissionDialogueLine(LOST_ORACLE_MISSION, 'wydaLuminousMissing', 'You do not have a Luminous Orb. Ask the King to unveil an Orb first.'),
              addMessage,
              'Wyda'
            );
            return;
          }
          if (mentionsLuminous || mentionsSpectral) {
            const ok = await exchangeLuminousOrbForSpectralStone();
            wydaCooldown.queueResponse(
              text,
              ok
                ? getMissionDialogueLine(LOST_ORACLE_MISSION, 'wydaLuminousExchanged', 'There. A Spectral Stone — pulsating with spectral energy. Do not lose it.')
                : getMissionDialogueLine(LOST_ORACLE_MISSION, 'wydaLuminousMissing', 'You do not have a Luminous Orb. Ask the King to unveil an Orb first.'),
              addMessage,
              'Wyda'
            );
            return;
          }
          awaitingLostOracleLuminousConfirm = true;
          wydaCooldown.queueResponse(
            text,
            getMissionDialogueLine(LOST_ORACLE_MISSION, 'wydaLuminousAsk', 'A Luminous Orb... yes. I can bind its light into a Spectral Stone. Will you give it to me?'),
            addMessage,
            'Wyda'
          );
          return;
        } catch (err) {
          console.error('[Quests Mod][Wyda] Error handling Lost Oracle luminous orb:', err);
          wydaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Wyda');
          return;
        }
      }

      // The Mother of All Spiders: give Spider Silk to Wyda to complete (check before mission/quest so "silk" / "spider silk" complete the hand-in)
      const giveSilkKeywords = ['silk', 'spider silk', 'give', 'here', 'take', 'offer', 'mission', 'quest'];
      const wantsToGiveSilk = giveSilkKeywords.some(kw => lowerText.includes(kw));
      if (motherProgress.accepted && !motherProgress.completed && wantsToGiveSilk) {
        try {
          const questItems = await getQuestItems(false);
          const hasSilk = (questItems['Spider Silk'] || 0) >= 1;
          if (hasSilk) {
            await consumeQuestItem('Spider Silk', 1);
            await persistMissionProgress(MOTHER_OF_ALL_SPIDERS_MISSION, { accepted: true, completed: true });
            await addQuestItem(MOTHER_OF_ALL_SPIDERS_MISSION.rewardItemName, 1);
            if (typeof updateTile83WydaRightClickState === 'function') updateTile83WydaRightClickState();
            wydaCooldown.queueResponse(text, getMissionDialogueLine(MOTHER_OF_ALL_SPIDERS_MISSION, 'wydaSilkComplete', 'The silk! Excellent. I can make good use of this. Here, take this Spool of Yarn as thanks.'), addMessage, 'Wyda');
            NotificationService.showQuestCompleted(MOTHER_OF_ALL_SPIDERS_MISSION, '[Quests Mod][Wyda]');
            NotificationService.showItemReceived(MOTHER_OF_ALL_SPIDERS_MISSION.rewardItemName, '[Quests Mod][Wyda]');
            return;
          }
          wydaCooldown.queueResponse(text, getMissionDialogueLine(MOTHER_OF_ALL_SPIDERS_MISSION, 'wydaMissingSilk', "You don't have the spider silk. Defeat the mother of all spiders in the secluded herb and return with the silk."), addMessage, 'Wyda');
          return;
        } catch (err) {
          console.error('[Quests Mod][Wyda] Error completing Mother of All Spiders:', err);
          wydaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Wyda');
          return;
        }
      }

      // The Follower of Zathroth: give Blessed Ankh to Wyda to complete
      const giveAnkhKeywords = ['ankh', 'blessed ankh', 'give', 'here', 'take', 'offer', 'mission', 'quest'];
      const wantsToGiveAnkh = giveAnkhKeywords.some(kw => lowerText.includes(kw));
      if (followerOfZathrothProgress.accepted && !followerOfZathrothProgress.completed && wantsToGiveAnkh) {
        try {
          const questItems = await getQuestItems(false);
          const hasAnkh = (questItems['Blessed Ankh'] || 0) >= 1;
          if (hasAnkh) {
            await consumeQuestItem('Blessed Ankh', 1);
            await persistMissionProgress(FOLLOWER_OF_ZATHROTH_MISSION, { accepted: true, completed: true });
            const coinsAdder = globalThis.addGuildCoins ||
              (globalThis.Guilds && globalThis.Guilds.addGuildCoins) ||
              (globalThis.BestiaryModAPI && globalThis.BestiaryModAPI.guilds && globalThis.BestiaryModAPI.guilds.addGuildCoins) ||
              (typeof addGuildCoins === 'function' ? addGuildCoins : null);
            if (coinsAdder) {
              await coinsAdder(FOLLOWER_OF_ZATHROTH_MISSION.rewardCoins);
            }
            if (typeof updateTile83WydaRightClickState === 'function') updateTile83WydaRightClickState();
            const coinMsg = FOLLOWER_OF_ZATHROTH_MISSION.rewardCoins
              ? formatDialogueLine(getMissionDialogueLine(FOLLOWER_OF_ZATHROTH_MISSION, 'wydaHandInCoinLine', ' Here are {coins} guild coins for your trouble.'), { coins: FOLLOWER_OF_ZATHROTH_MISSION.rewardCoins })
              : '';
            wydaCooldown.queueResponse(text, getMissionDialogueLine(FOLLOWER_OF_ZATHROTH_MISSION, 'wydaHandInComplete', 'The Blessed Ankh! Yes, this is what I needed. You have done well. The matter Costello spoke of is complete.') + coinMsg, addMessage, 'Wyda');
            NotificationService.showQuestCompleted(FOLLOWER_OF_ZATHROTH_MISSION, '[Quests Mod][Wyda]', {
              rewardCoins: FOLLOWER_OF_ZATHROTH_MISSION.rewardCoins > 0 ? FOLLOWER_OF_ZATHROTH_MISSION.rewardCoins : undefined
            });
            return;
          }
        } catch (err) {
          console.error('[Quests Mod][Wyda] Error completing Follower of Zathroth:', err);
        }
      }

      // The Jakundaf Desert: report cleared path to Wyda for Stuffed Toad
      const jakundafReportKeywords = [
        'mission', 'quest', 'desert', 'jakundaf', 'path', 'done', 'finished',
        'cleared', 'report', 'reward', 'toad', 'complete', 'victory'
      ];
      const wantsJakundafReport = jakundafReportKeywords.some((kw) => lowerText.includes(kw));
      if (
        jakundafProgress.accepted
        && !jakundafProgress.completed
        && jakundafProgress.pathCleared
        && wantsJakundafReport
      ) {
        try {
          const rewardName = JAKUNDAF_DESERT_MISSION.rewardItemName || 'Stuffed Toad';
          const alreadyOwned = (await getQuestItems(true))?.[rewardName] > 0;
          await persistMissionProgress(JAKUNDAF_DESERT_MISSION, {
            accepted: true,
            completed: true,
            pathCleared: true
          });
          if (!alreadyOwned) {
            await addQuestItem(rewardName, 1).catch((error) => {
              console.error('[Quests Mod][Wyda] Error adding Jakundaf reward:', error);
            });
          }
          if (typeof updateTile76JakundafState === 'function') updateTile76JakundafState();
          if (typeof refreshQuestTileHighlights === 'function') refreshQuestTileHighlights();
          NotificationService.showQuestCompleted(JAKUNDAF_DESERT_MISSION, '[Quests Mod][Wyda]');
          if (!alreadyOwned) {
            NotificationService.showItemReceived(rewardName, '[Quests Mod][Wyda]');
          }
          wydaCooldown.queueResponse(
            text,
            getMissionDialogueLine(
              JAKUNDAF_DESERT_MISSION,
              'wydaHandInComplete',
              'You cleared the desert path? Good. Take this Stuffed Toad — and leave me to my boredom.'
            ),
            addMessage,
            'Wyda'
          );
        } catch (err) {
          console.error('[Quests Mod][Wyda] Error completing Jakundaf Desert:', err);
          wydaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Wyda');
        }
        return;
      }

      // The Tainted Souls: report Ekatrix slain to Wyda for Ekatrix Soul Core
      const taintedSoulsReportKeywords = [
        'mission', 'quest', 'ekatrix', 'eclipse', 'portal', 'witch', 'soul', 'core',
        'done', 'finished', 'report', 'reward', 'complete', 'victory', 'killed',
        'dead', 'defeat', 'toad', 'cauldron'
      ];
      const wantsTaintedSoulsReport = taintedSoulsReportKeywords.some((kw) => lowerText.includes(kw));
      if (
        taintedSoulsProgress.accepted
        && !taintedSoulsProgress.completed
        && taintedSoulsProgress.battleCompleted
        && wantsTaintedSoulsReport
      ) {
        try {
          const rewardName = getEkatrixSoulCoreName();
          const alreadyOwned = (await getQuestItems(true))?.[rewardName] > 0;
          await persistMissionProgress(TAINTED_SOULS_MISSION, buildTaintedSoulsProgress({
            accepted: true,
            completed: true,
            portalOpened: true,
            battleCompleted: true
          }));
          if (!alreadyOwned) {
            await addQuestItem(rewardName, 1).catch((error) => {
              console.error('[Quests Mod][Wyda] Error adding Ekatrix Soul Core:', error);
            });
          }
          if (typeof updateEclipseTaintedSoulsState === 'function') updateEclipseTaintedSoulsState();
          if (typeof refreshQuestTileHighlights === 'function') refreshQuestTileHighlights();
          NotificationService.showQuestCompleted(TAINTED_SOULS_MISSION, '[Quests Mod][Wyda]');
          if (!alreadyOwned) {
            NotificationService.showItemReceived(rewardName, '[Quests Mod][Wyda]');
          }
          wydaCooldown.queueResponse(
            text,
            getMissionDialogueLine(
              TAINTED_SOULS_MISSION,
              'wydaHandInComplete',
              'Ekatrix is dead, then? Good. Take this Ekatrix Soul Core — and leave me to my boredom.'
            ),
            addMessage,
            'Wyda'
          );
        } catch (err) {
          console.error('[Quests Mod][Wyda] Error completing The Tainted Souls:', err);
          wydaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Wyda');
        }
        return;
      }

      // The Mother of All Spiders / The Jakundaf Desert / The Tainted Souls: offer next available Wyda task
      if (lowerText.includes('mission') || lowerText.includes('quest')) {
        if (followerOfZathrothProgress.completed && !motherProgress.accepted) {
          wydaOfferingMotherOfAllSpiders = true;
          wydaOfferingJakundafDesert = false;
          wydaOfferingTaintedSouls = false;
          wydaCooldown.queueResponse(text, MOTHER_OF_ALL_SPIDERS_MISSION.prompt, addMessage, 'Wyda');
          return;
        }
        if (motherProgress.accepted && !motherProgress.completed) {
          wydaCooldown.queueResponse(text, MOTHER_OF_ALL_SPIDERS_MISSION.alreadyActive, addMessage, 'Wyda');
          return;
        }
        if (motherProgress.completed && !jakundafProgress.accepted) {
          wydaOfferingJakundafDesert = true;
          wydaOfferingMotherOfAllSpiders = false;
          wydaOfferingTaintedSouls = false;
          wydaCooldown.queueResponse(text, JAKUNDAF_DESERT_MISSION.prompt, addMessage, 'Wyda');
          return;
        }
        if (jakundafProgress.accepted && !jakundafProgress.completed) {
          wydaCooldown.queueResponse(
            text,
            jakundafProgress.pathCleared
              ? getMissionDialogueLine(
                JAKUNDAF_DESERT_MISSION,
                'reportBack',
                'The desert path is clear. Return to Wyda for your reward.'
              )
              : JAKUNDAF_DESERT_MISSION.alreadyActive,
            addMessage,
            'Wyda'
          );
          return;
        }
        if (jakundafProgress.completed && !taintedSoulsProgress.accepted) {
          wydaOfferingTaintedSouls = true;
          wydaOfferingJakundafDesert = false;
          wydaOfferingMotherOfAllSpiders = false;
          wydaCooldown.queueResponse(text, TAINTED_SOULS_MISSION.prompt, addMessage, 'Wyda');
          return;
        }
        if (taintedSoulsProgress.accepted && !taintedSoulsProgress.completed) {
          wydaCooldown.queueResponse(
            text,
            taintedSoulsProgress.battleCompleted
              ? getMissionDialogueLine(
                TAINTED_SOULS_MISSION,
                'reportBack',
                'Ekatrix has fallen. Return to Wyda for your reward.'
              )
              : taintedSoulsProgress.portalOpened
                ? getMissionDialogueLine(
                  TAINTED_SOULS_MISSION,
                  'alreadyPortalOpen',
                  'The portal is open at Eclipse. Step through and kill Ekatrix.'
                )
                : TAINTED_SOULS_MISSION.alreadyActive,
            addMessage,
            'Wyda'
          );
          return;
        }
        if (taintedSoulsProgress.completed) {
          wydaCooldown.queueResponse(text, TAINTED_SOULS_MISSION.alreadyCompleted, addMessage, 'Wyda');
          return;
        }
        if (jakundafProgress.completed) {
          wydaCooldown.queueResponse(text, JAKUNDAF_DESERT_MISSION.alreadyCompleted, addMessage, 'Wyda');
          return;
        }
        if (motherProgress.completed) {
          wydaCooldown.queueResponse(text, MOTHER_OF_ALL_SPIDERS_MISSION.alreadyCompleted, addMessage, 'Wyda');
          return;
        }
      }

      if (wydaOfferingMotherOfAllSpiders && (lowerText.includes('yes') || lowerText.includes('accept'))) {
        wydaOfferingMotherOfAllSpiders = false;
        try {
          await persistMissionProgress(MOTHER_OF_ALL_SPIDERS_MISSION, { accepted: true, completed: false });
          wydaCooldown.queueResponse(text, MOTHER_OF_ALL_SPIDERS_MISSION.accept, addMessage, 'Wyda');
        } catch (err) {
          console.error('[Quests Mod][Wyda] Error accepting Mother of All Spiders:', err);
          wydaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Wyda');
        }
        return;
      }
      if (wydaOfferingMotherOfAllSpiders && (lowerText.includes('no') || lowerText.includes('not'))) {
        wydaOfferingMotherOfAllSpiders = false;
        wydaCooldown.queueResponse(text, getMissionCommonLine('notReady', 'Return when you are ready for this task.'), addMessage, 'Wyda');
        return;
      }

      if (wydaOfferingJakundafDesert && (lowerText.includes('yes') || lowerText.includes('accept'))) {
        wydaOfferingJakundafDesert = false;
        try {
          await persistMissionProgress(JAKUNDAF_DESERT_MISSION, {
            accepted: true,
            completed: false,
            pathCleared: false
          });
          if (typeof setupTile76JakundafObserver === 'function') setupTile76JakundafObserver();
          if (typeof updateTile76JakundafState === 'function') updateTile76JakundafState();
          if (typeof refreshQuestTileHighlights === 'function') refreshQuestTileHighlights();
          NotificationService.showQuestAccepted(JAKUNDAF_DESERT_MISSION, '[Quests Mod][Wyda]');
          wydaCooldown.queueResponse(text, JAKUNDAF_DESERT_MISSION.accept, addMessage, 'Wyda');
        } catch (err) {
          console.error('[Quests Mod][Wyda] Error accepting Jakundaf Desert:', err);
          wydaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Wyda');
        }
        return;
      }
      if (wydaOfferingJakundafDesert && (lowerText.includes('no') || lowerText.includes('not'))) {
        wydaOfferingJakundafDesert = false;
        wydaCooldown.queueResponse(text, getMissionCommonLine('notReady', 'Return when you are ready for this task.'), addMessage, 'Wyda');
        return;
      }

      if (wydaOfferingTaintedSouls && (lowerText.includes('yes') || lowerText.includes('accept'))) {
        wydaOfferingTaintedSouls = false;
        try {
          const jakundafDone = getMissionProgress(JAKUNDAF_DESERT_MISSION) || {};
          if (!jakundafDone.completed) {
            wydaCooldown.queueResponse(text, JAKUNDAF_DESERT_MISSION.alreadyActive, addMessage, 'Wyda');
            return;
          }
          await persistMissionProgress(TAINTED_SOULS_MISSION, {
            accepted: true,
            completed: false,
            portalOpened: false,
            battleCompleted: false
          });
          if (typeof setupEkatrixEclipseObserver === 'function') setupEkatrixEclipseObserver();
          if (typeof refreshQuestTileHighlights === 'function') refreshQuestTileHighlights();
          NotificationService.showQuestAccepted(TAINTED_SOULS_MISSION, '[Quests Mod][Wyda]');
          wydaCooldown.queueResponse(text, TAINTED_SOULS_MISSION.accept, addMessage, 'Wyda');
        } catch (err) {
          console.error('[Quests Mod][Wyda] Error accepting The Tainted Souls:', err);
          wydaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Wyda');
        }
        return;
      }
      if (wydaOfferingTaintedSouls && (lowerText.includes('no') || lowerText.includes('not'))) {
        wydaOfferingTaintedSouls = false;
        wydaCooldown.queueResponse(text, getMissionCommonLine('notReady', 'Return when you are ready for this task.'), addMessage, 'Wyda');
        return;
      }

      const lostOracleWonder = tryLostOracleNpcWonderResponse(text, wydaPlayerName, 'wyda', 'Wyda');
      if (lostOracleWonder != null) {
        wydaCooldown.queueResponse(text, lostOracleWonder, addMessage, 'Wyda', ModalHelpers.getFarewellCloseCallback(text));
        return;
      }

      let wydaResponse = getWydaResponse(text, wydaPlayerName);
      if (wydaResponse == null) {
        wydaResponse = getNpcQuestItemChatResponse('wyda', text, wydaPlayerName);
      }
      if (wydaResponse == null) {
        wydaResponse = getRandomNpcConfusionResponse(WYDA_CONFUSION_RESPONSES, wydaPlayerName);
      }
      wydaCooldown.queueResponse(text, wydaResponse, addMessage, 'Wyda', ModalHelpers.getFarewellCloseCallback(text));
    }

    textarea.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendMessageToWyda();
      }
    });
    sendBtn.addEventListener('click', sendMessageToWyda);

    openQuestsModal({
      title: 'Wyda',
      content: contentDiv,
      maxWidth: KING_TIBI_MODAL_WIDTH,
      maxHeight: COSTELLO_MODAL_HEIGHT,
      minHeight: QUESTS_MODAL_CONFIG.npcChat.minHeight,
      onAfterLayout: (dialog) => {
        if (typeof removeDefaultModalFooter === 'function') {
          removeDefaultModalFooter(dialog);
        }
      }
    });
  }

  // Tesha Modal (Darama Oasis) – uses shared NPC chat layout
  async function showTeshaModal() {
    await ensureQuestDialogueLoaded();
    const teshaPlayerName = getCurrentPlayerName() || 'Player';
    const teshaIconUrl = getQuestItemsAssetUrl('Tesha.gif');
    const { contentDiv, addMessage, imageContainer: teshaImageContainer, textarea, sendBtn } = createNPCChatModalContent({
      npcName: 'Tesha',
      playerName: teshaPlayerName,
      imageUrl: teshaIconUrl,
      imageAlt: 'Tesha',
      welcomeMessage: 'Be mourned pilgrim in flesh, ' + teshaPlayerName + '. Welcome to the bank and jewel store.',
      placeholder: 'Type your message to Tesha...',
      modalWidth: KING_TIBI_MODAL_WIDTH,
      modalHeight: COSTELLO_MODAL_HEIGHT,
      messageContainerId: 'tesha-messages'
    });
    setNpcModalPendingBadge(teshaImageContainer, hasTeshaQuestAction());

    const teshaCooldown = createNPCCooldownManager();
    let teshaOfferingSerpentineTower = false;
    let teshaOfferingRealmOfDreams = false;

    async function sendMessageToTesha() {
      const text = (textarea.value || '').trim();
      if (!text) return;
      addMessage(teshaPlayerName, text, false);
      textarea.value = '';
      teshaCooldown.clearPendingResponse();
      const lowerText = text.toLowerCase();

      const scarabProgress = getMissionProgress(KING_SCARAB_COIN_MISSION);
      const serpentineProgress = getMissionProgress(SERPENTINE_TOWER_MISSION);

      // Key to Magic (Book) → "The Key to Magic" quest (prep for a later Realm of
      // Dreams quest). Offered when the player asks Tesha about the book/quest
      // directly, or asks for a "mission" once every earlier Tesha quest is wrapped
      // up. Saying "yes" sends the player down into the Northern Dragon Lair to put
      // out the fire guarding the way; the book is consumed on battle victory, and a
      // further ask on return hands Chayenne's Magical Key over.
      async function handleTeshaRealmOfDreams() {
        const realmProgress = getMissionProgress(REALM_OF_DREAMS_MISSION) || {};

        if (realmProgress.completed) {
          teshaCooldown.queueResponse(
            text,
            getMissionDialogueLine(REALM_OF_DREAMS_MISSION, 'alreadyCompleted', 'The fire in the dragon graveyard is out and the way to the Realm of Dreams stands open. Chayenne herself is a visit for another day.'),
            addMessage,
            'Tesha',
            ModalHelpers.getFarewellCloseCallback(text)
          );
          return;
        }

        // Fire-path cleared, back with Tesha — hand over the reward and close the quest.
        if (isRealmOfDreamsCompletionPending()) {
          const completed = await completeRealmOfDreamsMission();
          teshaCooldown.queueResponse(
            text,
            completed
              ? getMissionDialogueLine(REALM_OF_DREAMS_MISSION, 'reward', "You put out a fire that has guarded the dragon graveyard for an age. Take this: Chayenne's Magical Key. When the time comes to walk into the Realm of Dreams and stand before Chayenne, it will carry you there.")
              : getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'),
            addMessage,
            'Tesha',
            ModalHelpers.getFarewellCloseCallback(text)
          );
          setNpcModalPendingBadge(teshaImageContainer, hasTeshaQuestAction());
          return;
        }

        // Quest accepted, book already spent, battle not yet cleared — offer to step
        // back through the fire (no second book needed).
        if (realmProgress.accepted) {
          teshaOfferingRealmOfDreams = true;
          teshaCooldown.queueResponse(
            text,
            getMissionDialogueLine(REALM_OF_DREAMS_MISSION, 'alreadyActive', 'The Northern Dragon Lair is still burning — the way to Chayenne is not open yet. Shall I send you back down among the bones?'),
            addMessage,
            'Tesha'
          );
          return;
        }

        const draconiaQuestDone = !!(getMissionProgress(DRACONIA_QUEST_MISSION) || {}).completed;
        let hasKeyToMagicBook = false;
        try {
          const questItems = await getQuestItems(false);
          hasKeyToMagicBook = (questItems?.['Key to Magic (Book)'] || 0) >= 1;
        } catch (err) {
          console.error('[Quests Mod][Tesha] Error checking for Key to Magic (Book):', err);
        }
        if (!hasKeyToMagicBook && !draconiaQuestDone) {
          teshaCooldown.queueResponse(
            text,
            getMissionDialogueLine(REALM_OF_DREAMS_MISSION, 'teshaNoBook', 'You speak of the Key to Magic? I cannot read you the way from a rumour, pilgrim. Bring the book itself before me.'),
            addMessage,
            'Tesha',
            ModalHelpers.getFarewellCloseCallback(text)
          );
          return;
        }
        if (!hasKeyToMagicBook) {
          teshaCooldown.queueResponse(
            text,
            'The book itself, pilgrim — not just the memory of it. I cannot read you the way to the dragon graveyard without it. Bring the Key to Magic here.',
            addMessage,
            'Tesha',
            ModalHelpers.getFarewellCloseCallback(text)
          );
          return;
        }

        teshaOfferingRealmOfDreams = true;
        teshaCooldown.queueResponse(
          text,
          getMissionDialogueLine(REALM_OF_DREAMS_MISSION, 'offer', 'The Key to Magic... so it surfaced at last. This book names the one who keeps the Realm of Dreams — Chayenne. It traces the way to her back to the dragon graveyard, the Northern Dragon Lair, and to something down among the bones that still burns and will not let anyone past. Before I can send anyone to her, that has to be put out. Will you go down and end it?'),
          addMessage,
          'Tesha'
        );
      }

      function isRealmOfDreamsEligible() {
        const realm = getMissionProgress(REALM_OF_DREAMS_MISSION) || {};
        if (realm.completed) return false;
        return realm.accepted
          || getCachedQuestItemCount('Key to Magic (Book)') > 0
          || !!(getMissionProgress(DRACONIA_QUEST_MISSION) || {}).completed;
      }

      const askingAboutKeyToMagic =
        lowerText.includes('key to magic') ||
        lowerText.includes('realm of dreams');
      if (askingAboutKeyToMagic) {
        await handleTeshaRealmOfDreams();
        return;
      }

      if (teshaOfferingRealmOfDreams && (lowerText.includes('yes') || lowerText.includes('open'))) {
        teshaOfferingRealmOfDreams = false;
        const alreadyAccepted = !!(getMissionProgress(REALM_OF_DREAMS_MISSION) || {}).accepted;
        try {
          if (!alreadyAccepted) {
            const questItems = await getQuestItems(false);
            if ((questItems?.['Key to Magic (Book)'] || 0) < 1) {
              teshaCooldown.queueResponse(
                text,
                getMissionDialogueLine(REALM_OF_DREAMS_MISSION, 'teshaNoBook', 'The book is gone from your hands, pilgrim. I cannot read you the way to the dragon graveyard without it.'),
                addMessage,
                'Tesha',
                ModalHelpers.getFarewellCloseCallback(text)
              );
              return;
            }
            // The book is spent walking through the fire — consumed on battle victory,
            // not here, so a defeat leaves it in hand for another attempt.
            await persistMissionProgress(REALM_OF_DREAMS_MISSION, { accepted: true, completed: false, battleCompleted: false });
            NotificationService.showQuestAccepted(REALM_OF_DREAMS_MISSION, '[Quests Mod][Tesha]');
            setNpcModalPendingBadge(teshaImageContainer, hasTeshaQuestAction());
          }
        } catch (err) {
          console.error('[Quests Mod][Tesha] Error starting Realm of Dreams battle:', err);
          teshaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Tesha');
          return;
        }
        teshaCooldown.queueResponse(
          text,
          getMissionDialogueLine(REALM_OF_DREAMS_MISSION, 'accept', 'Then go down among the bones, and hold nothing back. End the fire there and the way to the Realm of Dreams stands open at last.'),
          addMessage,
          'Tesha',
          () => {
            setTimeout(() => {
              ModalHelpers.closeModal(0);
              enterRealmOfDreams();
            }, 2000);
          }
        );
        return;
      }

      if (teshaOfferingRealmOfDreams && (lowerText.includes('no') || lowerText.includes('not'))) {
        teshaOfferingRealmOfDreams = false;
        teshaCooldown.queueResponse(
          text,
          getMissionDialogueLine(REALM_OF_DREAMS_MISSION, 'decline', 'Then the fire keeps the graveyard, as it has for an age. Come back when you are ready to go down.'),
          addMessage,
          'Tesha',
          ModalHelpers.getFarewellCloseCallback(text)
        );
        return;
      }

      // Player is back from the fire-path — almost anything on-topic hands the reward over.
      if (isRealmOfDreamsCompletionPending()
        && (lowerText.includes('reward') || lowerText.includes('mission') || lowerText.includes('quest')
          || lowerText.includes('key') || lowerText.includes('chayenne') || lowerText.includes('dream')
          || lowerText.includes('done') || lowerText.includes('back') || lowerText.includes('fire')
          || lowerText.includes('magic'))) {
        await handleTeshaRealmOfDreams();
        return;
      }

      const wantsSerpentineReward =
        lowerText.includes('mission') ||
        lowerText.includes('quest') ||
        lowerText.includes('reward') ||
        lowerText.includes('sceptre') ||
        lowerText.includes('scepter') ||
        lowerText.includes('putrid') ||
        lowerText.includes('chamber');
      if (
        serpentineProgress.accepted &&
        serpentineProgress.putridChamberComplete &&
        !serpentineProgress.completed &&
        wantsSerpentineReward
      ) {
        try {
          const rewarded = await completeSerpentineTowerQuestWithTeshaReward();
          if (rewarded) {
            const completeLines = SERPENTINE_TOWER_MISSION.teshaRewardLines.map(
              line => line.replace(/Player/g, teshaPlayerName)
            );
            teshaCooldown.queueResponse(text, completeLines, addMessage, 'Tesha');
          } else {
            teshaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Tesha');
          }
        } catch (err) {
          console.error('[Quests Mod][Tesha] Error completing Serpentine Tower quest reward:', err);
          teshaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Tesha');
        }
        return;
      }

      const giveCoinKeywords = ['scarab coin', 'scarab', 'coin', 'give', 'here', 'take', 'offer', 'show'];
      const wantsToGiveCoin =
        giveCoinKeywords.some(kw => lowerText.includes(kw)) ||
        (lowerText.includes('yes') && !teshaOfferingSerpentineTower);
      if (scarabProgress.accepted && !scarabProgress.completed && wantsToGiveCoin) {
        try {
          const questItems = await getQuestItems(false);
          const hasCoin = (questItems[SCARAB_COIN_CONFIG.productName] || 0) >= 1;
          if (hasCoin) {
            await consumeQuestItem(SCARAB_COIN_CONFIG.productName, 1);
            await completeLostInTheSandsQuest({ showCompletionToast: true });
            const completeLines = [
              ...KING_SCARAB_COIN_MISSION.teshaCompleteLines,
              KING_SCARAB_COIN_MISSION.teshaCompleteCoinLine.replace('{coins}', String(KING_SCARAB_COIN_MISSION.rewardCoins))
            ].map(line => line.replace(/Player/g, teshaPlayerName));
            teshaCooldown.queueResponse(text, completeLines, addMessage, 'Tesha');
            return;
          }
          teshaCooldown.queueResponse(text, KING_SCARAB_COIN_MISSION.teshaNoCoin, addMessage, 'Tesha');
          return;
        } catch (err) {
          console.error('[Quests Mod][Tesha] Error completing Lost in the Sands:', err);
          teshaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Tesha');
          return;
        }
      }

      if (scarabProgress.completed && wantsToGiveCoin) {
        teshaCooldown.queueResponse(
          text,
          KING_SCARAB_COIN_MISSION.teshaAlreadyCompleted.replace(/Player/g, teshaPlayerName),
          addMessage,
          'Tesha'
        );
        return;
      }

      if (lowerText.includes('mission') || lowerText.includes('quest')) {
        // When no earlier Tesha chain is mid-progress and the player has earned the
        // Key to Magic (Book), Realm of Dreams is the current offer.
        const scarabActive = scarabProgress.accepted && !scarabProgress.completed;
        const serpentineActive = serpentineProgress.accepted && !serpentineProgress.completed;
        if (!scarabActive && !serpentineActive && isRealmOfDreamsEligible()) {
          await handleTeshaRealmOfDreams();
          return;
        }

        if (scarabProgress.accepted && !scarabProgress.completed) {
          teshaCooldown.queueResponse(
            text,
            KING_SCARAB_COIN_MISSION.teshaAskForCoin.replace(/Player/g, teshaPlayerName),
            addMessage,
            'Tesha'
          );
          return;
        }

        if (!scarabProgress.completed) {
          teshaCooldown.queueResponse(
            text,
            SERPENTINE_TOWER_MISSION.requiresMeetingWithTesha.replace(/Player/g, teshaPlayerName),
            addMessage,
            'Tesha'
          );
          return;
        }

        if (!serpentineProgress.accepted) {
          teshaOfferingSerpentineTower = true;
          teshaCooldown.queueResponse(
            text,
            SERPENTINE_TOWER_MISSION.prompt.replace(/Player/g, teshaPlayerName),
            addMessage,
            'Tesha'
          );
          return;
        }

        if (!serpentineProgress.completed) {
          if (serpentineProgress.putridChamberComplete) {
            teshaCooldown.queueResponse(
              text,
              SERPENTINE_TOWER_MISSION.putridChamberReturnObjective.replace(/Player/g, teshaPlayerName),
              addMessage,
              'Tesha'
            );
            return;
          }
          teshaCooldown.queueResponse(
            text,
            SERPENTINE_TOWER_MISSION.alreadyActive.replace(/Player/g, teshaPlayerName),
            addMessage,
            'Tesha'
          );
          return;
        }

        teshaCooldown.queueResponse(
          text,
          SERPENTINE_TOWER_MISSION.alreadyCompleted.replace(/Player/g, teshaPlayerName),
          addMessage,
          'Tesha'
        );
        return;
      }

      if (teshaOfferingSerpentineTower && lowerText.includes('yes')) {
        teshaOfferingSerpentineTower = false;
        if (!getMissionProgress(KING_SCARAB_COIN_MISSION).completed) {
          teshaCooldown.queueResponse(
            text,
            SERPENTINE_TOWER_MISSION.requiresMeetingWithTesha.replace(/Player/g, teshaPlayerName),
            addMessage,
            'Tesha'
          );
          return;
        }
        try {
          const questItems = await getQuestItems(false);
          const hasRune = (questItems?.[DESTROY_FIELD_RUNE_CONFIG.productName] || 0) >= 1;
          await persistMissionProgress(SERPENTINE_TOWER_MISSION, buildSerpentineTowerProgress({
            accepted: true,
            completed: false,
            destroyFieldRuneTaken: hasRune,
            putridChamberComplete: false
          }));
          teshaCooldown.queueResponse(
            text,
            SERPENTINE_TOWER_MISSION.accept.replace(/Player/g, teshaPlayerName),
            addMessage,
            'Tesha'
          );
          NotificationService.showQuestAccepted(SERPENTINE_TOWER_MISSION, '[Quests Mod][Tesha]');
          updateSerpentineBasementRightClickState(globalThis.state?.board?.getSnapshot?.()?.context);
          setTimeout(() => {
            updateSerpentineBasementRightClickState(globalThis.state?.board?.getSnapshot?.()?.context);
          }, FISHING_CONFIG.MAP_SWITCH_DELAY);
        } catch (err) {
          console.error('[Quests Mod][Tesha] Error accepting Serpentine Tower quest:', err);
          teshaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Tesha');
        }
        return;
      }

      if (teshaOfferingSerpentineTower && (lowerText.includes('no') || lowerText.includes('not'))) {
        teshaOfferingSerpentineTower = false;
        teshaCooldown.queueResponse(text, getMissionCommonLine('notReady', 'Return when you are ready for this task.'), addMessage, 'Tesha');
        return;
      }

      if (teshaOfferingSerpentineTower) {
        teshaCooldown.queueResponse(
          text,
          SERPENTINE_TOWER_MISSION.answerYesNo.replace(/Player/g, teshaPlayerName),
          addMessage,
          'Tesha'
        );
        return;
      }

      const askingMagicElf =
        lowerText.includes('magic elf') ||
        lowerText.includes('magic elves');
      if (askingMagicElf) {
        const serpentineProgress = getMissionProgress(SERPENTINE_TOWER_MISSION);
        if (serpentineProgress.accepted && !serpentineProgress.completed) {
          try {
            const questItems = await getQuestItems(false);
            const hasRune = (questItems?.[DESTROY_FIELD_RUNE_CONFIG.productName] || 0) >= 1;
            teshaCooldown.queueResponse(
              text,
              (hasRune
                ? SERPENTINE_TOWER_MISSION.destroyFieldRuneAlreadyHave
                : (SERPENTINE_TOWER_MISSION.magicElfHint
                  || 'Search Shadowthorn near Venore for the remains of a magic elf. The destroy field rune rests upon that corpse, Player.')
              ).replace(/Player/g, teshaPlayerName),
              addMessage,
              'Tesha'
            );
          } catch (err) {
            console.error('[Quests Mod][Tesha] Error responding about magic elf:', err);
            teshaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Tesha');
          }
          return;
        }
      }

      const askingDestroyFieldRune =
        lowerText.includes('destroy field rune') ||
        lowerText.includes('destroy field') ||
        lowerText.includes('field rune') ||
        lowerText.includes('adito grav');
      if (askingDestroyFieldRune) {
        const serpentineProgress = getMissionProgress(SERPENTINE_TOWER_MISSION);
        if (serpentineProgress.accepted && !serpentineProgress.completed) {
          try {
            const questItems = await getQuestItems(false);
            const hasRune = (questItems?.[DESTROY_FIELD_RUNE_CONFIG.productName] || 0) >= 1;
            teshaCooldown.queueResponse(
              text,
              (hasRune
                ? SERPENTINE_TOWER_MISSION.destroyFieldRuneAlreadyHave
                : SERPENTINE_TOWER_MISSION.destroyFieldRuneHint
              ).replace(/Player/g, teshaPlayerName),
              addMessage,
              'Tesha'
            );
          } catch (err) {
            console.error('[Quests Mod][Tesha] Error responding about Destroy Field Rune:', err);
            teshaCooldown.queueResponse(text, getMissionCommonLine('errorGeneric', 'Something went wrong. Please try again.'), addMessage, 'Tesha');
          }
          return;
        }
      }

      const lostOracleWonder = tryLostOracleNpcWonderResponse(text, teshaPlayerName, 'tesha', 'Tesha');
      if (lostOracleWonder != null) {
        teshaCooldown.queueResponse(text, [lostOracleWonder], addMessage, 'Tesha', ModalHelpers.getFarewellCloseCallback(text));
        return;
      }

      let teshaLines = getTeshaResponse(text, teshaPlayerName);
      if (teshaLines == null) {
        const questItemLine = getNpcQuestItemChatResponse('tesha', text, teshaPlayerName);
        if (questItemLine != null) teshaLines = [questItemLine];
      }
      if (teshaLines == null) {
        teshaLines = [getRandomNpcConfusionResponse(TESHA_CONFUSION_RESPONSES, teshaPlayerName)];
      }
      teshaCooldown.queueResponse(text, teshaLines, addMessage, 'Tesha', ModalHelpers.getFarewellCloseCallback(text));
    }

    textarea.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendMessageToTesha();
      }
    });
    sendBtn.addEventListener('click', sendMessageToTesha);

    openQuestsModal({
      title: 'Tesha',
      content: contentDiv,
      maxWidth: KING_TIBI_MODAL_WIDTH,
      maxHeight: COSTELLO_MODAL_HEIGHT,
      minHeight: QUESTS_MODAL_CONFIG.npcChat.minHeight,
      onAfterLayout: (dialog) => {
        if (typeof removeDefaultModalFooter === 'function') {
          removeDefaultModalFooter(dialog);
        }
      }
    });
  }

  // =======================
  // 7. Quest Log
  // =======================

  function isNativeQuestLogDialog(dialog) {
    if (!dialog || dialog.getAttribute('data-ba-mod-dialog') === '1') return false;
    if (dialog.querySelector('.quests-modal-content')) return false;
    const titleEl = dialog.querySelector('h2.widget-top p, .widget-top-text p, .widget-top p');
    return !!(titleEl && titleEl.textContent?.trim() === 'Quest Log');
  }

  function isQuestsModDialogOpen() {
    return !!(
      document.querySelector('[data-ba-mod-dialog="1"]') ||
      document.querySelector('.quests-modal-content')
    );
  }

  function findQuestLogContainer() {
    const selectors = [
      '.widget-bottom .grid.h-\\[260px\\].items-start.gap-1', // Most specific
      '[data-radix-scroll-area-viewport] .grid.h-\\[260px\\].items-start.gap-1',
      '.grid.h-\\[260px\\].items-start.gap-1',
      '.widget-bottom .grid.items-start.gap-1',
      '[data-radix-scroll-area-viewport] .grid.items-start.gap-1',
      '.grid.items-start.gap-1'
    ];
    
    for (let i = 0; i < selectors.length; i++) {
      const selector = selectors[i];
      const candidates = document.querySelectorAll(selector);

      for (const container of candidates) {
        const dialog = container.closest('div[role="dialog"]');
        if (!isNativeQuestLogDialog(dialog)) continue;

        // Only log on first successful find to reduce spam
        if (!window.questsModLoggedContainer) {
          console.log(`[Quests Mod] Found quest log container with selector: ${selector}`);
          window.questsModLoggedContainer = true;
        }
        return container;
      }
    }
    
    return null;
  }

  function findQuestLogFooter() {
    const selectors = [
      '.widget-bottom .flex.justify-end.gap-2',
      '.flex.justify-end.gap-2'
    ];

    for (const selector of selectors) {
      const footers = document.querySelectorAll(selector);
      for (const footer of footers) {
        const dialog = footer.closest('div[role="dialog"]');
        if (isNativeQuestLogDialog(dialog)) {
          return footer;
        }
      }
    }

    return null;
  }

  function resetNativeQuestLogDialogLayout() {
    const footer = findQuestLogFooter();
    const dialog = footer?.closest('div[role="dialog"]');
    if (!dialog || dialog.querySelector('.quests-modal-content')) return;

    dialog.style.removeProperty('width');
    dialog.style.removeProperty('min-width');
    dialog.style.removeProperty('max-width');
    dialog.style.removeProperty('height');
    dialog.style.removeProperty('min-height');
    dialog.style.removeProperty('max-height');
    dialog.style.removeProperty('box-sizing');

    const contentWrapper = dialog.querySelector(':scope > div') || dialog.firstElementChild;
    if (contentWrapper) {
      contentWrapper.style.removeProperty('height');
      contentWrapper.style.removeProperty('display');
      contentWrapper.style.removeProperty('flex-direction');
      contentWrapper.style.removeProperty('flex');
      contentWrapper.style.removeProperty('min-height');
    }

    const widgetBottom = dialog.querySelector('.widget-bottom');
    if (widgetBottom) {
      widgetBottom.style.removeProperty('display');
      widgetBottom.style.removeProperty('flex-direction');
      widgetBottom.style.removeProperty('flex');
      widgetBottom.style.removeProperty('min-height');
      widgetBottom.style.removeProperty('overflow');
    }

    lockNativeQuestLogListSize(findQuestLogContainer());
  }

  const QUEST_LOG_LIST_HEIGHT_PX = 260;

  function getQuestLogScrollAreaRoot(questLogContainer) {
    if (!questLogContainer) return null;
    const viewport = questLogContainer.closest('[data-radix-scroll-area-viewport]');
    if (viewport?.parentElement) return viewport.parentElement;
    return questLogContainer.closest('.relative.overflow-hidden.frame-pressed-1');
  }

  function lockNativeQuestLogListSize(questLogContainer = findQuestLogContainer()) {
    const container = questLogContainer || findQuestLogContainer();
    const scrollRoot = getQuestLogScrollAreaRoot(container);
    if (!scrollRoot) return;

    const height = `${QUEST_LOG_LIST_HEIGHT_PX}px`;
    scrollRoot.style.height = height;
    scrollRoot.style.minHeight = height;
    scrollRoot.style.maxHeight = height;
    scrollRoot.style.overflow = 'hidden';
    scrollRoot.style.boxSizing = 'border-box';
    scrollRoot.style.flex = '0 0 auto';

    if (container) {
      container.style.height = 'auto';
      container.style.minHeight = '0';
      container.style.maxHeight = 'none';
    }

    const viewport = scrollRoot.querySelector('[data-radix-scroll-area-viewport]');
    if (viewport) {
      viewport.style.height = '100%';
      viewport.style.maxHeight = '100%';
      bindNativeQuestLogScrollbar(scrollRoot, viewport);
    }
    syncNativeQuestLogScrollbar(scrollRoot);
    requestAnimationFrame(() => syncNativeQuestLogScrollbar(scrollRoot));
  }

  function getQuestLogScrollbarParts(scrollRoot) {
    if (!scrollRoot) return {};
    const viewport = scrollRoot.querySelector('[data-radix-scroll-area-viewport]');
    const scrollbar = scrollRoot.querySelector('[data-orientation="vertical"]');
    const thumb = scrollbar?.querySelector('[data-orientation="vertical"]') || scrollbar?.firstElementChild;
    return { viewport, scrollbar, thumb };
  }

  function syncNativeQuestLogScrollbar(scrollRoot) {
    const { viewport, scrollbar, thumb } = getQuestLogScrollbarParts(scrollRoot);
    if (!viewport || !scrollbar || !thumb) return;

    const viewportHeight = viewport.clientHeight;
    const scrollHeight = viewport.scrollHeight;
    if (viewportHeight <= 0) return;

    if (scrollHeight <= viewportHeight + 1) {
      scrollbar.style.setProperty('--radix-scroll-area-thumb-height', `${viewportHeight}px`);
      thumb.style.height = 'var(--radix-scroll-area-thumb-height)';
      thumb.style.transform = 'translate3d(0px, 0px, 0px)';
      return;
    }

    const thumbHeight = Math.max(24, (viewportHeight / scrollHeight) * viewportHeight);
    const maxOffset = Math.max(0, viewportHeight - thumbHeight);
    const range = scrollHeight - viewportHeight;
    const offset = range > 0 ? (viewport.scrollTop / range) * maxOffset : 0;
    scrollbar.style.setProperty('--radix-scroll-area-thumb-height', `${thumbHeight}px`);
    thumb.style.height = 'var(--radix-scroll-area-thumb-height)';
    thumb.style.transform = `translate3d(0px, ${offset}px, 0px)`;
  }

  function bindNativeQuestLogScrollbar(scrollRoot, viewport) {
    if (!viewport || viewport.dataset.questsScrollBound === '1') return;
    viewport.dataset.questsScrollBound = '1';
    const update = () => syncNativeQuestLogScrollbar(scrollRoot);
    viewport.addEventListener('scroll', update, { passive: true });
    if (typeof ResizeObserver === 'function') {
      const observer = new ResizeObserver(update);
      observer.observe(viewport);
      if (viewport.firstElementChild) observer.observe(viewport.firstElementChild);
    }
  }

  function getKingTabElement() {
    const kingTab = document.getElementById(KING_TIBIANUS_TAB_ID);
    return kingTab && isInDOM(kingTab) ? kingTab : null;
  }

  function getArenaLeaderboardTabElement() {
    const tab = document.getElementById(ARENA_LEADERBOARD_TAB_ID);
    return tab && isInDOM(tab) ? tab : null;
  }

  function getQuestAdminDevTabElement() {
    const tab = document.getElementById(QUEST_ADMIN_DEV_TAB_ID);
    return tab && isInDOM(tab) ? tab : null;
  }

  async function isCurrentPlayerQuestAdminAsync() {
    try {
      const playerName = getCurrentPlayerName();
      if (!playerName) return false;
      const adminApi = globalThis.FirebaseAdminsAPI || (typeof window !== 'undefined' ? window.FirebaseAdminsAPI : null);
      if (!adminApi) return false;
      if (typeof adminApi.isPlayerAdminAsync === 'function') {
        return Boolean(await adminApi.isPlayerAdminAsync(playerName));
      }
      if (typeof adminApi.isPlayerAdmin === 'function') {
        if (typeof adminApi.refreshAdminList === 'function') {
          await adminApi.refreshAdminList();
        }
        return Boolean(adminApi.isPlayerAdmin(playerName));
      }
      return false;
    } catch (error) {
      console.warn('[Quests Mod] Admin check failed:', error);
      return false;
    }
  }

  function getActiveMissionTabId(tabKey) {
    return `${ACTIVE_MISSION_TAB_ID_PREFIX}${tabKey}`;
  }

  function getActiveMissionTabElements() {
    return Array.from(document.querySelectorAll(`[id^="${ACTIVE_MISSION_TAB_ID_PREFIX}"]`))
      .filter((el) => isInDOM(el));
  }

  function getActiveQuestLogMissions() {
    return QUEST_LOG_MISSIONS.filter((mission) => MissionManager.isActive(mission));
  }

  /**
   * Expand active missions into Quest Log tab entries.
   * Most missions map 1:1; red dragon materials get one tab per material.
   */
  function getActiveMissionTabEntries(activeMissions = getActiveQuestLogMissions()) {
    const entries = [];
    for (const mission of activeMissions) {
      if (mission.id === KING_RED_DRAGON_MISSION.id) {
        const scales = Math.min(getCachedQuestItemCount('Red Dragon Scale'), 30);
        const leathers = Math.min(getCachedQuestItemCount('Red Dragon Leather'), 30);
        entries.push({
          key: `${mission.id}:scales`,
          missionId: mission.id,
          mission,
          objective: mission.objectiveLine1 || 'Gather 30 red dragon scales.',
          progress: makeActiveMissionCountProgress(scales, 30),
          iconFilename: 'Red_Dragon_Scale.png'
        });
        entries.push({
          key: `${mission.id}:leathers`,
          missionId: mission.id,
          mission,
          objective: mission.objectiveLine2 || 'Gather 30 red dragon leathers.',
          progress: makeActiveMissionCountProgress(leathers, 30),
          iconFilename: 'Red_Dragon_Leather.png'
        });
        continue;
      }
      entries.push({
        key: mission.id,
        missionId: mission.id,
        mission,
        objective: null,
        progress: null,
        iconFilename: null
      });
    }
    return entries;
  }

  function getMissionQuestLogIconFilename(mission) {
    if (!mission) return 'King_Tibianus.gif';
    return MISSION_QUEST_LOG_ICON_MAP[mission.id] || 'King_Tibianus.gif';
  }

  function getMissionQuestLogSpriteId(mission) {
    if (!mission) return null;
    const spriteId = MISSION_QUEST_LOG_SPRITE_ICON_MAP[mission.id];
    return Number.isFinite(spriteId) ? spriteId : null;
  }

  function createActiveMissionIconElement(mission, iconFilenameOverride = null) {
    if (!iconFilenameOverride) {
      const spriteId = getMissionQuestLogSpriteId(mission);
      if (spriteId != null) {
        const wrap = document.createElement('div');
        wrap.className = `sprite item relative id-${spriteId}`;
        wrap.style.zIndex = '1000';
        wrap.innerHTML = `<div class="viewport"><img alt="${spriteId}" data-cropped="false" class="spritesheet" style="--cropX: 0; --cropY: 0;"></div>`;
        return wrap;
      }
    }

    const iconImg = document.createElement('img');
    iconImg.alt = mission?.title || 'Mission';
    iconImg.className = 'pixelated';
    iconImg.width = 32;
    iconImg.height = 32;
    iconImg.src = getQuestItemsAssetUrl(iconFilenameOverride || getMissionQuestLogIconFilename(mission));
    iconImg.style.imageRendering = 'pixelated';
    return iconImg;
  }

  function getCachedQuestItemCount(itemName) {
    return cachedQuestItems?.[itemName] || 0;
  }

  function getLetterMissionItemCounts(products = cachedQuestItems) {
    const items = products && typeof products === 'object' ? products : {};
    return {
      letterCount: items['Letter from Al Dee'] || 0,
      stampedLetterCount: items['Stamped Letter'] || 0
    };
  }

  function getLetterMissionOfferPrompt(mission, products = cachedQuestItems) {
    const { letterCount } = getLetterMissionItemCounts(products);
    if (letterCount > 0) {
      return mission?.promptWithLetter || mission?.prompt || '';
    }
    return mission?.prompt || '';
  }

  function getLetterMissionObjectiveText(mission = KING_LETTER_MISSION, products = cachedQuestItems) {
    const { letterCount, stampedLetterCount } = getLetterMissionItemCounts(products);
    if (stampedLetterCount > 0) {
      return mission?.objectiveLine2 || 'Return the stamped letter to Al Dee.';
    }
    if (letterCount > 0) {
      return mission?.objectiveLineBringLetter || 'Bring the letter to King Tibianus to be stamped.';
    }
    return mission?.objectiveLine1 || 'Find Al Dee.';
  }

  function getLetterMissionAlreadyActiveReply(mission = KING_LETTER_MISSION, products = cachedQuestItems) {
    const { letterCount, stampedLetterCount } = getLetterMissionItemCounts(products);
    if (stampedLetterCount > 0) {
      return mission?.alreadyActiveStamped
        || 'You already have my stamp on that letter. Deliver it to Al Dee in Rookgaard to finish this task.';
    }
    if (letterCount > 0) {
      return mission?.alreadyActiveWithLetter
        || 'You already have Al Dee\'s letter. Hand it to me and I shall stamp it for delivery.';
    }
    return mission?.alreadyActive
      || 'You are already on this task. Seek Al Dee in Rookgaard — and bring me any letter of his you find so I may stamp it.';
  }

  function makeActiveMissionCountProgress(current, total) {
    const safeTotal = Math.max(1, total);
    return {
      current: Math.max(0, Math.min(current, safeTotal)),
      total: safeTotal
    };
  }

  function hasSerpentineDestroyFieldRune() {
    return getCachedQuestItemCount(DESTROY_FIELD_RUNE_CONFIG.productName) > 0
      || !!getMissionProgress(SERPENTINE_TOWER_MISSION)?.destroyFieldRuneTaken;
  }

  function getActiveMissionObjectiveLine(mission) {
    if (!mission) return 'In progress';
    const progress = getMissionProgress(mission);

    if (mission.id === SERPENTINE_TOWER_MISSION.id) {
      if (progress?.putridChamberComplete) {
        return mission.putridChamberReturnObjective
          || 'Return to Tesha in Darama Oasis to receive your reward.';
      }
      if (hasSerpentineDestroyFieldRune()) {
        return mission.objectiveLine2
          || 'Clear the energy fields and use the lever in the Serpentine Tower basement.';
      }
      return mission.objectiveLine1
        || 'Find a Destroy Field Rune in Shadowthorn near Venore.';
    }

    if (mission.id === KING_LETTER_MISSION.id) {
      return getLetterMissionObjectiveText(mission);
    }

    if (mission.id === KING_SCARAB_COIN_MISSION.id) {
      if (getCachedQuestItemCount(SCARAB_COIN_CONFIG.productName) > 0) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === KING_HONEYFLOWER_MISSION.id) {
      if (getCachedQuestItemCount(HONEYFLOWER_CONFIG.productName) > 0 || progress?.honeyflowerPicked) {
        return mission.objectiveLine2;
      }
      return mission.objectiveLine1;
    }

    if (mission.id === KING_COPPER_KEY_MISSION.id) {
      if (getCachedQuestItemCount(COPPER_KEY_CONFIG.productName) > 0) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === KING_RED_DRAGON_MISSION.id) {
      if (getCachedQuestItemCount('Red Dragon Scale') < 30) return mission.objectiveLine1;
      return mission.objectiveLine2;
    }

    if (mission.id === AL_DEE_FISHING_MISSION.id) {
      if (getCachedQuestItemCount('Small Axe') > 0) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === AL_DEE_GOLDEN_ROPE_MISSION.id) {
      if (getCachedQuestItemCount('Elvenhair Rope') > 0) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === COSTELLO_QUEEN_BANSHEES_MISSION.id) {
      const done = (kingChatState.sevenSealsCompleted || []).filter(Boolean).length;
      if (done >= SEVEN_SEALS_COUNT) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === FOLLOWER_OF_ZATHROTH_MISSION.id) {
      if (getCachedQuestItemCount(COSTELLO_QUEEN_BANSHEES_MISSION.rewardItemName) > 0) {
        return mission.objectiveLine2;
      }
      return mission.objectiveLine1;
    }

    if (mission.id === MOTHER_OF_ALL_SPIDERS_MISSION.id) {
      if (getCachedQuestItemCount('Spider Silk') > 0) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === JAKUNDAF_DESERT_MISSION.id) {
      if (progress?.pathCleared) return mission.objectiveLine3 || mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === TAINTED_SOULS_MISSION.id) {
      if (progress?.battleCompleted) return mission.objectiveLine3 || mission.objectiveLine2;
      if (progress?.portalOpened) return mission.objectiveLine2 || mission.objectiveLine1;
      return mission.objectiveLine1;
    }

    if (mission.id === APPRENTICE_SHENG_MISSION.id) {
      if (progress?.battleCompleted) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === CHRISTMAS_MIRACLE_MISSION.id) {
      if (getCachedQuestItemCount(PRESENT_CONFIG.productName) > 0) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === SVENSON_LOVE_STORY_MISSION.id) {
      if (progress?.strandedAtWhiteWave && !progress?.whiteWaveSlippersDelivered) return mission.objectiveLine9 || mission.objectiveLine8 || mission.objectiveLine7;
      if (progress?.strandedAtUnderground && progress?.undergroundCompassDelivered && !progress?.strandedAtWhiteWave) return mission.objectiveLine8 || mission.objectiveLine7;
      if (progress?.strandedAtUnderground && !progress?.undergroundCompassDelivered) {
        if (!progress?.undergroundCompassRequested) return mission.objectiveLine6 || mission.objectiveLine5;
        return mission.objectiveLine7 || mission.objectiveLine6 || mission.objectiveLine5;
      }
      if (progress?.strandedAtAwash && !progress?.awashYarnDelivered) {
        if (!progress?.awashYarnRequested) return mission.objectiveLine3 || mission.objectiveLine2;
        return mission.objectiveLine4 || mission.objectiveLine3 || mission.objectiveLine2;
      }
      if (progress?.strandedAtAwash && progress?.awashYarnDelivered && !progress?.strandedAtUnderground && !progress?.completed) {
        return mission.objectiveLine5 || mission.objectiveLine4 || mission.objectiveLine3;
      }
      if (progress?.plankDelivered) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === WEAKENED_ARCHDEMON_MISSION.id) {
      if (progress?.battleCompleted) return mission.objectiveLine3 || mission.objectiveLine2;
      if (playerTraveledToGhazHideout || isOnRoomByName(GHAZBARAN_HIDEOUT_ROOM_NAME)) {
        return mission.objectiveLine2 || mission.objectiveLine1;
      }
      return mission.objectiveLine1;
    }

    if (mission.id === LOST_ORACLE_MISSION.id) {
      if (progress?.completed || progress?.oracleDismissed) {
        return mission.objectiveLine6 || mission.objectiveLine5 || "Survive The Oracle's wrath.";
      }
      if (progress?.battleCompleted) {
        return mission.objectiveLine6 || 'Speak with The Oracle.';
      }
      if (progress?.oracleEnraged || playerAcceptedOracleRageBattle) {
        return mission.objectiveLine5 || "Survive The Oracle's wrath.";
      }
      if (progress?.spectralStoneReceived || hasSpectralStoneInInventory()) {
        return mission.objectiveLine4 || 'Return the Spectral Stone to The Oracle.';
      }
      if (progress?.orbExchanged || hasLuminousOrbInInventory()) {
        return mission.objectiveLine3 || 'Bring the Luminous Orb to Wyda in the Venore swamps.';
      }
      if (progress?.kingInformed) {
        return mission.objectiveLine2 || 'Bring an Orb to King Tibianus.';
      }
      return mission.objectiveLine1 || 'Ask other NPCs about the Oracle.';
    }

    if (mission.id === KING_CROSSING_THE_LINE_MISSION.id) {
      if (progress?.crossingObjectiveComplete) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    if (mission.id === KING_MONKS_STUDY_MISSION.id) {
      if (kingChatState.costelloVisited) return mission.objectiveLine2;
      return mission.objectiveLine1;
    }

    return mission.objectiveLine1 || mission.objectiveLine2 || 'In progress';
  }

  function getActiveMissionHintLine(mission) {
    if (!mission) return '';
    const progress = getMissionProgress(mission);

    if (mission.id === SERPENTINE_TOWER_MISSION.id) {
      if (progress?.putridChamberComplete) return '';
      if (hasSerpentineDestroyFieldRune()) {
        return mission.hintBasement || mission.hint || '';
      }
      return mission.hint || '';
    }

    if (mission.id === SVENSON_LOVE_STORY_MISSION.id) {
      if (progress?.strandedAtWhiteWave && !progress?.whiteWaveSlippersDelivered) {
        return mission.hintWhiteWave || mission.hint || '';
      }
      if (progress?.strandedAtUnderground && progress?.undergroundCompassDelivered && !progress?.strandedAtWhiteWave) {
        return '';
      }
      if (progress?.strandedAtUnderground && !progress?.undergroundCompassDelivered) {
        if (!progress?.undergroundCompassRequested) return '';
        return mission.hintUnderground || mission.hint || '';
      }
      if (progress?.strandedAtAwash && progress?.awashYarnDelivered && !progress?.strandedAtUnderground) {
        return '';
      }
      if (progress?.strandedAtAwash && !progress?.awashYarnDelivered) {
        if (!progress?.awashYarnRequested) return '';
        return mission.hintAwash || mission.hint || '';
      }
      if (progress?.plankDelivered) {
        // Travel step ("Talk to Svenson and set sail") should not display item-finding hints.
        return '';
      }
      return mission.hint || '';
    }

    if (mission.id === LOST_ORACLE_MISSION.id) {
      if (progress?.battleCompleted && !progress?.completed && !progress?.oracleDismissed) {
        return mission.hintThanks || 'The Oracle awaits your return in the Monastery Catacombs.';
      }
      if (progress?.oracleEnraged || playerAcceptedOracleRageBattle) {
        return mission.hintBattle || '';
      }
      if (progress?.spectralStoneReceived || hasSpectralStoneInInventory()) {
        return mission.hintSpectral || mission.hint || '';
      }
      return mission.hint || '';
    }

    if (mission.id === TAINTED_SOULS_MISSION.id) {
      if (progress?.battleCompleted) return mission.hintReport || mission.hint || '';
      if (progress?.portalOpened) return mission.hintPortal || mission.hint || '';
      return mission.hint || '';
    }

    return mission.hint || '';
  }

  function getActiveMissionProgressDisplay(mission) {
    if (!mission) return null;
    const progress = getMissionProgress(mission);

    if (mission.id === KING_RED_DRAGON_MISSION.id) {
      const scales = Math.min(getCachedQuestItemCount('Red Dragon Scale'), 30);
      const leathers = Math.min(getCachedQuestItemCount('Red Dragon Leather'), 30);
      // Combined fallback if a single tab path is used; Quest Log uses split tabs.
      return makeActiveMissionCountProgress(scales + leathers, 60);
    }

    if (mission.id === COSTELLO_QUEEN_BANSHEES_MISSION.id) {
      const done = (kingChatState.sevenSealsCompleted || []).filter(Boolean).length;
      return makeActiveMissionCountProgress(done, SEVEN_SEALS_COUNT);
    }

    if (mission.id === KING_HONEYFLOWER_MISSION.id) {
      const has = getCachedQuestItemCount(HONEYFLOWER_CONFIG.productName) > 0 || !!progress?.honeyflowerPicked;
      return makeActiveMissionCountProgress(has ? 1 : 0, 1);
    }

    if (mission.id === KING_CROSSING_THE_LINE_MISSION.id) {
      return makeActiveMissionCountProgress(progress?.crossingObjectiveComplete ? 1 : 0, 1);
    }

    if (mission.id === KING_SCARAB_COIN_MISSION.id) {
      const hasCoin = getCachedQuestItemCount(SCARAB_COIN_CONFIG.productName) > 0;
      return makeActiveMissionCountProgress(hasCoin ? 1 : 0, 1);
    }

    if (mission.id === KING_COPPER_KEY_MISSION.id) {
      const hasKey = getCachedQuestItemCount(COPPER_KEY_CONFIG.productName) > 0;
      return makeActiveMissionCountProgress(hasKey ? 1 : 0, 1);
    }

    if (mission.id === KING_LETTER_MISSION.id) {
      const { letterCount, stampedLetterCount } = getLetterMissionItemCounts();
      if (stampedLetterCount > 0) {
        return makeActiveMissionCountProgress(1, 1);
      }
      // Find Al Dee / bring letter for stamping — ready when the unstamped letter is held
      return makeActiveMissionCountProgress(letterCount > 0 ? 1 : 0, 1);
    }

    if (mission.id === AL_DEE_FISHING_MISSION.id) {
      return makeActiveMissionCountProgress(getCachedQuestItemCount('Small Axe') > 0 ? 1 : 0, 1);
    }

    if (mission.id === AL_DEE_GOLDEN_ROPE_MISSION.id) {
      return makeActiveMissionCountProgress(getCachedQuestItemCount('Elvenhair Rope') > 0 ? 1 : 0, 1);
    }

    if (mission.id === FOLLOWER_OF_ZATHROTH_MISSION.id) {
      return makeActiveMissionCountProgress(
        getCachedQuestItemCount(COSTELLO_QUEEN_BANSHEES_MISSION.rewardItemName) > 0 ? 1 : 0,
        1
      );
    }

    if (mission.id === MOTHER_OF_ALL_SPIDERS_MISSION.id) {
      return makeActiveMissionCountProgress(getCachedQuestItemCount('Spider Silk') > 0 ? 1 : 0, 1);
    }

    if (mission.id === JAKUNDAF_DESERT_MISSION.id) {
      return makeActiveMissionCountProgress(progress?.pathCleared ? 1 : 0, 1);
    }

    if (mission.id === TAINTED_SOULS_MISSION.id) {
      return makeActiveMissionCountProgress(progress?.battleCompleted ? 1 : 0, 1);
    }

    if (mission.id === KING_MONKS_STUDY_MISSION.id) {
      return makeActiveMissionCountProgress(kingChatState.costelloVisited ? 1 : 0, 1);
    }

    if (mission.id === APPRENTICE_SHENG_MISSION.id) {
      return makeActiveMissionCountProgress(progress?.battleCompleted ? 1 : 0, 1);
    }

    if (mission.id === WEAKENED_ARCHDEMON_MISSION.id) {
      return makeActiveMissionCountProgress(progress?.battleCompleted ? 1 : 0, 1);
    }

    if (mission.id === CHRISTMAS_MIRACLE_MISSION.id) {
      const hasPresent = getCachedQuestItemCount(PRESENT_CONFIG.productName) > 0;
      return makeActiveMissionCountProgress(hasPresent ? 1 : 0, 1);
    }

    if (mission.id === SVENSON_LOVE_STORY_MISSION.id) {
      const delivered = !!progress?.plankDelivered;
      if (!delivered) {
        return makeActiveMissionCountProgress(0, 1);
      }
      if (progress?.strandedAtWhiteWave) {
        return makeActiveMissionCountProgress(progress?.whiteWaveSlippersDelivered ? 1 : 0, 1);
      }
      if (progress?.strandedAtUnderground) {
        if (progress?.undergroundCompassDelivered && !progress?.strandedAtWhiteWave) {
          return makeActiveMissionCountProgress(0, 1);
        }
        if (!progress?.undergroundCompassRequested) {
          return makeActiveMissionCountProgress(0, 1);
        }
        return makeActiveMissionCountProgress(progress?.undergroundCompassDelivered ? 1 : 0, 1);
      }
      if (progress?.strandedAtAwash && progress?.awashYarnDelivered && !progress?.strandedAtUnderground) {
        return makeActiveMissionCountProgress(0, 1);
      }
      if (!progress?.strandedAtAwash) {
        return makeActiveMissionCountProgress(0, 1);
      }
      if (!progress?.awashYarnRequested) {
        return makeActiveMissionCountProgress(0, 1);
      }
      return makeActiveMissionCountProgress(progress?.awashYarnDelivered ? 1 : 0, 1);
    }

    if (mission.id === SERPENTINE_TOWER_MISSION.id) {
      // One binary bar per active stage (never 1/2):
      // rune hunt → basement/lever → return to Tesha.
      if (progress?.putridChamberComplete) {
        return makeActiveMissionCountProgress(1, 1);
      }
      if (hasSerpentineDestroyFieldRune()) {
        return makeActiveMissionCountProgress(0, 1);
      }
      return makeActiveMissionCountProgress(0, 1);
    }

    return null;
  }

  function getActiveMissionTabClassName() {
    return 'frame-1 surface-regular relative grid gap-2 p-1.5 text-left data-[disabled=\'true\']:order-last md:data-[highlighted=\'true\']:brightness-[1.2]';
  }

  function createActiveMissionProgressBar(progressDisplay) {
    const wrap = document.createElement('div');
    wrap.className = '-mt-0.5 flex items-center gap-2';

    const track = document.createElement('div');
    track.className = 'relative w-full border border-solid border-black bg-black frame-pressed-1 surface-darker h-1.5';
    const fillRow = document.createElement('div');
    fillRow.className = 'absolute left-0 top-0 flex h-full w-full';
    const fill = document.createElement('div');
    fill.className = 'h-full shrink-0';
    const pct = progressDisplay.total > 0
      ? Math.max(0, Math.min(100, (progressDisplay.current / progressDisplay.total) * 100))
      : 0;
    fill.style.width = `${pct}%`;
    fill.style.background = 'rgb(96, 192, 96)';
    fillRow.appendChild(fill);
    track.appendChild(fillRow);

    const count = document.createElement('span');
    count.className = 'text-whiteHighlight data-[completed=\'true\']:text-hpHealthy';
    count.dataset.completed = progressDisplay.current >= progressDisplay.total ? 'true' : 'false';
    count.textContent = `${progressDisplay.current}/${progressDisplay.total}`;

    wrap.appendChild(track);
    wrap.appendChild(count);
    return wrap;
  }

  function renderActiveMissionTabContent(tab, entryOrMission) {
    const entry = entryOrMission?.mission
      ? entryOrMission
      : { mission: entryOrMission, objective: null, progress: null, iconFilename: null };
    const mission = entry.mission;
    tab.replaceChildren();

    const row = document.createElement('div');
    row.className = 'flex justify-between gap-2';

    const iconSlot = document.createElement('div');
    iconSlot.className = 'container-slot surface-darker grid place-items-center px-3.5 py-0.5 relative';
    iconSlot.appendChild(createActiveMissionIconElement(mission, entry.iconFilename));

    const info = document.createElement('div');
    info.className = 'flex w-full flex-col justify-center';

    const title = document.createElement('p');
    title.className = 'text-whiteHighlight';
    title.textContent = mission.title;
    info.appendChild(title);

    const objectiveLine = entry.objective || getActiveMissionObjectiveLine(mission);
    const progressDisplay = entry.progress || getActiveMissionProgressDisplay(mission);

    const statusLine = document.createElement('p');
    statusLine.className = 'pixel-font-14 mt-1';
    statusLine.textContent = objectiveLine;
    info.appendChild(statusLine);

    if (progressDisplay) {
      info.appendChild(createActiveMissionProgressBar(progressDisplay));
    }

    row.appendChild(iconSlot);
    row.appendChild(info);
    tab.appendChild(row);
  }

  function syncActiveMissionTabs() {
    const questLogContainer = findQuestLogContainer();
    const kingTab = getKingTabElement();
    const existingTabs = getActiveMissionTabElements();

    if (!questLogContainer || !kingTab) {
      existingTabs.forEach((tab) => tab.remove());
      return;
    }

    const activeMissions = getActiveQuestLogMissions();
    const activeMissionIds = new Set(activeMissions.map((mission) => mission.id));
    const tabEntries = getActiveMissionTabEntries(activeMissions);
    const activeTabKeys = new Set(tabEntries.map((entry) => entry.key));

    existingTabs.forEach((tab) => {
      const missionId = tab.getAttribute(ACTIVE_MISSION_TAB_ATTR);
      const tabKey = tab.getAttribute('data-quests-active-mission-tab-key') || missionId;
      if (!activeMissionIds.has(missionId) || !activeTabKeys.has(tabKey)) {
        tab.remove();
      }
    });

    let insertAfter = kingTab;
    tabEntries.forEach((entry, index) => {
      const tabId = getActiveMissionTabId(entry.key);
      let tab = document.getElementById(tabId);

      if (!tab) {
        tab = document.createElement('div');
        tab.id = tabId;
        tab.setAttribute(ACTIVE_MISSION_TAB_ATTR, entry.missionId);
        tab.setAttribute('data-quests-active-mission-tab-key', entry.key);
        tab.setAttribute('data-highlighted', 'false');
        tab.setAttribute('data-disabled', 'false');
        tab.dataset.questsOriginalDisplay = '';
        tab.style.display = 'none';
      }

      tab.className = getActiveMissionTabClassName();
      tab.style.order = String(-1 + index);
      renderActiveMissionTabContent(tab, entry);

      const desiredNext = insertAfter.nextElementSibling;
      if (tab.parentNode !== questLogContainer || desiredNext !== tab) {
        questLogContainer.insertBefore(tab, insertAfter.nextSibling);
      }

      if (kingModeActive) {
        tab.style.display = '';
      } else {
        tab.style.display = 'none';
      }

      insertAfter = tab;
    });
    lockNativeQuestLogListSize(questLogContainer);
  }

  function getArenaQuestLogCards() {
    return [
      getQuestAdminDevTabElement(),
      getKingTabElement(),
      getArenaLeaderboardTabElement(),
      ...getActiveMissionTabElements()
    ].filter(Boolean);
  }

  function getArenaProfileUrl(playerName) {
    return `https://bestiaryarena.com/profile/${encodeURIComponent(String(playerName || '').trim())}`;
  }

  function appendArenaLeaderboardBox(listElement, content) {
    const box = createBox({ title: 'Rankings', content });
    // Let the box fill the modal's list area so a long ranking list (more than ~10
    // players) scrolls inside it instead of overflowing the modal.
    box.style.flex = '1 1 auto';
    box.style.minHeight = '0';
    box.style.display = 'flex';
    box.style.flexDirection = 'column';
    const wrapper = box.querySelector('.column-content-wrapper');
    if (wrapper) {
      wrapper.style.overflowX = 'hidden';
      wrapper.style.overflowY = 'auto';
      wrapper.style.minWidth = '0';
      wrapper.style.maxWidth = '100%';
      wrapper.style.boxSizing = 'border-box';
      wrapper.style.flex = '1 1 auto';
      wrapper.style.minHeight = '0';
      wrapper.style.maxHeight = '100%';
      // Drop the top padding so the sticky table header sits flush against the
      // scroll viewport's top edge — otherwise rows scroll up into the padding
      // strip and peek out above the pinned header.
      wrapper.style.paddingTop = '0';
    }
    listElement.innerHTML = '';
    listElement.appendChild(box);
  }

  function createArenaLeaderboardPlaceholderMessage(text) {
    const message = document.createElement('p');
    message.style.margin = '0';
    message.style.color = '#888';
    message.style.fontStyle = 'italic';
    message.style.textAlign = 'center';
    message.textContent = text;
    return message;
  }

  const ARENA_LEADERBOARD_GRID_COLUMNS = 'minmax(0, 8%) minmax(0, 30%) minmax(0, 36%) minmax(0, 20%)';

  function createArenaLeaderboardTableHeader() {
    const gridRowStyle = 'width:100%;max-width:100%;min-width:0;box-sizing:border-box;';
    const ellipsisCellStyle = 'min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
    const header = document.createElement('div');
    header.className = 'pixel-font-16 text-whiteRegular';
    // Bleed 8px sideways to cover the scroll wrapper's horizontal padding, and
    // back the tiled texture with a solid opaque colour + a shadow so scrolled
    // rows are fully hidden behind the pinned header instead of showing through.
    header.style.cssText = `${gridRowStyle}width:calc(100% + 16px);max-width:none;margin:0 -8px;display:grid;grid-template-columns:${ARENA_LEADERBOARD_GRID_COLUMNS};gap:6px;padding:8px 8px 6px;border-bottom:1px solid rgba(255,255,255,0.18);align-items:end;position:sticky;top:0;z-index:5;background-color:#191919;background-image:url("https://bestiaryarena.com/_next/static/media/background-dark.95edca67.png");background-repeat:repeat;box-shadow:0 6px 8px -4px rgba(0,0,0,0.6);color:rgb(255,255,255);`;

    const headerLabels = ['#', 'Player', 'Rank', 'Missions\ncompleted'];
    headerLabels.forEach((label, colIndex) => {
      const cell = document.createElement('span');
      cell.className = 'pixel-font-16';
      cell.style.cssText = colIndex === 0 || colIndex === 3
        ? `text-align:center;color:rgb(255,255,255);${ellipsisCellStyle}`
        : `color:rgb(255,255,255);${ellipsisCellStyle}`;
      if (colIndex === 3) {
        cell.style.whiteSpace = 'pre-line';
        cell.style.lineHeight = '1.2';
      }
      cell.textContent = label;
      header.appendChild(cell);
    });
    return header;
  }

  function buildArenaLeaderboardTableShell(loadingText = 'Loading...') {
    const gridRowStyle = 'width:100%;max-width:100%;min-width:0;box-sizing:border-box;';
    const table = document.createElement('div');
    table.style.cssText = `${gridRowStyle}display:flex;flex-direction:column;gap:2px;`;
    table.appendChild(createArenaLeaderboardTableHeader());
    table.appendChild(createArenaLeaderboardPlaceholderMessage(loadingText));
    return table;
  }

  async function renderArenaLeaderboardInto(listElement, forceRefresh = false) {
    if (!listElement) return;

    appendArenaLeaderboardBox(listElement, buildArenaLeaderboardTableShell('Loading...'));

    try {
      const entries = await loadArenaLeaderboard(forceRefresh);
      const currentPlayer = getCurrentPlayerName();

      if (!entries.length) {
        appendArenaLeaderboardBox(listElement, createArenaLeaderboardPlaceholderMessage('No rankings yet.'));
        return;
      }

      const gridRowStyle = 'width:100%;max-width:100%;min-width:0;box-sizing:border-box;';
      const ellipsisCellStyle = 'min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
      const table = document.createElement('div');
      table.style.cssText = `${gridRowStyle}display:flex;flex-direction:column;gap:2px;`;
      table.appendChild(createArenaLeaderboardTableHeader());

      entries.forEach((entry, index) => {
        const playerName = entry.playerName || 'Unknown';
        const completedCount = entry.completedCount || 0;
        const { rankName, color: rankColor, animationClass } = getArenaRankInfo(completedCount);
        const isCurrentPlayer = currentPlayer && entry.playerName === currentPlayer;
        const rowBackground = isCurrentPlayer
          ? 'rgba(100,150,255,0.22)'
          : index % 2 === 1
            ? 'rgba(255,255,255,0.04)'
            : 'transparent';

        const row = document.createElement('div');
        row.className = 'pixel-font-16';
        row.style.cssText = `${gridRowStyle}display:grid;grid-template-columns:${ARENA_LEADERBOARD_GRID_COLUMNS};gap:6px;padding:4px 0;align-items:center;min-height:28px;border-radius:2px;background:${rowBackground};${isCurrentPlayer ? 'box-shadow:inset 2px 0 0 rgb(100,150,255);' : ''}`;

        const rankCell = document.createElement('span');
        rankCell.className = 'pixel-font-16';
        rankCell.style.cssText = `min-width:0;text-align:center;font-variant-numeric:tabular-nums;color:${isCurrentPlayer ? 'rgb(230,215,176)' : 'rgb(255,255,255)'};`;
        rankCell.textContent = String(index + 1);

        const nameLink = document.createElement('a');
        nameLink.href = getArenaProfileUrl(playerName);
        nameLink.target = '_blank';
        nameLink.rel = 'noopener noreferrer';
        nameLink.className = 'pixel-font-16';
        nameLink.style.cssText = `margin:0;${ellipsisCellStyle}color:${isCurrentPlayer ? 'rgb(230,215,176)' : 'rgb(255,255,255)'};font-style:normal;cursor:pointer;text-decoration:underline;`;
        nameLink.textContent = playerName;
        nameLink.title = `Open ${playerName}'s profile`;

        const rankTitleCell = document.createElement('span');
        rankTitleCell.className = 'pixel-font-16';
        rankTitleCell.style.cssText = `color:${rankColor};${ellipsisCellStyle}`;
        rankTitleCell.textContent = rankName;
        rankTitleCell.title = rankName;
        applyArenaRankAnimation(rankTitleCell, animationClass);

        const countCell = document.createElement('span');
        countCell.className = 'pixel-font-16';
        countCell.style.cssText = `min-width:0;overflow:hidden;text-align:center;font-variant-numeric:tabular-nums;color:${isCurrentPlayer ? 'rgb(230,215,176)' : 'rgb(255,255,255)'};`;
        countCell.textContent = String(entry.completedCount || 0);

        row.appendChild(rankCell);
        row.appendChild(nameLink);
        row.appendChild(rankTitleCell);
        row.appendChild(countCell);
        table.appendChild(row);
      });

      appendArenaLeaderboardBox(listElement, table);
    } catch (error) {
      console.error('[Quests Mod] Error loading arena leaderboard:', error);
      appendArenaLeaderboardBox(listElement, createArenaLeaderboardPlaceholderMessage('Could not load rankings.'));
    }
  }

  async function updateArenaLeaderboardDisplay(forceRefresh = false) {
    const modalList = document.getElementById(ARENA_LEADERBOARD_MODAL_LIST_ID);
    if (modalList) {
      await renderArenaLeaderboardInto(modalList, forceRefresh);
    }
  }

  function clearQuestLogMissionsRestoreTimeout() {
    if (questLogMissionsRestoreTimeout) {
      clearTimeout(questLogMissionsRestoreTimeout);
      questLogMissionsRestoreTimeout = null;
    }
  }

  function isVisibleNavElement(element) {
    return !!(element && element.offsetParent !== null);
  }

  function findQuestLogNavButton() {
    const imageSelectors = [
      'button img[src*="quest.png"]',
      'button img[src*="enemy.png"]',
      'button img[src*="taskrank.png"]',
      'button img[alt="Quests"]',
      'button img[alt="Tasking"]',
      'button img[alt="Enemy"]'
    ];

    for (const selector of imageSelectors) {
      const button = document.querySelector(selector)?.closest('button');
      if (isVisibleNavElement(button)) return button;
    }

    const textMatches = ['Raiding', 'Tasking'];
    const navButtons = document.querySelectorAll('header button, #header-slot button, [role="banner"] button');
    for (const btn of navButtons) {
      if (!isVisibleNavElement(btn)) continue;

      const spanText = btn.querySelector('span')?.textContent?.trim();
      if (spanText && textMatches.includes(spanText)) return btn;

      const text = (btn.textContent || '').replace(/\s+/g, ' ').trim();
      if (textMatches.some((match) => text === match)) return btn;
    }

    return null;
  }

  function clickQuestLogOpener() {
    const questBlipSelectors = [
      '#header-slot img[src*="quest-blip"]',
      'img[src*="quest-blip.png"]',
      'img[src*="/assets/icons/quest-blip.png"]'
    ];

    for (const selector of questBlipSelectors) {
      const blip = document.querySelector(selector);
      if (isVisibleNavElement(blip)) {
        blip.click();
        return true;
      }
    }

    const navButton = findQuestLogNavButton();
    if (navButton) {
      navButton.click();
      return true;
    }

    return false;
  }

  function restoreQuestLogMissionsView(attempt = 0) {
    const maxAttempts = 25;
    const questLogContainer = findQuestLogContainer();
    if (questLogContainer) {
      clearQuestLogMissionsRestoreTimeout();
      pendingQuestLogMissionsRestore = true;
      kingModeActive = true;
      handleQuestLogReady(questLogContainer);
      pendingQuestLogMissionsRestore = false;
      if (!getKingTabElement()) {
        createKingTibianusTab();
      } else {
        createArenaLeaderboardTab();
      }
      verifyKingTibianusTabPosition();
      verifyArenaLeaderboardTabPosition();
      syncQuestAdminDevTab().catch(() => {});
      const kingTab = getKingTabElement();
      if (kingTab) {
        syncActiveMissionTabs();
        hideQuestLogWidgetsExceptKing(questLogContainer, kingTab);
      }
      ensureMissionsFooterButton();
      updateMissionsButtonState();
      scheduleArenaRankDisplayUpdate(0);
      return;
    }

    if (attempt >= maxAttempts) {
      clearQuestLogMissionsRestoreTimeout();
      pendingQuestLogMissionsRestore = false;
      return;
    }

    questLogMissionsRestoreTimeout = setTimeout(() => {
      restoreQuestLogMissionsView(attempt + 1);
    }, 100);
  }

  function openQuestLogMissionsView() {
    clearQuestLogMissionsRestoreTimeout();
    if (!clickQuestLogOpener()) {
      console.warn('[Quests Mod] Could not find quest log opener for Back navigation');
      return;
    }
    restoreQuestLogMissionsView(0);
  }

  function showArenaRankingsModal() {
    const api = (typeof globalThis !== 'undefined' && globalThis.BestiaryModAPI) || (typeof window !== 'undefined' && window.BestiaryModAPI);
    if (!api?.ui?.components?.createModal) {
      console.warn('[Quests Mod] Modal API unavailable for arena rankings');
      return;
    }

    clearTimeoutOrInterval(modalTimeout);
    clearTimeoutOrInterval(dialogTimeout);
    const shouldRestoreMissions = kingModeActive;

    for (let i = 0; i < 2; i++) {
      document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true }));
    }

    modalTimeout = setTimeout(() => {
      const contentDiv = document.createElement('div');
      applyModalContentStyles(contentDiv, ARENA_LEADERBOARD_MODAL_WIDTH, ARENA_LEADERBOARD_MODAL_MAX_HEIGHT);
      contentDiv.classList.add('quests-king-chat-content');
      contentDiv.style.flexDirection = 'column';
      contentDiv.style.gap = '0';

      const modalBody = document.createElement('div');
      modalBody.className = 'quests-king-chat-body';
      modalBody.style.cssText = 'display:flex;flex-direction:column;gap:12px;padding:0;width:100%;min-width:0;height:100%;box-sizing:border-box;max-width:100%;flex:1 1 auto;min-height:0;';

      const mainRow = document.createElement('div');
      mainRow.className = 'quests-king-chat-main';
      mainRow.style.cssText = 'width:100%;max-width:100%;min-width:0;flex:1 1 auto;min-height:0;height:100%;display:flex;gap:12px;margin:0;align-self:stretch;box-sizing:border-box;';

      const listContainer = document.createElement('div');
      listContainer.id = ARENA_LEADERBOARD_MODAL_LIST_ID;
      listContainer.className = 'arena-leaderboard-modal-list';
      listContainer.style.cssText = 'flex:1;height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:0;padding:0;box-sizing:border-box;';
      appendArenaLeaderboardBox(listContainer, buildArenaLeaderboardTableShell('Loading...'));
      mainRow.appendChild(listContainer);
      modalBody.appendChild(mainRow);
      contentDiv.appendChild(modalBody);

      const modalDims = getQuestsModalDimensions(
        ARENA_LEADERBOARD_MODAL_WIDTH,
        ARENA_LEADERBOARD_MODAL_MAX_HEIGHT,
        ARENA_LEADERBOARD_MODAL_MIN_HEIGHT
      );
      const modal = api.ui.components.createModal({
        title: 'Mission Leaderboard',
        width: modalDims.width,
        height: modalDims.height,
        content: contentDiv,
        buttons: [{
          text: 'Back',
          primary: false,
          onClick: () => {
            clearQuestsModalLayoutCleanup();
            if (shouldRestoreMissions) {
              setTimeout(() => openQuestLogMissionsView(), 100);
            }
          }
        }]
      });

      setupQuestsModalResponsiveLayout(
        modal,
        contentDiv,
        ARENA_LEADERBOARD_MODAL_WIDTH,
        ARENA_LEADERBOARD_MODAL_MAX_HEIGHT,
        ARENA_LEADERBOARD_MODAL_MIN_HEIGHT,
        (dialog) => {
          const backButton = Array.from(dialog?.querySelectorAll('.flex.justify-end.gap-2 button') || [])
            .find((btn) => btn.textContent?.trim() === 'Back');
          if (backButton) {
            backButton.className = 'focus-style-visible flex items-center justify-center tracking-wide text-whiteRegular disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1-blue active:frame-pressed-1-blue surface-blue gap-1 px-2 py-0.5 pb-[3px] pixel-font-14';
            backButton.style.cssText = 'cursor: pointer; white-space: nowrap; box-sizing: border-box; max-height: 21px; height: 21px; font-size: 14px;';
          }
        }
      );

      renderArenaLeaderboardInto(listContainer, true).catch((err) => {
        console.warn('[Quests Mod] Error loading arena rankings modal:', err);
      });

      modalTimeout = null;
    }, 50);
  }

  function bindArenaRankingsOpenButton(tabElement) {
    const openButton = tabElement?.querySelector(`#${ARENA_RANKINGS_OPEN_BTN_ID}`);
    if (!openButton || openButton.dataset.questsBound === '1') return;
    openButton.dataset.questsBound = '1';
    openButton.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      showArenaRankingsModal();
    });
  }

  function updateMissionsButtonState() {
    if (!missionsToggleButton) return;
    missionsToggleButton.setAttribute('aria-pressed', kingModeActive ? 'true' : 'false');
    missionsToggleButton.textContent = kingModeActive ? 'Back' : 'Missions';
  }

  function applyMissionsQuestLogGridPacking(questLogContainer) {
    if (!questLogContainer) return;
    if (questLogContainer.dataset.questsGridAlignContent === undefined) {
      questLogContainer.dataset.questsGridAlignContent = questLogContainer.style.alignContent || '';
    }
    if (questLogContainer.dataset.questsGridAutoRows === undefined) {
      questLogContainer.dataset.questsGridAutoRows = questLogContainer.style.gridAutoRows || '';
    }
    if (questLogContainer.dataset.questsGridPaddingBottom === undefined) {
      questLogContainer.dataset.questsGridPaddingBottom = questLogContainer.style.paddingBottom || '';
    }
    // Fixed-height quest log stretches few Missions cards apart; pack them to the top.
    questLogContainer.style.alignContent = 'start';
    questLogContainer.style.gridAutoRows = 'max-content';
    // Match the inter-card gap (gap-1 = 4px) below the last card too, so it doesn't
    // sit flush against the scroll area's bottom edge.
    questLogContainer.style.paddingBottom = '4px';
    lockNativeQuestLogListSize(questLogContainer);
  }

  function restoreQuestLogGridPacking(questLogContainer) {
    if (!questLogContainer) return;
    if (questLogContainer.dataset.questsGridAlignContent !== undefined) {
      questLogContainer.style.alignContent = questLogContainer.dataset.questsGridAlignContent;
      delete questLogContainer.dataset.questsGridAlignContent;
    } else {
      questLogContainer.style.removeProperty('align-content');
    }
    if (questLogContainer.dataset.questsGridAutoRows !== undefined) {
      questLogContainer.style.gridAutoRows = questLogContainer.dataset.questsGridAutoRows;
      delete questLogContainer.dataset.questsGridAutoRows;
    } else {
      questLogContainer.style.removeProperty('grid-auto-rows');
    }
    if (questLogContainer.dataset.questsGridPaddingBottom !== undefined) {
      questLogContainer.style.paddingBottom = questLogContainer.dataset.questsGridPaddingBottom;
      delete questLogContainer.dataset.questsGridPaddingBottom;
    } else {
      questLogContainer.style.removeProperty('padding-bottom');
    }
    lockNativeQuestLogListSize(questLogContainer);
  }

  function showAllQuestLogWidgets(questLogContainer, kingTab) {
    if (!questLogContainer) return;

    restoreQuestLogGridPacking(questLogContainer);

    const questCards = new Set(getArenaQuestLogCards());

    const children = Array.from(questLogContainer.children);
    children.forEach(child => {
      if (questCards.has(child)) {
        if (!child.dataset.questsOriginalDisplay) {
          child.dataset.questsOriginalDisplay = child.style.display || '';
        }
        child.style.display = 'none';
      } else {
        if (child.dataset && child.dataset.questsOriginalDisplay !== undefined) {
          child.style.display = child.dataset.questsOriginalDisplay;
        } else {
          child.style.display = '';
        }
      }

      if (child?.dataset?.questsOriginalDisplay !== undefined) {
        delete child.dataset.questsOriginalDisplay;
      }
    });
  }

  function hideQuestLogWidgetsExceptKing(questLogContainer, kingTab) {
    if (!questLogContainer || !kingTab) return;

    applyMissionsQuestLogGridPacking(questLogContainer);

    const visibleCards = new Set(getArenaQuestLogCards());
    const children = Array.from(questLogContainer.children);
    children.forEach(child => {
      if (!child.dataset) return;

      if (!child.dataset.questsOriginalDisplay) {
        child.dataset.questsOriginalDisplay = child.style.display || '';
      }
      child.style.display = visibleCards.has(child) ? '' : 'none';
    });
  }

  function resetQuestLogView(questLogContainer = findQuestLogContainer()) {
    const kingTab = getKingTabElement();
    const leaderboardTab = getArenaLeaderboardTabElement();
    const adminDevTab = getQuestAdminDevTabElement();
    const activeMissionTabs = getActiveMissionTabElements();
    if (!questLogContainer) {
      kingModeActive = false;
      updateMissionsButtonState();
      if (kingTab) {
        kingTab.style.display = 'none';
      }
      if (leaderboardTab) {
        leaderboardTab.style.display = 'none';
      }
      if (adminDevTab) {
        adminDevTab.style.display = 'none';
      }
      activeMissionTabs.forEach((tab) => {
        tab.style.display = 'none';
      });
      return;
    }

    showAllQuestLogWidgets(questLogContainer, kingTab);
    kingModeActive = false;
    if (kingTab) {
      kingTab.style.display = 'none';
    }
    if (leaderboardTab) {
      leaderboardTab.style.display = 'none';
    }
    if (adminDevTab) {
      adminDevTab.style.display = 'none';
    }
    activeMissionTabs.forEach((tab) => {
      tab.style.display = 'none';
    });
    updateMissionsButtonState();
  }

  function toggleKingQuestLogView() {
    const questLogContainer = findQuestLogContainer();
    if (!questLogContainer) return;

    resetNativeQuestLogDialogLayout();

    if (!getKingTabElement()) {
      createKingTibianusTab();
    } else {
      createArenaLeaderboardTab();
    }
    const kingTab = getKingTabElement();
    if (!kingTab) return;

    verifyKingTibianusTabPosition();
    verifyArenaLeaderboardTabPosition();

    if (!kingModeActive) {
      kingModeActive = true;
      syncActiveMissionTabs();
      hideQuestLogWidgetsExceptKing(questLogContainer, kingTab);
    } else {
      resetQuestLogView(questLogContainer);
    }
    updateMissionsButtonState();
  }

  function ensureMissionsFooterButton() {
    const footer = findQuestLogFooter();
    if (!footer) return;

    // Check if title says "Quest Log"
    const dialog = footer.closest('div[role="dialog"]');
    const titleElement = dialog?.querySelector('.widget-top-text, .widget-top');
    const hasQuestLogTitle = titleElement?.textContent?.trim().includes('Quest Log');

    let missionsButton = document.getElementById(KING_MISSIONS_BUTTON_ID);
    
    // Remove button if it exists but title doesn't match
    if (missionsButton && !hasQuestLogTitle) {
      missionsButton.remove();
      missionsToggleButton = null;
      return;
    }

    // Only add button if title says "Quest Log"
    if (!hasQuestLogTitle) {
      return;
    }
    if (!missionsButton) {
      missionsButton = document.createElement('button');
      missionsButton.id = KING_MISSIONS_BUTTON_ID;
      missionsButton.type = 'button';
      missionsButton.className = 'focus-style-visible flex items-center justify-center tracking-wide text-whiteRegular disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1-blue active:frame-pressed-1-blue surface-blue gap-1 px-2 py-0.5 pb-[3px] pixel-font-14';
      missionsButton.style.cssText = 'cursor: pointer; white-space: nowrap; box-sizing: border-box; max-height: 21px; height: 21px; font-size: 14px;';
      missionsButton.textContent = 'Missions';
      missionsButton.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        toggleKingQuestLogView();
      });

      const closeButton = Array.from(footer.querySelectorAll('button')).find(btn => btn.textContent?.trim() === 'Close');
      if (closeButton) {
        footer.insertBefore(missionsButton, closeButton);
      } else {
        footer.appendChild(missionsButton);
      }
    }

    missionsToggleButton = missionsButton;
    updateMissionsButtonState();
  }

  function handleQuestLogReady(questLogContainer) {
    if (!questLogContainer) return;

    resetNativeQuestLogDialogLayout();
    ensureMissionsFooterButton();
    const kingTab = getKingTabElement();
    const leaderboardTab = getArenaLeaderboardTabElement();
    if (kingTab && !leaderboardTab) {
      createArenaLeaderboardTab();
    }
    if (kingTab) {
      syncQuestAdminDevTab().catch(() => {});
      syncActiveMissionTabs();
    }

    if (lastQuestLogContainer !== questLogContainer) {
      lastQuestLogContainer = questLogContainer;
      if (!pendingQuestLogMissionsRestore) {
        kingModeActive = false;
        if (kingTab) {
          kingTab.style.display = 'none';
        }
        if (leaderboardTab) {
          leaderboardTab.style.display = 'none';
        }
        const adminDevTab = getQuestAdminDevTabElement();
        if (adminDevTab) {
          adminDevTab.style.display = 'none';
        }
        getActiveMissionTabElements().forEach((tab) => {
          tab.style.display = 'none';
        });
        showAllQuestLogWidgets(questLogContainer, kingTab);
        updateMissionsButtonState();
      }
    }
  }

  function findRaidHunterTab() {
    const questLogContainer = findQuestLogContainer();
    if (!questLogContainer) return null;
    
    // Find Raid Hunter tab by its ID
    const raidHunterTab = document.getElementById('raid-hunter-raid-clock');
    if (raidHunterTab && questLogContainer.contains(raidHunterTab)) {
      return raidHunterTab;
    }
    
    // Fallback: Find by text content
    const allElements = questLogContainer.querySelectorAll('.frame-1');
    for (const element of allElements) {
      const text = element.textContent || '';
      if (text.includes('Raid Monitor') || text.includes('Next raid check in:')) {
        return element;
      }
    }
    
    return null;
  }

  function getArenaLeaderboardTabHtml() {
    return `
      <div class="flex w-full flex-col items-center text-center">
        <p class="w-full text-whiteHighlight">Mission Leaderboard</p>
        <div class="flex gap-1 mt-1 w-full">
          <button class="focus-style-visible flex items-center justify-center tracking-wide disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1-blue active:frame-pressed-1-blue surface-blue gap-1 px-2 py-0.5 pb-[3px] pixel-font-16 flex-1 text-whiteHighlight" id="${ARENA_RANKINGS_OPEN_BTN_ID}">
            View Leaderboard
          </button>
        </div>
      </div>
    `;
  }

  function getArenaLeaderboardTabClassName() {
    return 'frame-1 surface-regular relative grid gap-2 p-1.5 text-center data-[disabled=\'true\']:order-last md:data-[highlighted=\'true\']:brightness-[1.2]';
  }

  function getQuestAdminDevTabHtml() {
    return `
      <div class="flex w-full flex-col items-center text-center">
        <p class="w-full text-whiteHighlight">Quest Dev Tools</p>
        <p class="pixel-font-14 mt-0.5" style="color:#888;">Admin only</p>
        <div class="flex gap-1 mt-1 w-full">
          <button class="focus-style-visible flex items-center justify-center tracking-wide disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1-blue active:frame-pressed-1-blue surface-blue gap-1 px-2 py-0.5 pb-[3px] pixel-font-16 flex-1 text-whiteHighlight" id="${QUEST_ADMIN_DEV_OPEN_BTN_ID}">
            Open Tools
          </button>
        </div>
      </div>
    `;
  }

  function createQuestAdminDevButtonStyle() {
    return `
      focus-style-visible flex items-center justify-center tracking-wide disabled:cursor-not-allowed
      disabled:text-whiteDark/60 disabled:grayscale-50 frame-1-blue active:frame-pressed-1-blue
      surface-blue gap-1 px-2 py-0.5 pb-[3px] pixel-font-14 text-whiteHighlight
    `.replace(/\s+/g, ' ').trim();
  }

  function createQuestAdminDevDangerButtonStyle() {
    return `
      focus-style-visible flex items-center justify-center tracking-wide disabled:cursor-not-allowed
      disabled:text-whiteDark/60 disabled:grayscale-50 frame-1 active:frame-pressed-1
      surface-regular gap-1 px-2 py-0.5 pb-[3px] pixel-font-14
    `.replace(/\s+/g, ' ').trim();
  }

  function bindQuestAdminDevOpenButton(tabElement) {
    const btn = tabElement?.querySelector(`#${QUEST_ADMIN_DEV_OPEN_BTN_ID}`);
    if (!btn || btn.dataset.questsBound === '1') return;
    btn.dataset.questsBound = '1';
    btn.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      showQuestAdminDevModal().catch((err) => {
        console.error('[Quests Mod][Dev] Failed to open admin tools modal:', err);
      });
    });
  }

  async function syncQuestAdminDevTab() {
    const allowed = await isCurrentPlayerQuestAdminAsync();
    if (!allowed) {
      getQuestAdminDevTabElement()?.remove();
      return null;
    }
    return createQuestAdminDevTab();
  }

  function createQuestAdminDevTab() {
    const questLogContainer = findQuestLogContainer();
    const leaderboardTab = getArenaLeaderboardTabElement();
    const kingTab = getKingTabElement();
    if (!questLogContainer || !kingTab) return null;

    let tabElement = getQuestAdminDevTabElement();
    if (tabElement) {
      tabElement.className = getArenaLeaderboardTabClassName();
      tabElement.style.order = '-4';
      tabElement.innerHTML = getQuestAdminDevTabHtml();
      bindQuestAdminDevOpenButton(tabElement);
      verifyQuestAdminDevTabPosition();
      if (kingModeActive) {
        tabElement.style.display = '';
      }
      return tabElement;
    }

    tabElement = document.createElement('div');
    tabElement.id = QUEST_ADMIN_DEV_TAB_ID;
    tabElement.className = getArenaLeaderboardTabClassName();
    tabElement.setAttribute('data-highlighted', 'false');
    tabElement.setAttribute('data-disabled', 'false');
    tabElement.style.order = '-4';
    tabElement.innerHTML = getQuestAdminDevTabHtml();
    tabElement.dataset.questsOriginalDisplay = tabElement.style.display || '';
    tabElement.style.display = kingModeActive ? '' : 'none';

    const insertBefore = leaderboardTab || kingTab;
    questLogContainer.insertBefore(tabElement, insertBefore);
    bindQuestAdminDevOpenButton(tabElement);
    verifyQuestAdminDevTabPosition();
    return tabElement;
  }

  function verifyQuestAdminDevTabPosition() {
    const adminTab = getQuestAdminDevTabElement();
    const leaderboardTab = getArenaLeaderboardTabElement();
    const kingTab = getKingTabElement();
    const questLogContainer = findQuestLogContainer();
    if (!adminTab || !kingTab || !questLogContainer) return;
    if (adminTab.parentNode !== questLogContainer) return;

    if (adminTab.style.order !== '-4') {
      adminTab.style.order = '-4';
    }

    const insertBefore = leaderboardTab || kingTab;
    if (adminTab.nextElementSibling !== insertBefore) {
      questLogContainer.insertBefore(adminTab, insertBefore);
    }
  }

  async function showQuestAdminDevModal() {
    const allowed = await isCurrentPlayerQuestAdminAsync();
    if (!allowed) {
      console.warn('[Quests Mod][Dev] Quest Dev Tools are restricted to Firebase admins');
      getQuestAdminDevTabElement()?.remove();
      return;
    }

    const contentDiv = document.createElement('div');
    applyModalContentStyles(contentDiv, QUEST_ADMIN_DEV_MODAL_WIDTH, QUEST_ADMIN_DEV_MODAL_HEIGHT);
    contentDiv.classList.add('quests-king-chat-content');
    contentDiv.style.flexDirection = 'column';
    contentDiv.style.gap = '10px';
    contentDiv.style.overflowY = 'auto';

    const statusEl = document.createElement('p');
    statusEl.className = 'pixel-font-14 frame-pressed-1 surface-darker';
    statusEl.style.cssText = 'margin:0;color:#888;min-height:18px;padding:4px 6px;';
    statusEl.textContent = 'Ready.';

    const setStatus = (text, isError = false) => {
      statusEl.textContent = text;
      statusEl.style.color = isError ? '#ff8a80' : '#888';
    };

    let refreshItemCounts = () => {};
    let refreshMissionStatuses = () => {};
    let refreshSealStatuses = () => {};
    let receivedFlagsCache = {
      copperKey: false,
      letter: false,
      ironOre: false,
      wishlist: false,
      present: false
    };

    const runGuarded = async (label, fn) => {
      try {
        setStatus(`Running: ${label}...`);
        await fn();
        if (typeof syncActiveMissionTabs === 'function') syncActiveMissionTabs();
        receivedFlagsCache = await loadQuestDevItemReceivedFlags(getCurrentPlayerName());
        refreshItemCounts();
        refreshMissionStatuses();
        refreshSealStatuses();
        setStatus(`Done: ${label}`);
      } catch (error) {
        console.error('[Quests Mod][Dev]', label, error);
        setStatus(`${label} failed: ${error?.message || error}`, true);
      }
    };

    const copyCommand = async (command) => {
      const text = String(command || '').trim();
      if (!text) return;
      try {
        if (navigator.clipboard?.writeText) {
          await navigator.clipboard.writeText(text);
        } else {
          const ta = document.createElement('textarea');
          ta.value = text;
          ta.style.cssText = 'position:fixed;left:-9999px;top:0;';
          document.body.appendChild(ta);
          ta.select();
          document.execCommand('copy');
          ta.remove();
        }
        setStatus(`Copied: ${text.length > 72 ? `${text.slice(0, 72)}…` : text}`);
      } catch (error) {
        console.error('[Quests Mod][Dev] Copy failed:', error);
        setStatus(`Copy failed: ${error?.message || error}`, true);
      }
    };

    const PROGRESS_GREEN = 'rgba(76, 175, 80, 0.28)';
    const PROGRESS_RED = 'rgba(244, 67, 54, 0.22)';
    const PROGRESS_ACTIVE = 'rgba(230, 215, 176, 0.22)';
    const TEXT_GREEN = 'rgb(96, 192, 96)';
    const TEXT_RED = 'rgb(255, 138, 128)';
    const TEXT_ACTIVE = 'rgb(230, 215, 176)';
    const FRAME_BORDER = `4px solid transparent`;
    const FRAME_BORDER_IMAGE = GAME_FRAME_BORDER_IMAGE;
    const FRAME_BG = `${GAME_FRAME_BACKGROUND} repeat`;

    const productDefsByName = new Map();
    for (const def of buildProductDefinitions({ includeDragonClaw: true, includeObsidianKnife: true })) {
      if (def?.name) productDefsByName.set(def.name, def);
    }

    const applyRowProgressStyle = (row, state) => {
      if (state === 'done') {
        row.style.background = PROGRESS_GREEN;
        row.style.outline = '1px solid rgba(96, 192, 96, 0.55)';
      } else if (state === 'active') {
        row.style.background = PROGRESS_ACTIVE;
        row.style.outline = '1px solid rgba(230, 215, 176, 0.45)';
      } else {
        row.style.background = PROGRESS_RED;
        row.style.outline = '1px solid rgba(255, 138, 128, 0.45)';
      }
    };

    const section = (titleText) => {
      const wrap = ModalHelpers.createFramedBox({
        background: FRAME_BG,
        borderImage: FRAME_BORDER_IMAGE,
        padding: '6px 8px',
        minHeight: '0'
      });
      wrap.style.display = 'flex';
      wrap.style.flexDirection = 'column';
      wrap.style.gap = '6px';
      wrap.style.boxSizing = 'border-box';
      wrap.style.border = FRAME_BORDER;
      const title = document.createElement('p');
      title.className = 'widget-top widget-top-text pixel-font-14 text-whiteHighlight';
      title.style.cssText = 'margin:0;padding:2px 4px;text-align:left;';
      title.textContent = titleText;
      wrap.appendChild(title);
      return wrap;
    };

    const buttonRow = (parent) => {
      const row = document.createElement('div');
      row.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;';
      parent.appendChild(row);
      return row;
    };

    const makeBtn = (label, onClick, { danger = false, command = null } = {}) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = label;
      btn.className = danger ? createQuestAdminDevDangerButtonStyle() : createQuestAdminDevButtonStyle();
      if (danger) btn.style.color = '#ff8a80';
      if (command) {
        btn.title = `${command}\nRight-click or Ctrl+click to copy`;
        btn.dataset.questsDevCommand = command;
        btn.addEventListener('contextmenu', (event) => {
          event.preventDefault();
          copyCommand(command);
        });
        btn.addEventListener('click', (event) => {
          if (event.ctrlKey || event.metaKey) {
            event.preventDefault();
            copyCommand(command);
            return;
          }
          onClick(event);
        });
      } else {
        btn.addEventListener('click', onClick);
      }
      return btn;
    };

    const makeCopyBtn = (command, label = 'Copy') => {
      const btn = makeBtn(label, () => copyCommand(command));
      btn.title = command;
      return btn;
    };

    const createDevIconSlot = (child) => {
      const slot = document.createElement('div');
      slot.className = 'container-slot surface-darker grid place-items-center overflow-hidden';
      slot.style.cssText = 'width:28px;height:28px;flex-shrink:0;';
      if (child) {
        if (child.style) {
          child.style.width = '24px';
          child.style.height = '24px';
          child.style.maxWidth = '24px';
          child.style.maxHeight = '24px';
        }
        if (child.tagName === 'IMG') {
          child.width = 24;
          child.height = 24;
        }
        slot.appendChild(child);
      }
      return slot;
    };

    // Quick actions
    const quick = section('Quick actions');
    const quickRow = buttonRow(quick);
    const quickActions = [
      { label: 'Log state', command: 'QuestsDev.check()', run: () => QuestsDev.check() },
      { label: 'Complete all', command: 'QuestsDev.completeAll()', run: () => QuestsDev.completeAll() },
      { label: 'Reset all', command: 'QuestsDev.resetAll()', run: () => QuestsDev.resetAll(), danger: true },
      { label: 'Reset Santa', command: 'QuestsDev.resetSanta()', run: () => QuestsDev.resetSanta() },
      { label: 'Reset Iron Ore flag', command: 'QuestsDev.resetIronOreReceived()', run: () => QuestsDev.resetIronOreReceived() },
      { label: 'Reset Love Story + items', command: 'QuestsDev.resetLoveStoryWithItems()', run: () => QuestsDev.resetLoveStoryWithItems() }
    ];
    for (const action of quickActions) {
      const group = document.createElement('div');
      group.style.cssText = 'display:flex;gap:2px;';
      group.appendChild(makeBtn(action.label, () => runGuarded(action.label, action.run), {
        danger: !!action.danger,
        command: action.command
      }));
      group.appendChild(makeCopyBtn(action.command));
      quickRow.appendChild(group);
    }
    contentDiv.appendChild(quick);

    const listWrapStyle = 'display:flex;flex-direction:column;gap:3px;max-height:320px;overflow-y:auto;padding:4px;flex:1 1 auto;min-height:0;';
    const rowGridStyle = 'display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:4px 8px;align-items:center;padding:3px 4px;border-radius:2px;cursor:context-menu;';
    const readableFont = 'font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:0.01em;';
    const cellNameStyle = `${readableFont}overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;`;
    const cellStatusStyle = `${readableFont}text-align:right;white-space:nowrap;`;
    let openDevContextMenu = null;

    const closeDevContextMenu = () => {
      if (openDevContextMenu?.closeMenu) openDevContextMenu.closeMenu();
      openDevContextMenu = null;
    };

    const openDevMenu = (event, buttons) => {
      event.preventDefault();
      event.stopPropagation();
      closeDevContextMenu();
      let menuObj = null;
      const wrapped = buttons.map((btn) => ({
        ...btn,
        width: btn.width || '160px',
        onClick: () => {
          menuObj?.closeMenu();
          openDevContextMenu = null;
          if (btn.onClick) btn.onClick();
        }
      }));
      menuObj = createContextMenu({
        x: event.clientX,
        y: event.clientY,
        layout: 'column',
        minWidth: '160px',
        gap: '4px',
        anchorElement: event.target instanceof Element ? event.target : null,
        buttons: wrapped,
        onClose: () => { openDevContextMenu = null; }
      });
      openDevContextMenu = menuObj;
    };

    const appendGridHeader = (list, nameLabel, statusLabel) => {
      const header = document.createElement('div');
      header.style.cssText = [
        rowGridStyle,
        'cursor:default',
        'opacity:1',
        'position:sticky',
        'top:0',
        'z-index:2',
        'margin:0 -4px',
        'padding:4px 8px',
        'background:url("https://bestiaryarena.com/_next/static/media/background-dark.95edca67.png") repeat',
        'box-shadow:0 1px 0 rgba(0,0,0,0.45)'
      ].join(';');
      header.appendChild(document.createElement('div'));
      const name = document.createElement('span');
      name.className = 'text-whiteHighlight';
      name.style.cssText = cellNameStyle;
      name.textContent = nameLabel;
      const status = document.createElement('span');
      status.className = 'text-whiteHighlight';
      status.style.cssText = `${cellStatusStyle}font-weight:600;`;
      status.textContent = statusLabel;
      header.appendChild(name);
      header.appendChild(status);
      list.appendChild(header);
    };

    const itemsMissionsRow = document.createElement('div');
    itemsMissionsRow.style.cssText = 'display:flex;flex-direction:row;align-items:stretch;gap:8px;width:100%;min-width:0;box-sizing:border-box;';

    // All items in story order
    const itemsSection = section('Items (story order)');
    itemsSection.style.flex = '1 1 0';
    itemsSection.style.minWidth = '0';
    itemsSection.style.height = '100%';
    const itemsList = document.createElement('div');
    itemsList.className = 'frame-pressed-1 surface-dark';
    itemsList.style.cssText = listWrapStyle;
    appendGridHeader(itemsList, 'Item', 'Qty');
    const itemRows = new Map();

    refreshItemCounts = () => {
      for (const [key, { row, countEl, nameEl }] of itemRows.entries()) {
        const itemName = resolveQuestDevItemName(key);
        nameEl.textContent = itemName;
        const count = cachedQuestItems?.[itemName] || 0;
        const owned = count > 0;
        const receivedBefore = owned || wasQuestDevItemReceivedBefore(key, receivedFlagsCache);
        if (owned) {
          countEl.textContent = String(count);
          countEl.title = `${itemName}: ${count} in inventory — right-click for actions`;
          countEl.style.color = TEXT_GREEN;
          nameEl.style.color = TEXT_GREEN;
          applyRowProgressStyle(row, 'done');
        } else if (receivedBefore) {
          countEl.textContent = 'had';
          countEl.title = `${itemName}: received before (0 in inventory) — right-click for actions`;
          countEl.style.color = TEXT_ACTIVE;
          nameEl.style.color = TEXT_ACTIVE;
          applyRowProgressStyle(row, 'active');
        } else {
          countEl.textContent = '0';
          countEl.title = `${itemName}: never received — right-click for actions`;
          countEl.style.color = TEXT_RED;
          nameEl.style.color = TEXT_RED;
          applyRowProgressStyle(row, 'missing');
        }
      }
    };

    for (const key of getQuestDevItemKeysInProgressOrder()) {
      const itemName = resolveQuestDevItemName(key);
      const grantAmount = getQuestDevItemGrantAmount(key);
      const grantCmd = `QuestsDev.grant({ ${key}: ${grantAmount} })`;
      const removeCmd = `QuestsDev.grant({ ${key}: -1 })`;

      const iconCell = document.createElement('div');
      const productDef = productDefsByName.get(itemName);
      iconCell.appendChild(productDef
        ? createDevIconSlot(createProductIcon(productDef, 24))
        : createDevIconSlot(null));

      const nameEl = document.createElement('span');
      nameEl.style.cssText = cellNameStyle;
      nameEl.textContent = itemName;
      nameEl.title = `${key} — right-click for actions`;

      const countEl = document.createElement('span');
      countEl.style.cssText = cellStatusStyle;

      const rowWrap = document.createElement('div');
      rowWrap.style.cssText = rowGridStyle;
      rowWrap.title = 'Right-click for actions';
      rowWrap.appendChild(iconCell);
      rowWrap.appendChild(nameEl);
      rowWrap.appendChild(countEl);
      itemRows.set(key, { row: rowWrap, countEl, nameEl });

      rowWrap.addEventListener('contextmenu', (event) => {
        openDevMenu(event, [
          {
            text: `Grant +${grantAmount}`,
            backgroundColor: '#2a4a7a',
            color: '#4FC3F7',
            border: '1px solid #4FC3F7',
            onClick: () => runGuarded(`Grant ${resolveQuestDevItemName(key)} +${grantAmount}`, () => QuestsDev.grant({ [key]: grantAmount }))
          },
          {
            text: 'Remove -1',
            backgroundColor: '#4a2a2a',
            color: '#ff8a80',
            border: '1px solid #ff8a80',
            hoverBackgroundColor: '#2a1a1a',
            hoverBorderColor: '#ffcdd2',
            onClick: () => runGuarded(`Remove ${resolveQuestDevItemName(key)} -1`, () => QuestsDev.grant({ [key]: -1 }))
          },
          {
            text: 'Copy grant cmd',
            onClick: () => copyCommand(grantCmd)
          },
          {
            text: 'Copy remove cmd',
            onClick: () => copyCommand(removeCmd)
          },
          {
            text: 'Copy all cmds',
            onClick: () => copyCommand(`${grantCmd}\n${removeCmd}`)
          }
        ]);
      });

      itemsList.appendChild(rowWrap);
    }
    refreshItemCounts();
    itemsSection.appendChild(itemsList);
    itemsMissionsRow.appendChild(itemsSection);

    loadQuestDevItemReceivedFlags(getCurrentPlayerName()).then((flags) => {
      receivedFlagsCache = flags;
      refreshItemCounts();
    }).catch(() => {});

    // All missions in story order
    const missionSection = section('Missions (story order)');
    missionSection.style.flex = '1 1 0';
    missionSection.style.minWidth = '0';
    missionSection.style.height = '100%';
    const missionsList = document.createElement('div');
    missionsList.className = 'frame-pressed-1 surface-dark';
    missionsList.style.cssText = listWrapStyle;
    appendGridHeader(missionsList, 'Mission', 'Status');
    const missionRows = new Map();

    refreshMissionStatuses = () => {
      for (const [missionId, { row, statusEl, nameEl }] of missionRows.entries()) {
        const mission = QUESTS_DEV_MISSIONS_BY_ID[missionId];
        const status = getQuestDevMissionStatusLabel(mission);
        statusEl.textContent = status;
        if (status === 'completed') {
          statusEl.style.color = TEXT_GREEN;
          nameEl.style.color = TEXT_GREEN;
          applyRowProgressStyle(row, 'done');
        } else if (status === 'accepted') {
          statusEl.style.color = TEXT_ACTIVE;
          nameEl.style.color = TEXT_ACTIVE;
          applyRowProgressStyle(row, 'active');
        } else {
          statusEl.style.color = TEXT_RED;
          nameEl.style.color = TEXT_RED;
          applyRowProgressStyle(row, 'missing');
        }
      }
    };

    for (const mission of getQuestDevMissionsInProgressOrder()) {
      const acceptCmd = `QuestsDev.setAccepted(${JSON.stringify(mission.id)})`;
      const completeCmd = `QuestsDev.complete(${JSON.stringify(mission.id)})`;
      const resetCmd = `QuestsDev.reset(${JSON.stringify(mission.id)})`;

      const iconCell = document.createElement('div');
      iconCell.appendChild(createDevIconSlot(createActiveMissionIconElement(mission)));

      const nameEl = document.createElement('span');
      nameEl.style.cssText = cellNameStyle;
      nameEl.textContent = mission.title || mission.id;
      nameEl.title = `${mission.id} — right-click for actions`;

      const missionStatusEl = document.createElement('span');
      missionStatusEl.style.cssText = `${cellStatusStyle};text-transform:lowercase;`;

      const rowWrap = document.createElement('div');
      rowWrap.style.cssText = rowGridStyle;
      rowWrap.title = 'Right-click for actions';
      rowWrap.appendChild(iconCell);
      rowWrap.appendChild(nameEl);
      rowWrap.appendChild(missionStatusEl);
      missionRows.set(mission.id, { row: rowWrap, statusEl: missionStatusEl, nameEl });

      rowWrap.addEventListener('contextmenu', (event) => {
        openDevMenu(event, [
          {
            text: 'Accept',
            backgroundColor: '#2a4a7a',
            color: '#4FC3F7',
            border: '1px solid #4FC3F7',
            onClick: () => runGuarded(`Accept ${mission.id}`, () => QuestsDev.setAccepted(mission.id))
          },
          {
            text: 'Complete',
            backgroundColor: '#2a4a7a',
            color: '#4FC3F7',
            border: '1px solid #4FC3F7',
            onClick: () => runGuarded(`Complete ${mission.id}`, () => QuestsDev.complete(mission.id))
          },
          {
            text: 'Reset',
            backgroundColor: '#4a2a2a',
            color: '#ff8a80',
            border: '1px solid #ff8a80',
            hoverBackgroundColor: '#2a1a1a',
            hoverBorderColor: '#ffcdd2',
            onClick: () => runGuarded(`Reset ${mission.id}`, () => QuestsDev.reset(mission.id))
          },
          {
            text: 'Copy accept cmd',
            onClick: () => copyCommand(acceptCmd)
          },
          {
            text: 'Copy complete cmd',
            onClick: () => copyCommand(completeCmd)
          },
          {
            text: 'Copy reset cmd',
            onClick: () => copyCommand(resetCmd)
          },
          {
            text: 'Copy all cmds',
            onClick: () => copyCommand(`${acceptCmd}\n${completeCmd}\n${resetCmd}`)
          }
        ]);
      });

      missionsList.appendChild(rowWrap);
    }
    refreshMissionStatuses();
    missionSection.appendChild(missionsList);
    itemsMissionsRow.appendChild(missionSection);
    contentDiv.appendChild(itemsMissionsRow);

    // Seals
    const sealsSection = section('Seven seals');
    const sealsRow = buttonRow(sealsSection);
    const sealButtons = [];
    for (let i = 0; i < SEVEN_SEALS_COUNT; i++) {
      const command = `QuestsDev.setSealCompleted(${i}, true)`;
      const group = document.createElement('div');
      group.style.cssText = 'display:flex;gap:2px;';
      const btn = makeBtn(`Seal ${i + 1}`, () => runGuarded(`Complete seal ${i + 1}`, async () => {
        await QuestsDev.setSealCompleted(i, true);
      }), { command });
      sealButtons.push({ index: i, btn });
      group.appendChild(btn);
      group.appendChild(makeCopyBtn(command));
      sealsRow.appendChild(group);
    }
    const allSealsCmd = 'QuestsDev.grant({ firstSeal: 1, secondSeal: 1, thirdSeal: 1, fourthSeal: 1, fifthSeal: 1, sixthSeal: 1, seventhSeal: 1 })';
    const clearSealsCmd = 'QuestsDev.grant({ resetAllSeals: true })';
    const allSealsGroup = document.createElement('div');
    allSealsGroup.style.cssText = 'display:flex;gap:2px;';
    allSealsGroup.appendChild(makeBtn('All seals', () => runGuarded('Complete all seals', () => QuestsDev.grant({
      firstSeal: 1, secondSeal: 1, thirdSeal: 1, fourthSeal: 1, fifthSeal: 1, sixthSeal: 1, seventhSeal: 1
    })), { command: allSealsCmd }));
    allSealsGroup.appendChild(makeCopyBtn(allSealsCmd));
    sealsRow.appendChild(allSealsGroup);
    const clearSealsGroup = document.createElement('div');
    clearSealsGroup.style.cssText = 'display:flex;gap:2px;';
    clearSealsGroup.appendChild(makeBtn('Clear seals', () => runGuarded('Clear seals', () => QuestsDev.grant({ resetAllSeals: true })), { danger: true, command: clearSealsCmd }));
    clearSealsGroup.appendChild(makeCopyBtn(clearSealsCmd));
    sealsRow.appendChild(clearSealsGroup);
    contentDiv.appendChild(sealsSection);

    refreshSealStatuses = () => {
      for (const { index, btn } of sealButtons) {
        const done = typeof QuestsDev.getSealCompleted === 'function'
          ? QuestsDev.getSealCompleted(index)
          : getSealCompleted(index);
        btn.style.background = done ? PROGRESS_GREEN : PROGRESS_RED;
        btn.style.color = done ? TEXT_GREEN : TEXT_RED;
        btn.style.outline = done
          ? '1px solid rgba(96, 192, 96, 0.55)'
          : '1px solid rgba(255, 138, 128, 0.45)';
      }
    };
    refreshSealStatuses();

    contentDiv.appendChild(statusEl);

    const help = document.createElement('p');
    help.className = 'pixel-font-14';
    help.style.cssText = 'margin:0;color:#666;';
    help.textContent = 'Console: QuestsDev.help() — Right-click items/missions for actions. Copy / Ctrl+click quick actions.';
    contentDiv.appendChild(help);

    openQuestsModal({
      title: 'Quest Dev Tools',
      content: contentDiv,
      maxWidth: QUEST_ADMIN_DEV_MODAL_WIDTH,
      maxHeight: QUEST_ADMIN_DEV_MODAL_HEIGHT,
      minHeight: QUEST_ADMIN_DEV_MODAL_MIN_HEIGHT,
      buttons: [{ text: 'Close', primary: false }]
    });
  }

  function createArenaLeaderboardTab() {
    const questLogContainer = findQuestLogContainer();
    const kingTab = getKingTabElement();
    if (!questLogContainer || !kingTab) return;

    let tabElement = document.getElementById(ARENA_LEADERBOARD_TAB_ID);
    if (tabElement) {
      tabElement.className = getArenaLeaderboardTabClassName();
      tabElement.style.order = '-3';
      tabElement.innerHTML = getArenaLeaderboardTabHtml();
      bindArenaRankingsOpenButton(tabElement);
      verifyArenaLeaderboardTabPosition();
      verifyQuestAdminDevTabPosition();
      return;
    }

    tabElement = document.createElement('div');
    tabElement.id = ARENA_LEADERBOARD_TAB_ID;
    tabElement.className = getArenaLeaderboardTabClassName();
    tabElement.setAttribute('data-highlighted', 'false');
    tabElement.setAttribute('data-disabled', 'false');
    tabElement.style.order = '-3';
    tabElement.innerHTML = getArenaLeaderboardTabHtml();
    tabElement.dataset.questsOriginalDisplay = tabElement.style.display || '';
    tabElement.style.display = 'none';

    questLogContainer.insertBefore(tabElement, kingTab);

    bindArenaRankingsOpenButton(tabElement);
    verifyQuestAdminDevTabPosition();
  }

  function verifyArenaLeaderboardTabPosition() {
    const kingTab = getKingTabElement();
    const leaderboardTab = getArenaLeaderboardTabElement();
    const questLogContainer = findQuestLogContainer();
    if (!kingTab || !leaderboardTab || !questLogContainer) return;
    if (leaderboardTab.parentNode !== questLogContainer) return;

    if (leaderboardTab.style.order !== '-3') {
      leaderboardTab.style.order = '-3';
    }

    const kingIndex = Array.from(questLogContainer.children).indexOf(kingTab);
    const leaderboardIndex = Array.from(questLogContainer.children).indexOf(leaderboardTab);
    if (leaderboardIndex >= kingIndex) {
      // insertBefore moves an already-attached node; avoid remove()+insert races with React
      questLogContainer.insertBefore(leaderboardTab, kingTab);
    }
  }

  function createKingTibianusTab() {
    console.log('[Quests Mod] Creating King Tibianus tab');
    
    const existingTab = document.getElementById(KING_TIBIANUS_TAB_ID);
    if (existingTab) {
      console.log('[Quests Mod] King Tibianus tab already exists, skipping');
      createArenaLeaderboardTab();
      verifyArenaLeaderboardTabPosition();
      syncQuestAdminDevTab().catch(() => {});
      syncActiveMissionTabs();
      return;
    }

    const questLogContainer = findQuestLogContainer();
    
    if (!questLogContainer) {
      console.log('[Quests Mod] Quest log container not found, aborting');
      return;
    }
    
    // Container found, proceeding with creation

    const tabElement = document.createElement('div');
    tabElement.id = KING_TIBIANUS_TAB_ID;
    tabElement.className = 'frame-1 surface-regular relative grid gap-2 p-1.5 text-left data-[disabled=\'true\']:order-last md:data-[highlighted=\'true\']:brightness-[1.2]';
    tabElement.setAttribute('data-highlighted', 'false');
    tabElement.setAttribute('data-disabled', 'false');
    tabElement.style.order = '-2'; // Place before Raid Hunter (which has order: -1)

    const kingTibianusIconUrl = getQuestItemsAssetUrl('King_Tibianus.gif');
    
    tabElement.innerHTML = `
      <div class="flex justify-between gap-2">
        <div id="king-tibianus-tab-portrait" class="container-slot surface-darker grid place-items-center relative" style="width: 106px; height: 64px; min-width: 106px; min-height: 64px; padding: 0;">
          <div class="relative flex items-center justify-center" style="width: 106px; height: 64px;">
            <img alt="King Tibianus" class="pixelated" src="${kingTibianusIconUrl}" style="width: 106px; height: 64px; object-fit: contain; image-rendering: pixelated;">
          </div>
        </div>
        <div class="flex w-full flex-col">
          <p class="flex w-fit cursor-pointer items-center gap-1 text-whiteHighlight">King Tibianus</p>
          <div class="flex gap-1 mt-1">
            <button class="focus-style-visible flex items-center justify-center tracking-wide disabled:cursor-not-allowed disabled:text-whiteDark/60 disabled:grayscale-50 frame-1-blue active:frame-pressed-1-blue surface-blue gap-1 px-2 py-0.5 pb-[3px] pixel-font-16 flex-1 text-whiteHighlight" id="king-tibianus-open-btn">
              Hail the King!
            </button>
          </div>
          <div class="mt-1 text-center">
            <p id="king-tibianus-rank-display" class="text-sm pixel-font-16 italic" style="color: rgb(150, 150, 150);">Rank: Scout of the Arena</p>
          </div>
        </div>
      </div>
    `;
    tabElement.dataset.questsOriginalDisplay = tabElement.style.display || '';
    tabElement.style.display = 'none';

    // Find Raid Hunter tab and place before it (at the top)
    const raidHunterTab = findRaidHunterTab();
    if (raidHunterTab) {
      questLogContainer.insertBefore(tabElement, raidHunterTab);
    } else if (!tabElement.parentNode) {
      // No Raid Hunter yet — CSS order handles visual position; append once without thrashing
      questLogContainer.appendChild(tabElement);
      console.log('[Quests Mod] King Tibianus tab placed (Raid Hunter not found; using CSS order)');
    }

    // Add event listener for Open button
    const openButton = tabElement.querySelector('#king-tibianus-open-btn');
    if (openButton) {
      openButton.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        console.log('[Quests Mod] King Tibianus button clicked');
        showKingTibianusModal();
      });
    }

    // Initialize rank display
    scheduleArenaRankDisplayUpdate(0);
    createArenaLeaderboardTab();
    verifyArenaLeaderboardTabPosition();
    syncQuestAdminDevTab().catch((err) => {
      console.warn('[Quests Mod] Could not sync Quest Dev admin tab:', err);
    });
    syncActiveMissionTabs();

    console.log('[Quests Mod] King Tibianus tab created successfully!');
  }

  function getNextElementSibling(element) {
    let sibling = element.nextSibling;
    while (sibling && sibling.nodeType !== Node.ELEMENT_NODE) {
      sibling = sibling.nextSibling;
    }
    return sibling;
  }

  function verifyKingTibianusTabPosition() {
    const tabElement = document.getElementById(KING_TIBIANUS_TAB_ID);
    if (!tabElement) return;
    
    const raidHunterTab = findRaidHunterTab();
    const questLogContainer = findQuestLogContainer();
    if (!questLogContainer || tabElement.parentNode !== questLogContainer) return;

    // Avoid DOM surgery while a Quests/mod modal is open — React may still own the Quest Log
    if (isQuestsModDialogOpen()) return;
    
    // Ensure order style is set (visual ordering without remove/insert thrash)
    if (tabElement.style.order !== '-2') {
      tabElement.style.order = '-2';
    }
    
    if (raidHunterTab && raidHunterTab.parentNode === questLogContainer) {
      const tabIndex = Array.from(questLogContainer.children).indexOf(tabElement);
      const raidHunterIndex = Array.from(questLogContainer.children).indexOf(raidHunterTab);
      
      if (tabIndex >= raidHunterIndex) {
        // insertBefore moves an already-attached node; do not remove() first
        questLogContainer.insertBefore(tabElement, raidHunterTab);
      }
    }
    // When Raid Hunter is absent: rely on CSS order only. Forcing firstChild fights
    // Arena Leaderboard / mission tabs and triggers React removeChild crashes.

    syncActiveMissionTabs();
  }

  function tryImmediateKingTibianusCreation() {
    const questLogContainer = findQuestLogContainer();
    if (!questLogContainer) {
      return false;
    }

    // Final verification - check for the exact Quest Log header structure
    const questLogHeader = document.querySelector('h2[id*="radix-"][class*="widget-top"] p[id*="radix-"]');
    if (!questLogHeader || questLogHeader.textContent !== 'Quest Log') {
      console.log('[Quests Mod] Quest Log verification failed');
      return false; // Not the actual Quest Log, abort
    }

    const existingTab = document.getElementById(KING_TIBIANUS_TAB_ID);
    if (existingTab) {
      // Tab exists, verify its position
      verifyKingTibianusTabPosition();
      handleQuestLogReady(questLogContainer);
      return false;
    }
    
    console.log('[Quests Mod] Quest Log verified');
    createKingTibianusTab();
    handleQuestLogReady(questLogContainer);
    return true;
  }

  function checkForQuestLogContent(node) {
    return node.textContent?.includes('Quest Log') || 
           (node.querySelector?.('*') && 
            Array.from(node.querySelectorAll('*')).some(el => 
              el.textContent?.includes('Quest Log')
            )) ||
           // Check for quest log container structure
           (node.classList?.contains('grid') && 
            node.classList?.contains('items-start') && 
            node.classList?.contains('gap-1')) ||
           // Check for widget-bottom that might contain quest log
           node.classList?.contains('widget-bottom') ||
           // Check for any element with quest log related classes
           (node.querySelector && node.querySelector('.grid.h-\\[260px\\].items-start.gap-1'));
  }

  function handleQuestLogDetection(mutations) {
    try {
      let hasQuestLogContent = false;
      
      // Process mutations for quest log content
      for (const mutation of mutations) {
        if (mutation.type === 'childList' && mutation.addedNodes.length > 0) {
          for (const node of mutation.addedNodes) {
            if (node.nodeType === Node.ELEMENT_NODE && !document.getElementById(KING_TIBIANUS_TAB_ID)) {
              hasQuestLogContent = checkForQuestLogContent(node);
              if (hasQuestLogContent) break;
            }
          }
        }
        if (hasQuestLogContent) break;
      }
      
      // Handle quest log detection
      if (hasQuestLogContent) {
        console.log('[Quests Mod] Quest log content detected!');
        
        // Clear any existing timeout
        if (questLogObserverTimeout) {
          clearTimeout(questLogObserverTimeout);
        }
        
        // Try immediate detection first
        if (tryImmediateKingTibianusCreation()) {
          return;
        }
        
        // Verify position if tab already exists
        verifyKingTibianusTabPosition();
        
        // Fallback with minimal delay
        questLogObserverTimeout = setTimeout(() => {
          if (!document.getElementById(KING_TIBIANUS_TAB_ID) && tryImmediateKingTibianusCreation()) {
            console.log('[Quests Mod] King Tibianus tab created via delayed detection!');
          } else {
            // Verify position after delay as well
            verifyKingTibianusTabPosition();
          }
        }, 50);
      }
    } catch (error) {
      console.error('[Quests Mod] Error in handleQuestLogDetection:', error);
    }
  }

  function monitorQuestLogVisibility() {
    // Skip if observer already exists
    if (questLogObserver) {
      console.log('[Quests Mod] monitorQuestLogVisibility: Observer already exists, skipping');
      return;
    }
    
    // MutationObserver for quest log detection
    questLogObserver = new MutationObserver(handleQuestLogDetection);
    
    questLogObserver.observe(document.body, {
      childList: true,
      subtree: true
    });
    
    console.log('[Quests Mod] MutationObserver set up for quest log detection');
  }

  function startQuestLogMonitoring() {
    console.log('[Quests Mod] startQuestLogMonitoring: Starting quest log monitoring...');
    
    // Clear any existing monitoring first
    if (questLogMonitorInterval) {
      console.log('[Quests Mod] startQuestLogMonitoring: Clearing existing interval');
      clearInterval(questLogMonitorInterval);
      questLogMonitorInterval = null;
    }
    
    if (questLogObserver) {
      console.log('[Quests Mod] startQuestLogMonitoring: Disconnecting existing observer');
      questLogObserver.disconnect();
      questLogObserver = null;
    }
    
    // Set up MutationObserver for quest log detection
    monitorQuestLogVisibility();
    
    // Simple interval monitoring as backup
    questLogMonitorInterval = setInterval(() => {
      try {
        // Check if quest log is visible
        const questLogHeader = document.querySelector('h2[id*="radix-"][class*="widget-top"] p[id*="radix-"]');
        const isQuestLogOpen = questLogHeader && questLogHeader.textContent === 'Quest Log';
        
        if (isQuestLogOpen) {
          // Try immediate detection
          if (tryImmediateKingTibianusCreation()) {
            // Tab created successfully, continue monitoring for future reopenings
          } else {
            // Verify position even if tab already exists (more frequently when quest log is open)
            verifyKingTibianusTabPosition();
          }
        }
      } catch (error) {
        console.error('[Quests Mod] Error in quest log monitoring interval:', error);
      }
    }, 2000); // Check every 2 seconds when quest log is open
  }

  function stopQuestLogMonitoring() {
    // Clear interval
    if (questLogMonitorInterval) {
      clearInterval(questLogMonitorInterval);
      questLogMonitorInterval = null;
    }
    
    // Disconnect observer
    if (questLogObserver) {
      questLogObserver.disconnect();
      questLogObserver = null;
    }
    
    // Clear timeout
    if (questLogObserverTimeout) {
      clearTimeout(questLogObserverTimeout);
      questLogObserverTimeout = null;
    }
    
    // Remove tab element if it exists
    const tabElement = document.getElementById(KING_TIBIANUS_TAB_ID);
    if (tabElement && isInDOM(tabElement)) {
      tabElement.remove();
    }
    
    console.log('[Quests Mod] Quest log monitoring stopped');
  }

