  function shouldEnableTile77SpiderLair(boardContext = null) {
    const progress = kingChatState.progressMotherOfAllSpiders;
    if (!progress?.accepted || progress.completed) return false;
    return isOnRoomByName(SECLUDED_HERB_ROOM_NAME);
  }

  // Listener is on whenever we're not in the Sewers battle room (so we don't disable on map view or other rooms); pointer-events only when on A Secluded Herb
  function shouldEnableTile77SpiderLairListener(boardContext = null) {
    const progress = kingChatState.progressMotherOfAllSpiders;
    if (!progress?.accepted || progress.completed) return false;
    return !isOnRoomByName(SPIDER_LAIR_BATTLE_ROOM_NAME);
  }

  function updateTile77SpiderLairState(boardContext = null, retryCount = 0) {
    try {
      const listenerShouldBeOn = shouldEnableTile77SpiderLairListener(boardContext);
      const pointerEventsShouldBeOn = shouldEnableTile77SpiderLair(boardContext);
      const tile77El = getTileElement(SECLUDED_HERB_TILE_77);
      if (listenerShouldBeOn && !tile77SpiderLairRightClickEnabled) {
        document.addEventListener('contextmenu', handleTile77SpiderLairRightClickDocument, true);
        tile77SpiderLairRightClickEnabled = true;
      }
      if (!listenerShouldBeOn && tile77SpiderLairRightClickEnabled) {
        document.removeEventListener('contextmenu', handleTile77SpiderLairRightClickDocument, true);
        const el = getTileElement(SECLUDED_HERB_TILE_77);
        if (el) el.style.pointerEvents = '';
        tile77SpiderLairRightClickEnabled = false;
        console.log('[Quests Mod][Tile 77 Spider Lair] Right-click disabled');
        return;
      }
      if (pointerEventsShouldBeOn && tile77El) {
        tile77El.style.pointerEvents = 'auto';
        if (retryCount === 0) console.log('[Quests Mod][Tile 77 Spider Lair] Right-click enabled on A Secluded Herb');
      } else if (pointerEventsShouldBeOn && !tile77El && retryCount < 5) {
        setTimeout(() => updateTile77SpiderLairState(boardContext || globalThis.state?.board?.getSnapshot?.()?.context, retryCount + 1), 200);
      }
    } catch (e) {
      console.error('[Quests Mod][Tile 77 Spider Lair] Error updating right-click state:', e);
    }
  }

  function setupTile77SpiderLairObserver() {
    if (tile77SpiderLairBoardSubscription) return;
    if (typeof globalThis === 'undefined' || !globalThis.state?.board?.subscribe) return;
    tile77SpiderLairBoardSubscription = globalThis.state.board.subscribe(({ context: boardContext }) => {
      updateTile77SpiderLairState(boardContext);
    });
    updateTile77SpiderLairState(globalThis.state?.board?.getSnapshot()?.context);
    console.log(`[Quests Mod][Tile 77 Spider Lair] Board observer set up for ${SECLUDED_HERB_ROOM_NAME || '(room pending)'}`);
  }

  function cleanupTile77SpiderLairObserver() {
    if (tile77SpiderLairBoardSubscription) {
      try {
        tile77SpiderLairBoardSubscription.unsubscribe();
      } catch (e) {
        console.warn('[Quests Mod][Tile 77 Spider Lair] Error unsubscribing from board:', e);
      }
      tile77SpiderLairBoardSubscription = null;
    }
  }

  function cleanupTile77SpiderLairSystem() {
    if (tile77SpiderLairRightClickEnabled) {
      document.removeEventListener('contextmenu', handleTile77SpiderLairRightClickDocument, true);
      const tile77El = getTileElement(SECLUDED_HERB_TILE_77);
      if (tile77El) tile77El.style.pointerEvents = '';
      tile77SpiderLairRightClickEnabled = false;
    }
    cleanupTile77SpiderLairObserver();
    try {
      cleanupSpiderLairQuest();
    } catch (e) {
      console.warn('[Quests Mod][Tile 77 Spider Lair] cleanupSpiderLairQuest during teardown:', e);
    }
    console.log('[Quests Mod][Tile 77 Spider Lair] System cleaned up');
  }

  // Tile 76 in Plains of Havoc (The Jakundaf Desert) — right-click stub; battle/nav later
  function closeTile76JakundafContextMenu() {
    if (tile76JakundafContextMenu && tile76JakundafContextMenu.closeMenu) {
      tile76JakundafContextMenu.closeMenu();
    }
    tile76JakundafContextMenu = null;
  }

  function removeJakundafDesertArrow() {
    document.querySelectorAll(`.${JAKUNDAF_ARROW_CLASS}`).forEach((el) => el.remove());
    jakundafArrowVisible = false;
  }

  function placeJakundafDesertArrow(tileElement) {
    if (!tileElement || !areQuestHelpersEnabled()) return;
    if (tileElement.querySelector(`.${JAKUNDAF_ARROW_CLASS}`)) {
      jakundafArrowVisible = true;
      return;
    }
    const arrow = document.createElement('img');
    arrow.className = `${JAKUNDAF_ARROW_CLASS} pixelated`;
    arrow.src = getQuestItemsAssetUrl('Tutorial_Arrow_Effect.gif');
    arrow.alt = JAKUNDAF_DESERT_CONTEXT_MENU_LABEL;
    arrow.title = QUEST_ACCESS_TILE_TITLE;
    arrow.draggable = false;
    arrow.style.cssText = [
      'position:absolute',
      'left:0',
      'top:0',
      'width:100%',
      'height:100%',
      'pointer-events:none',
      'z-index:10003',
      'image-rendering:pixelated',
      'object-fit:contain'
    ].join(';');
    tileElement.appendChild(arrow);
    jakundafArrowVisible = true;
  }

  function updateJakundafDesertArrow(boardContext = null) {
    try {
      if (!shouldEnableTile76Jakundaf(boardContext) || !areQuestHelpersEnabled()) {
        if (jakundafArrowVisible) removeJakundafDesertArrow();
        return;
      }
      const tile = getTileElement(JAKUNDAF_DESERT_TILE_INDEX);
      if (!tile) {
        if (jakundafArrowVisible) removeJakundafDesertArrow();
        return;
      }
      placeJakundafDesertArrow(tile);
    } catch (error) {
      console.error('[Quests Mod][Jakundaf Desert] Error updating arrow:', error);
    }
  }

  async function enterJakundafDesertBattle() {
    const progress = kingChatState.progressJakundafDesert;
    if (!progress?.accepted || progress.completed || progress.pathCleared) return;

    let roomId = JAKUNDAF_BATTLE_ROOM_ID || getRoomIdByRoomName(JAKUNDAF_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(JAKUNDAF_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({
        message: TOAST_MESSAGES.jakundafDesertNotFound || 'Sewers battle room not found.',
        logPrefix: BATTLE_TOAST_LOG.jakundafDesert || '[Quests Mod][Jakundaf Desert]'
      });
      return;
    }

    playerUsedTile76ToJakundafDesert = true;
    jakundafDesertReinitTriggered = false;
    if (jakundafDesertBattle) {
      jakundafDesertBattle.cleanup(restoreBoardSetupJakundafDesert, showQuestOverlays);
      jakundafDesertBattle = null;
    }

    const initResult = initializeJakundafDesertBattle(roomId);
    const logPrefix = BATTLE_TOAST_LOG.jakundafDesert || '[Quests Mod][Jakundaf Desert]';
    if (initResult && initResult.then) {
      initResult.then((battle) => {
        if (battle) {
          jakundafDesertBattle = battle;
          jakundafDesertBattle.setup(
            () => playerUsedTile76ToJakundafDesert,
            NotificationService.createBattleToastCallback(logPrefix)
          );
          setupJakundafDesertTileRestrictions();
          showCustomBattleStatusToast({
            battleName: JAKUNDAF_BATTLE_DISPLAY_NAME || 'Jakundaf Desert',
            allyLimit: battle.config?.allyLimit ?? 10,
            battle,
            logPrefix
          });
        }
      }).catch((err) => console.error('[Quests Mod][Jakundaf Desert] Error initializing battle:', err));
    } else if (initResult) {
      jakundafDesertBattle = initResult;
      jakundafDesertBattle.setup(
        () => playerUsedTile76ToJakundafDesert,
        NotificationService.createBattleToastCallback(logPrefix)
      );
      setupJakundafDesertTileRestrictions();
      showCustomBattleStatusToast({
        battleName: JAKUNDAF_BATTLE_DISPLAY_NAME || 'Jakundaf Desert',
        allyLimit: initResult.config?.allyLimit ?? 10,
        battle: initResult,
        logPrefix
      });
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    showToast({
      message: TOAST_MESSAGES.enteringJakundafDesert || 'Entering the Jakundaf Desert path...',
      logPrefix
    });
  }

  function createTile76JakundafContextMenu(x, y, anchorElement = null) {
    closeTile76JakundafContextMenu();
    tile76JakundafContextMenu = createContextMenu({
      x,
      y,
      layout: 'center',
      logPrefix: '[Quests Mod][Jakundaf Desert]',
      anchorElement: anchorElement || getTileElement(JAKUNDAF_DESERT_TILE_INDEX),
      buttons: [
        {
          text: JAKUNDAF_DESERT_CONTEXT_MENU_LABEL,
          width: '180px',
          backgroundColor: '#2a4a2a',
          color: '#4CAF50',
          border: '1px solid #4CAF50',
          hoverBackgroundColor: '#1a2a1a',
          hoverBorderColor: '#66BB6A',
          onClick: () => {
            closeTile76JakundafContextMenu();
            enterJakundafDesertBattle();
          }
        }
      ],
      onClose: () => {
        tile76JakundafContextMenu = null;
      }
    });
    return tile76JakundafContextMenu;
  }

  function isOnJakundafEntryRoom(boardContext = null) {
    try {
      const context = boardContext || globalThis.state?.board?.getSnapshot()?.context;
      const currentRoomId = context?.selectedMap?.selectedRoom?.id || globalThis.state?.selectedMap?.selectedRoom?.id;
      const roomNames = globalThis.state?.utils?.ROOM_NAME;
      const currentRoomName = roomNames && currentRoomId ? roomNames[currentRoomId] : '';
      if (!currentRoomName) return false;
      return JAKUNDAF_ENTRY_ROOM_NAMES.some(
        (name) => currentRoomName === name || String(currentRoomName).includes(name)
      );
    } catch (_) {
      return false;
    }
  }

  function handleTile76JakundafRightClickDocument(event) {
    const progress = kingChatState.progressJakundafDesert;
    if (!progress?.accepted || progress.completed) return;
    if (!isOnJakundafEntryRoom()) return;

    const tile76El = getTileElement(JAKUNDAF_DESERT_TILE_INDEX);
    if (!tile76El || !tile76El.contains(event.target)) return;

    event.preventDefault();
    event.stopImmediatePropagation();
    event.stopPropagation();
    createTile76JakundafContextMenu(event.clientX, event.clientY, tile76El);
  }

  function shouldEnableTile76Jakundaf(boardContext = null) {
    const progress = kingChatState.progressJakundafDesert;
    if (!progress?.accepted || progress.completed || progress.pathCleared) return false;
    return isOnJakundafEntryRoom(boardContext);
  }

  function shouldEnableTile76JakundafListener(boardContext = null) {
    const progress = kingChatState.progressJakundafDesert;
    if (!progress?.accepted || progress.completed || progress.pathCleared) return false;
    return true;
  }

  function updateTile76JakundafState(boardContext = null, retryCount = 0) {
    try {
      const listenerShouldBeOn = shouldEnableTile76JakundafListener(boardContext);
      const pointerEventsShouldBeOn = shouldEnableTile76Jakundaf(boardContext);
      const tile76El = getTileElement(JAKUNDAF_DESERT_TILE_INDEX);
      if (listenerShouldBeOn && !tile76JakundafRightClickEnabled) {
        document.addEventListener('contextmenu', handleTile76JakundafRightClickDocument, true);
        tile76JakundafRightClickEnabled = true;
      }
      if (!listenerShouldBeOn && tile76JakundafRightClickEnabled) {
        document.removeEventListener('contextmenu', handleTile76JakundafRightClickDocument, true);
        const el = getTileElement(JAKUNDAF_DESERT_TILE_INDEX);
        if (el) el.style.pointerEvents = '';
        tile76JakundafRightClickEnabled = false;
        closeTile76JakundafContextMenu();
        removeJakundafDesertArrow();
        return;
      }
      if (pointerEventsShouldBeOn && tile76El) {
        tile76El.style.pointerEvents = 'auto';
        if (retryCount === 0) {
          console.log('[Quests Mod][Jakundaf Desert] Right-click enabled on Wyda house tile', JAKUNDAF_DESERT_TILE_INDEX);
        }
      } else if (pointerEventsShouldBeOn && !tile76El && retryCount < 5) {
        setTimeout(() => updateTile76JakundafState(boardContext || globalThis.state?.board?.getSnapshot?.()?.context, retryCount + 1), 200);
      }
      updateJakundafDesertArrow(boardContext);
    } catch (e) {
      console.error('[Quests Mod][Jakundaf Desert] Error updating right-click state:', e);
    }
  }

  function setupTile76JakundafObserver() {
    if (tile76JakundafBoardSubscription) return;
    if (typeof globalThis === 'undefined' || !globalThis.state?.board?.subscribe) return;
    tile76JakundafBoardSubscription = globalThis.state.board.subscribe(({ context: boardContext }) => {
      updateTile76JakundafState(boardContext);
    });
    updateTile76JakundafState(globalThis.state?.board?.getSnapshot()?.context);
    console.log('[Quests Mod][Jakundaf Desert] Board observer set up for Wyda house entry tile');
  }

  function cleanupTile76JakundafObserver() {
    if (tile76JakundafBoardSubscription) {
      try {
        tile76JakundafBoardSubscription.unsubscribe();
      } catch (e) {
        console.warn('[Quests Mod][Jakundaf Desert] Error unsubscribing from board:', e);
      }
      tile76JakundafBoardSubscription = null;
    }
  }

  function cleanupTile76JakundafSystem() {
    closeTile76JakundafContextMenu();
    if (tile76JakundafRightClickEnabled) {
      document.removeEventListener('contextmenu', handleTile76JakundafRightClickDocument, true);
      const tile76El = getTileElement(JAKUNDAF_DESERT_TILE_INDEX);
      if (tile76El) tile76El.style.pointerEvents = '';
      tile76JakundafRightClickEnabled = false;
    }
    removeJakundafDesertArrow();
    cleanupTile76JakundafObserver();
    console.log('[Quests Mod][Jakundaf Desert] System cleaned up');
  }

  // The Tainted Souls — Eclipse cauldron (tiles 20/21/35/36) → teleporter on tile 81 → Ekatrix
  function getTaintedSoulsRequiredItemName() {
    return EKATRIX_REQUIRED_ITEM_NAME || JAKUNDAF_DESERT_MISSION.rewardItemName || 'Stuffed Toad';
  }

  function getTaintedSoulsLogPrefix() {
    return BATTLE_TOAST_LOG.taintedSouls || '[Quests Mod][The Tainted Souls]';
  }

  function buildTaintedSoulsProgress(patch = {}) {
    const current = getMissionProgress(TAINTED_SOULS_MISSION) || {};
    return {
      accepted: patch.accepted ?? current.accepted ?? false,
      completed: patch.completed ?? current.completed ?? false,
      portalOpened: patch.portalOpened ?? current.portalOpened ?? false,
      battleCompleted: patch.battleCompleted ?? current.battleCompleted ?? false
    };
  }

  function hasStuffedToadForEclipseCauldron() {
    return getCachedQuestItemCount(getTaintedSoulsRequiredItemName()) > 0;
  }

  function isTaintedSoulsEclipseReady() {
    const progress = getMissionProgress(TAINTED_SOULS_MISSION) || {};
    return !!(progress.accepted && !progress.completed && !progress.battleCompleted);
  }

  function isOnEclipseRoom(boardContext = null) {
    try {
      const context = boardContext || globalThis.state?.board?.getSnapshot?.()?.context;
      const currentRoomId = context?.selectedMap?.selectedRoom?.id;
      if (!currentRoomId) return false;
      return isOnRoomByName(ECLIPSE_ROOM_NAME);
    } catch (_) {
      return false;
    }
  }

  function navigateToEclipseRoom() {
    try {
      const roomId = getRoomIdByRoomName(ECLIPSE_ROOM_NAME);
      if (!roomId) {
        console.warn('[Quests Mod][The Tainted Souls] Eclipse room not found');
        return;
      }
      globalThis.state.board.send({ type: 'selectRoomById', roomId });
    } catch (error) {
      console.error('[Quests Mod][The Tainted Souls] Error navigating to Eclipse:', error);
    }
  }

  function getEclipseCauldronTileIndexFromEvent(event) {
    for (const tileIndex of ECLIPSE_CAULDRON_TILE_INDICES) {
      const tileEl = getTileElement(tileIndex);
      if (tileEl && tileEl.contains(event.target)) return tileIndex;
    }
    return null;
  }

  function showTaintedSoulsToast(messageKey, fallback) {
    showToast({
      message: TOAST_MESSAGES[messageKey] || fallback,
      logPrefix: getTaintedSoulsLogPrefix()
    });
  }

  function getEkatrixPortalSpriteHTML() {
    const spriteId = ECLIPSE_PORTAL_SPRITE_ID || 1959;
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_EKATRIX}="1" style="z-index: 1000;"><div class="viewport"><img alt="${spriteId}" data-cropped="false" class="spritesheet" style="--cropX: 0; --cropY: 0;"></div></div>`;
  }

  function shouldShowEkatrixPortal(boardContext = null) {
    const progress = getMissionProgress(TAINTED_SOULS_MISSION) || {};
    if (!progress.accepted || progress.completed || progress.battleCompleted || !progress.portalOpened) return false;
    if (playerEnteredEkatrixPortal) return false;
    return isOnEclipseRoom(boardContext);
  }

  function removeEkatrixPortalSprite() {
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_EKATRIX}="1"]`).forEach((el) => el.remove());
  }

  function applyEkatrixPortalSprite(boardContext = null) {
    if (!shouldShowEkatrixPortal(boardContext)) {
      removeEkatrixPortalSprite();
      return;
    }
    const tile = getTileElement(ECLIPSE_PORTAL_TILE_INDEX);
    if (!tile) return;
    if (tile.querySelector(`[${QUEST_BOARD_ADDED_ATTR_EKATRIX}="1"]`)) return;
    const wrap = document.createElement('div');
    wrap.innerHTML = getEkatrixPortalSpriteHTML();
    if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
  }

  function closeEclipseCauldronContextMenu() {
    if (eclipseCauldronContextMenu && eclipseCauldronContextMenu.closeMenu) {
      eclipseCauldronContextMenu.closeMenu();
    }
    eclipseCauldronContextMenu = null;
  }

  function closeEclipsePortalContextMenu() {
    if (eclipsePortalContextMenu && eclipsePortalContextMenu.closeMenu) {
      eclipsePortalContextMenu.closeMenu();
    }
    eclipsePortalContextMenu = null;
  }

  async function useStuffedToadInEclipseCauldron() {
    const jakundaf = getMissionProgress(JAKUNDAF_DESERT_MISSION) || {};
    if (!jakundaf.completed) {
      showTaintedSoulsToast('taintedSoulsNeedMission', 'The cauldron does not stir. Wyda may know more.');
      return false;
    }
    const progress = getMissionProgress(TAINTED_SOULS_MISSION) || {};
    if (!progress.accepted || progress.completed) {
      showTaintedSoulsToast('taintedSoulsNeedMission', 'The cauldron does not stir. Wyda may know more.');
      return false;
    }
    if (progress.portalOpened) {
      showTaintedSoulsToast('taintedSoulsPortalOpened', 'A portal opens from the cauldron.');
      applyEkatrixPortalSprite();
      return true;
    }
    if (!hasStuffedToadForEclipseCauldron()) {
      showTaintedSoulsToast('taintedSoulsNeedToad', 'You need the Stuffed Toad to use this cauldron.');
      return false;
    }

    const toadName = getTaintedSoulsRequiredItemName();
    const consumed = await consumeQuestItem(toadName, 1);
    if (!consumed) {
      showTaintedSoulsToast('taintedSoulsNeedToad', 'You need the Stuffed Toad to use this cauldron.');
      return false;
    }
    NotificationService.showItemRemoved(toadName, getTaintedSoulsLogPrefix());

    await persistMissionProgress(TAINTED_SOULS_MISSION, buildTaintedSoulsProgress({
      accepted: true,
      completed: false,
      portalOpened: true,
      battleCompleted: false
    }));
    const portalTile = getTileElement(ECLIPSE_PORTAL_TILE_INDEX);
    if (portalTile) createPoofAnimation(portalTile, { scale: 1.5, frameMs: 32 });
    applyEkatrixPortalSprite();
    updateEclipseTaintedSoulsState();
    if (typeof refreshQuestTileHighlights === 'function') refreshQuestTileHighlights();
    showTaintedSoulsToast('taintedSoulsPortalOpened', 'A portal opens from the cauldron.');
    return true;
  }

  function buildEkatrixMutationSpriteHTML(entry) {
    const spriteId = entry?.spriteId;
    if (spriteId == null) return '';
    const cropX = entry.cropX != null ? entry.cropX : 0;
    const cropY = entry.cropY != null ? entry.cropY : 0;
    const cropped = entry.cropped ? 'true' : 'false';
    const bankStyle = entry.bank != null ? ` --bank: ${entry.bank};` : '';
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_EKATRIX_BATTLE}="1" style="z-index: 1000;${bankStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
  }

  function applyEkatrixTileMutations() {
    const mutations = EKATRIX_TILE_MUTATIONS;
    if (!mutations || typeof mutations !== 'object') return;

    const battle = ekatrixBattle;
    const hadMask = battle?._placementHitboxMaskActive === true;
    if (hadMask) battle.restorePlacementHitboxes?.();

    let wroteHitboxes = false;
    Object.entries(mutations).forEach(([tileKey, entry]) => {
      const tileIndex = Number(tileKey);
      if (!Number.isFinite(tileIndex) || !entry || typeof entry !== 'object') return;
      const tile = getTileElement(tileIndex);

      (entry.remove || []).forEach((spriteId) => {
        if (spriteId == null || !tile) return;
        tile.querySelectorAll(`.sprite.item.relative.id-${spriteId}`).forEach((sprite) => {
          hideQuestBoardElement(sprite, { tag: QUEST_BOARD_HIDDEN_TAG_EKATRIX });
        });
      });

      (entry.add || []).forEach((spriteEntry) => {
        const spriteId = spriteEntry?.spriteId;
        if (spriteId == null || !tile) return;
        const already = tile.querySelectorAll(`.id-${spriteId}[${QUEST_BOARD_ADDED_ATTR_EKATRIX_BATTLE}="1"]`);
        if (already.length) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = buildEkatrixMutationSpriteHTML(spriteEntry);
        if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
      });

      if (Object.prototype.hasOwnProperty.call(entry, 'hitbox')) {
        try {
          const roomId = EKATRIX_BATTLE_ROOM_ID;
          const selected = globalThis.state?.board?.getSnapshot?.()?.context?.selectedMap?.selectedRoom
            || globalThis.state?.selectedMap?.selectedRoom;
          const utils = globalThis.state?.utils;
          const roomRefs = [];
          if (selected?.id === roomId) roomRefs.push(selected);
          if (Array.isArray(utils?.ROOMS)) {
            utils.ROOMS.forEach((room) => {
              if (room?.id === roomId) roomRefs.push(room);
            });
          }
          if (Array.isArray(utils?.REGIONS)) {
            utils.REGIONS.forEach((region) => {
              (region?.rooms || []).forEach((room) => {
                if (room?.id === roomId) roomRefs.push(room);
              });
            });
          }
          roomRefs.forEach((room) => {
            const data = room?.file?.data;
            if (!data) return;
            if (!Array.isArray(data.hitboxes)) data.hitboxes = [];
            data.hitboxes[tileIndex] = entry.hitbox === true;
            wroteHitboxes = true;
          });
        } catch (_) {}
      }
    });

    if (wroteHitboxes) ekatrixHitboxesApplied = true;

    if (battle?.refreshPlacementHitboxMaskFromLive) {
      battle.refreshPlacementHitboxMaskFromLive(
        () => playerEnteredEkatrixPortal
      );
    } else if (battle?.syncPlacementHitboxMask) {
      battle.syncPlacementHitboxMask(() => playerEnteredEkatrixPortal);
    }
  }

  function restoreEkatrixTileMutations() {
    restoreQuestBoardElementsByTag(QUEST_BOARD_HIDDEN_TAG_EKATRIX);
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_EKATRIX_BATTLE}="1"]`).forEach((el) => {
      try { el.remove(); } catch (_) {}
    });
    ekatrixHitboxesApplied = false;
  }

  const EKATRIX_VISUAL_RETRY_DELAYS_MS = [0, 50, 150, 300, 500, 800, 1200, 2000];
  let ekatrixVisualRetryTimers = [];

  function clearEkatrixVisualRetries() {
    ekatrixVisualRetryTimers.forEach((id) => clearTimeout(id));
    ekatrixVisualRetryTimers = [];
  }

  function applyEkatrixBattlefieldVisuals({ forceSceneSprites = false } = {}) {
    if (!playerEnteredEkatrixPortal || !ekatrixBattle) return;
    applyEkatrixTileMutations();
    if (typeof ekatrixBattle.scheduleSceneSpriteReplacementsForEntry === 'function') {
      if (forceSceneSprites || !ekatrixBattle.isSceneSpriteReplacementsComplete?.()) {
        ekatrixBattle.scheduleSceneSpriteReplacementsForEntry({ force: forceSceneSprites });
      }
    }
  }

  function scheduleEkatrixBattlefieldVisuals({ forceSceneSprites = true } = {}) {
    clearEkatrixVisualRetries();
    applyEkatrixBattlefieldVisuals({ forceSceneSprites });
    EKATRIX_VISUAL_RETRY_DELAYS_MS.forEach((delay) => {
      if (delay <= 0) return;
      ekatrixVisualRetryTimers.push(setTimeout(() => {
        applyEkatrixBattlefieldVisuals({ forceSceneSprites: false });
      }, delay));
    });
  }

  function restoreBoardSetupEkatrix() {
    if (ekatrixBattle) {
      ekatrixBattle.restoreBoardSetup();
    }
    restoreEkatrixTileMutations();
  }

  function cleanupEkatrixQuest() {
    try {
      removeCustomBattleStatusToast();
      ekatrixBossHpBar.remove();
      clearEkatrixVisualRetries();
      playerEnteredEkatrixPortal = false;
      ekatrixReinitTriggered = false;
      ekatrixRetryWithoutPortal = false;
      restoreEkatrixTileMutations();
      if (ekatrixBattle) {
        ekatrixBattle.cleanup(restoreBoardSetupEkatrix, showQuestOverlays);
        ekatrixBattle = null;
      }
      applyEkatrixPortalSprite();
      updateEclipseTaintedSoulsState();
      if (typeof refreshQuestTileHighlights === 'function') refreshQuestTileHighlights();
    } catch (error) {
      console.error('[Quests Mod][The Tainted Souls] Error cleaning up:', error);
    }
  }

  function setupEkatrixTileRestrictions() {
    if (!ekatrixBattle) return;
    ekatrixBattle.setupTileRestrictions(
      () => playerEnteredEkatrixPortal,
      NotificationService.createBattleToastCallback(getTaintedSoulsLogPrefix())
    );
    ekatrixBattle.setupAllyLimit?.(
      () => playerEnteredEkatrixPortal,
      NotificationService.createBattleToastCallback(getTaintedSoulsLogPrefix())
    );
  }

  function createEkatrixBattleInstance(roomId) {
    if (!window.CustomBattles) {
      console.error('[Quests Mod][The Tainted Souls] CustomBattles still not available');
      return null;
    }
    const spawn = getHydratedQuestBattleSpawn(EKATRIX_BATTLE_ID || 'ekatrix');
    const villains = spawn.villains;
    const tileRestrictions = {};
    if (spawn.allowedTiles?.length) {
      tileRestrictions.allowedTiles = spawn.allowedTiles;
      tileRestrictions.message = spawn.allowedTilesMessage || 'Ally creatures can only be placed on the marked tiles!';
    }
    const config = {
      name: EKATRIX_BATTLE_DISPLAY_NAME || 'Ekatrix',
      roomId,
      villains,
      allyLimit: spawn.allyLimit ?? 6,
      preventVillainMovement: spawn.preventVillainMovement !== false,
      hideVillainSprites: spawn.hideVillainSprites !== false,
      ...(Object.keys(tileRestrictions).length ? { tileRestrictions } : {}),
      entrySetup: {
        sceneSpriteAttemptDelays: EKATRIX_VISUAL_RETRY_DELAYS_MS.slice()
      },
      activationCheck: (isSandbox, inBattleArea) => {
        return isSandbox && inBattleArea && playerEnteredEkatrixPortal;
      },
      victoryDefeat: {
        onVictory: async () => {
          try {
            await persistMissionProgress(TAINTED_SOULS_MISSION, buildTaintedSoulsProgress({
              accepted: true,
              completed: false,
              portalOpened: true,
              battleCompleted: true
            }));
            if (typeof updateEclipseTaintedSoulsState === 'function') updateEclipseTaintedSoulsState();
            if (typeof refreshQuestTileHighlights === 'function') refreshQuestTileHighlights();
          } catch (error) {
            console.error('[Quests Mod][The Tainted Souls] Error saving battleCompleted flag:', error);
          }
          removeEkatrixPortalSprite();
        },
        onDefeat: () => {},
        onClose: (isVictory) => {
          cleanupEkatrixQuest();
          ekatrixRetryWithoutPortal = !isVictory;
          setTimeout(() => {
            if (isVictory) navigateToJakundafEntryRoom();
            else navigateToEclipseRoom();
          }, 100);
        },
        victoryTitle: 'Victory!',
        defeatTitle: 'Defeat',
        victoryMessage: getMissionDialogueLine(
          TAINTED_SOULS_MISSION,
          'battleVictory',
          'Ekatrix has fallen. Return to Wyda for your reward.'
        ),
        defeatMessage: getMissionDialogueLine(
          TAINTED_SOULS_MISSION,
          'battleDefeat',
          'Ekatrix was too strong.'
        ),
        showItems: false,
        items: []
      }
    };
    return window.CustomBattles.create(config);
  }

  function initializeEkatrixBattle(roomId) {
    if (window.CustomBattles) {
      return createEkatrixBattleInstance(roomId);
    }
    return waitForCustomBattles({ logPrefix: getTaintedSoulsLogPrefix() }).then((api) => {
      if (!api) return null;
      return createEkatrixBattleInstance(roomId);
    });
  }

  function setupEkatrixBattleInstance(battle) {
    if (!battle) return false;
    ekatrixBattle = battle;
    ekatrixBattle.setup(
      () => playerEnteredEkatrixPortal,
      NotificationService.createBattleToastCallback(getTaintedSoulsLogPrefix())
    );
    setupEkatrixTileRestrictions();
    showCustomBattleStatusToast({
      battleName: EKATRIX_BATTLE_DISPLAY_NAME || 'Ekatrix',
      allyLimit: battle.config?.allyLimit ?? 6,
      battle,
      logPrefix: getTaintedSoulsLogPrefix()
    });
    return true;
  }

  function enterEkatrixPortal() {
    const progress = getMissionProgress(TAINTED_SOULS_MISSION) || {};
    if (progress.battleCompleted || progress.completed) {
      showTaintedSoulsToast('taintedSoulsReportBack', 'Ekatrix has fallen. Return to Wyda for your reward.');
      return false;
    }
    if (!progress.accepted || !progress.portalOpened) {
      showTaintedSoulsToast('taintedSoulsPortalStub', 'The portal to Ekatrix is not yet open.');
      return false;
    }

    let roomId = EKATRIX_BATTLE_ROOM_ID || getRoomIdByRoomName(EKATRIX_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(EKATRIX_BATTLE_ROOM_NAME);
    if (!roomId) {
      showTaintedSoulsToast('ekatrixNotFound', "Ekatrix's domain was not found.");
      return false;
    }

    playerEnteredEkatrixPortal = true;
    ekatrixReinitTriggered = false;
    removeEkatrixPortalSprite();
    if (ekatrixBattle) {
      ekatrixBattle.cleanup(restoreBoardSetupEkatrix, showQuestOverlays);
      ekatrixBattle = null;
    }

    const initResult = initializeEkatrixBattle(roomId);
    if (initResult && initResult.then) {
      initResult.then((battle) => {
        if (battle) setupEkatrixBattleInstance(battle);
      }).catch((err) => console.error('[Quests Mod][The Tainted Souls] Error initializing battle:', err));
    } else if (initResult) {
      setupEkatrixBattleInstance(initResult);
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    showTaintedSoulsToast('enteringEkatrixPortal', 'Stepping through the portal...');
    return true;
  }

  function createEclipseCauldronContextMenu(x, y, anchorElement = null) {
    closeEclipseCauldronContextMenu();
    eclipseCauldronContextMenu = createContextMenu({
      x,
      y,
      layout: 'center',
      logPrefix: getTaintedSoulsLogPrefix(),
      anchorElement,
      buttons: [
        {
          text: ECLIPSE_CAULDRON_CONTEXT_MENU_LABEL,
          width: '180px',
          backgroundColor: '#2a4a2a',
          color: '#4CAF50',
          border: '1px solid #4CAF50',
          hoverBackgroundColor: '#1a2a1a',
          hoverBorderColor: '#66BB6A',
          onClick: () => {
            closeEclipseCauldronContextMenu();
            useStuffedToadInEclipseCauldron();
          }
        }
      ],
      onClose: () => {
        eclipseCauldronContextMenu = null;
      }
    });
    return eclipseCauldronContextMenu;
  }

  function createEclipsePortalContextMenu(x, y, anchorElement = null) {
    closeEclipsePortalContextMenu();
    eclipsePortalContextMenu = createContextMenu({
      x,
      y,
      layout: 'center',
      logPrefix: getTaintedSoulsLogPrefix(),
      anchorElement,
      buttons: [
        {
          text: ECLIPSE_PORTAL_CONTEXT_MENU_LABEL,
          width: '180px',
          backgroundColor: '#2a4a2a',
          color: '#4CAF50',
          border: '1px solid #4CAF50',
          hoverBackgroundColor: '#1a2a1a',
          hoverBorderColor: '#66BB6A',
          onClick: () => {
            closeEclipsePortalContextMenu();
            enterEkatrixPortal();
          }
        }
      ],
      onClose: () => {
        eclipsePortalContextMenu = null;
      }
    });
    return eclipsePortalContextMenu;
  }

  function shouldEnableEclipseCauldron(boardContext = null) {
    const progress = getMissionProgress(TAINTED_SOULS_MISSION) || {};
    if (!progress.accepted || progress.completed || progress.portalOpened) return false;
    if (!hasStuffedToadForEclipseCauldron()) return false;
    return isOnEclipseRoom(boardContext);
  }

  function shouldEnableEclipsePortal(boardContext = null) {
    return shouldShowEkatrixPortal(boardContext);
  }

  function shouldEnableEclipseTaintedSoulsListener() {
    return isTaintedSoulsEclipseReady();
  }

  function handleEclipseCauldronRightClickDocument(event) {
    if (!shouldEnableEclipseCauldron()) return;
    const tileIndex = getEclipseCauldronTileIndexFromEvent(event);
    if (tileIndex == null) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    event.stopPropagation();
    createEclipseCauldronContextMenu(event.clientX, event.clientY, getTileElement(tileIndex));
  }

  function handleEclipsePortalRightClickDocument(event) {
    if (!shouldEnableEclipsePortal()) return;
    const tileEl = getTileElement(ECLIPSE_PORTAL_TILE_INDEX);
    if (!tileEl || !tileEl.contains(event.target)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    event.stopPropagation();
    createEclipsePortalContextMenu(event.clientX, event.clientY, tileEl);
  }

  function setEclipseCauldronPointerEvents(enabled) {
    for (const tileIndex of ECLIPSE_CAULDRON_TILE_INDICES) {
      const tileEl = getTileElement(tileIndex);
      if (tileEl) tileEl.style.pointerEvents = enabled ? 'auto' : '';
    }
  }

  function updateEclipseTaintedSoulsState(boardContext = null, retryCount = 0) {
    try {
      const listenerShouldBeOn = shouldEnableEclipseTaintedSoulsListener();
      const cauldronActive = shouldEnableEclipseCauldron(boardContext);
      const portalActive = shouldEnableEclipsePortal(boardContext);

      if (listenerShouldBeOn && !eclipseCauldronRightClickEnabled) {
        document.addEventListener('contextmenu', handleEclipseCauldronRightClickDocument, true);
        eclipseCauldronRightClickEnabled = true;
      }
      if (listenerShouldBeOn && !eclipsePortalRightClickEnabled) {
        document.addEventListener('contextmenu', handleEclipsePortalRightClickDocument, true);
        eclipsePortalRightClickEnabled = true;
      }
      if (!listenerShouldBeOn) {
        if (eclipseCauldronRightClickEnabled) {
          document.removeEventListener('contextmenu', handleEclipseCauldronRightClickDocument, true);
          eclipseCauldronRightClickEnabled = false;
          closeEclipseCauldronContextMenu();
        }
        if (eclipsePortalRightClickEnabled) {
          document.removeEventListener('contextmenu', handleEclipsePortalRightClickDocument, true);
          eclipsePortalRightClickEnabled = false;
          closeEclipsePortalContextMenu();
        }
        setEclipseCauldronPointerEvents(false);
        const portalTile = getTileElement(ECLIPSE_PORTAL_TILE_INDEX);
        if (portalTile) portalTile.style.pointerEvents = '';
        removeEkatrixPortalSprite();
        return;
      }

      setEclipseCauldronPointerEvents(cauldronActive);
      const portalTile = getTileElement(ECLIPSE_PORTAL_TILE_INDEX);
      if (portalTile) portalTile.style.pointerEvents = portalActive ? 'auto' : '';

      applyEkatrixPortalSprite(boardContext);

      if ((cauldronActive || portalActive) && retryCount < 5) {
        const missingCauldron = cauldronActive && ECLIPSE_CAULDRON_TILE_INDICES.some((idx) => !getTileElement(idx));
        const missingPortal = portalActive && !getTileElement(ECLIPSE_PORTAL_TILE_INDEX);
        if (missingCauldron || missingPortal) {
          setTimeout(() => {
            updateEclipseTaintedSoulsState(
              boardContext || globalThis.state?.board?.getSnapshot?.()?.context,
              retryCount + 1
            );
          }, 200);
        }
      }
    } catch (e) {
      console.error('[Quests Mod][The Tainted Souls] Error updating Eclipse state:', e);
    }
  }

  function setupEkatrixEclipseObserver() {
    if (eclipseBoardSubscription) {
      updateEclipseTaintedSoulsState();
      return;
    }
    if (typeof globalThis === 'undefined' || !globalThis.state?.board?.subscribe) return;
    eclipseBoardSubscription = globalThis.state.board.subscribe(({ context: boardContext }) => {
      updateEclipseTaintedSoulsState(boardContext);
    });
    updateEclipseTaintedSoulsState(globalThis.state?.board?.getSnapshot()?.context);
  }

  function cleanupEkatrixEclipseObserver() {
    if (eclipseBoardSubscription) {
      try {
        eclipseBoardSubscription.unsubscribe();
      } catch (e) {
        console.warn('[Quests Mod][The Tainted Souls] Error unsubscribing Eclipse observer:', e);
      }
      eclipseBoardSubscription = null;
    }
  }

  function needsTaintedSoulsObserver() {
    return isMissionAcceptedIncomplete(kingChatState.progressTaintedSouls);
  }

  // Tile 47 in Dragon Lair (The Dragonmother) — right-click menu with Descend (requires Dragon Claw)
  function hasDragonClawForStairs() {
    return getCachedQuestItemCount(getDragonClawProductName()) > 0;
  }

  function closeTile47LonesomeDragonContextMenu() {
    if (tile47LonesomeDragonContextMenu && tile47LonesomeDragonContextMenu.closeMenu) {
      tile47LonesomeDragonContextMenu.closeMenu();
    }
    tile47LonesomeDragonContextMenu = null;
  }

  function enterLonesomeDragonFromStairs() {
    const roomId = getRoomIdByRoomName(LONESOME_DRAGON_ROOM_NAME);
    if (!roomId) {
      showToast({ message: TOAST_MESSAGES.lonesomeDragonNotFound, logPrefix: BATTLE_TOAST_LOG.lonesomeDragon });
      return;
    }
    console.log('[Quests Mod][Lonesome Dragon] Descending stairs — roomId:', roomId);

    playerUsedTile47ToLonesomeDragon = true;
    if (lonesomeDragonBattle) {
      lonesomeDragonBattle.cleanup(restoreBoardSetupLonesomeDragon, showQuestOverlays);
      lonesomeDragonBattle = null;
    }

    const initResult = initializeLonesomeDragonBattle(roomId);
    if (initResult && initResult.then) {
      initResult.then((battle) => {
        if (setupLonesomeDragonBattleInstance(battle)) {
          console.log('[Quests Mod][Lonesome Dragon] Battle initialized (async); scheduling Demodras entry setup', roomId);
        } else {
          console.error('[Quests Mod][Lonesome Dragon] Failed to initialize battle after waiting');
        }
      }).catch((err) => console.error('[Quests Mod][Lonesome Dragon] Error initializing battle:', err));
    } else if (setupLonesomeDragonBattleInstance(initResult)) {
      console.log('[Quests Mod][Lonesome Dragon] Battle initialized (sync); scheduling Demodras entry setup', roomId);
    } else {
      console.error('[Quests Mod][Lonesome Dragon] CustomBattles not available');
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId: roomId });
    showToast({ message: TOAST_MESSAGES.enteringLonesomeDragon, logPrefix: BATTLE_TOAST_LOG.lonesomeDragon });
  }

  function createTile47LonesomeDragonContextMenu(x, y, anchorElement = null) {
    closeTile47LonesomeDragonContextMenu();

    tile47LonesomeDragonContextMenu = createContextMenu({
      x,
      y,
      layout: 'center',
      logPrefix: '[Quests Mod][Lonesome Dragon]',
      anchorElement: anchorElement || getTileElement(DRAGON_LAIR_STAIRS_TILE_47),
      buttons: [
        {
          text: 'Descend',
          width: '120px',
          backgroundColor: '#2a4a2a',
          color: '#4CAF50',
          border: '1px solid #4CAF50',
          hoverBackgroundColor: '#1a2a1a',
          hoverBorderColor: '#66BB6A',
          onClick: () => {
            closeTile47LonesomeDragonContextMenu();
            enterLonesomeDragonFromStairs();
          }
        }
      ],
      onClose: () => {
        tile47LonesomeDragonContextMenu = null;
      }
    });

    return tile47LonesomeDragonContextMenu;
  }

  async function handleTile47LonesomeDragonRightClickDocument(event) {
    const progress = kingChatState.progressDragonmother;
    if (progress?.completed) return;
    if (!isOnRoomByName(DRAGON_LAIR_ROOM_NAME)) return;

    const tile47El = getTileElement(DRAGON_LAIR_STAIRS_TILE_47);
    if (!tile47El || !tile47El.contains(event.target)) return;

    event.preventDefault();
    event.stopImmediatePropagation();
    event.stopPropagation();

    let hasClaw = hasDragonClawForStairs();
    if (!hasClaw) {
      try {
        const questItems = await getQuestItems(false);
        hasClaw = (questItems?.[getDragonClawProductName()] || 0) > 0;
      } catch (_) { /* ignore */ }
    }
    if (!hasClaw) {
      showToast({ message: TOAST_MESSAGES.needDragonClawForStairs, logPrefix: BATTLE_TOAST_LOG.lonesomeDragon });
      return;
    }

    createTile47LonesomeDragonContextMenu(event.clientX, event.clientY, tile47El);
  }

  function shouldEnableTile47LonesomeDragon(boardContext = null) {
    const progress = kingChatState.progressDragonmother;
    if (progress?.completed) return false;
    if (!hasDragonClawForStairs()) return false;
    return isOnRoomByName(DRAGON_LAIR_ROOM_NAME);
  }

  function shouldEnableTile47LonesomeDragonListener(boardContext = null) {
    const progress = kingChatState.progressDragonmother;
    if (progress?.completed) return false;
    return !isOnRoomByName(LONESOME_DRAGON_ROOM_NAME);
  }

  function updateTile47LonesomeDragonState(boardContext = null, retryCount = 0) {
    try {
      const listenerShouldBeOn = shouldEnableTile47LonesomeDragonListener(boardContext);
      const pointerEventsShouldBeOn = shouldEnableTile47LonesomeDragon(boardContext);
      const tile47El = getTileElement(DRAGON_LAIR_STAIRS_TILE_47);
      if (listenerShouldBeOn && !tile47LonesomeDragonRightClickEnabled) {
        document.addEventListener('contextmenu', handleTile47LonesomeDragonRightClickDocument, true);
        tile47LonesomeDragonRightClickEnabled = true;
      }
      if (!listenerShouldBeOn && tile47LonesomeDragonRightClickEnabled) {
        document.removeEventListener('contextmenu', handleTile47LonesomeDragonRightClickDocument, true);
        const el = getTileElement(DRAGON_LAIR_STAIRS_TILE_47);
        if (el) el.style.pointerEvents = '';
        tile47LonesomeDragonRightClickEnabled = false;
        closeTile47LonesomeDragonContextMenu();
        console.log('[Quests Mod][Tile 47 Lonesome Dragon] Right-click disabled');
        return;
      }
      if (pointerEventsShouldBeOn && tile47El) {
        tile47El.style.pointerEvents = 'auto';
        if (retryCount === 0) console.log('[Quests Mod][Tile 47 Lonesome Dragon] Right-click enabled on Dragon Lair');
      } else if (pointerEventsShouldBeOn && !tile47El && retryCount < 5) {
        setTimeout(() => updateTile47LonesomeDragonState(boardContext || globalThis.state?.board?.getSnapshot?.()?.context, retryCount + 1), 200);
      } else if (!pointerEventsShouldBeOn && tile47El) {
        tile47El.style.pointerEvents = '';
      }
    } catch (e) {
      console.error('[Quests Mod][Tile 47 Lonesome Dragon] Error updating right-click state:', e);
    }
  }

  function setupTile47LonesomeDragonObserver() {
    if (tile47LonesomeDragonBoardSubscription) return;
    if (typeof globalThis === 'undefined' || !globalThis.state?.board?.subscribe) return;
    tile47LonesomeDragonBoardSubscription = globalThis.state.board.subscribe(({ context: boardContext }) => {
      updateTile47LonesomeDragonState(boardContext);
    });
    updateTile47LonesomeDragonState(globalThis.state?.board?.getSnapshot()?.context);
    console.log(`[Quests Mod][Tile 47 Lonesome Dragon] Board observer set up for ${DRAGON_LAIR_ROOM_NAME || '(room pending)'}`);
  }

  function cleanupTile47LonesomeDragonObserver() {
    if (tile47LonesomeDragonBoardSubscription) {
      try {
        tile47LonesomeDragonBoardSubscription.unsubscribe();
      } catch (e) {
        console.warn('[Quests Mod][Tile 47 Lonesome Dragon] Error unsubscribing from board:', e);
      }
      tile47LonesomeDragonBoardSubscription = null;
    }
  }

  function cleanupTile47LonesomeDragonSystem() {
    closeTile47LonesomeDragonContextMenu();
    if (tile47LonesomeDragonRightClickEnabled) {
      document.removeEventListener('contextmenu', handleTile47LonesomeDragonRightClickDocument, true);
      const tile47El = getTileElement(DRAGON_LAIR_STAIRS_TILE_47);
      if (tile47El) tile47El.style.pointerEvents = '';
      tile47LonesomeDragonRightClickEnabled = false;
    }
    cleanupTile47LonesomeDragonObserver();
    try {
      cleanupLonesomeDragonQuest();
    } catch (e) {
      console.warn('[Quests Mod][Tile 47 Lonesome Dragon] cleanupLonesomeDragonQuest during teardown:', e);
    }
    console.log('[Quests Mod][Tile 47 Lonesome Dragon] System cleaned up');
  }

  // ============================================================
  // The Rookie Guard (Al Dee): portal on tile 109 in Katana Quest → Sewers (Knarknaknork)
  // ============================================================
  function getRookieGuardLogPrefix() {
    return '[Quests Mod][The Rookie Guard]';
  }

  function createSewersBattleInstance(roomId) {
    if (!window.CustomBattles) {
      console.error(`${getRookieGuardLogPrefix()} CustomBattles still not available`);
      return null;
    }
    const spawn = getHydratedQuestBattleSpawn(SEWERS_BATTLE_ID || 'sewers');
    const villains = spawn.villains;
    const tileRestrictions = {};
    if (spawn.allowedTiles?.length) {
      tileRestrictions.allowedTiles = spawn.allowedTiles;
      tileRestrictions.message = spawn.allowedTilesMessage || 'Ally creatures can only be placed on the marked tiles!';
    }
    const config = {
      name: SEWERS_BATTLE_DISPLAY_NAME || 'Knarknaknork',
      roomId,
      villains,
      // Non-removable custom ally auto-placed during entry setup (e.g. Rookstayer).
      allies: spawn.allies,
      allyLimit: spawn.allyLimit ?? 3,
      preventVillainMovement: spawn.preventVillainMovement !== false,
      hideVillainSprites: spawn.hideVillainSprites !== false,
      ...(Object.keys(tileRestrictions).length ? { tileRestrictions } : {}),
      activationCheck: (isSandbox, inBattleArea) => {
        return isSandbox && inBattleArea && playerEnteredSewersPortal;
      },
      victoryDefeat: {
        onVictory: async () => {
          console.log(`${getRookieGuardLogPrefix()} Knarknaknork defeated!`);
          try {
            await persistMissionProgress(AL_DEE_ROOKIE_GUARD_MISSION, {
              accepted: true,
              completed: false,
              battleCompleted: true
            });
          } catch (error) {
            console.error(`${getRookieGuardLogPrefix()} Error saving battleCompleted flag:`, error);
          }
        },
        onDefeat: () => {},
        onClose: () => {
          cleanupSewersQuest();
          setTimeout(() => navigateToKatanaQuest(), 100);
        },
        victoryTitle: 'Victory!',
        defeatTitle: 'Defeat',
        victoryMessage: getMissionDialogueLine(
          AL_DEE_ROOKIE_GUARD_MISSION,
          'battleVictory',
          "Whatever it was, it's dead now. No Sword of Fury out there after all — but return to Al Dee with the news."
        ),
        defeatMessage: getMissionDialogueLine(
          AL_DEE_ROOKIE_GUARD_MISSION,
          'battleDefeat',
          "Knarknaknork proved you weren't humble enough today."
        ),
        showItems: false,
        items: []
      }
    };
    return window.CustomBattles.create(config);
  }

  function initializeSewersBattle(roomId) {
    if (window.CustomBattles) {
      return createSewersBattleInstance(roomId);
    }
    return waitForCustomBattles({ logPrefix: getRookieGuardLogPrefix() }).then((api) => {
      if (!api) return null;
      return createSewersBattleInstance(roomId);
    });
  }

  function formatSewersMutationOffsetCalc(px) {
    const value = Number(px);
    if (!Number.isFinite(value) || value === 0) return '';
    const sign = value < 0 ? '-' : '';
    return `calc(${sign}${Math.abs(value)}px * var(--zoomFactor))`;
  }

  function buildSewersMutationSpriteHTML(entry, mutationKey) {
    const spriteId = entry?.spriteId;
    if (spriteId == null) return '';
    const cropX = entry.cropX != null ? entry.cropX : 0;
    const cropY = entry.cropY != null ? entry.cropY : 0;
    const cropped = entry.cropped ? 'true' : 'false';
    const bankStyle = entry.bank != null ? ` --bank: ${entry.bank};` : '';
    // Map Editor layer offsets (e.g. a torch flame nudged off its base sprite) — same
    // right/bottom calc() the editor itself uses (Map_Editor.js applySpritePlacementToElement).
    const rightCalc = formatSewersMutationOffsetCalc(entry.offsetX);
    const bottomCalc = formatSewersMutationOffsetCalc(entry.offsetY);
    const offsetStyle = `${rightCalc ? ` right: ${rightCalc};` : ''}${bottomCalc ? ` bottom: ${bottomCalc};` : ''}`;
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_SEWERS}="1" data-quests-sewers-mutation-key="${mutationKey}" style="z-index: 1000;${bankStyle}${offsetStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
  }

  function applySewersTileMutations() {
    const mutations = SEWERS_TILE_MUTATIONS;
    if (!mutations || typeof mutations !== 'object') return;

    const battle = sewersBattle;
    const hadMask = battle?._placementHitboxMaskActive === true;
    if (hadMask) battle.restorePlacementHitboxes?.();

    let wroteHitboxes = false;
    Object.entries(mutations).forEach(([tileKey, entry]) => {
      const tileIndex = Number(tileKey);
      if (!Number.isFinite(tileIndex) || !entry || typeof entry !== 'object') return;
      const tile = getTileElement(tileIndex);

      (entry.remove || []).forEach((spriteId) => {
        if (spriteId == null || !tile) return;
        tile.querySelectorAll(`.sprite.item.relative.id-${spriteId}`).forEach((sprite) => {
          hideQuestBoardElement(sprite, { tag: QUEST_BOARD_HIDDEN_TAG_SEWERS });
        });
      });

      // Keyed by tile+position (not by sprite id class), so a retry pass can't mistake
      // an already-placed sprite for missing and stack a duplicate on top of it.
      (entry.add || []).forEach((spriteEntry, spriteIndex) => {
        const spriteId = spriteEntry?.spriteId;
        if (spriteId == null || !tile) return;
        const mutationKey = `${tileIndex}-${spriteIndex}`;
        if (tile.querySelector(`[data-quests-sewers-mutation-key="${mutationKey}"]`)) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = buildSewersMutationSpriteHTML(spriteEntry, mutationKey);
        if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
      });

      if (Object.prototype.hasOwnProperty.call(entry, 'hitbox')) {
        try {
          const roomId = SEWERS_BATTLE_ROOM_ID;
          const selected = globalThis.state?.board?.getSnapshot?.()?.context?.selectedMap?.selectedRoom
            || globalThis.state?.selectedMap?.selectedRoom;
          const utils = globalThis.state?.utils;
          const roomRefs = [];
          if (selected?.id === roomId) roomRefs.push(selected);
          if (Array.isArray(utils?.ROOMS)) {
            utils.ROOMS.forEach((room) => {
              if (room?.id === roomId) roomRefs.push(room);
            });
          }
          if (Array.isArray(utils?.REGIONS)) {
            utils.REGIONS.forEach((region) => {
              (region?.rooms || []).forEach((room) => {
                if (room?.id === roomId) roomRefs.push(room);
              });
            });
          }
          roomRefs.forEach((room) => {
            const data = room?.file?.data;
            if (!data) return;
            if (!Array.isArray(data.hitboxes)) data.hitboxes = [];
            data.hitboxes[tileIndex] = entry.hitbox === true;
            wroteHitboxes = true;
          });
        } catch (_) {}
      }
    });

    if (wroteHitboxes) sewersHitboxesApplied = true;

    if (battle?.refreshPlacementHitboxMaskFromLive) {
      battle.refreshPlacementHitboxMaskFromLive(
        () => playerEnteredSewersPortal
      );
    } else if (battle?.syncPlacementHitboxMask) {
      battle.syncPlacementHitboxMask(() => playerEnteredSewersPortal);
    }
  }

  function restoreSewersTileMutations() {
    restoreQuestBoardElementsByTag(QUEST_BOARD_HIDDEN_TAG_SEWERS);
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_SEWERS}="1"]`).forEach((el) => {
      try { el.remove(); } catch (_) {}
    });
    sewersHitboxesApplied = false;
  }

  const SEWERS_VISUAL_RETRY_DELAYS_MS = [0, 50, 150, 300, 500, 800, 1200, 2000];

  function clearSewersVisualRetries() {
    sewersVisualRetryTimers.forEach((id) => clearTimeout(id));
    sewersVisualRetryTimers = [];
  }

  // No live recolor pass needed — tileMutations bake the final sprite (e.g. 4609)
  // directly, same as Ekatrix's own tile mutations do. Just place them.
  function applySewersBattlefieldVisuals() {
    if (!playerEnteredSewersPortal || !sewersBattle) return;
    applySewersTileMutations();
  }

  function scheduleSewersBattlefieldVisuals() {
    clearSewersVisualRetries();
    applySewersBattlefieldVisuals();
    SEWERS_VISUAL_RETRY_DELAYS_MS.forEach((delay) => {
      if (delay <= 0) return;
      sewersVisualRetryTimers.push(setTimeout(() => {
        applySewersBattlefieldVisuals();
      }, delay));
    });
  }

  function restoreBoardSetupSewers() {
    if (sewersBattle) {
      sewersBattle.restoreBoardSetup();
    }
    restoreSewersTileMutations();
  }

  function cleanupSewersQuest() {
    try {
      removeCustomBattleStatusToast();
      knarknaknorkBossHpBar.remove();
      clearSewersVisualRetries();
      playerEnteredSewersPortal = false;
      restoreSewersTileMutations();
      if (sewersBattle) {
        sewersBattle.cleanup(restoreBoardSetupSewers, showQuestOverlays);
        sewersBattle = null;
        console.log(`${getRookieGuardLogPrefix()} Battle cleaned up`);
      }
    } catch (error) {
      console.error(`${getRookieGuardLogPrefix()} Error cleaning up:`, error);
    }
  }

  function setupSewersTileRestrictions() {
    if (!sewersBattle) return;
    sewersBattle.setupTileRestrictions(
      () => playerEnteredSewersPortal,
      NotificationService.createBattleToastCallback(getRookieGuardLogPrefix())
    );
    sewersBattle.setupAllyLimit?.(
      () => playerEnteredSewersPortal,
      NotificationService.createBattleToastCallback(getRookieGuardLogPrefix())
    );
  }

  function navigateToKatanaQuest() {
    try {
      const roomId = getRoomIdByRoomName(KATANA_QUEST_ROOM_NAME);
      if (!roomId) {
        console.warn(`${getRookieGuardLogPrefix()} Katana Quest room not found`);
        return;
      }
      globalThis.state.board.send({ type: 'selectRoomById', roomId });
    } catch (error) {
      console.error(`${getRookieGuardLogPrefix()} Error navigating to Katana Quest:`, error);
    }
  }

  function setupSewersBattleInstance(battle) {
    if (!battle) return false;
    sewersBattle = battle;
    sewersBattle.setup(
      () => playerEnteredSewersPortal,
      NotificationService.createBattleToastCallback(getRookieGuardLogPrefix())
    );
    sewersBattle.resetSandboxBattleState();
    setupSewersTileRestrictions();
    showCustomBattleStatusToast({
      battleName: SEWERS_BATTLE_DISPLAY_NAME || 'Knarknaknork',
      allyLimit: battle.config?.allyLimit ?? 3,
      battle,
      logPrefix: getRookieGuardLogPrefix()
    });
    // Puts the board into sandbox mode (required for activationCheck's isSandbox check)
    // and spawns the custom villains onto the room tiles, with retries for remounts.
    sewersBattle.scheduleEntryVillainSetup({
      attemptDelays: [0, 100, 250, 500, 800, 1200],
      isActiveCheck: () => playerEnteredSewersPortal,
      onComplete: () => {
        hideQuestOverlays();
        hideHeroEditorButton();
        // Tile mutations (decor swap) are a separate system from villain placement —
        // they don't apply automatically from the create() config alone, so trigger
        // them explicitly here, with retries in case the room DOM remounts right
        // after navigation.
        scheduleSewersBattlefieldVisuals();
      }
    });
    return true;
  }

  function enterSewersPortal() {
    let roomId = SEWERS_BATTLE_ROOM_ID || getRoomIdByRoomName(SEWERS_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(SEWERS_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'The sewers could not be found.', logPrefix: getRookieGuardLogPrefix() });
      return;
    }

    playerEnteredSewersPortal = true;
    swordOfFurySignReader.resetRead();
    if (sewersBattle) {
      sewersBattle.cleanup(restoreBoardSetupSewers, showQuestOverlays);
      sewersBattle = null;
    }

    const initResult = initializeSewersBattle(roomId);
    if (initResult && initResult.then) {
      initResult.then((battle) => {
        if (!setupSewersBattleInstance(battle)) {
          console.error(`${getRookieGuardLogPrefix()} Failed to initialize battle after waiting`);
        }
      }).catch((err) => console.error(`${getRookieGuardLogPrefix()} Error initializing battle:`, err));
    } else if (!setupSewersBattleInstance(initResult)) {
      console.error(`${getRookieGuardLogPrefix()} CustomBattles not available`);
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    showToast({ message: 'Stepping through the portal...', logPrefix: getRookieGuardLogPrefix() });
  }

  function closeSewersPortalContextMenu() {
    if (sewersPortalContextMenu && sewersPortalContextMenu.closeMenu) {
      sewersPortalContextMenu.closeMenu();
    }
    sewersPortalContextMenu = null;
  }

  function createSewersPortalContextMenu(x, y, anchorElement = null) {
    closeSewersPortalContextMenu();
    sewersPortalContextMenu = createContextMenu({
      x,
      y,
      layout: 'center',
      logPrefix: getRookieGuardLogPrefix(),
      anchorElement: anchorElement || getTileElement(KATANA_QUEST_PORTAL_TILE),
      buttons: [
        {
          text: KATANA_QUEST_PORTAL_CONTEXT_MENU_LABEL || 'Teleport',
          width: '120px',
          backgroundColor: '#2a4a2a',
          color: '#4CAF50',
          border: '1px solid #4CAF50',
          hoverBackgroundColor: '#1a2a1a',
          hoverBorderColor: '#66BB6A',
          onClick: () => {
            closeSewersPortalContextMenu();
            enterSewersPortal();
          }
        }
      ],
      onClose: () => {
        sewersPortalContextMenu = null;
      }
    });
    return sewersPortalContextMenu;
  }

  function handleSewersPortalRightClickDocument(event) {
    if (!shouldEnableSewersPortal()) return;
    const tileEl = getTileElement(KATANA_QUEST_PORTAL_TILE);
    if (!tileEl || !tileEl.contains(event.target)) return;

    event.preventDefault();
    event.stopImmediatePropagation();
    event.stopPropagation();

    createSewersPortalContextMenu(event.clientX, event.clientY, tileEl);
  }

  function shouldEnableSewersPortal(boardContext = null) {
    const progress = getMissionProgress(AL_DEE_ROOKIE_GUARD_MISSION);
    if (!progress?.accepted || progress.completed || progress.battleCompleted) return false;
    return isOnRoomByName(KATANA_QUEST_ROOM_NAME);
  }

  function updateSewersPortalState(boardContext = null, retryCount = 0) {
    try {
      // Piggyback on this same board subscription to keep the battle's tile decor
      // alive across later remounts, not just the initial entry window.
      if (playerEnteredSewersPortal && sewersBattle && isOnRoomByName(SEWERS_BATTLE_ROOM_NAME)) {
        applySewersBattlefieldVisuals();
      }

      const shouldBeEnabled = shouldEnableSewersPortal(boardContext);
      const tileEl = getTileElement(KATANA_QUEST_PORTAL_TILE);
      if (shouldBeEnabled && !sewersPortalRightClickEnabled) {
        document.addEventListener('contextmenu', handleSewersPortalRightClickDocument, true);
        sewersPortalRightClickEnabled = true;
      }
      if (!shouldBeEnabled && sewersPortalRightClickEnabled) {
        document.removeEventListener('contextmenu', handleSewersPortalRightClickDocument, true);
        sewersPortalRightClickEnabled = false;
        const el = getTileElement(KATANA_QUEST_PORTAL_TILE);
        if (el) el.style.pointerEvents = '';
        closeSewersPortalContextMenu();
        return;
      }
      if (shouldBeEnabled && tileEl) {
        tileEl.style.pointerEvents = 'auto';
      } else if (shouldBeEnabled && !tileEl && retryCount < 5) {
        setTimeout(() => updateSewersPortalState(
          boardContext || globalThis.state?.board?.getSnapshot?.()?.context,
          retryCount + 1
        ), 200);
      } else if (!shouldBeEnabled && tileEl) {
        tileEl.style.pointerEvents = '';
      }
    } catch (e) {
      console.error(`${getRookieGuardLogPrefix()} Error updating portal state:`, e);
    }
  }

  function setupSewersPortalObserver() {
    if (sewersPortalBoardSubscription) {
      updateSewersPortalState();
      return;
    }
    if (typeof globalThis === 'undefined' || !globalThis.state?.board?.subscribe) return;
    sewersPortalBoardSubscription = globalThis.state.board.subscribe(({ context: boardContext }) => {
      updateSewersPortalState(boardContext);
    });
    updateSewersPortalState(globalThis.state?.board?.getSnapshot()?.context);
    console.log(`${getRookieGuardLogPrefix()} Board observer set up for ${KATANA_QUEST_ROOM_NAME || '(room pending)'}`);
  }

  function cleanupSewersPortalObserver() {
    if (sewersPortalBoardSubscription) {
      try {
        sewersPortalBoardSubscription.unsubscribe();
      } catch (e) {
        console.warn(`${getRookieGuardLogPrefix()} Error unsubscribing from board:`, e);
      }
      sewersPortalBoardSubscription = null;
    }
  }

  function cleanupSewersPortalSystem() {
    closeSewersPortalContextMenu();
    if (sewersPortalRightClickEnabled) {
      document.removeEventListener('contextmenu', handleSewersPortalRightClickDocument, true);
      const tileEl = getTileElement(KATANA_QUEST_PORTAL_TILE);
      if (tileEl) tileEl.style.pointerEvents = '';
      sewersPortalRightClickEnabled = false;
    }
    cleanupSewersPortalObserver();
    try {
      cleanupSewersQuest();
    } catch (e) {
      console.warn(`${getRookieGuardLogPrefix()} cleanupSewersQuest during teardown:`, e);
    }
    console.log(`${getRookieGuardLogPrefix()} System cleaned up`);
  }

  // =======================
  // Hellgate Part 1 (Elathriel — chat-triggered teleport into the Fire Elemental
  // battle in Sewers. Reuses the same room as Knarknaknork/Ekatrix/Spider Lair;
  // each battle's own activationCheck flag keeps them from colliding.)
  // =======================

  function getHellgateLogPrefix() {
    return '[Quests Mod][Hellgate Part 1]';
  }

  function createHellgateBattleInstance(roomId) {
    if (!window.CustomBattles) {
      console.error(`${getHellgateLogPrefix()} CustomBattles still not available`);
      return null;
    }
    const spawn = getHydratedQuestBattleSpawn(HELLGATE_BATTLE_ID || 'hellgate_treasure_room');
    const villains = spawn.villains;
    const tileRestrictions = {};
    if (spawn.allowedTiles?.length) {
      tileRestrictions.allowedTiles = spawn.allowedTiles;
      tileRestrictions.message = spawn.allowedTilesMessage || 'Ally creatures can only be placed on the marked tiles!';
    }
    const config = {
      name: HELLGATE_BATTLE_DISPLAY_NAME || 'Hellgate Treasure Room',
      roomId,
      villains,
      allyLimit: spawn.allyLimit ?? 5,
      preventVillainMovement: spawn.preventVillainMovement !== false,
      hideVillainSprites: spawn.hideVillainSprites !== false,
      ...(Object.keys(tileRestrictions).length ? { tileRestrictions } : {}),
      activationCheck: (isSandbox, inBattleArea) => {
        return isSandbox && inBattleArea && playerFollowedElathrielToHellgate;
      },
      victoryDefeat: {
        onVictory: async () => {
          console.log(`${getHellgateLogPrefix()} Fire Elementals defeated!`);
          // Reward (Beware of the Bonelords (Book)) is handed over by Elathriel in person,
          // not granted automatically here — see isHellgateBattleCompletedPendingReward()/
          // completeHellgatePart1MissionWithBook(), delivered from the Elathriel chat handler
          // once the player speaks to him again. Only the battleCompleted flag is persisted now.
          try {
            await persistMissionProgress(HELLGATE_PART_1_MISSION, {
              accepted: true,
              completed: false,
              battleCompleted: true
            });
          } catch (error) {
            console.error(`${getHellgateLogPrefix()} Error saving battleCompleted flag:`, error);
          }
        },
        onDefeat: () => {},
        onClose: () => {
          cleanupHellgateTreasureRoomQuest();
          setTimeout(() => navigateToHedgeMazeFromHellgate(), 100);
        },
        victoryTitle: 'Victory!',
        defeatTitle: 'Defeat',
        victoryMessage: getMissionDialogueLine(
          HELLGATE_PART_1_MISSION,
          'battleVictory',
          'The treasure room is cleared. Return to Elathriel.'
        ),
        defeatMessage: getMissionDialogueLine(
          HELLGATE_PART_1_MISSION,
          'battleDefeat',
          'Whatever guards that treasure was not so easily bested.'
        ),
        showItems: false,
        items: []
      }
    };
    return window.CustomBattles.create(config);
  }

  // Same pattern as isApprenticeShengBattleCompletedPendingReward/isLostOracleBattleCompletedPendingThanks:
  // victory only sets battleCompleted, the actual reward is handed over on the next
  // conversation with the quest's own NPC.
  function isHellgateBattleCompletedPendingReward() {
    const progress = getMissionProgress(HELLGATE_PART_1_MISSION);
    return !!progress?.battleCompleted && !progress?.completed;
  }

  async function completeHellgatePart1MissionWithBook() {
    const progress = getMissionProgress(HELLGATE_PART_1_MISSION);
    if (progress?.completed) return false;
    try {
      await addQuestItem('Beware of the Bonelords (Book)', 1);
      showQuestItemNotification('Beware of the Bonelords (Book)', 1);
      await persistMissionProgress(HELLGATE_PART_1_MISSION, {
        accepted: true,
        completed: true,
        battleCompleted: true
      });
      NotificationService.showQuestCompleted(HELLGATE_PART_1_MISSION, getHellgateLogPrefix(), {
        productName: 'Beware of the Bonelords (Book)'
      });
      console.log(`${getHellgateLogPrefix()} Mission completed — Beware of the Bonelords (Book) awarded`);
      return true;
    } catch (error) {
      console.error(`${getHellgateLogPrefix()} Error completing mission with book reward:`, error);
      return false;
    }
  }

  function initializeHellgateBattle(roomId) {
    if (window.CustomBattles) {
      return createHellgateBattleInstance(roomId);
    }
    return waitForCustomBattles({ logPrefix: getHellgateLogPrefix() }).then((api) => {
      if (!api) return null;
      return createHellgateBattleInstance(roomId);
    });
  }

  function formatHellgateMutationOffsetCalc(px) {
    const value = Number(px);
    if (!Number.isFinite(value) || value === 0) return '';
    const sign = value < 0 ? '-' : '';
    return `calc(${sign}${Math.abs(value)}px * var(--zoomFactor))`;
  }

  const HELLGATE_ELATHRIEL_DUMMY_TILE_INDEX = 157;
  const HELLGATE_ELATHRIEL_DUMMY_ATTR = 'data-quests-hellgate-elathriel-dummy';

  // Elathriel "follows" the player into the treasure room narratively, so a purely
  // decorative (non-interactive) copy of him stands on tile 157 for the whole battle.
  // Deliberately NOT a real Board NPC placement (shouldPlaceBoardNpc refuses to place
  // any Board NPC while a battle is active) and NOT a forced combat ally (no fight/death
  // interaction wanted — just a visual). Reuses the same outfit-sprite markup
  // placeBoardNpcOverlay renders for him on the map, minus every interactive bit, and is
  // tagged with QUEST_BOARD_ADDED_ATTR_HELLGATE so restoreHellgateTileMutations() tears
  // it down automatically along with every other decorative sprite in this room.
  const HELLGATE_ELATHRIEL_DUMMY_NAME_TAG_CLASS = 'quests-hellgate-elathriel-dummy-name-tag';

  // Name label above the dummy — same nameplate positioning trick as the real Board NPC
  // system (positionBoardNpcNameTag): parented onto the tile's own parent (not the tile
  // itself) and offset up by one tile height off the tile's *live* right/bottom, since
  // that's what keeps it correctly aligned across zoom/board re-renders. Built once and
  // repositioned on every call rather than rebuilt, so remounts don't stack duplicates.
  function ensureHellgateElathrielDummyNameTag(tileElement) {
    let nameTag = document.querySelector(`.${HELLGATE_ELATHRIEL_DUMMY_NAME_TAG_CLASS}`);
    if (!nameTag) {
      nameTag = document.createElement('span');
      nameTag.className = `${HELLGATE_ELATHRIEL_DUMMY_NAME_TAG_CLASS} revert-pixel-font-spacing pointer-events-none absolute flex w-[192px] flex-col items-center`;
      nameTag.style.cssText = [
        'position:absolute',
        'user-select:none',
        `z-index:${QUEST_FIGHT_ICON_Z_INDEX}`,
        'pointer-events:none',
        'line-height:1'
      ].join(';');
      nameTag.setAttribute(QUEST_BOARD_ADDED_ATTR_HELLGATE, '1');

      const nameLine = document.createElement('span');
      nameLine.setAttribute('translate', 'no');
      nameLine.className = 'select-none text-center pixel-font-16 text-whiteHighlight';
      nameLine.style.cssText = 'line-height:1;font-size:16px;display:inline-flex;align-items:center;';

      const nameText = document.createElement('span');
      nameText.className = 'text-whiteHighlight';
      nameText.style.cssText = 'color:rgb(96, 192, 96);text-shadow:-1px 0 #000,1px 0 #000,0 -1px #000,0 1px #000;';
      nameText.textContent = 'Elathriel';

      nameLine.appendChild(nameText);
      nameTag.appendChild(nameLine);
    }
    positionBoardNpcNameTag(nameTag, tileElement);
  }

  function ensureHellgateElathrielDummy() {
    const tile = getTileElement(HELLGATE_ELATHRIEL_DUMMY_TILE_INDEX);
    if (!tile) return;
    if (!tile.querySelector(`[${HELLGATE_ELATHRIEL_DUMMY_ATTR}="1"]`)) {
      const outfitSpriteId = ELATHRIEL_OUTFIT_SPRITE_ID || '64';
      const wrap = document.createElement('div');
      wrap.innerHTML = `<div class="sprite outfit id-${outfitSpriteId} idle north pointer-events-none absolute bottom-0 right-0 select-none" ${QUEST_BOARD_ADDED_ATTR_HELLGATE}="1" ${HELLGATE_ELATHRIEL_DUMMY_ATTR}="1" style="z-index: 1000;"><div class="viewport"><img alt="north" class="actor spritesheet" data-shiny="false" style="animation-play-state: running;"></div></div>`;
      if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
    }
    ensureHellgateElathrielDummyNameTag(tile);
  }

  function buildHellgateMutationSpriteHTML(entry, mutationKey) {
    const spriteId = entry?.spriteId;
    if (spriteId == null) return '';
    const cropX = entry.cropX != null ? entry.cropX : 0;
    const cropY = entry.cropY != null ? entry.cropY : 0;
    const cropped = entry.cropped ? 'true' : 'false';
    const bankStyle = entry.bank != null ? ` --bank: ${entry.bank};` : '';
    const rightCalc = formatHellgateMutationOffsetCalc(entry.offsetX);
    const bottomCalc = formatHellgateMutationOffsetCalc(entry.offsetY);
    const offsetStyle = `${rightCalc ? ` right: ${rightCalc};` : ''}${bottomCalc ? ` bottom: ${bottomCalc};` : ''}`;
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_HELLGATE}="1" data-quests-hellgate-mutation-key="${mutationKey}" style="z-index: 1000;${bankStyle}${offsetStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
  }

  // rkswrs (native "Sewers") is shared by Sewers/Knarknaknork, Spider Lair, Ekatrix,
  // Jakundaf, and now this quest — five separate battle instances can all target the
  // same room. Extracted (mirrors getSpiderLairRoomRefs) so the hitbox-mutation writer
  // and every diagnostic below look up the live room object the same way.
  function getHellgateRoomRefs() {
    const roomId = HELLGATE_BATTLE_ROOM_ID;
    const selected = globalThis.state?.board?.getSnapshot?.()?.context?.selectedMap?.selectedRoom
      || globalThis.state?.selectedMap?.selectedRoom;
    const utils = globalThis.state?.utils;
    const roomRefs = [];
    if (selected?.id === roomId) roomRefs.push(selected);
    if (Array.isArray(utils?.ROOMS)) {
      utils.ROOMS.forEach((room) => {
        if (room?.id === roomId) roomRefs.push(room);
      });
    }
    if (Array.isArray(utils?.REGIONS)) {
      utils.REGIONS.forEach((region) => {
        (region?.rooms || []).forEach((room) => {
          if (room?.id === roomId) roomRefs.push(room);
        });
      });
    }
    return roomRefs;
  }

  // The full set of 165 tiles' intended-walkable ("hitbox: false") state per rooms.json's
  // hellgateTreasureRoom.tileMutations (48 tiles — the 7 villain-spawn tiles plus the
  // 30-tile allowedTiles ally-placement zone plus a handful of extra walkable-but-not-
  // placeable floor tiles). Anything in this list that reads `true` at runtime has been
  // flipped from its intended value. Computed directly from rooms.json, same derivation as
  // SPIDER_LAIR_WALKABLE_TILES/MORNENION_WALKABLE_TILES.
  const HELLGATE_WALKABLE_TILES = [
    34, 37, 40, 49, 52, 55, 94, 95, 96, 97, 98, 99, 100, 106, 107, 108, 109, 110, 111, 112,
    113, 114, 115, 116, 117, 118, 121, 122, 123, 124, 125, 128, 129, 130, 131, 132, 133,
    136, 137, 138, 139, 140, 143, 144, 145, 146, 147, 148
  ];

  // Safety net, not a debug trace — same reasoning as checkSpiderLairHitboxIntegrity: only
  // prints when a tile that's supposed to be walkable is actually reading as blocked.
  function checkHellgateHitboxIntegrity(label) {
    try {
      // While the pre-battle placement mask is active, CustomBattles' own
      // applyPlacementHitboxMask() deliberately blocks every walkable tile outside
      // allowedTiles (+ villain tiles) — that's the ally-placement-restriction feature
      // working as intended, not corruption. Only compare once the mask is lifted.
      if (hellgateBattle?._placementHitboxMaskActive === true) return;

      const roomRefs = getHellgateRoomRefs();
      const hitboxes = roomRefs.find((room) => Array.isArray(room?.file?.data?.hitboxes))?.file?.data?.hitboxes || null;
      if (!Array.isArray(hitboxes)) return;

      const corruptedWalkableTiles = HELLGATE_WALKABLE_TILES.filter((i) => hitboxes[i] === true);
      if (!corruptedWalkableTiles.length) return;

      console.warn(`[Quests Mod][Hellgate Part 1][hitbox-check] ${label}: ${corruptedWalkableTiles.length} walkable tile(s) reading as blocked`, {
        corruptedWalkableTiles,
        blockedCount: hitboxes.filter((v) => v === true).length,
        placementHitboxMaskActive: hellgateBattle?._placementHitboxMaskActive === true
      });
    } catch (error) {
      console.error('[Quests Mod][Hellgate Part 1][hitbox-check] Error checking hitbox integrity:', error);
    }
  }

  // Prints every tile's live hitbox state (ALLOWED = walkable, BLOCKED = blocked) plus a
  // phase-aware mismatch table against HELLGATE_TILE_MUTATIONS — mirrors
  // logSpiderLairHitboxTable. While the placement mask is active the expected value is
  // derived the same way the mask itself derives it (allowedTiles ∪ villain-occupied ⇒
  // open, everything else ⇒ blocked); once combat starts, expected reverts to the raw
  // tileMutations value.
  function logHellgateHitboxTable(label) {
    try {
      const mutations = HELLGATE_TILE_MUTATIONS;
      if (!mutations || typeof mutations !== 'object') return;
      const roomRefs = getHellgateRoomRefs();
      const liveHitboxes = roomRefs.find((room) => Array.isArray(room?.file?.data?.hitboxes))?.file?.data?.hitboxes || null;

      const battle = hellgateBattle;
      const maskActive = battle?._placementHitboxMaskActive === true;
      let maskWalkableTiles = null;
      if (maskActive) {
        maskWalkableTiles = new Set(battle?.config?.tileRestrictions?.allowedTiles || []);
        (battle?.getVillainOccupiedTiles?.() || []).forEach((t) => {
          const n = Number(t);
          if (Number.isFinite(n)) maskWalkableTiles.add(n);
        });
        (battle?.getForcedAllyOccupiedTiles?.() || []).forEach((t) => {
          const n = Number(t);
          if (Number.isFinite(n)) maskWalkableTiles.add(n);
        });
      }

      const rows = [];
      let mismatchCount = 0;
      for (let tileIndex = 0; tileIndex <= 164; tileIndex += 1) {
        const entry = mutations[String(tileIndex)];
        const rawExpected = entry && Object.prototype.hasOwnProperty.call(entry, 'hitbox')
          ? entry.hitbox === true
          : null;
        const expected = maskActive && maskWalkableTiles
          ? !maskWalkableTiles.has(tileIndex)
          : rawExpected;
        const actual = Array.isArray(liveHitboxes) ? liveHitboxes[tileIndex] === true : null;
        const match = expected === actual;
        if (!match) mismatchCount += 1;
        rows.push({ tile: tileIndex, expectedBlocked: expected, liveBlocked: actual, rawCombatExpected: rawExpected, match });
      }

      const liveAllowedTiles = [];
      const liveBlockedTiles = [];
      if (Array.isArray(liveHitboxes)) {
        for (let tileIndex = 0; tileIndex <= 164; tileIndex += 1) {
          if (liveHitboxes[tileIndex] === true) liveBlockedTiles.push(tileIndex);
          else liveAllowedTiles.push(tileIndex);
        }
      }

      const context = {
        placementHitboxMaskActive: maskActive,
        isBoardBattleActive: battle?.isBoardBattleActive?.() === true,
        liveHitboxesArrayLength: Array.isArray(liveHitboxes) ? liveHitboxes.length : null,
        roomRefsFound: roomRefs.length
      };

      const phaseLabel = maskActive ? 'PRE-BATTLE (placement mask active)' : (context.isBoardBattleActive ? 'BATTLE (combat active)' : 'PRE-BATTLE (no mask)');
      console.log(`[Quests Mod][Hellgate Part 1][hitbox-tiles] ${label} — phase: ${phaseLabel}`, context);
      console.log(`[Quests Mod][Hellgate Part 1][hitbox-tiles] ALLOWED (${liveAllowedTiles.length}):`, liveAllowedTiles);
      console.log(`[Quests Mod][Hellgate Part 1][hitbox-tiles] BLOCKED (${liveBlockedTiles.length}):`, liveBlockedTiles);

      if (mismatchCount === 0) {
        console.log(`[Quests Mod][Hellgate Part 1][hitbox-table] ${label}: all 165 tiles match expected hitbox values for current phase`, context);
        return;
      }

      console.warn(`[Quests Mod][Hellgate Part 1][hitbox-table] ${label}: ${mismatchCount}/165 tile(s) mismatch expected hitbox values for current phase`, context);
      if (typeof console.table === 'function') {
        console.table(rows.filter((r) => !r.match));
      } else {
        console.log(rows.filter((r) => !r.match));
      }
    } catch (error) {
      console.error('[Quests Mod][Hellgate Part 1][hitbox-table] Error building hitbox comparison table:', error);
    }
  }

  // rkswrs is shared by 5 quests now (Sewers/Knarknaknork, Spider Lair, Ekatrix, Jakundaf,
  // this one) — custom-battles.js's ownsBoardRestrictions()/getRestrictionPriority() pick
  // exactly ONE currently-active battle instance to govern the placement-hitbox mask/
  // ally-tile restrictions for the room. If a battle object from one of the OTHER four
  // quests is still isActive (e.g. abandoned mid-battle earlier this session without its
  // onClose ever firing), it can outscore and silently govern the room using ITS OWN
  // allowedTiles instead of this quest's — every tile this quest needs reads as blocked,
  // 0 allies can ever land. Mirrors logSpiderLairBoardOwnership.
  function logHellgateBoardOwnership(label) {
    try {
      const getActive = globalThis.CustomBattles?.getActiveBattles;
      if (typeof getActive !== 'function') {
        console.log(`[Quests Mod][Hellgate Part 1][board-ownership] ${label}: window.CustomBattles.getActiveBattles not available yet`);
        return;
      }
      const roomId = HELLGATE_BATTLE_ROOM_ID;
      const sharingRoom = getActive().filter((b) => b?.config?.roomId === roomId);

      if (sharingRoom.length <= 1) {
        console.log(`[Quests Mod][Hellgate Part 1][board-ownership] ${label}: only ${sharingRoom.length} active battle instance(s) for room ${roomId} — no competition`, {
          names: sharingRoom.map((b) => b?.config?.name)
        });
        return;
      }

      const rows = sharingRoom.map((b) => {
        let ownsBoard = false;
        try { ownsBoard = b.ownsBoardRestrictions?.() === true; } catch (_) {}
        return {
          name: b?.config?.name,
          isHellgateInstance: b === hellgateBattle,
          isActive: b?.isActive === true,
          ownsBoardRestrictions: ownsBoard,
          allowedTiles: b?.config?.tileRestrictions?.allowedTiles || null,
          setupSeq: b?._setupSeq
        };
      });

      const hellgateOwns = rows.find((r) => r.isHellgateInstance)?.ownsBoardRestrictions === true;
      const logFn = hellgateOwns ? console.log : console.warn;
      logFn(`[Quests Mod][Hellgate Part 1][board-ownership] ${label}: ${sharingRoom.length} active battle instances share room ${roomId}${hellgateOwns ? '' : ' — HELLGATE DOES NOT OWN BOARD RESTRICTIONS, another quest\'s allowedTiles are governing ally placement right now'}`);
      if (typeof console.table === 'function') {
        console.table(rows);
      } else {
        console.log(rows);
      }
    } catch (error) {
      console.error('[Quests Mod][Hellgate Part 1][board-ownership] Error checking board ownership:', error);
    }
  }

  function applyHellgateTileMutations() {
    const mutations = HELLGATE_TILE_MUTATIONS;
    if (!mutations || typeof mutations !== 'object') return;

    const battle = hellgateBattle;

    let wroteHitboxes = false;
    Object.entries(mutations).forEach(([tileKey, entry]) => {
      const tileIndex = Number(tileKey);
      if (!Number.isFinite(tileIndex) || !entry || typeof entry !== 'object') return;
      const tile = getTileElement(tileIndex);

      (entry.remove || []).forEach((spriteId) => {
        if (spriteId == null || !tile) return;
        tile.querySelectorAll(`.sprite.item.relative.id-${spriteId}`).forEach((sprite) => {
          hideQuestBoardElement(sprite, { tag: QUEST_BOARD_HIDDEN_TAG_HELLGATE });
        });
      });

      // Keyed by tile+position (not by sprite id class), so a retry pass can't mistake
      // an already-placed sprite for missing and stack a duplicate on top of it.
      (entry.add || []).forEach((spriteEntry, spriteIndex) => {
        const spriteId = spriteEntry?.spriteId;
        if (spriteId == null || !tile) return;
        const mutationKey = `${tileIndex}-${spriteIndex}`;
        if (tile.querySelector(`[data-quests-hellgate-mutation-key="${mutationKey}"]`)) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = buildHellgateMutationSpriteHTML(spriteEntry, mutationKey);
        if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
      });

      if (Object.prototype.hasOwnProperty.call(entry, 'hitbox')) {
        try {
          getHellgateRoomRefs().forEach((room) => {
            const data = room?.file?.data;
            if (!data) return;
            if (!Array.isArray(data.hitboxes)) data.hitboxes = [];
            data.hitboxes[tileIndex] = entry.hitbox === true;
            wroteHitboxes = true;
          });
        } catch (_) {}
      }
    });

    if (wroteHitboxes) hellgateHitboxesApplied = true;

    ensureHellgateElathrielDummy();

    if (battle?.refreshPlacementHitboxMaskFromLive) {
      battle.refreshPlacementHitboxMaskFromLive(
        () => playerFollowedElathrielToHellgate
      );
    } else if (battle?.syncPlacementHitboxMask) {
      battle.syncPlacementHitboxMask(() => playerFollowedElathrielToHellgate);
    }

    if (playerFollowedElathrielToHellgate) checkHellgateHitboxIntegrity('applyHellgateTileMutations');
    if (playerFollowedElathrielToHellgate) logHellgateHitboxTable('applyHellgateTileMutations');
    if (playerFollowedElathrielToHellgate) logHellgateBoardOwnership('applyHellgateTileMutations');
  }

  function restoreHellgateTileMutations() {
    restoreQuestBoardElementsByTag(QUEST_BOARD_HIDDEN_TAG_HELLGATE);
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_HELLGATE}="1"]`).forEach((el) => {
      try { el.remove(); } catch (_) {}
    });
    hellgateHitboxesApplied = false;
  }

  // Keeping hitboxes synced beyond the initial entry window is now CustomBattle's own
  // startPersistentVisualSync() (custom-battles.js) — a single source of truth shared by
  // every quest instead of each one hand-rolling its own retry-burst + board-subscription
  // pair (which is exactly how Hellgate Part 1 shipped broken: it only had the retry burst,
  // so nothing re-synced the placement hitbox mask once that ~2s window closed). See
  // setupHellgateBattleInstance() for where this gets wired up, and cleanup() in
  // custom-battles.js for the automatic teardown — no separate stop call needed here.

  function restoreBoardSetupHellgate() {
    if (hellgateBattle) {
      hellgateBattle.restoreBoardSetup();
    }
    restoreHellgateTileMutations();
  }

  function cleanupHellgateTreasureRoomQuest() {
    try {
      removeCustomBattleStatusToast();
      playerFollowedElathrielToHellgate = false;
      restoreHellgateTileMutations();
      if (hellgateBattle) {
        hellgateBattle.cleanup(restoreBoardSetupHellgate, showQuestOverlays);
        hellgateBattle = null;
        console.log(`${getHellgateLogPrefix()} Battle cleaned up`);
      }
    } catch (error) {
      console.error(`${getHellgateLogPrefix()} Error cleaning up:`, error);
    }
  }

  function setupHellgateTileRestrictions() {
    if (!hellgateBattle) return;
    hellgateBattle.setupTileRestrictions(
      () => playerFollowedElathrielToHellgate,
      NotificationService.createBattleToastCallback(getHellgateLogPrefix())
    );
    hellgateBattle.setupAllyLimit?.(
      () => playerFollowedElathrielToHellgate,
      NotificationService.createBattleToastCallback(getHellgateLogPrefix())
    );
  }

  function navigateToHedgeMazeFromHellgate() {
    try {
      const roomId = getRoomIdByRoomName(ELATHRIEL_ROOM_NAME);
      if (!roomId) {
        console.warn(`${getHellgateLogPrefix()} Hedge Maze room not found`);
        return;
      }
      globalThis.state.board.send({ type: 'selectRoomById', roomId });
    } catch (error) {
      console.error(`${getHellgateLogPrefix()} Error navigating to Hedge Maze:`, error);
    }
  }

  function setupHellgateBattleInstance(battle) {
    if (!battle) return false;
    hellgateBattle = battle;
    hellgateBattle.setup(
      () => playerFollowedElathrielToHellgate,
      NotificationService.createBattleToastCallback(getHellgateLogPrefix())
    );
    hellgateBattle.resetSandboxBattleState();
    setupHellgateTileRestrictions();
    showCustomBattleStatusToast({
      battleName: HELLGATE_BATTLE_DISPLAY_NAME || 'Hellgate Treasure Room',
      allyLimit: battle.config?.allyLimit ?? 5,
      battle,
      logPrefix: getHellgateLogPrefix()
    });
    // Puts the board into sandbox mode (required for activationCheck's isSandbox check)
    // and spawns the custom villains onto the room tiles, with retries for remounts.
    hellgateBattle.scheduleEntryVillainSetup({
      attemptDelays: [0, 100, 250, 500, 800, 1200],
      isActiveCheck: () => playerFollowedElathrielToHellgate,
      onComplete: () => {
        hideQuestOverlays();
        hideHeroEditorButton();
        hellgateBattle.startPersistentVisualSync(applyHellgateTileMutations, {
          isActiveCheck: () => playerFollowedElathrielToHellgate
        });
      }
    });
    return true;
  }

  function enterHellgateTreasureRoom() {
    let roomId = HELLGATE_BATTLE_ROOM_ID || getRoomIdByRoomName(HELLGATE_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(HELLGATE_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'The Hellgate treasure room could not be found.', logPrefix: getHellgateLogPrefix() });
      return;
    }

    playerFollowedElathrielToHellgate = true;
    hellgateElathrielSignReader.resetRead();
    if (hellgateBattle) {
      hellgateBattle.cleanup(restoreBoardSetupHellgate, showQuestOverlays);
      hellgateBattle = null;
    }

    const initResult = initializeHellgateBattle(roomId);
    if (initResult && initResult.then) {
      initResult.then((battle) => {
        if (!setupHellgateBattleInstance(battle)) {
          console.error(`${getHellgateLogPrefix()} Failed to initialize battle after waiting`);
        }
      }).catch((err) => console.error(`${getHellgateLogPrefix()} Error initializing battle:`, err));
    } else if (!setupHellgateBattleInstance(initResult)) {
      console.error(`${getHellgateLogPrefix()} CustomBattles not available`);
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    showToast({ message: 'Following Elathriel into the treasure room...', logPrefix: getHellgateLogPrefix() });
  }

  // =======================
  // Hellgate Library (Elathriel — after Hellgate Part 1, teleports the player into the
  // Sewers re-skinned as a library. The Wrinkled Bonelord stands on tile 68 as a board
  // NPC; asking him for the "book" while holding "Beware of the Bonelords (Book)" makes
  // him take it and spawn the full villain roster for a battle in place. Reward: White
  // Mushroom, handed over by Elathriel on return. Mirrors createHellgateBattleInstance +
  // the Lost Oracle rage-battle "keyword starts a battle in this room" pattern.)
  // =======================

  function getHellgateLibraryLogPrefix() {
    return '[Quests Mod][Hellgate Library]';
  }

  function buildHellgateLibraryMutationSpriteHTML(entry, mutationKey) {
    const spriteId = entry?.spriteId;
    if (spriteId == null) return '';
    const cropX = entry.cropX != null ? entry.cropX : 0;
    const cropY = entry.cropY != null ? entry.cropY : 0;
    const cropped = entry.cropped ? 'true' : 'false';
    const bankStyle = entry.bank != null ? ` --bank: ${entry.bank};` : '';
    const rightCalc = formatHellgateMutationOffsetCalc(entry.offsetX);
    const bottomCalc = formatHellgateMutationOffsetCalc(entry.offsetY);
    const offsetStyle = `${rightCalc ? ` right: ${rightCalc};` : ''}${bottomCalc ? ` bottom: ${bottomCalc};` : ''}`;
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_HELLGATE_LIBRARY}="1" data-quests-hellgate-library-mutation-key="${mutationKey}" style="z-index: 1000;${bankStyle}${offsetStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
  }

  // Decorative "Elathriel followed me down" copy standing on tile 152, facing north — the
  // same trick as ensureHellgateElathrielDummy() in the treasure room. Non-interactive,
  // not a Board NPC, not a combat ally; tagged QUEST_BOARD_ADDED_ATTR_HELLGATE_LIBRARY so
  // restoreHellgateLibraryTileMutations() tears it (and its name tag) down.
  const HELLGATE_LIBRARY_ELATHRIEL_DUMMY_TILE_INDEX = 152;
  const HELLGATE_LIBRARY_ELATHRIEL_DUMMY_ATTR = 'data-quests-hellgate-library-elathriel-dummy';
  const HELLGATE_LIBRARY_ELATHRIEL_DUMMY_NAME_TAG_CLASS = 'quests-hellgate-library-elathriel-dummy-name-tag';

  function ensureHellgateLibraryElathrielDummyNameTag(tileElement) {
    let nameTag = document.querySelector(`.${HELLGATE_LIBRARY_ELATHRIEL_DUMMY_NAME_TAG_CLASS}`);
    if (!nameTag) {
      nameTag = document.createElement('span');
      nameTag.className = `${HELLGATE_LIBRARY_ELATHRIEL_DUMMY_NAME_TAG_CLASS} revert-pixel-font-spacing pointer-events-none absolute flex w-[192px] flex-col items-center`;
      nameTag.style.cssText = [
        'position:absolute',
        'user-select:none',
        `z-index:${QUEST_FIGHT_ICON_Z_INDEX}`,
        'pointer-events:none',
        'line-height:1'
      ].join(';');
      nameTag.setAttribute(QUEST_BOARD_ADDED_ATTR_HELLGATE_LIBRARY, '1');

      const nameLine = document.createElement('span');
      nameLine.setAttribute('translate', 'no');
      nameLine.className = 'select-none text-center pixel-font-16 text-whiteHighlight';
      nameLine.style.cssText = 'line-height:1;font-size:16px;display:inline-flex;align-items:center;';

      const nameText = document.createElement('span');
      nameText.className = 'text-whiteHighlight';
      nameText.style.cssText = 'color:rgb(96, 192, 96);text-shadow:-1px 0 #000,1px 0 #000,0 -1px #000,0 1px #000;';
      nameText.textContent = 'Elathriel';

      nameLine.appendChild(nameText);
      nameTag.appendChild(nameLine);
    }
    positionBoardNpcNameTag(nameTag, tileElement);
  }

  function ensureHellgateLibraryElathrielDummy() {
    const tile = getTileElement(HELLGATE_LIBRARY_ELATHRIEL_DUMMY_TILE_INDEX);
    if (!tile) return;
    if (!tile.querySelector(`[${HELLGATE_LIBRARY_ELATHRIEL_DUMMY_ATTR}="1"]`)) {
      const outfitSpriteId = ELATHRIEL_OUTFIT_SPRITE_ID || '64';
      const wrap = document.createElement('div');
      wrap.innerHTML = `<div class="sprite outfit id-${outfitSpriteId} idle north pointer-events-none absolute bottom-0 right-0 select-none" ${QUEST_BOARD_ADDED_ATTR_HELLGATE_LIBRARY}="1" ${HELLGATE_LIBRARY_ELATHRIEL_DUMMY_ATTR}="1" style="z-index: 1000;"><div class="viewport"><img alt="north" class="actor spritesheet" data-shiny="false" style="animation-play-state: running;"></div></div>`;
      if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
    }
    ensureHellgateLibraryElathrielDummyNameTag(tile);
  }

  function applyHellgateLibraryTileMutations() {
    const mutations = HELLGATE_LIBRARY_TILE_MUTATIONS;
    if (!mutations || typeof mutations !== 'object') return;
    let wroteHitboxes = false;
    Object.entries(mutations).forEach(([tileKey, entry]) => {
      const tileIndex = Number(tileKey);
      if (!Number.isFinite(tileIndex) || !entry || typeof entry !== 'object') return;
      const tile = getTileElement(tileIndex);

      (entry.remove || []).forEach((spriteId) => {
        if (spriteId == null || !tile) return;
        tile.querySelectorAll(`.sprite.item.relative.id-${spriteId}`).forEach((sprite) => {
          hideQuestBoardElement(sprite, { tag: QUEST_BOARD_HIDDEN_TAG_HELLGATE_LIBRARY });
        });
      });

      (entry.add || []).forEach((spriteEntry, spriteIndex) => {
        const spriteId = spriteEntry?.spriteId;
        if (spriteId == null || !tile) return;
        const mutationKey = `${tileIndex}-${spriteIndex}`;
        if (tile.querySelector(`[data-quests-hellgate-library-mutation-key="${mutationKey}"]`)) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = buildHellgateLibraryMutationSpriteHTML(spriteEntry, mutationKey);
        if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
      });

      if (Array.isArray(entry.floorBelow) && entry.floorBelow.length) {
        applyQuestFloorBelowSprites(
          tileIndex, entry.floorBelow, QUEST_BOARD_ADDED_ATTR_HELLGATE_LIBRARY, 'data-quests-hellgate-library-fb-key'
        );
      }

      if (Object.prototype.hasOwnProperty.call(entry, 'hitbox')) {
        try {
          getHellgateRoomRefs().forEach((room) => {
            const data = room?.file?.data;
            if (!data) return;
            if (!Array.isArray(data.hitboxes)) data.hitboxes = [];
            data.hitboxes[tileIndex] = entry.hitbox === true;
            wroteHitboxes = true;
          });
        } catch (_) {}
      }
    });

    if (wroteHitboxes) hellgateLibraryHitboxesApplied = true;

    ensureHellgateLibraryElathrielDummy();

    const battle = hellgateLibraryBattle;
    if (battle?.refreshPlacementHitboxMaskFromLive) {
      battle.refreshPlacementHitboxMaskFromLive(() => playerEnteredHellgateLibrary);
    } else if (battle?.syncPlacementHitboxMask) {
      battle.syncPlacementHitboxMask(() => playerEnteredHellgateLibrary);
    }
  }

  function restoreHellgateLibraryTileMutations() {
    restoreQuestBoardElementsByTag(QUEST_BOARD_HIDDEN_TAG_HELLGATE_LIBRARY);
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_HELLGATE_LIBRARY}="1"]`).forEach((el) => {
      try { el.remove(); } catch (_) {}
    });
    hellgateLibraryHitboxesApplied = false;
  }

  function stopHellgateLibraryPreBattleSync() {
    if (hellgateLibraryPreBattleSub) {
      try { hellgateLibraryPreBattleSub.unsubscribe?.(); } catch (_) {}
      hellgateLibraryPreBattleSub = null;
    }
  }

  // Paint the library reskin on every animation frame for `durationMs` — used right after
  // a room navigation so the plain Sewers is covered on the first frame its tiles mount,
  // rather than waiting for a fixed retry tick or the battle's persistent visual sync.
  function paintHellgateLibrarySceneBurst(durationMs = 600) {
    const deadline = (typeof performance !== 'undefined' ? performance.now() : Date.now()) + durationMs;
    const tick = () => {
      if (!playerEnteredHellgateLibrary) return;
      if (isOnRoomByName(HELLGATE_LIBRARY_BATTLE_ROOM_NAME)) applyHellgateLibraryTileMutations();
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
      if (now < deadline && typeof requestAnimationFrame === 'function') requestAnimationFrame(tick);
    };
    tick();
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(tick);
    [120, 300, 600].forEach((d) => setTimeout(tick, d));
  }

  // During the talk-to-the-Bonelord window there is no battle yet, so navigating into the
  // Sewers makes the game auto-place the player's saved autoplay team (and any native
  // Sewers actors). Nobody should be on the board until "book" starts the fight — strip
  // every piece back out. Stops running the instant the battle instance is created.
  function clearHellgateLibraryBoardPieces() {
    try {
      const cfg = globalThis.state?.board?.getSnapshot?.()?.context?.boardConfig;
      if (!Array.isArray(cfg) || cfg.length === 0) return;
      globalThis.state.board.send({
        type: 'setState',
        fn: (prev) => ({ ...prev, boardConfig: [] })
      });
    } catch (_) {}
  }

  // Before the fight starts there is no CustomBattle instance to run startPersistentVisualSync,
  // so keep the library scene painted until it hands off. The plain Sewers is visible for
  // exactly as long as it takes React to mount the new room's tiles — so instead of a few
  // spaced-out setTimeouts, paint on every animation frame for the first ~600ms (catches
  // the room the instant its DOM exists) and keep a board subscription for anything after.
  function startHellgateLibraryPreBattleSync() {
    stopHellgateLibraryPreBattleSync();
    const paint = () => {
      if (playerEnteredHellgateLibrary
        && !hellgateLibraryBattleStarted
        && isOnRoomByName(HELLGATE_LIBRARY_BATTLE_ROOM_NAME)) {
        clearHellgateLibraryBoardPieces();
        applyHellgateLibraryTileMutations();
      }
    };
    paint();
    const rafDeadline = (typeof performance !== 'undefined' ? performance.now() : Date.now()) + 600;
    const rafPaint = () => {
      if (!playerEnteredHellgateLibrary || hellgateLibraryBattleStarted) return;
      paint();
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
      if (now < rafDeadline && typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    };
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    [200, 500, 1000, 1600].forEach((d) => setTimeout(paint, d));
    if (!globalThis.state?.board?.subscribe) return;
    hellgateLibraryPreBattleSub = globalThis.state.board.subscribe(() => {
      if (!playerEnteredHellgateLibrary || hellgateLibraryBattleStarted) {
        stopHellgateLibraryPreBattleSync();
        return;
      }
      paint();
    });
  }

  function restoreBoardSetupHellgateLibrary() {
    if (hellgateLibraryBattle) hellgateLibraryBattle.restoreBoardSetup();
    restoreHellgateLibraryTileMutations();
  }

  function cleanupHellgateLibraryQuest() {
    try {
      removeCustomBattleStatusToast();
      stopHellgateLibraryPreBattleSync();
      wrinkledBonelordBossHpBar.remove();
      playerEnteredHellgateLibrary = false;
      hellgateLibraryBattleStarted = false;
      restoreHellgateLibraryTileMutations();
      if (hellgateLibraryBattle) {
        hellgateLibraryBattle.cleanup(restoreBoardSetupHellgateLibrary, showQuestOverlays);
        hellgateLibraryBattle = null;
        console.log(`${getHellgateLibraryLogPrefix()} Battle cleaned up`);
      }
      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    } catch (error) {
      console.error(`${getHellgateLibraryLogPrefix()} Error cleaning up:`, error);
    }
  }

  function createHellgateLibraryBattleInstance(roomId) {
    if (!window.CustomBattles) {
      console.error(`${getHellgateLibraryLogPrefix()} CustomBattles still not available`);
      return null;
    }
    const spawn = getHydratedQuestBattleSpawn(HELLGATE_LIBRARY_BATTLE_ID || 'hellgate_library');
    const villains = spawn.villains;
    const tileRestrictions = {};
    if (spawn.allowedTiles?.length) {
      tileRestrictions.allowedTiles = spawn.allowedTiles;
      tileRestrictions.message = spawn.allowedTilesMessage || 'Ally creatures can only be placed on the marked tiles!';
    }
    const config = {
      name: HELLGATE_LIBRARY_BATTLE_DISPLAY_NAME || 'Hellgate Library',
      roomId,
      villains,
      allyLimit: spawn.allyLimit ?? 8,
      preventVillainMovement: spawn.preventVillainMovement !== false,
      hideVillainSprites: spawn.hideVillainSprites !== false,
      ...(Object.keys(tileRestrictions).length ? { tileRestrictions } : {}),
      activationCheck: (isSandbox, inBattleArea) => isSandbox && inBattleArea && playerEnteredHellgateLibrary,
      victoryDefeat: {
        onVictory: async () => {
          console.log(`${getHellgateLibraryLogPrefix()} The librarian's guardians defeated!`);
          try {
            await persistMissionProgress(HELLGATE_LIBRARY_MISSION, {
              accepted: true,
              completed: false,
              battleCompleted: true
            });
          } catch (error) {
            console.error(`${getHellgateLibraryLogPrefix()} Error saving battleCompleted flag:`, error);
          }
        },
        onDefeat: () => {},
        onClose: () => {
          cleanupHellgateLibraryQuest();
          setTimeout(() => navigateToHedgeMazeFromHellgate(), 100);
        },
        victoryTitle: 'Victory!',
        defeatTitle: 'Defeat',
        victoryMessage: getMissionDialogueLine(
          HELLGATE_LIBRARY_MISSION,
          'battleVictory',
          'The library is silent now. Return to Elathriel.'
        ),
        defeatMessage: getMissionDialogueLine(
          HELLGATE_LIBRARY_MISSION,
          'battleDefeat',
          "The librarian's guardians proved the sharper scholars."
        ),
        showItems: false,
        items: []
      }
    };
    return window.CustomBattles.create(config);
  }

  function isHellgateLibraryBattleCompletedPendingReward() {
    const progress = getMissionProgress(HELLGATE_LIBRARY_MISSION);
    return !!progress?.battleCompleted && !progress?.completed;
  }

  async function completeHellgateLibraryMissionWithMushroom() {
    const progress = getMissionProgress(HELLGATE_LIBRARY_MISSION);
    if (progress?.completed) return false;
    try {
      await addQuestItem('White Mushroom', 1);
      showQuestItemNotification('White Mushroom', 1);
      await persistMissionProgress(HELLGATE_LIBRARY_MISSION, {
        accepted: true,
        completed: true,
        battleCompleted: true
      });
      NotificationService.showQuestCompleted(HELLGATE_LIBRARY_MISSION, getHellgateLibraryLogPrefix(), {
        productName: 'White Mushroom'
      });
      console.log(`${getHellgateLibraryLogPrefix()} Mission completed — White Mushroom awarded`);
      return true;
    } catch (error) {
      console.error(`${getHellgateLibraryLogPrefix()} Error completing mission with mushroom reward:`, error);
      return false;
    }
  }

  function initializeHellgateLibraryBattle(roomId) {
    if (window.CustomBattles) return createHellgateLibraryBattleInstance(roomId);
    return waitForCustomBattles({ logPrefix: getHellgateLibraryLogPrefix() }).then((api) => {
      if (!api) return null;
      return createHellgateLibraryBattleInstance(roomId);
    });
  }

  function setupHellgateLibraryTileRestrictions() {
    if (!hellgateLibraryBattle) return;
    hellgateLibraryBattle.setupTileRestrictions(
      () => playerEnteredHellgateLibrary,
      NotificationService.createBattleToastCallback(getHellgateLibraryLogPrefix())
    );
    hellgateLibraryBattle.setupAllyLimit?.(
      () => playerEnteredHellgateLibrary,
      NotificationService.createBattleToastCallback(getHellgateLibraryLogPrefix())
    );
  }

  // Pre-battle: bring the CustomBattle instance up (setup() marks it active + adds it to
  // activeCustomBattles, so isAnyCustomBattleActiveForRoom('rkswrs') is true and every
  // Sewers quest helper — "Visit Al Dee" on tile 79, the Elathriel/Copper Key sign
  // readers, the Sewers portal, Spider Lair / Jakundaf marks — suppresses itself the same
  // way it does for every other custom battle in this room). Villains are NOT spawned yet;
  // that waits for the Bonelord to take the book.
  function setupHellgateLibraryPreBattle(battle) {
    if (!battle) return false;
    hellgateLibraryBattle = battle;
    hellgateLibraryBattle.setup(
      () => playerEnteredHellgateLibrary,
      NotificationService.createBattleToastCallback(getHellgateLibraryLogPrefix())
    );
    hellgateLibraryBattle.resetSandboxBattleState();
    setupHellgateLibraryTileRestrictions();
    return true;
  }

  // Book taken — spawn the villain roster on the already-active instance and hand the
  // scene painting over to the battle's persistent visual sync.
  function spawnHellgateLibraryVillains() {
    const battle = hellgateLibraryBattle;
    if (!battle) return false;
    stopHellgateLibraryPreBattleSync();
    // Keep the library scene painted through the gap between the pre-battle sync stopping
    // and startPersistentVisualSync() taking over in the villain-setup onComplete.
    paintHellgateLibrarySceneBurst(1400);
    showCustomBattleStatusToast({
      battleName: HELLGATE_LIBRARY_BATTLE_DISPLAY_NAME || 'Hellgate Library',
      allyLimit: battle.config?.allyLimit ?? 8,
      battle,
      logPrefix: getHellgateLibraryLogPrefix()
    });
    battle.scheduleEntryVillainSetup({
      attemptDelays: [0, 100, 250, 500, 800, 1200],
      isActiveCheck: () => playerEnteredHellgateLibrary,
      onComplete: () => {
        hideQuestOverlays();
        hideHeroEditorButton();
        battle.startPersistentVisualSync(applyHellgateLibraryTileMutations, {
          isActiveCheck: () => playerEnteredHellgateLibrary
        });
      }
    });
    return true;
  }

  function startHellgateLibraryBattle(npcConfig = null) {
    const progress = getMissionProgress(HELLGATE_LIBRARY_MISSION) || {};
    if (progress.completed || progress.battleCompleted) {
      console.log(`${getHellgateLibraryLogPrefix()} Mission already finished — not starting battle`);
      return;
    }
    const roomId = HELLGATE_LIBRARY_BATTLE_ROOM_ID || getRoomIdByRoomName(HELLGATE_LIBRARY_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'The Hellgate Library could not be found.', logPrefix: getHellgateLibraryLogPrefix() });
      return;
    }
    try {
      hellgateLibraryBattleStarted = true;
      const config = npcConfig || BOARD_NPC_CONFIGS.find((c) => c.id === BOARD_NPC_BONELORD_ID);
      if (config) removeBoardNpcOverlay(config);
      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);

      // The instance is normally already up from enterHellgateLibrary() — just spawn the
      // villains. If entry's async create hasn't landed yet, build it now first.
      if (hellgateLibraryBattle) {
        spawnHellgateLibraryVillains();
        return;
      }
      const initResult = initializeHellgateLibraryBattle(roomId);
      const finish = (battle) => {
        if (setupHellgateLibraryPreBattle(battle)) {
          spawnHellgateLibraryVillains();
        } else {
          hellgateLibraryBattleStarted = false;
          console.error(`${getHellgateLibraryLogPrefix()} Failed to set up battle`);
        }
      };
      if (initResult && typeof initResult.then === 'function') {
        initResult.then(finish).catch((error) => {
          hellgateLibraryBattleStarted = false;
          console.error(`${getHellgateLibraryLogPrefix()} Error initializing battle:`, error);
        });
        return;
      }
      finish(initResult);
    } catch (error) {
      hellgateLibraryBattleStarted = false;
      console.error(`${getHellgateLibraryLogPrefix()} Error starting battle:`, error);
    }
  }

  function enterHellgateLibrary() {
    let roomId = HELLGATE_LIBRARY_BATTLE_ROOM_ID || getRoomIdByRoomName(HELLGATE_LIBRARY_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(HELLGATE_LIBRARY_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'The Hellgate Library could not be found.', logPrefix: getHellgateLibraryLogPrefix() });
      return;
    }

    playerEnteredHellgateLibrary = true;
    hellgateLibraryBattleStarted = false;
    hellgateLibraryElathrielSignReader.resetRead();
    if (hellgateLibraryBattle) {
      hellgateLibraryBattle.cleanup(restoreBoardSetupHellgateLibrary, showQuestOverlays);
      hellgateLibraryBattle = null;
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });

    // Book already handed over on an earlier visit (fight abandoned / lost) — there's no
    // talk step left, the Bonelord has nothing to take. Skip straight to the battle.
    const libProgress = getMissionProgress(HELLGATE_LIBRARY_MISSION) || {};
    const skipToBattle = libProgress.bookGiven && !libProgress.battleCompleted && !libProgress.completed;

    // Bring the battle instance up now (no villains yet) so it registers as the active
    // custom battle for rkswrs and the Sewers quest helpers hide — then paint the library
    // scene / keep the board clear until the villains spawn.
    const initResult = initializeHellgateLibraryBattle(roomId);
    if (initResult && typeof initResult.then === 'function') {
      initResult.then((battle) => {
        // Bail if the player already left, or "book" beat this async create to it and
        // started its own instance — never stand up a second battle for the same room.
        if (playerEnteredHellgateLibrary && !hellgateLibraryBattleStarted && !hellgateLibraryBattle) {
          setupHellgateLibraryPreBattle(battle);
          if (skipToBattle) startHellgateLibraryBattle();
        }
      }).catch((error) => console.error(`${getHellgateLibraryLogPrefix()} Error initializing pre-battle instance:`, error));
    } else if (initResult) {
      setupHellgateLibraryPreBattle(initResult);
    }
    startHellgateLibraryPreBattleSync();
    updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);

    if (skipToBattle) {
      showToast({ message: 'The librarian is still waiting. No more words.', logPrefix: getHellgateLibraryLogPrefix() });
      // Instance is already up from the sync path above (unless CustomBattles was still
      // loading, handled in the async branch) — spawn the villains straight away.
      if (hellgateLibraryBattle && !hellgateLibraryBattleStarted) startHellgateLibraryBattle();
      return;
    }

    showToast({ message: 'Following Elathriel down into the library...', logPrefix: getHellgateLibraryLogPrefix() });
  }

  // =======================
  // Isle of Solitude / GM Island (King Tibianus easter egg — chat-triggered teleport into
  // the Sewers re-skinned as the isle. No mission, no villains, no rewards: a walk-around
  // scene. An empty CustomBattle is stood up purely so the board clears and the Sewers
  // quest overlays suppress themselves (same trick as Hellgate Library's pre-battle
  // instance). Right-click the teleporter on tile 37 to return to the room the player was
  // in when they asked the King. Mirrors enterHellgateLibrary() + the Draconia post-battle
  // scene-sync helpers, stripped down.)
  // =======================

  function getIsleLogPrefix() {
    return '[Quests Mod][Isle of Solitude]';
  }

  function buildIsleMutationSpriteHTML(entry, mutationKey) {
    const spriteId = entry?.spriteId;
    if (spriteId == null) return '';
    const cropX = entry.cropX != null ? entry.cropX : 0;
    const cropY = entry.cropY != null ? entry.cropY : 0;
    const cropped = entry.cropped ? 'true' : 'false';
    const bankStyle = entry.bank != null ? ` --bank: ${entry.bank};` : '';
    const rightCalc = formatHellgateMutationOffsetCalc(entry.offsetX);
    const bottomCalc = formatHellgateMutationOffsetCalc(entry.offsetY);
    const offsetStyle = `${rightCalc ? ` right: ${rightCalc};` : ''}${bottomCalc ? ` bottom: ${bottomCalc};` : ''}`;
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_ISLE}="1" data-quests-isle-mutation-key="${mutationKey}" style="z-index: 1000;${bankStyle}${offsetStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
  }

  // "Muhamad" — a purely decorative dummy standing on tile 38 wearing the GM outfit
  // (assets/quests/GMOutfit.png, a single 64x64 frame). Not a Board NPC / combat ally.
  // Tagged QUEST_BOARD_ADDED_ATTR_ISLE so restoreIsleTileMutations() removes it and its
  // name tag. Right-clicking it shows green flavour text via muhamadSignReader.
  const MUHAMAD_DUMMY_TILE_INDEX = 38;
  const MUHAMAD_DUMMY_ATTR = 'data-quests-muhamad-dummy';
  const MUHAMAD_DUMMY_NAME_TAG_CLASS = 'quests-muhamad-dummy-name-tag';

  function ensureMuhamadDummyNameTag(tileElement) {
    let nameTag = document.querySelector(`.${MUHAMAD_DUMMY_NAME_TAG_CLASS}`);
    if (!nameTag) {
      nameTag = document.createElement('span');
      nameTag.className = `${MUHAMAD_DUMMY_NAME_TAG_CLASS} revert-pixel-font-spacing pointer-events-none absolute flex w-[192px] flex-col items-center`;
      nameTag.style.cssText = [
        'position:absolute',
        'user-select:none',
        `z-index:${QUEST_FIGHT_ICON_Z_INDEX}`,
        'pointer-events:none',
        'line-height:1'
      ].join(';');
      nameTag.setAttribute(QUEST_BOARD_ADDED_ATTR_ISLE, '1');

      const nameLine = document.createElement('span');
      nameLine.setAttribute('translate', 'no');
      nameLine.className = 'select-none text-center pixel-font-16 text-whiteHighlight';
      nameLine.style.cssText = 'line-height:1;font-size:16px;display:inline-flex;align-items:center;';

      const nameText = document.createElement('span');
      nameText.className = 'text-whiteHighlight';
      nameText.style.cssText = 'color:rgb(96, 192, 96);text-shadow:-1px 0 #000,1px 0 #000,0 -1px #000,0 1px #000;';
      nameText.textContent = 'Muhamad';

      nameLine.appendChild(nameText);
      nameTag.appendChild(nameLine);
    }
    positionBoardNpcNameTag(nameTag, tileElement);
  }

  function ensureMuhamadDummy() {
    if (!playerEnteredIsleOfSolitude) return;
    const tile = getTileElement(MUHAMAD_DUMMY_TILE_INDEX);
    if (!tile) return;
    if (!tile.querySelector(`[${MUHAMAD_DUMMY_ATTR}="1"]`)) {
      const url = getQuestItemsAssetUrl('GMOutfit.png').replace(/['"\\]/g, '');
      const node = document.createElement('div');
      node.className = 'pointer-events-none absolute select-none';
      node.setAttribute(QUEST_BOARD_ADDED_ATTR_ISLE, '1');
      node.setAttribute(MUHAMAD_DUMMY_ATTR, '1');
      // One tile (32x32) anchored to the tile's bottom-right. Kept click-through
      // (pointer-events:none) so it can never steal right-clicks from tile 37 next door —
      // Muhamad's line is wired to the tile-38 floor sprite via muhamadSignReader instead.
      node.style.cssText = `right:0;bottom:0;width:calc(32px * var(--zoomFactor));height:calc(32px * var(--zoomFactor));background-image:url("${url}");background-repeat:no-repeat;background-position:center bottom;background-size:contain;image-rendering:pixelated;pointer-events:none;z-index:1000;`;
      tile.appendChild(node);
    }
    ensureMuhamadDummyNameTag(tile);
  }

  // Live rkswrs data.hitboxes arrays (selected room + the canonical utils.ROOMS/REGIONS
  // copies). Shares the room with Hellgate, so getHellgateRoomRefs() resolves them.
  function getIsleHitboxDataRefs() {
    return getHellgateRoomRefs()
      .map((room) => room?.file?.data)
      .filter((data) => data && Array.isArray(data.hitboxes));
  }

  function applyIsleTileMutations() {
    const mutations = ISLE_TILE_MUTATIONS;
    if (!mutations || typeof mutations !== 'object') return;

    // Snapshot the room's real hitboxes ONCE, before the reskin overwrites them, so
    // restoreIsleTileMutations() can put the map back exactly on leave (otherwise the
    // isle's walkability carries over to rkswrs until a manual room change).
    if (isleHitboxSnapshot == null) {
      const live = isleOfSolitudeBattle?.getRoomHitboxesArray?.()
        || getIsleHitboxDataRefs()[0]?.hitboxes;
      if (Array.isArray(live) && live.length) isleHitboxSnapshot = live.slice();
    }

    let wroteHitboxes = false;
    Object.entries(mutations).forEach(([tileKey, entry]) => {
      const tileIndex = Number(tileKey);
      if (!Number.isFinite(tileIndex) || !entry || typeof entry !== 'object') return;
      const tile = getTileElement(tileIndex);

      (entry.remove || []).forEach((spriteId) => {
        if (spriteId == null || !tile) return;
        tile.querySelectorAll(`.sprite.item.relative.id-${spriteId}`).forEach((sprite) => {
          hideQuestBoardElement(sprite, { tag: QUEST_BOARD_HIDDEN_TAG_ISLE });
        });
      });

      (entry.add || []).forEach((spriteEntry, spriteIndex) => {
        const spriteId = spriteEntry?.spriteId;
        if (spriteId == null || !tile) return;
        const mutationKey = `${tileIndex}-${spriteIndex}`;
        if (tile.querySelector(`[data-quests-isle-mutation-key="${mutationKey}"]`)) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = buildIsleMutationSpriteHTML(spriteEntry, mutationKey);
        if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
      });

      if (Array.isArray(entry.floorBelow) && entry.floorBelow.length) {
        applyQuestFloorBelowSprites(
          tileIndex, entry.floorBelow, QUEST_BOARD_ADDED_ATTR_ISLE, 'data-quests-isle-fb-key'
        );
      }

      if (Object.prototype.hasOwnProperty.call(entry, 'hitbox')) {
        try {
          // hitboxes is boolean-shaped — assign, never delete (CLAUDE.md).
          getIsleHitboxDataRefs().forEach((data) => {
            data.hitboxes[tileIndex] = entry.hitbox === true;
            wroteHitboxes = true;
          });
        } catch (_) {}
      }
    });

    if (wroteHitboxes) {
      isleOfSolitudeHitboxesApplied = true;
      isleOfSolitudeBattle?.bumpSelectedRoomFileIdentity?.();
    }

    ensureMuhamadDummy();
  }

  function restoreIsleTileMutations() {
    restoreQuestBoardElementsByTag(QUEST_BOARD_HIDDEN_TAG_ISLE);
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_ISLE}="1"]`).forEach((el) => {
      try { el.remove(); } catch (_) {}
    });

    // Put the room's real hitboxes back so the isle's walkability doesn't stick to rkswrs.
    if (Array.isArray(isleHitboxSnapshot) && isleHitboxSnapshot.length) {
      const snap = isleHitboxSnapshot;
      if (isleOfSolitudeBattle?.writeHitboxesInPlace) {
        isleOfSolitudeBattle.writeHitboxesInPlace(snap);
      } else {
        getIsleHitboxDataRefs().forEach((data) => {
          const t = data.hitboxes;
          for (let i = 0; i < snap.length; i += 1) t[i] = snap[i];
          if (t.length > snap.length) t.length = snap.length;
        });
        isleOfSolitudeBattle?.bumpSelectedRoomFileIdentity?.();
      }
    }
    isleHitboxSnapshot = null;
    isleOfSolitudeHitboxesApplied = false;
  }

  // Wipe every piece off the board so the isle stays empty (mirrors clearDraconiaBoardPieces).
  function clearIsleBoardPieces() {
    try {
      const cfg = globalThis.state?.board?.getSnapshot?.()?.context?.boardConfig;
      if (!Array.isArray(cfg) || cfg.length === 0) return;
      globalThis.state.board.send({
        type: 'setState',
        fn: (prev) => ({ ...prev, boardConfig: [] })
      });
    } catch (_) {}
  }

  function stopIsleSceneSync() {
    if (isleSceneSub) {
      try { isleSceneSub.unsubscribe?.(); } catch (_) {}
      isleSceneSub = null;
    }
  }

  // Keeps the isle reskin painted + the board empty across room navigations / React
  // remounts. Runs alongside the CustomBattle's own startPersistentVisualSync, and covers
  // the brief window before that instance comes up. Mirrors startDraconiaSceneSync().
  function startIsleSceneSync() {
    stopIsleSceneSync();
    const paint = () => {
      if (playerEnteredIsleOfSolitude && isOnRoomByName(ISLE_BATTLE_ROOM_NAME)) {
        applyIsleTileMutations();
        clearIsleBoardPieces();
      }
    };
    paint();
    const deadline = (typeof performance !== 'undefined' ? performance.now() : Date.now()) + 800;
    const rafPaint = () => {
      if (!playerEnteredIsleOfSolitude) return;
      paint();
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
      if (now < deadline && typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    };
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    [150, 400, 900, 1600].forEach((d) => setTimeout(paint, d));
    if (!globalThis.state?.board?.subscribe) return;
    isleSceneSub = globalThis.state.board.subscribe(() => {
      if (!playerEnteredIsleOfSolitude) {
        stopIsleSceneSync();
        return;
      }
      paint();
    });
  }

  function restoreBoardSetupIsle() {
    if (isleOfSolitudeBattle) isleOfSolitudeBattle.restoreBoardSetup();
    restoreIsleTileMutations();
  }

  function cleanupIsleOfSolitudeQuest() {
    try {
      removeCustomBattleStatusToast();
      stopIsleSceneSync();
      disableIsleTeleporterRightClick();
      playerEnteredIsleOfSolitude = false;
      restoreIsleTileMutations();
      if (isleOfSolitudeBattle) {
        isleOfSolitudeBattle.cleanup(restoreBoardSetupIsle, showQuestOverlays);
        isleOfSolitudeBattle = null;
        console.log(`${getIsleLogPrefix()} Battle cleaned up`);
      }
      showQuestOverlays();
      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    } catch (error) {
      console.error(`${getIsleLogPrefix()} Error cleaning up:`, error);
    }
  }

  function createIsleBattleInstance(roomId) {
    if (!window.CustomBattles) {
      console.error(`${getIsleLogPrefix()} CustomBattles still not available`);
      return null;
    }
    const spawn = getHydratedQuestBattleSpawn(ISLE_BATTLE_ID || 'isle_of_solitude');
    const config = {
      name: ISLE_BATTLE_DISPLAY_NAME || 'Isle of Solitude',
      roomId,
      villains: [],
      allyLimit: spawn.allyLimit ?? 1,
      preventVillainMovement: spawn.preventVillainMovement !== false,
      hideVillainSprites: spawn.hideVillainSprites !== false,
      activationCheck: (isSandbox, inBattleArea) => isSandbox && inBattleArea && playerEnteredIsleOfSolitude
    };
    return window.CustomBattles.create(config);
  }

  function initializeIsleBattle(roomId) {
    if (window.CustomBattles) return createIsleBattleInstance(roomId);
    return waitForCustomBattles({ logPrefix: getIsleLogPrefix() }).then((api) => {
      if (!api) return null;
      return createIsleBattleInstance(roomId);
    });
  }

  function setupIslePreBattle(battle) {
    if (!battle) return false;
    isleOfSolitudeBattle = battle;
    isleOfSolitudeBattle.setup(
      () => playerEnteredIsleOfSolitude,
      NotificationService.createBattleToastCallback(getIsleLogPrefix())
    );
    isleOfSolitudeBattle.resetSandboxBattleState();
    isleOfSolitudeBattle.setupAllyLimit?.(
      () => playerEnteredIsleOfSolitude,
      NotificationService.createBattleToastCallback(getIsleLogPrefix())
    );
    isleOfSolitudeBattle.startPersistentVisualSync(applyIsleTileMutations, {
      isActiveCheck: () => playerEnteredIsleOfSolitude
    });
    return true;
  }

  function enterIsleOfSolitude() {
    if (playerEnteredIsleOfSolitude) return;
    let roomId = ISLE_BATTLE_ROOM_ID || getRoomIdByRoomName(ISLE_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(ISLE_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'The Isle of Solitude could not be found.', logPrefix: getIsleLogPrefix() });
      return;
    }

    // Capture where the player is now, BEFORE navigating — tile 37 sends them back here.
    isleReturnRoomId = globalThis.state?.board?.getSnapshot?.()?.context?.selectedMap?.selectedRoom?.id
      || globalThis.state?.board?.getSnapshot?.()?.context?.selectedRoomId
      || getRoomIdByRoomName('Rookgaard')
      || null;

    playerEnteredIsleOfSolitude = true;
    isleHitboxSnapshot = null; // fresh capture for this visit
    if (isleOfSolitudeBattle) {
      isleOfSolitudeBattle.cleanup(restoreBoardSetupIsle, showQuestOverlays);
      isleOfSolitudeBattle = null;
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    startIsleSceneSync();

    const initResult = initializeIsleBattle(roomId);
    if (initResult && typeof initResult.then === 'function') {
      initResult.then((battle) => {
        if (playerEnteredIsleOfSolitude && !isleOfSolitudeBattle) {
          setupIslePreBattle(battle);
          hideQuestOverlays();
          hideHeroEditorButton();
          clearIsleBoardPieces();
        }
      }).catch((error) => console.error(`${getIsleLogPrefix()} Error initializing isle instance:`, error));
    } else if (initResult) {
      setupIslePreBattle(initResult);
    }

    muhamadSignReader.resetRead();
    hideQuestOverlays();
    hideHeroEditorButton();
    clearIsleBoardPieces();
    enableIsleTeleporterRightClick();
    updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    showToast({ message: 'You step onto the Isle of Solitude. Right-click the teleporter on the ladder to leave.', logPrefix: getIsleLogPrefix() });
  }

  // Leaves the isle and returns the player to the room they came from (captured on entry).
  function leaveIsleOfSolitude() {
    const back = isleReturnRoomId || getRoomIdByRoomName('Rookgaard');
    console.log(`${getIsleLogPrefix()} Teleporter used on tile 37 — returning to room ${back || '(unknown)'}`);
    cleanupIsleOfSolitudeQuest();
    isleReturnRoomId = null;
    if (back) {
      setTimeout(() => {
        try { globalThis.state.board.send({ type: 'selectRoomById', roomId: back }); } catch (_) {}
      }, 60);
    }
  }

  function isIsleTeleporterActive(boardContext = null) {
    return playerEnteredIsleOfSolitude && isOnRoomByName(ISLE_BATTLE_ROOM_NAME);
  }

  // Return teleporter — right-click the ladder on tile 37 for a small context menu with a
  // single "Use the teleporter" option. Same createContextMenu helper as the Jakundaf /
  // Eclipse tile menus.
  function closeIsleTeleporterContextMenu() {
    if (isleTeleporterContextMenu && isleTeleporterContextMenu.closeMenu) {
      isleTeleporterContextMenu.closeMenu();
    }
    isleTeleporterContextMenu = null;
  }

  function createIsleTeleporterContextMenu(x, y, anchorElement = null) {
    closeIsleTeleporterContextMenu();
    isleTeleporterContextMenu = createContextMenu({
      x,
      y,
      layout: 'center',
      logPrefix: getIsleLogPrefix(),
      anchorElement: anchorElement || getTileElement(37),
      buttons: [
        {
          text: 'Use the teleporter',
          width: '180px',
          backgroundColor: '#2a4a2a',
          color: '#4CAF50',
          border: '1px solid #4CAF50',
          hoverBackgroundColor: '#1a2a1a',
          hoverBorderColor: '#66BB6A',
          onClick: () => {
            closeIsleTeleporterContextMenu();
            leaveIsleOfSolitude();
          }
        }
      ],
      onClose: () => { isleTeleporterContextMenu = null; }
    });
    return isleTeleporterContextMenu;
  }

  function handleIsleTeleporterRightClickDocument(event) {
    if (!isIsleTeleporterActive()) return;
    const tile37 = getTileElement(37);
    if (!tile37) return;
    const clickedTile = tile37.contains(event.target);
    const clickedOwnHighlightOverlay = typeof isQuestTileHighlightOverlay === 'function'
      && isQuestTileHighlightOverlay(event.target)
      && event.target.closest('[id^="tile-index-"]') === tile37;
    if (!clickedTile && !clickedOwnHighlightOverlay) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    event.stopPropagation();
    createIsleTeleporterContextMenu(event.clientX, event.clientY, tile37);
  }

  function enableIsleTeleporterRightClick() {
    if (isleTeleporterRightClickEnabled) return;
    document.addEventListener('contextmenu', handleIsleTeleporterRightClickDocument, true);
    isleTeleporterRightClickEnabled = true;
    const tile37 = getTileElement(37);
    if (tile37) tile37.style.pointerEvents = 'auto';
  }

  function disableIsleTeleporterRightClick() {
    closeIsleTeleporterContextMenu();
    if (!isleTeleporterRightClickEnabled) return;
    document.removeEventListener('contextmenu', handleIsleTeleporterRightClickDocument, true);
    isleTeleporterRightClickEnabled = false;
    const tile37 = getTileElement(37);
    if (tile37) tile37.style.pointerEvents = '';
  }

  // Right-click Muhamad (tile 38) for a green "thanks for trying the mod" line — same
  // sign-reader mechanism the Elathriel dummies use.
  const muhamadSignReader = createSignReaderSystem({
    id: 'Muhamad',
    tileIndex: MUHAMAD_DUMMY_TILE_INDEX,
    // Target tile 38's own floor sprite (the reskin mutation), not the Muhamad image —
    // the image is click-through so it can't block tile 37; right-clicking anywhere on
    // tile 38 (or its highlight glow) opens Muhamad's line.
    spriteSelector: '[data-quests-isle-mutation-key="38-0"]',
    lines: [
      'You look to Muhamad.',
      'He says: "Thanks for trying out this mod! Enjoy your stay on the isle."'
    ],
    isRoomActive: () => playerEnteredIsleOfSolitude && isOnRoomByName(ISLE_BATTLE_ROOM_NAME),
    durationMs: 5000
  });

  // =======================
  // Draconia Tower (Elathriel — after Hellgate Library, teleports the player into the
  // Sewers re-skinned as a dragon cemetery. The battle spawns on entry (Dragon Lord,
  // Dragon, An Old Dragonlord). On victory the fight is torn down and An Old Dragonlord
  // places as a board NPC on tile 80; saying "hi" while holding a White Mushroom trades
  // it for the Dragonfetish and teleports the player back to Hedge Maze, where Elathriel
  // closes the quest. Mirrors the Lost Oracle rage-battle "win → talk to the NPC" flow.)
  // =======================

  function getDraconiaLogPrefix() {
    return '[Quests Mod][Draconia Tower]';
  }

  // Decorative "Elathriel waits here" — his outfit sprite only, no name tag, west-facing.
  // Rendered onto the main tile layer at tile 72 (the #floor-below layer only shows through
  // real gaps in the floor, which the solid Sewers reskin doesn't have). Tagged
  // QUEST_BOARD_ADDED_ATTR_DRACONIA so restoreDraconiaTileMutations() clears it with the
  // rest of the reskin.
  const DRACONIA_ELATHRIEL_DUMMY_TILE_INDEX = 72;
  const DRACONIA_ELATHRIEL_DUMMY_ATTR = 'data-quests-draconia-elathriel-dummy';

  function ensureDraconiaElathrielFloorBelowDummy() {
    const tile = getTileElement(DRACONIA_ELATHRIEL_DUMMY_TILE_INDEX);
    if (!tile) return;
    if (tile.querySelector(`[${DRACONIA_ELATHRIEL_DUMMY_ATTR}="1"]`)) return;
    const outfitSpriteId = ELATHRIEL_OUTFIT_SPRITE_ID || '64';
    const wrap = document.createElement('div');
    wrap.innerHTML = `<div class="sprite outfit id-${outfitSpriteId} idle west pointer-events-none absolute bottom-0 right-0 select-none" ${QUEST_BOARD_ADDED_ATTR_DRACONIA}="1" ${DRACONIA_ELATHRIEL_DUMMY_ATTR}="1" style="z-index: 1000;"><div class="viewport"><img alt="west" class="actor spritesheet" data-shiny="false" style="animation-play-state: running;"></div></div>`;
    if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
  }

  // Renders editor-authored floor-below sprites (a mutation entry's `.floorBelow` array)
  // as bare `.sprite.item` direct children of #floor-below — the same shape the native
  // game uses, with z = floor*(-30000) + 10*tileIndex + stackIndex. Quest reskins that
  // painted a lower floor in the Map Editor came through empty before this, because the
  // export dropped addedFloorBelowConfigs and there was no render path here.
  function applyQuestFloorBelowSprites(tileIndex, list, addedAttr, keyAttr) {
    const floorBelow = document.getElementById('floor-below');
    const tile = getTileElement(tileIndex);
    if (!floorBelow || !tile || !Array.isArray(list) || !list.length) return;
    const rightPx = parseInt(String(tile.style.right).replace(/[^0-9-]/g, ''), 10);
    const bottomPx = parseInt(String(tile.style.bottom).replace(/[^0-9-]/g, ''), 10);
    if (!Number.isFinite(rightPx) || !Number.isFinite(bottomPx)) return;
    list.forEach((entry, idx) => {
      const spriteId = entry?.spriteId;
      if (spriteId == null) return;
      const mkey = `${tileIndex}-${idx}`;
      if (floorBelow.querySelector(`[${keyAttr}="${mkey}"]`)) return;
      const floor = Math.max(1, Math.min(9, Math.floor(Number(entry.floor) || 1)));
      const z = floor * -30000 + 10 * tileIndex + idx;
      const r = rightPx + (Number(entry.offsetX) || 0);
      const b = bottomPx + (Number(entry.offsetY) || 0);
      const cropX = entry.cropX != null ? entry.cropX : 0;
      const cropY = entry.cropY != null ? entry.cropY : 0;
      const cropped = entry.cropped ? 'true' : 'false';
      const bankStyle = entry.bank != null ? `--bank: ${entry.bank};` : '';
      const wrap = document.createElement('div');
      wrap.innerHTML = `<div class="sprite item id-${spriteId} pointer-events-none absolute size-scaled-sprite" ${addedAttr}="1" ${keyAttr}="${mkey}" style="z-index:${z};right:calc(${r}px * var(--zoomFactor));bottom:calc(${b}px * var(--zoomFactor));${bankStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
      if (wrap.firstElementChild) floorBelow.appendChild(wrap.firstElementChild);
    });
  }

  function buildDraconiaMutationSpriteHTML(entry, mutationKey) {
    const spriteId = entry?.spriteId;
    if (spriteId == null) return '';
    const cropX = entry.cropX != null ? entry.cropX : 0;
    const cropY = entry.cropY != null ? entry.cropY : 0;
    const cropped = entry.cropped ? 'true' : 'false';
    const bankStyle = entry.bank != null ? ` --bank: ${entry.bank};` : '';
    const rightCalc = formatHellgateMutationOffsetCalc(entry.offsetX);
    const bottomCalc = formatHellgateMutationOffsetCalc(entry.offsetY);
    const offsetStyle = `${rightCalc ? ` right: ${rightCalc};` : ''}${bottomCalc ? ` bottom: ${bottomCalc};` : ''}`;
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_DRACONIA}="1" data-quests-draconia-mutation-key="${mutationKey}" style="z-index: 1000;${bankStyle}${offsetStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
  }

  function applyDraconiaTileMutations() {
    const mutations = DRACONIA_TILE_MUTATIONS;
    if (!mutations || typeof mutations !== 'object') return;
    let wroteHitboxes = false;
    Object.entries(mutations).forEach(([tileKey, entry]) => {
      const tileIndex = Number(tileKey);
      if (!Number.isFinite(tileIndex) || !entry || typeof entry !== 'object') return;
      const tile = getTileElement(tileIndex);

      (entry.remove || []).forEach((spriteId) => {
        if (spriteId == null || !tile) return;
        tile.querySelectorAll(`.sprite.item.relative.id-${spriteId}`).forEach((sprite) => {
          hideQuestBoardElement(sprite, { tag: QUEST_BOARD_HIDDEN_TAG_DRACONIA });
        });
      });

      (entry.add || []).forEach((spriteEntry, spriteIndex) => {
        const spriteId = spriteEntry?.spriteId;
        if (spriteId == null || !tile) return;
        const mutationKey = `${tileIndex}-${spriteIndex}`;
        if (tile.querySelector(`[data-quests-draconia-mutation-key="${mutationKey}"]`)) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = buildDraconiaMutationSpriteHTML(spriteEntry, mutationKey);
        if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
      });

      if (Array.isArray(entry.floorBelow) && entry.floorBelow.length) {
        applyQuestFloorBelowSprites(
          tileIndex, entry.floorBelow, QUEST_BOARD_ADDED_ATTR_DRACONIA, 'data-quests-draconia-fb-key'
        );
      }

      if (Object.prototype.hasOwnProperty.call(entry, 'hitbox')) {
        try {
          getHellgateRoomRefs().forEach((room) => {
            const data = room?.file?.data;
            if (!data) return;
            if (!Array.isArray(data.hitboxes)) data.hitboxes = [];
            data.hitboxes[tileIndex] = entry.hitbox === true;
            wroteHitboxes = true;
          });
        } catch (_) {}
      }
    });

    if (wroteHitboxes) draconiaTowerHitboxesApplied = true;

    ensureDraconiaElathrielFloorBelowDummy();

    const battle = draconiaTowerBattle;
    if (battle?.refreshPlacementHitboxMaskFromLive) {
      battle.refreshPlacementHitboxMaskFromLive(() => playerEnteredDraconiaTower);
    } else if (battle?.syncPlacementHitboxMask) {
      battle.syncPlacementHitboxMask(() => playerEnteredDraconiaTower);
    }
  }

  function restoreDraconiaTileMutations() {
    restoreQuestBoardElementsByTag(QUEST_BOARD_HIDDEN_TAG_DRACONIA);
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_DRACONIA}="1"]`).forEach((el) => {
      try { el.remove(); } catch (_) {}
    });
    draconiaTowerHitboxesApplied = false;
  }

  function stopDraconiaSceneSync() {
    if (draconiaTowerSceneSub) {
      try { draconiaTowerSceneSub.unsubscribe?.(); } catch (_) {}
      draconiaTowerSceneSub = null;
    }
  }

  // Keeps the dragon-cemetery reskin painted on room navigations / React remounts while
  // there is no active battle instance to run startPersistentVisualSync — i.e. the brief
  // window before the villains spawn on entry, and the whole post-battle talk window.
  function startDraconiaSceneSync() {
    stopDraconiaSceneSync();
    const paint = () => {
      if (playerEnteredDraconiaTower
        && !draconiaTowerBattle
        && isOnRoomByName(DRACONIA_BATTLE_ROOM_NAME)) {
        applyDraconiaTileMutations();
        if (draconiaTowerPostBattle) {
          // Keep the board empty for the whole post-battle window — the only thing
          // standing should be the Old Dragonlord NPC overlay. Guards against a room
          // reload dropping the player's saved team back onto the tiles.
          clearDraconiaBoardPieces();
          updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
        }
      }
    };
    paint();
    const deadline = (typeof performance !== 'undefined' ? performance.now() : Date.now()) + 800;
    const rafPaint = () => {
      if (!playerEnteredDraconiaTower) return;
      paint();
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
      if (now < deadline && typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    };
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    [150, 400, 900, 1600].forEach((d) => setTimeout(paint, d));
    if (!globalThis.state?.board?.subscribe) return;
    draconiaTowerSceneSub = globalThis.state.board.subscribe(() => {
      if (!playerEnteredDraconiaTower) {
        stopDraconiaSceneSync();
        return;
      }
      paint();
    });
  }

  function restoreBoardSetupDraconia() {
    if (draconiaTowerBattle) draconiaTowerBattle.restoreBoardSetup();
    restoreDraconiaTileMutations();
  }

  function cleanupDraconiaTowerQuest() {
    try {
      removeCustomBattleStatusToast();
      stopDraconiaSceneSync();
      oldDragonlordBossHpBar.remove();
      playerEnteredDraconiaTower = false;
      draconiaTowerPostBattle = false;
      restoreDraconiaTileMutations();
      if (draconiaTowerBattle) {
        draconiaTowerBattle.cleanup(restoreBoardSetupDraconia, showQuestOverlays);
        draconiaTowerBattle = null;
        console.log(`${getDraconiaLogPrefix()} Battle cleaned up`);
      }
      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    } catch (error) {
      console.error(`${getDraconiaLogPrefix()} Error cleaning up:`, error);
    }
  }

  // Victory: tear down the fight but stay in the room. An Old Dragonlord places as a
  // board NPC on tile 80 (post-battle talk); the dragon-cemetery reskin keeps painting
  // via the scene sync. Deliberately does NOT restoreDraconiaTileMutations() — the reskin
  // must stay up while the player talks to the old one.
  // Wipe every piece (defeated villains + the player's surviving allies) off the board so
  // the only thing left standing after victory is the Old Dragonlord board NPC.
  function clearDraconiaBoardPieces() {
    try {
      const cfg = globalThis.state?.board?.getSnapshot?.()?.context?.boardConfig;
      if (!Array.isArray(cfg) || cfg.length === 0) return;
      globalThis.state.board.send({
        type: 'setState',
        fn: (prev) => ({ ...prev, boardConfig: [] })
      });
    } catch (_) {}
  }

  function enterDraconiaTowerPostBattle() {
    draconiaTowerPostBattle = true;
    oldDragonlordBossHpBar.remove();
    if (draconiaTowerBattle) {
      draconiaTowerBattle.cleanup(
        () => { if (draconiaTowerBattle) draconiaTowerBattle.restoreBoardSetup(); },
        showQuestOverlays
      );
      draconiaTowerBattle = null;
    }
    removeCustomBattleStatusToast();
    // Order matters: clear ALL ally/villain pieces first, THEN place the ally NPC, so the
    // NPC never has to fight the board framework re-adding pieces underneath it.
    clearDraconiaBoardPieces();
    startDraconiaSceneSync();
    updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    showToast({
      message: getMissionDialogueLine(
        DRACONIA_TOWER_MISSION,
        'battleVictory',
        'The guardians are down. Speak with the Old Dragonlord among the bones.'
      ),
      logPrefix: getDraconiaLogPrefix()
    });
  }

  function createDraconiaTowerBattleInstance(roomId) {
    if (!window.CustomBattles) {
      console.error(`${getDraconiaLogPrefix()} CustomBattles still not available`);
      return null;
    }
    const spawn = getHydratedQuestBattleSpawn(DRACONIA_BATTLE_ID || 'draconia_tower');
    const villains = spawn.villains;
    const tileRestrictions = {};
    if (spawn.allowedTiles?.length) {
      tileRestrictions.allowedTiles = spawn.allowedTiles;
      tileRestrictions.message = spawn.allowedTilesMessage || 'Ally creatures can only be placed on the marked tiles!';
    }
    const config = {
      name: DRACONIA_BATTLE_DISPLAY_NAME || 'Draconia Tower',
      roomId,
      villains,
      allyLimit: spawn.allyLimit ?? 6,
      preventVillainMovement: spawn.preventVillainMovement !== false,
      hideVillainSprites: spawn.hideVillainSprites !== false,
      ...(Object.keys(tileRestrictions).length ? { tileRestrictions } : {}),
      activationCheck: (isSandbox, inBattleArea) => isSandbox && inBattleArea && playerEnteredDraconiaTower,
      victoryDefeat: {
        onVictory: async () => {
          console.log(`${getDraconiaLogPrefix()} Dragon Lord and beast defeated`);
          try {
            await persistMissionProgress(DRACONIA_TOWER_MISSION, {
              accepted: true,
              completed: false,
              battleCompleted: true
            });
          } catch (error) {
            console.error(`${getDraconiaLogPrefix()} Error saving battleCompleted flag:`, error);
          }
        },
        onDefeat: () => {},
        // No reloadRoomOnClose — the room stays as-is (reskin already painted) and we
        // just hand over to the post-battle talk. A reload/bounce would race the
        // room-leave cleanup handler and drop the post-battle state.
        onClose: (isVictory) => {
          if (isVictory) {
            // Stay in the cemetery — hand over to the post-battle talk with the old one.
            enterDraconiaTowerPostBattle();
          } else {
            cleanupDraconiaTowerQuest();
            setTimeout(() => navigateToHedgeMazeFromHellgate(), 100);
          }
        },
        victoryTitle: 'Victory!',
        defeatTitle: 'Defeat',
        victoryMessage: getMissionDialogueLine(
          DRACONIA_TOWER_MISSION,
          'battleVictory',
          'The guardians are down and the Old Dragonlord kneels among the bones. Go and speak with him.'
        ),
        defeatMessage: getMissionDialogueLine(
          DRACONIA_TOWER_MISSION,
          'battleDefeat',
          'The dragons of Draconia are not so easily put to rest.'
        ),
        showItems: false,
        items: []
      }
    };
    return window.CustomBattles.create(config);
  }

  function isDraconiaTradePending() {
    const progress = getMissionProgress(DRACONIA_TOWER_MISSION) || {};
    return !!progress.battleCompleted && !progress.dragonfetishReceived && !progress.completed;
  }

  function isDraconiaCompletionPending() {
    const progress = getMissionProgress(DRACONIA_TOWER_MISSION) || {};
    return !!progress.dragonfetishReceived && !progress.completed;
  }

  async function completeDraconiaTowerMission() {
    const progress = getMissionProgress(DRACONIA_TOWER_MISSION) || {};
    if (progress.completed) return false;
    try {
      await persistMissionProgress(DRACONIA_TOWER_MISSION, {
        accepted: true,
        completed: true,
        battleCompleted: true,
        dragonfetishReceived: true
      });
      NotificationService.showQuestCompleted(DRACONIA_TOWER_MISSION, getDraconiaLogPrefix(), {
        productName: 'Dragonfetish'
      });
      console.log(`${getDraconiaLogPrefix()} Mission completed`);
      return true;
    } catch (error) {
      console.error(`${getDraconiaLogPrefix()} Error completing mission:`, error);
      return false;
    }
  }

  function initializeDraconiaTowerBattle(roomId) {
    if (window.CustomBattles) return createDraconiaTowerBattleInstance(roomId);
    return waitForCustomBattles({ logPrefix: getDraconiaLogPrefix() }).then((api) => {
      if (!api) return null;
      return createDraconiaTowerBattleInstance(roomId);
    });
  }

  function setupDraconiaTowerBattleInstance(battle) {
    if (!battle) return false;
    draconiaTowerBattle = battle;
    stopDraconiaSceneSync();
    draconiaTowerBattle.setup(
      () => playerEnteredDraconiaTower,
      NotificationService.createBattleToastCallback(getDraconiaLogPrefix())
    );
    draconiaTowerBattle.resetSandboxBattleState();
    draconiaTowerBattle.setupTileRestrictions(
      () => playerEnteredDraconiaTower,
      NotificationService.createBattleToastCallback(getDraconiaLogPrefix())
    );
    draconiaTowerBattle.setupAllyLimit?.(
      () => playerEnteredDraconiaTower,
      NotificationService.createBattleToastCallback(getDraconiaLogPrefix())
    );
    showCustomBattleStatusToast({
      battleName: DRACONIA_BATTLE_DISPLAY_NAME || 'Draconia Tower',
      allyLimit: battle.config?.allyLimit ?? 6,
      battle,
      logPrefix: getDraconiaLogPrefix()
    });
    draconiaTowerBattle.scheduleEntryVillainSetup({
      attemptDelays: [0, 100, 250, 500, 800, 1200],
      isActiveCheck: () => playerEnteredDraconiaTower,
      onComplete: () => {
        hideQuestOverlays();
        hideHeroEditorButton();
        draconiaTowerBattle.startPersistentVisualSync(applyDraconiaTileMutations, {
          isActiveCheck: () => playerEnteredDraconiaTower
        });
      }
    });
    return true;
  }

  function enterDraconiaTower() {
    let roomId = DRACONIA_BATTLE_ROOM_ID || getRoomIdByRoomName(DRACONIA_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(DRACONIA_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'Draconia Tower could not be found.', logPrefix: getDraconiaLogPrefix() });
      return;
    }

    playerEnteredDraconiaTower = true;
    draconiaTowerPostBattle = false;
    if (draconiaTowerBattle) {
      draconiaTowerBattle.cleanup(restoreBoardSetupDraconia, showQuestOverlays);
      draconiaTowerBattle = null;
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    startDraconiaSceneSync();

    const initResult = initializeDraconiaTowerBattle(roomId);
    if (initResult && typeof initResult.then === 'function') {
      initResult.then((battle) => {
        if (playerEnteredDraconiaTower && !draconiaTowerPostBattle && !draconiaTowerBattle) {
          setupDraconiaTowerBattleInstance(battle);
        }
      }).catch((error) => console.error(`${getDraconiaLogPrefix()} Error initializing battle:`, error));
    } else if (initResult) {
      setupDraconiaTowerBattleInstance(initResult);
    }

    updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    showToast({ message: 'Following Elathriel down into Draconia Tower...', logPrefix: getDraconiaLogPrefix() });
  }

  // Battle already won (progress.battleCompleted) but mission not finished — Elathriel
  // sends the player straight back to the post-battle cemetery scene: reskin + the ally
  // Old Dragonlord NPC, NO fight. The scene sync keeps the board clear and the NPC placed.
  function enterDraconiaTowerPostBattleReturn() {
    let roomId = DRACONIA_BATTLE_ROOM_ID || getRoomIdByRoomName(DRACONIA_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'Draconia Tower could not be found.', logPrefix: getDraconiaLogPrefix() });
      return;
    }
    playerEnteredDraconiaTower = true;
    draconiaTowerPostBattle = true;
    oldDragonlordBossHpBar.remove();
    if (draconiaTowerBattle) {
      draconiaTowerBattle.cleanup(restoreBoardSetupDraconia, showQuestOverlays);
      draconiaTowerBattle = null;
    }
    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    startDraconiaSceneSync();
    clearDraconiaBoardPieces();
    hideQuestOverlays();
    hideHeroEditorButton();
    updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    showToast({ message: 'Following Elathriel back down into Draconia Tower...', logPrefix: getDraconiaLogPrefix() });
  }

  function getOldDragonlordKeywordResponse(message, playerName) {
    return matchKeywordResponsesSync(OLD_DRAGONLORD_RESPONSES, message, playerName, {
      defaultResponse: null,
      lowercaseKeys: true
    });
  }

  function needsAlDeeRookieGuardObserver() {
    return isMissionAcceptedIncomplete(getMissionProgress(AL_DEE_ROOKIE_GUARD_MISSION));
  }

  // =======================
  // Draconia Quest (Elathriel — the final step after Draconia Tower. Chat-triggered
  // teleport into the Sewers, re-skinned for one last battle. The full villain roster
  // spawns on entry. On victory the player "uses" the Dragonfetish (consumed) and is
  // returned to Hedge Maze, where Elathriel closes the mission and grants the
  // Key to Magic (Book).
  // Mirrors the Draconia Tower flow minus the post-battle board NPC / trade.)
  // =======================

  function getDraconiaQuestLogPrefix() {
    return '[Quests Mod][Draconia Quest]';
  }

  // Elathriel "follows" the player into the last room, so a purely decorative south-facing
  // copy of him stands on tile 36 for the whole battle with a green name tag above him —
  // same trick as ensureHellgateElathrielDummy(). Right-clicking him works through
  // draconiaQuestElathrielSignReader (createSignReaderSystem), the same nudge mechanism the
  // Hellgate Part 1 dummy uses. Tagged QUEST_BOARD_ADDED_ATTR_DRACONIA_QUEST so
  // restoreDraconiaQuestTileMutations() tears it (and its name tag) down.
  const DRACONIA_QUEST_ELATHRIEL_DUMMY_TILE_INDEX = 36;
  const DRACONIA_QUEST_ELATHRIEL_DUMMY_ATTR = 'data-quests-draconia-quest-elathriel-dummy';
  const DRACONIA_QUEST_ELATHRIEL_DUMMY_NAME_TAG_CLASS = 'quests-draconia-quest-elathriel-dummy-name-tag';

  function ensureDraconiaQuestElathrielDummyNameTag(tileElement) {
    let nameTag = document.querySelector(`.${DRACONIA_QUEST_ELATHRIEL_DUMMY_NAME_TAG_CLASS}`);
    if (!nameTag) {
      nameTag = document.createElement('span');
      nameTag.className = `${DRACONIA_QUEST_ELATHRIEL_DUMMY_NAME_TAG_CLASS} revert-pixel-font-spacing pointer-events-none absolute flex w-[192px] flex-col items-center`;
      nameTag.style.cssText = [
        'position:absolute',
        'user-select:none',
        `z-index:${QUEST_FIGHT_ICON_Z_INDEX}`,
        'pointer-events:none',
        'line-height:1'
      ].join(';');
      nameTag.setAttribute(QUEST_BOARD_ADDED_ATTR_DRACONIA_QUEST, '1');

      const nameLine = document.createElement('span');
      nameLine.setAttribute('translate', 'no');
      nameLine.className = 'select-none text-center pixel-font-16 text-whiteHighlight';
      nameLine.style.cssText = 'line-height:1;font-size:16px;display:inline-flex;align-items:center;';
      const nameText = document.createElement('span');
      nameText.className = 'text-whiteHighlight';
      nameText.style.cssText = 'color:rgb(96, 192, 96);text-shadow:-1px 0 #000,1px 0 #000,0 -1px #000,0 1px #000;';
      nameText.textContent = getMissionDialogueLine(DRACONIA_QUEST_MISSION, 'companionName', 'Elathriel');
      nameLine.appendChild(nameText);
      nameTag.appendChild(nameLine);
    }
    positionBoardNpcNameTag(nameTag, tileElement);
  }

  function ensureDraconiaQuestElathrielDummy() {
    const tile = getTileElement(DRACONIA_QUEST_ELATHRIEL_DUMMY_TILE_INDEX);
    if (!tile) return;
    if (!tile.querySelector(`[${DRACONIA_QUEST_ELATHRIEL_DUMMY_ATTR}="1"]`)) {
      const outfitSpriteId = ELATHRIEL_OUTFIT_SPRITE_ID || '64';
      const wrap = document.createElement('div');
      wrap.innerHTML = `<div class="sprite outfit id-${outfitSpriteId} idle south pointer-events-none absolute bottom-0 right-0 select-none" ${QUEST_BOARD_ADDED_ATTR_DRACONIA_QUEST}="1" ${DRACONIA_QUEST_ELATHRIEL_DUMMY_ATTR}="1" style="z-index: 1000;"><div class="viewport"><img alt="south" class="actor spritesheet" data-shiny="false" style="animation-play-state: running;"></div></div>`;
      if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
    }
    ensureDraconiaQuestElathrielDummyNameTag(tile);
  }

  function buildDraconiaQuestMutationSpriteHTML(entry, mutationKey) {
    const spriteId = entry?.spriteId;
    if (spriteId == null) return '';
    const cropX = entry.cropX != null ? entry.cropX : 0;
    const cropY = entry.cropY != null ? entry.cropY : 0;
    const cropped = entry.cropped ? 'true' : 'false';
    const bankStyle = entry.bank != null ? ` --bank: ${entry.bank};` : '';
    const rightCalc = formatHellgateMutationOffsetCalc(entry.offsetX);
    const bottomCalc = formatHellgateMutationOffsetCalc(entry.offsetY);
    const offsetStyle = `${rightCalc ? ` right: ${rightCalc};` : ''}${bottomCalc ? ` bottom: ${bottomCalc};` : ''}`;
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_DRACONIA_QUEST}="1" data-quests-draconia-quest-mutation-key="${mutationKey}" style="z-index: 1000;${bankStyle}${offsetStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
  }

  function applyDraconiaQuestTileMutations() {
    const mutations = DRACONIA_QUEST_TILE_MUTATIONS;
    if (!mutations || typeof mutations !== 'object') return;
    let wroteHitboxes = false;
    Object.entries(mutations).forEach(([tileKey, entry]) => {
      const tileIndex = Number(tileKey);
      if (!Number.isFinite(tileIndex) || !entry || typeof entry !== 'object') return;
      const tile = getTileElement(tileIndex);

      (entry.remove || []).forEach((spriteId) => {
        if (spriteId == null || !tile) return;
        tile.querySelectorAll(`.sprite.item.relative.id-${spriteId}`).forEach((sprite) => {
          hideQuestBoardElement(sprite, { tag: QUEST_BOARD_HIDDEN_TAG_DRACONIA_QUEST });
        });
      });

      (entry.add || []).forEach((spriteEntry, spriteIndex) => {
        const spriteId = spriteEntry?.spriteId;
        if (spriteId == null || !tile) return;
        const mutationKey = `${tileIndex}-${spriteIndex}`;
        if (tile.querySelector(`[data-quests-draconia-quest-mutation-key="${mutationKey}"]`)) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = buildDraconiaQuestMutationSpriteHTML(spriteEntry, mutationKey);
        if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
      });

      if (Array.isArray(entry.floorBelow) && entry.floorBelow.length) {
        applyQuestFloorBelowSprites(
          tileIndex, entry.floorBelow, QUEST_BOARD_ADDED_ATTR_DRACONIA_QUEST, 'data-quests-draconia-quest-fb-key'
        );
      }

      if (Object.prototype.hasOwnProperty.call(entry, 'hitbox')) {
        try {
          getHellgateRoomRefs().forEach((room) => {
            const data = room?.file?.data;
            if (!data) return;
            if (!Array.isArray(data.hitboxes)) data.hitboxes = [];
            data.hitboxes[tileIndex] = entry.hitbox === true;
            wroteHitboxes = true;
          });
        } catch (_) {}
      }
    });

    if (wroteHitboxes) draconiaQuestHitboxesApplied = true;

    ensureDraconiaQuestElathrielDummy();

    const battle = draconiaQuestBattle;
    if (battle?.refreshPlacementHitboxMaskFromLive) {
      battle.refreshPlacementHitboxMaskFromLive(() => playerEnteredDraconiaQuest);
    } else if (battle?.syncPlacementHitboxMask) {
      battle.syncPlacementHitboxMask(() => playerEnteredDraconiaQuest);
    }
  }

  function restoreDraconiaQuestTileMutations() {
    restoreQuestBoardElementsByTag(QUEST_BOARD_HIDDEN_TAG_DRACONIA_QUEST);
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_DRACONIA_QUEST}="1"]`).forEach((el) => {
      try { el.remove(); } catch (_) {}
    });
    draconiaQuestHitboxesApplied = false;
    draconiaQuestElathrielSignReader.resetRead();
  }

  function stopDraconiaQuestSceneSync() {
    if (draconiaQuestSceneSub) {
      try { draconiaQuestSceneSub.unsubscribe?.(); } catch (_) {}
      draconiaQuestSceneSub = null;
    }
  }

  function startDraconiaQuestSceneSync() {
    stopDraconiaQuestSceneSync();
    const paint = () => {
      if (playerEnteredDraconiaQuest
        && !draconiaQuestBattle
        && isOnRoomByName(DRACONIA_QUEST_BATTLE_ROOM_NAME)) {
        applyDraconiaQuestTileMutations();
      }
    };
    paint();
    const deadline = (typeof performance !== 'undefined' ? performance.now() : Date.now()) + 800;
    const rafPaint = () => {
      if (!playerEnteredDraconiaQuest) return;
      paint();
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
      if (now < deadline && typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    };
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    [150, 400, 900, 1600].forEach((d) => setTimeout(paint, d));
    if (!globalThis.state?.board?.subscribe) return;
    draconiaQuestSceneSub = globalThis.state.board.subscribe(() => {
      if (!playerEnteredDraconiaQuest) {
        stopDraconiaQuestSceneSync();
        return;
      }
      paint();
    });
  }

  function restoreBoardSetupDraconiaQuest() {
    if (draconiaQuestBattle) draconiaQuestBattle.restoreBoardSetup();
    restoreDraconiaQuestTileMutations();
  }

  function cleanupDraconiaQuestQuest() {
    try {
      removeCustomBattleStatusToast();
      stopDraconiaQuestSceneSync();
      playerEnteredDraconiaQuest = false;
      restoreDraconiaQuestTileMutations();
      if (draconiaQuestBattle) {
        draconiaQuestBattle.cleanup(restoreBoardSetupDraconiaQuest, showQuestOverlays);
        draconiaQuestBattle = null;
        console.log(`${getDraconiaQuestLogPrefix()} Battle cleaned up`);
      }
      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    } catch (error) {
      console.error(`${getDraconiaQuestLogPrefix()} Error cleaning up:`, error);
    }
  }

  function isDraconiaQuestCompletionPending() {
    const progress = getMissionProgress(DRACONIA_QUEST_MISSION) || {};
    return !!progress.battleCompleted && !progress.completed;
  }

  function getDraconiaQuestRewardItemName() {
    return getMissionRewardItemName(DRACONIA_QUEST_MISSION, 'keyToMagicBook') || 'Key to Magic (Book)';
  }

  async function grantDraconiaQuestReward() {
    const itemName = getDraconiaQuestRewardItemName();
    try {
      await addQuestItem(itemName, 1);
      showQuestItemNotification(itemName, 1);
      console.log(`${getDraconiaQuestLogPrefix()} Granted reward item:`, itemName);
    } catch (error) {
      console.error(`${getDraconiaQuestLogPrefix()} Error granting reward item:`, error);
    }
  }

  async function completeDraconiaQuestMission() {
    const progress = getMissionProgress(DRACONIA_QUEST_MISSION) || {};
    if (progress.completed) return false;
    const rewardItemName = getDraconiaQuestRewardItemName();
    try {
      await persistMissionProgress(DRACONIA_QUEST_MISSION, {
        accepted: true,
        completed: true,
        battleCompleted: true
      });
      await grantDraconiaQuestReward();
      // Belt-and-suspenders: the Dragonfetish should already have been consumed on the
      // victory return, but drop any leftover copy now that the quest is closed. Also
      // clear Key 3012 — the whole Elathriel chain (Hellgate -> Library -> Draconia) is
      // finished, so it has no further use (itemLifecycle.staleCleanupOnComplete covers
      // this too, on the next inventory sync).
      try { await consumeQuestItem('Dragonfetish', 1); } catch (_) {}
      try { await consumeQuestItem('Key 3012', 1); } catch (_) {}
      NotificationService.showQuestCompleted(DRACONIA_QUEST_MISSION, getDraconiaQuestLogPrefix(), { productName: rewardItemName });
      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
      console.log(`${getDraconiaQuestLogPrefix()} Mission completed`);
      return true;
    } catch (error) {
      console.error(`${getDraconiaQuestLogPrefix()} Error completing mission:`, error);
      return false;
    }
  }

  // Victory: the player "uses" the Dragonfetish — it is consumed and carries them back to
  // Hedge Maze, where Elathriel closes the quest.
  async function returnFromDraconiaQuestWithDragonfetish() {
    try {
      await consumeQuestItem('Dragonfetish', 1);
    } catch (error) {
      console.error(`${getDraconiaQuestLogPrefix()} Error consuming Dragonfetish:`, error);
    }
    showToast({
      message: 'You raise the Dragonfetish — and Draconia falls away around you. Speak with Elathriel.',
      logPrefix: getDraconiaQuestLogPrefix()
    });
    cleanupDraconiaQuestQuest();
    setTimeout(() => navigateToHedgeMazeFromHellgate(), 100);
  }

  function createDraconiaQuestBattleInstance(roomId) {
    if (!window.CustomBattles) {
      console.error(`${getDraconiaQuestLogPrefix()} CustomBattles still not available`);
      return null;
    }
    const spawn = getHydratedQuestBattleSpawn(DRACONIA_QUEST_BATTLE_ID || 'draconia_quest');
    const villains = spawn.villains;
    const tileRestrictions = {};
    if (spawn.allowedTiles?.length) {
      tileRestrictions.allowedTiles = spawn.allowedTiles;
      tileRestrictions.message = spawn.allowedTilesMessage || 'Ally creatures can only be placed on the marked tiles!';
    }
    const config = {
      name: DRACONIA_QUEST_BATTLE_DISPLAY_NAME || 'Draconia Quest',
      roomId,
      villains,
      allyLimit: spawn.allyLimit ?? 5,
      preventVillainMovement: spawn.preventVillainMovement !== false,
      hideVillainSprites: spawn.hideVillainSprites !== false,
      ...(Object.keys(tileRestrictions).length ? { tileRestrictions } : {}),
      activationCheck: (isSandbox, inBattleArea) => isSandbox && inBattleArea && playerEnteredDraconiaQuest,
      victoryDefeat: {
        onVictory: async () => {
          console.log(`${getDraconiaQuestLogPrefix()} Final room cleared`);
          try {
            await persistMissionProgress(DRACONIA_QUEST_MISSION, {
              accepted: true,
              completed: false,
              battleCompleted: true
            });
          } catch (error) {
            console.error(`${getDraconiaQuestLogPrefix()} Error saving battleCompleted flag:`, error);
          }
        },
        onDefeat: () => {},
        onClose: (isVictory) => {
          if (isVictory) {
            returnFromDraconiaQuestWithDragonfetish();
          } else {
            cleanupDraconiaQuestQuest();
            setTimeout(() => navigateToHedgeMazeFromHellgate(), 100);
          }
        },
        victoryTitle: 'Victory!',
        defeatTitle: 'Defeat',
        victoryMessage: getMissionDialogueLine(
          DRACONIA_QUEST_MISSION,
          'battleVictory',
          'The last room is clear. Use the Dragonfetish — it will take you back to the maze.'
        ),
        defeatMessage: getMissionDialogueLine(
          DRACONIA_QUEST_MISSION,
          'battleDefeat',
          'The deep room is not yet yours. Gather yourself and go down again.'
        ),
        showItems: false,
        items: []
      }
    };
    return window.CustomBattles.create(config);
  }

  function initializeDraconiaQuestBattle(roomId) {
    if (window.CustomBattles) return createDraconiaQuestBattleInstance(roomId);
    return waitForCustomBattles({ logPrefix: getDraconiaQuestLogPrefix() }).then((api) => {
      if (!api) return null;
      return createDraconiaQuestBattleInstance(roomId);
    });
  }

  function setupDraconiaQuestBattleInstance(battle) {
    if (!battle) return false;
    draconiaQuestBattle = battle;
    stopDraconiaQuestSceneSync();
    draconiaQuestBattle.setup(
      () => playerEnteredDraconiaQuest,
      NotificationService.createBattleToastCallback(getDraconiaQuestLogPrefix())
    );
    draconiaQuestBattle.resetSandboxBattleState();
    draconiaQuestBattle.setupTileRestrictions(
      () => playerEnteredDraconiaQuest,
      NotificationService.createBattleToastCallback(getDraconiaQuestLogPrefix())
    );
    draconiaQuestBattle.setupAllyLimit?.(
      () => playerEnteredDraconiaQuest,
      NotificationService.createBattleToastCallback(getDraconiaQuestLogPrefix())
    );
    showCustomBattleStatusToast({
      battleName: DRACONIA_QUEST_BATTLE_DISPLAY_NAME || 'Draconia Quest',
      allyLimit: battle.config?.allyLimit ?? 5,
      battle,
      logPrefix: getDraconiaQuestLogPrefix()
    });
    draconiaQuestBattle.scheduleEntryVillainSetup({
      attemptDelays: [0, 100, 250, 500, 800, 1200],
      isActiveCheck: () => playerEnteredDraconiaQuest,
      onComplete: () => {
        hideQuestOverlays();
        hideHeroEditorButton();
        draconiaQuestBattle.startPersistentVisualSync(applyDraconiaQuestTileMutations, {
          isActiveCheck: () => playerEnteredDraconiaQuest
        });
      }
    });
    return true;
  }

  function enterDraconiaQuest() {
    let roomId = DRACONIA_QUEST_BATTLE_ROOM_ID || getRoomIdByRoomName(DRACONIA_QUEST_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(DRACONIA_QUEST_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'The final room in Draconia could not be found.', logPrefix: getDraconiaQuestLogPrefix() });
      return;
    }

    playerEnteredDraconiaQuest = true;
    draconiaQuestElathrielSignReader.resetRead();
    if (draconiaQuestBattle) {
      draconiaQuestBattle.cleanup(restoreBoardSetupDraconiaQuest, showQuestOverlays);
      draconiaQuestBattle = null;
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    startDraconiaQuestSceneSync();

    const initResult = initializeDraconiaQuestBattle(roomId);
    if (initResult && typeof initResult.then === 'function') {
      initResult.then((battle) => {
        if (playerEnteredDraconiaQuest && !draconiaQuestBattle) {
          setupDraconiaQuestBattleInstance(battle);
        }
      }).catch((error) => console.error(`${getDraconiaQuestLogPrefix()} Error initializing battle:`, error));
    } else if (initResult) {
      setupDraconiaQuestBattleInstance(initResult);
    }

    updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    showToast({ message: 'Following Elathriel down into the last room of Draconia...', logPrefix: getDraconiaQuestLogPrefix() });
  }

  // =======================
  // Access the Realm of Dreams (Tesha — the Key to Magic. Chat-triggered teleport into
  // the Sewers, re-skinned as the burning Northern Dragon Lair. Saying "yes" drops the
  // player into the battle; the Key to Magic (Book) is consumed on victory, after which
  // they return to Darama Oasis and Tesha closes the mission for Chayenne's Magical Key
  // (used by a later quest to actually reach Chayenne). Mirrors the Draconia Quest flow
  // minus the companion NPC.)
  // =======================

  function getRealmOfDreamsLogPrefix() {
    return '[Quests Mod][Realm of Dreams]';
  }

  function buildRealmOfDreamsMutationSpriteHTML(entry, mutationKey) {
    const spriteId = entry?.spriteId;
    if (spriteId == null) return '';
    const cropX = entry.cropX != null ? entry.cropX : 0;
    const cropY = entry.cropY != null ? entry.cropY : 0;
    const cropped = entry.cropped ? 'true' : 'false';
    const bankStyle = entry.bank != null ? ` --bank: ${entry.bank};` : '';
    const rightCalc = formatHellgateMutationOffsetCalc(entry.offsetX);
    const bottomCalc = formatHellgateMutationOffsetCalc(entry.offsetY);
    const offsetStyle = `${rightCalc ? ` right: ${rightCalc};` : ''}${bottomCalc ? ` bottom: ${bottomCalc};` : ''}`;
    return `<div class="sprite item relative id-${spriteId}" ${QUEST_BOARD_ADDED_ATTR_REALM_OF_DREAMS}="1" data-quests-realm-of-dreams-mutation-key="${mutationKey}" style="z-index: 1000;${bankStyle}${offsetStyle}"><div class="viewport"><img alt="${spriteId}" data-cropped="${cropped}" class="spritesheet" style="--cropX: ${cropX}; --cropY: ${cropY};"></div></div>`;
  }

  function applyRealmOfDreamsTileMutations() {
    const mutations = REALM_OF_DREAMS_TILE_MUTATIONS;
    if (!mutations || typeof mutations !== 'object') return;
    let wroteHitboxes = false;
    Object.entries(mutations).forEach(([tileKey, entry]) => {
      const tileIndex = Number(tileKey);
      if (!Number.isFinite(tileIndex) || !entry || typeof entry !== 'object') return;
      const tile = getTileElement(tileIndex);

      (entry.remove || []).forEach((spriteId) => {
        if (spriteId == null || !tile) return;
        tile.querySelectorAll(`.sprite.item.relative.id-${spriteId}`).forEach((sprite) => {
          hideQuestBoardElement(sprite, { tag: QUEST_BOARD_HIDDEN_TAG_REALM_OF_DREAMS });
        });
      });

      (entry.add || []).forEach((spriteEntry, spriteIndex) => {
        const spriteId = spriteEntry?.spriteId;
        if (spriteId == null || !tile) return;
        const mutationKey = `${tileIndex}-${spriteIndex}`;
        if (tile.querySelector(`[data-quests-realm-of-dreams-mutation-key="${mutationKey}"]`)) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = buildRealmOfDreamsMutationSpriteHTML(spriteEntry, mutationKey);
        if (wrap.firstElementChild) tile.appendChild(wrap.firstElementChild);
      });

      if (Array.isArray(entry.floorBelow) && entry.floorBelow.length) {
        applyQuestFloorBelowSprites(
          tileIndex, entry.floorBelow, QUEST_BOARD_ADDED_ATTR_REALM_OF_DREAMS, 'data-quests-realm-of-dreams-fb-key'
        );
      }

      if (Object.prototype.hasOwnProperty.call(entry, 'hitbox')) {
        try {
          getHellgateRoomRefs().forEach((room) => {
            const data = room?.file?.data;
            if (!data) return;
            if (!Array.isArray(data.hitboxes)) data.hitboxes = [];
            data.hitboxes[tileIndex] = entry.hitbox === true;
            wroteHitboxes = true;
          });
        } catch (_) {}
      }
    });

    if (wroteHitboxes) realmOfDreamsHitboxesApplied = true;

    const battle = realmOfDreamsBattle;
    if (battle?.refreshPlacementHitboxMaskFromLive) {
      battle.refreshPlacementHitboxMaskFromLive(() => playerEnteredRealmOfDreams);
    } else if (battle?.syncPlacementHitboxMask) {
      battle.syncPlacementHitboxMask(() => playerEnteredRealmOfDreams);
    }
  }

  function restoreRealmOfDreamsTileMutations() {
    restoreQuestBoardElementsByTag(QUEST_BOARD_HIDDEN_TAG_REALM_OF_DREAMS);
    document.querySelectorAll(`[${QUEST_BOARD_ADDED_ATTR_REALM_OF_DREAMS}="1"]`).forEach((el) => {
      try { el.remove(); } catch (_) {}
    });
    realmOfDreamsHitboxesApplied = false;
  }

  function stopRealmOfDreamsSceneSync() {
    if (realmOfDreamsSceneSub) {
      try { realmOfDreamsSceneSub.unsubscribe?.(); } catch (_) {}
      realmOfDreamsSceneSub = null;
    }
  }

  function startRealmOfDreamsSceneSync() {
    stopRealmOfDreamsSceneSync();
    const paint = () => {
      if (playerEnteredRealmOfDreams
        && !realmOfDreamsBattle
        && isOnRoomByName(REALM_OF_DREAMS_BATTLE_ROOM_NAME)) {
        applyRealmOfDreamsTileMutations();
      }
    };
    paint();
    const deadline = (typeof performance !== 'undefined' ? performance.now() : Date.now()) + 800;
    const rafPaint = () => {
      if (!playerEnteredRealmOfDreams) return;
      paint();
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
      if (now < deadline && typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    };
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(rafPaint);
    [150, 400, 900, 1600].forEach((d) => setTimeout(paint, d));
    if (!globalThis.state?.board?.subscribe) return;
    realmOfDreamsSceneSub = globalThis.state.board.subscribe(() => {
      if (!playerEnteredRealmOfDreams) {
        stopRealmOfDreamsSceneSync();
        return;
      }
      paint();
    });
  }

  function restoreBoardSetupRealmOfDreams() {
    if (realmOfDreamsBattle) realmOfDreamsBattle.restoreBoardSetup();
    restoreRealmOfDreamsTileMutations();
  }

  function cleanupRealmOfDreamsQuest() {
    try {
      removeCustomBattleStatusToast();
      stopRealmOfDreamsSceneSync();
      playerEnteredRealmOfDreams = false;
      restoreRealmOfDreamsTileMutations();
      if (realmOfDreamsBattle) {
        realmOfDreamsBattle.cleanup(restoreBoardSetupRealmOfDreams, showQuestOverlays);
        realmOfDreamsBattle = null;
        console.log(`${getRealmOfDreamsLogPrefix()} Battle cleaned up`);
      }
      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    } catch (error) {
      console.error(`${getRealmOfDreamsLogPrefix()} Error cleaning up:`, error);
    }
  }

  function isRealmOfDreamsCompletionPending() {
    const progress = getMissionProgress(REALM_OF_DREAMS_MISSION) || {};
    return !!progress.battleCompleted && !progress.completed;
  }

  function getRealmOfDreamsRewardItemName() {
    return getMissionRewardItemName(REALM_OF_DREAMS_MISSION, 'chayennesMagicalKey') || "Chayenne's Magical Key";
  }

  async function grantRealmOfDreamsReward() {
    const itemName = getRealmOfDreamsRewardItemName();
    try {
      await addQuestItem(itemName, 1);
      showQuestItemNotification(itemName, 1);
      console.log(`${getRealmOfDreamsLogPrefix()} Granted reward item:`, itemName);
    } catch (error) {
      console.error(`${getRealmOfDreamsLogPrefix()} Error granting reward item:`, error);
    }
  }

  async function completeRealmOfDreamsMission() {
    const progress = getMissionProgress(REALM_OF_DREAMS_MISSION) || {};
    if (progress.completed) return false;
    const rewardItemName = getRealmOfDreamsRewardItemName();
    try {
      await persistMissionProgress(REALM_OF_DREAMS_MISSION, {
        accepted: true,
        completed: true,
        battleCompleted: true
      });
      await grantRealmOfDreamsReward();
      // The book was consumed on battle victory; drop any stray copy now the quest is
      // closed (itemLifecycle.staleCleanupOnComplete covers this too on the next sync).
      try { await consumeQuestItem('Key to Magic (Book)', 1); } catch (_) {}
      NotificationService.showQuestCompleted(REALM_OF_DREAMS_MISSION, getRealmOfDreamsLogPrefix(), { productName: rewardItemName });
      updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
      console.log(`${getRealmOfDreamsLogPrefix()} Mission completed`);
      return true;
    } catch (error) {
      console.error(`${getRealmOfDreamsLogPrefix()} Error completing mission:`, error);
      return false;
    }
  }

  function navigateToDaramaOasis() {
    try {
      const roomId = getRoomIdByRoomName(REALM_OF_DREAMS_RETURN_ROOM_NAME);
      if (!roomId) {
        console.warn(`${getRealmOfDreamsLogPrefix()} Darama Oasis room not found`);
        return;
      }
      globalThis.state.board.send({ type: 'selectRoomById', roomId });
    } catch (error) {
      console.error(`${getRealmOfDreamsLogPrefix()} Error navigating to Darama Oasis:`, error);
    }
  }

  function returnFromRealmOfDreams() {
    showToast({
      message: 'You climb up out of the dragon graveyard, the fire behind you dead at last. Speak with Tesha.',
      logPrefix: getRealmOfDreamsLogPrefix()
    });
    cleanupRealmOfDreamsQuest();
    setTimeout(() => navigateToDaramaOasis(), 100);
  }

  function createRealmOfDreamsBattleInstance(roomId) {
    if (!window.CustomBattles) {
      console.error(`${getRealmOfDreamsLogPrefix()} CustomBattles still not available`);
      return null;
    }
    const spawn = getHydratedQuestBattleSpawn(REALM_OF_DREAMS_BATTLE_ID || 'realm_of_dreams');
    const villains = spawn.villains;
    const tileRestrictions = {};
    if (spawn.allowedTiles?.length) {
      tileRestrictions.allowedTiles = spawn.allowedTiles;
      tileRestrictions.message = spawn.allowedTilesMessage || 'Ally creatures can only be placed on the marked tiles!';
    }
    const config = {
      name: REALM_OF_DREAMS_BATTLE_DISPLAY_NAME || 'The Northern Dragon Lair',
      roomId,
      villains,
      allyLimit: spawn.allyLimit ?? 6,
      preventVillainMovement: spawn.preventVillainMovement !== false,
      hideVillainSprites: spawn.hideVillainSprites !== false,
      ...(Object.keys(tileRestrictions).length ? { tileRestrictions } : {}),
      activationCheck: (isSandbox, inBattleArea) => isSandbox && inBattleArea && playerEnteredRealmOfDreams,
      victoryDefeat: {
        onVictory: async () => {
          console.log(`${getRealmOfDreamsLogPrefix()} Fire-path cleared`);
          // The Key to Magic (Book) is spent walking through the fire.
          try { await consumeQuestItem('Key to Magic (Book)', 1); } catch (_) {}
          try {
            await persistMissionProgress(REALM_OF_DREAMS_MISSION, {
              accepted: true,
              completed: false,
              battleCompleted: true
            });
          } catch (error) {
            console.error(`${getRealmOfDreamsLogPrefix()} Error saving battleCompleted flag:`, error);
          }
        },
        onDefeat: () => {},
        onClose: (isVictory) => {
          if (isVictory) {
            returnFromRealmOfDreams();
          } else {
            cleanupRealmOfDreamsQuest();
            setTimeout(() => navigateToDaramaOasis(), 100);
          }
        },
        victoryTitle: 'Victory!',
        defeatTitle: 'Defeat',
        victoryMessage: getMissionDialogueLine(
          REALM_OF_DREAMS_MISSION,
          'battleVictory',
          'The fire among the bones is spent and the way to the Realm of Dreams lies open. Return to Tesha in the Darama Oasis.'
        ),
        defeatMessage: getMissionDialogueLine(
          REALM_OF_DREAMS_MISSION,
          'battleDefeat',
          'The fire in the dragon graveyard is fiercer than the book warned. Gather yourself and go down again.'
        ),
        showItems: false,
        items: []
      }
    };
    return window.CustomBattles.create(config);
  }

  function initializeRealmOfDreamsBattle(roomId) {
    if (window.CustomBattles) return createRealmOfDreamsBattleInstance(roomId);
    return waitForCustomBattles({ logPrefix: getRealmOfDreamsLogPrefix() }).then((api) => {
      if (!api) return null;
      return createRealmOfDreamsBattleInstance(roomId);
    });
  }

  function setupRealmOfDreamsBattleInstance(battle) {
    if (!battle) return false;
    realmOfDreamsBattle = battle;
    stopRealmOfDreamsSceneSync();
    realmOfDreamsBattle.setup(
      () => playerEnteredRealmOfDreams,
      NotificationService.createBattleToastCallback(getRealmOfDreamsLogPrefix())
    );
    realmOfDreamsBattle.resetSandboxBattleState();
    realmOfDreamsBattle.setupTileRestrictions(
      () => playerEnteredRealmOfDreams,
      NotificationService.createBattleToastCallback(getRealmOfDreamsLogPrefix())
    );
    realmOfDreamsBattle.setupAllyLimit?.(
      () => playerEnteredRealmOfDreams,
      NotificationService.createBattleToastCallback(getRealmOfDreamsLogPrefix())
    );
    showCustomBattleStatusToast({
      battleName: REALM_OF_DREAMS_BATTLE_DISPLAY_NAME || 'The Northern Dragon Lair',
      allyLimit: battle.config?.allyLimit ?? 6,
      battle,
      logPrefix: getRealmOfDreamsLogPrefix()
    });
    realmOfDreamsBattle.scheduleEntryVillainSetup({
      attemptDelays: [0, 100, 250, 500, 800, 1200],
      isActiveCheck: () => playerEnteredRealmOfDreams,
      onComplete: () => {
        hideQuestOverlays();
        hideHeroEditorButton();
        realmOfDreamsBattle.startPersistentVisualSync(applyRealmOfDreamsTileMutations, {
          isActiveCheck: () => playerEnteredRealmOfDreams
        });
      }
    });
    return true;
  }

  function enterRealmOfDreams() {
    let roomId = REALM_OF_DREAMS_BATTLE_ROOM_ID || getRoomIdByRoomName(REALM_OF_DREAMS_BATTLE_ROOM_NAME);
    if (!roomId) roomId = getRoomIdByRoomName(REALM_OF_DREAMS_BATTLE_ROOM_NAME);
    if (!roomId) {
      showToast({ message: 'The way down into the Northern Dragon Lair could not be found.', logPrefix: getRealmOfDreamsLogPrefix() });
      return;
    }

    playerEnteredRealmOfDreams = true;
    if (realmOfDreamsBattle) {
      realmOfDreamsBattle.cleanup(restoreBoardSetupRealmOfDreams, showQuestOverlays);
      realmOfDreamsBattle = null;
    }

    globalThis.state.board.send({ type: 'selectRoomById', roomId });
    startRealmOfDreamsSceneSync();

    const initResult = initializeRealmOfDreamsBattle(roomId);
    if (initResult && typeof initResult.then === 'function') {
      initResult.then((battle) => {
        if (playerEnteredRealmOfDreams && !realmOfDreamsBattle) {
          setupRealmOfDreamsBattleInstance(battle);
        }
      }).catch((error) => console.error(`${getRealmOfDreamsLogPrefix()} Error initializing battle:`, error));
    } else if (initResult) {
      setupRealmOfDreamsBattleInstance(initResult);
    }

    updateAllBoardNpcStates(globalThis.state?.board?.getSnapshot()?.context);
    showToast({ message: 'Tesha reads the way — and sends you down into the Northern Dragon Lair, toward the fire among the bones...', logPrefix: getRealmOfDreamsLogPrefix() });
  }

  // ============================================================
  // Easter egg: right-clicking the Spike Sword prop in the Sewers (tile 42) makes it
  // vanish in a puff of red sparkles — a nod to the real Sword of Fury's "disappearing" trick.
  // ============================================================
  const SPIKE_SWORD_TILE_INDEX = 42;
  const SPIKE_SWORD_SPRITE_CLASS = 'id-3271';
  const SPIKE_SWORD_VANISH_EFFECT_URL = 'https://bestiaryarena.com/assets/EFFECT/13.png';
  const SPIKE_SWORD_VANISH_EFFECT_CLASS = 'quests-spike-sword-vanish-effect';
  const SPIKE_SWORD_VANISH_FRAME_MS = 45;
  let spikeSwordEasterEggRightClickEnabled = false;
  let spikeSwordEasterEggBoardSubscription = null;

  function getSpikeSwordSpriteElement() {
    const tileEl = getTileElement(SPIKE_SWORD_TILE_INDEX);
    if (!tileEl) return null;
    return tileEl.querySelector(`.sprite.item.relative.${SPIKE_SWORD_SPRITE_CLASS}`);
  }

  function ensureSpikeSwordVanishEffectStyles() {
    ensureQuestTileSuccessEffectStyles();
    if (document.getElementById('quests-spike-sword-vanish-effect-styles')) return;
    const style = document.createElement('style');
    style.id = 'quests-spike-sword-vanish-effect-styles';
    style.textContent = `
      .${SPIKE_SWORD_VANISH_EFFECT_CLASS} {
        position: absolute;
        right: 0;
        bottom: 0;
        width: calc(32px * var(--zoomFactor, 1));
        height: calc(32px * var(--zoomFactor, 1));
        pointer-events: none;
        z-index: 10005;
        overflow: hidden;
      }
      .${SPIKE_SWORD_VANISH_EFFECT_CLASS} > img {
        display: block;
        width: 100%;
        height: auto;
        image-rendering: pixelated;
      }
    `;
    document.head.appendChild(style);
  }

  function playSpikeSwordVanishEffect(tileElement) {
    if (!tileElement) return;
    ensureSpikeSwordVanishEffectStyles();

    const viewport = document.createElement('div');
    viewport.className = SPIKE_SWORD_VANISH_EFFECT_CLASS;

    const img = document.createElement('img');
    img.alt = '';
    img.draggable = false;
    img.className = 'pixelated';

    const armAnimation = () => {
      const frameWidth = img.naturalWidth || 32;
      const frameCount = Math.max(1, Math.round((img.naturalHeight || frameWidth) / frameWidth));
      const durationMs = frameCount * SPIKE_SWORD_VANISH_FRAME_MS;
      // steps() does not accept CSS variables — set a literal step count inline
      img.style.height = `calc(100% * ${frameCount})`;
      img.style.animation = `quests-tile-success-effect-play ${durationMs}ms steps(${frameCount}, end) 1 forwards`;
      setTimeout(() => {
        if (viewport.parentNode) viewport.remove();
      }, durationMs + 60);
    };

    if (img.complete && img.naturalHeight > 0) {
      armAnimation();
    } else {
      img.addEventListener('load', armAnimation, { once: true });
      img.addEventListener('error', () => {
        console.warn('[Quests Mod][Spike Sword] Vanish effect image failed to load');
        if (viewport.parentNode) viewport.remove();
      }, { once: true });
    }

    img.src = SPIKE_SWORD_VANISH_EFFECT_URL;
    viewport.appendChild(img);
    tileElement.appendChild(viewport);
  }

  function handleSpikeSwordVanishRightClick(event) {
    if (!areQuestHelpersEnabled() || !isOnRoomByName(SEWERS_BATTLE_ROOM_NAME)) return;
    const swordEl = getSpikeSwordSpriteElement();
    if (!swordEl || !swordEl.contains(event.target)) return;

    event.preventDefault();
    event.stopImmediatePropagation();
    event.stopPropagation();

    const tileEl = getTileElement(SPIKE_SWORD_TILE_INDEX);
    playSpikeSwordVanishEffect(tileEl);
    swordEl.remove();
    console.log('[Quests Mod][Spike Sword] The sword vanishes in a puff of red sparkles...');
  }

  function shouldEnableSpikeSwordEasterEgg(boardContext = null) {
    return areQuestHelpersEnabled() && isOnRoomByName(SEWERS_BATTLE_ROOM_NAME);
  }

  function updateSpikeSwordEasterEggState(boardContext = null, retryCount = 0) {
    try {
      const shouldBeEnabled = shouldEnableSpikeSwordEasterEgg(boardContext);
      if (shouldBeEnabled && !spikeSwordEasterEggRightClickEnabled) {
        document.addEventListener('contextmenu', handleSpikeSwordVanishRightClick, true);
        spikeSwordEasterEggRightClickEnabled = true;
      }
      if (!shouldBeEnabled && spikeSwordEasterEggRightClickEnabled) {
        document.removeEventListener('contextmenu', handleSpikeSwordVanishRightClick, true);
        spikeSwordEasterEggRightClickEnabled = false;
        const swordEl = getSpikeSwordSpriteElement();
        if (swordEl) swordEl.style.pointerEvents = '';
        return;
      }
      const swordEl = getSpikeSwordSpriteElement();
      if (shouldBeEnabled && swordEl) {
        swordEl.style.pointerEvents = 'auto';
      } else if (shouldBeEnabled && !swordEl && retryCount < 5) {
        setTimeout(() => updateSpikeSwordEasterEggState(
          boardContext || globalThis.state?.board?.getSnapshot?.()?.context,
          retryCount + 1
        ), 300);
      }
    } catch (e) {
      console.error('[Quests Mod][Spike Sword] Error updating easter egg state:', e);
    }
  }

  function setupSpikeSwordEasterEggObserver() {
    if (spikeSwordEasterEggBoardSubscription) {
      updateSpikeSwordEasterEggState();
      return;
    }
    if (typeof globalThis === 'undefined' || !globalThis.state?.board?.subscribe) return;
    spikeSwordEasterEggBoardSubscription = globalThis.state.board.subscribe(({ context: boardContext }) => {
      updateSpikeSwordEasterEggState(boardContext);
    });
    updateSpikeSwordEasterEggState(globalThis.state?.board?.getSnapshot()?.context);
  }

  function cleanupSpikeSwordEasterEggSystem() {
    if (spikeSwordEasterEggRightClickEnabled) {
      document.removeEventListener('contextmenu', handleSpikeSwordVanishRightClick, true);
      spikeSwordEasterEggRightClickEnabled = false;
      const swordEl = getSpikeSwordSpriteElement();
      if (swordEl) swordEl.style.pointerEvents = '';
    }
    if (spikeSwordEasterEggBoardSubscription) {
      try {
        spikeSwordEasterEggBoardSubscription.unsubscribe();
      } catch (e) {
        console.warn('[Quests Mod][Spike Sword] Error unsubscribing from board:', e);
      }
      spikeSwordEasterEggBoardSubscription = null;
    }
  }

  // ============================================================
  // Reusable factory: right-click a tile's decorative sprite to show a floating,
  // classic-Tibia-style "You see a sign / You read: ..." text above it.
  // Call createSignReaderSystem() once per sign, wire the returned handle's
  // setupObserver/cleanupSystem into the usual observer lifecycle, resetRead()
  // whenever the surrounding encounter is re-entered, and shouldEnable/getTiles
  // into registerQuestTileHighlightSource for a "there's something to read here" glow.
  // ============================================================
  function createSignReaderSystem({ id, tileIndex, spriteSelector, lines, isRoomActive, durationMs = 4000 }) {
    const logPrefix = `[Quests Mod][${id}]`;
    // `lines` may be an array or a function returning one (so mission-dialogue-driven
    // sign text can be resolved at read time, after assets have loaded).
    const resolveLines = () => {
      const value = typeof lines === 'function' ? lines() : lines;
      return Array.isArray(value) ? value : [];
    };
    const slug = String(id).toLowerCase().replace(/[^a-z0-9]+/g, '-');
    const textClass = `quests-sign-reader-${slug}-text`;
    const styleId = `${textClass}-styles`;
    let rightClickEnabled = false;
    let boardSubscription = null;
    let read = false;

    function getSpriteElement() {
      const tileEl = getTileElement(tileIndex);
      if (!tileEl) return null;
      return tileEl.querySelector(spriteSelector);
    }

    function ensureStyles() {
      if (document.getElementById(styleId)) return;
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = `
        .${textClass} {
          position: fixed;
          transform: translate(-50%, -100%);
          width: max-content;
          max-width: 300px;
          pointer-events: none;
          z-index: 2147483647;
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 2px;
          user-select: none;
        }
        .${textClass} .quests-sign-reader-line {
          display: block;
          white-space: normal;
          overflow-wrap: break-word;
          text-align: center;
          font-size: 16px;
          line-height: 1.2;
          color: #66ff66;
          text-shadow: -1px 0 #000, 1px 0 #000, 0 -1px #000, 0 1px #000;
        }
      `;
      document.head.appendChild(style);
    }

    function showText(tileElement) {
      if (!tileElement) return;
      ensureStyles();
      if (document.querySelector(`.${textClass}`)) return;

      // Each tile div carries its own explicit z-index for the isometric layout, so a
      // child positioned outside the tile's box can get visually covered by a neighboring
      // tile with a higher z-index (its stacking context, not this element's own z-index,
      // decides that). Mounting to document.body — same as the context-menu system does —
      // escapes per-tile stacking entirely, positioned from the tile's actual screen rect.
      const rect = tileElement.getBoundingClientRect();

      const resolvedLines = resolveLines();
      if (!resolvedLines.length) return;

      const bubble = document.createElement('div');
      bubble.className = `${textClass} pixel-font-16 revert-pixel-font-spacing`;
      bubble.style.left = `${rect.left + rect.width / 2}px`;
      bubble.style.top = `${rect.top - 6}px`;
      bubble.innerHTML = resolvedLines.map((line) => `<span class="quests-sign-reader-line">${line}</span>`).join('');
      document.body.appendChild(bubble);
      setTimeout(() => {
        if (bubble.parentNode) bubble.remove();
      }, durationMs + 60);
    }

    function shouldEnable(boardContext = null) {
      if (!areQuestHelpersEnabled()) return false;
      if (typeof isRoomActive === 'function' && !isRoomActive(boardContext)) return false;
      return true;
    }

    function handleRightClick(event) {
      if (!shouldEnable()) return;
      const spriteEl = getSpriteElement();
      if (!spriteEl) return;
      // The tile-highlight hitbox/overlay sits above the sprite (z-index 10001+) whenever
      // the highlight glow is showing, so it — not the sprite — is the real event.target.
      // Accept either a direct hit on the sprite, or any click on this same tile's own
      // highlight overlay (never a neighboring tile's, hence the tileIndex match).
      const clickedSprite = spriteEl.contains(event.target);
      const clickedOwnHighlightOverlay = isQuestTileHighlightOverlay(event.target)
        && event.target.closest('[id^="tile-index-"]') === getTileElement(tileIndex);
      if (!clickedSprite && !clickedOwnHighlightOverlay) return;

      event.preventDefault();
      event.stopImmediatePropagation();
      event.stopPropagation();

      showText(getTileElement(tileIndex));
      console.log(`${logPrefix} ${resolveLines().join(' / ')}`);

      if (!read) {
        read = true;
        if (typeof refreshQuestTileHighlights === 'function') refreshQuestTileHighlights();
      }
    }

    function updateState(boardContext = null, retryCount = 0) {
      try {
        const enabled = shouldEnable(boardContext);
        if (enabled && !rightClickEnabled) {
          document.addEventListener('contextmenu', handleRightClick, true);
          rightClickEnabled = true;
        }
        if (!enabled && rightClickEnabled) {
          document.removeEventListener('contextmenu', handleRightClick, true);
          rightClickEnabled = false;
          const spriteEl = getSpriteElement();
          if (spriteEl) spriteEl.style.pointerEvents = '';
          return;
        }
        const spriteEl = getSpriteElement();
        if (enabled && spriteEl) {
          spriteEl.style.pointerEvents = 'auto';
        } else if (enabled && !spriteEl && retryCount < 5) {
          setTimeout(() => updateState(
            boardContext || globalThis.state?.board?.getSnapshot?.()?.context,
            retryCount + 1
          ), 300);
        }
      } catch (e) {
        console.error(`${logPrefix} Error updating state:`, e);
      }
    }

    function setupObserver() {
      if (boardSubscription) {
        updateState();
        return;
      }
      if (typeof globalThis === 'undefined' || !globalThis.state?.board?.subscribe) return;
      boardSubscription = globalThis.state.board.subscribe(({ context: boardContext }) => {
        updateState(boardContext);
      });
      updateState(globalThis.state?.board?.getSnapshot()?.context);
    }

    function cleanupSystem() {
      if (rightClickEnabled) {
        document.removeEventListener('contextmenu', handleRightClick, true);
        rightClickEnabled = false;
        const spriteEl = getSpriteElement();
        if (spriteEl) spriteEl.style.pointerEvents = '';
      }
      if (boardSubscription) {
        try {
          boardSubscription.unsubscribe();
        } catch (e) {
          console.warn(`${logPrefix} Error unsubscribing from board:`, e);
        }
        boardSubscription = null;
      }
    }

    return {
      tileIndex,
      setupObserver,
      cleanupSystem,
      resetRead: () => { read = false; },
      // Tile-highlight source active whenever the sign is right-clickable and unread.
      shouldEnable: (boardContext) => shouldEnable(boardContext) && !read
    };
  }

  const swordOfFurySignReader = createSignReaderSystem({
    id: 'Sign',
    tileIndex: 81,
    spriteSelector: '.sprite.item.relative.id-2012',
    lines: ['You see a sign.', 'You read: Only the humble may touch the Sword of Fury'],
    isRoomActive: () => playerEnteredSewersPortal && !!sewersBattle && isOnRoomByName(SEWERS_BATTLE_ROOM_NAME)
  });

  // Shared by copperKeySignReader's isRoomActive below AND the separate "Copper Key quest
  // tile" highlight source registered in initializeQuestTileHighlightSources() — both need
  // to stop the instant the key is actually in hand, since the remaining step (handing it
  // to the King) has nothing left on tile 69 to point the player at.
  function isCopperKeyRubbleTileActive() {
    const progress = getMissionProgress(KING_COPPER_KEY_MISSION);
    if (!progress.accepted || progress.completed) return false;
    if (getCachedQuestItemCount(COPPER_KEY_CONFIG.productName) > 0) return false;
    return isOnMineHub();
  }

  // Right-click the rubble on Mine Hub's tile 69 (COPPER_KEY_CONFIG.targetTileIndex — hardcoded
