  // =======================
  // Tesha arrow (tile 157, Darama Oasis)
  // =======================

  function isBoardBattleActive(boardContext) {
    try {
      const ctx = boardContext || globalThis.state?.board?.getSnapshot()?.context;
      const timerContext = globalThis.state?.gameTimer?.getSnapshot()?.context;
      return !!(ctx?.gameStarted && timerContext?.state === 'initial');
    } catch (error) {
      return false;
    }
  }

  function countAllyPiecesOnBoard(boardContext) {
    try {
      const boardConfig = boardContext?.boardConfig || [];
      return boardConfig.filter(piece =>
        piece?.type === 'player' || (piece?.type === 'custom' && piece?.villain === false)
      ).length;
    } catch (error) {
      return 0;
    }
  }

  const questTileHighlightSources = [];
  const questFightIconSources = [];
  let tileHighlightBoardSubscription = null;
  let tileHighlightGameTimerSubscription = null;

  function getQuestFightIconUrl() {
    return QUEST_FIGHT_ICON_URL
      || APPRENTICE_SHENG_FIGHT_ICON_URL
      || 'https://bestiaryarena.com/assets/icons/fight.png';
  }

  const NPC_MODAL_PENDING_BADGE_CLASS = 'quests-npc-modal-pending-badge';

  // Same fight.png badge shown on board NPCs with a pending quest action, but
  // overlaid on an NPC's portrait inside their own chat modal.
  function createNpcModalPendingBadge() {
    const icon = document.createElement('img');
    icon.className = `${NPC_MODAL_PENDING_BADGE_CLASS} pixelated`;
    icon.src = getQuestFightIconUrl();
    icon.alt = 'Quest pending';
    icon.title = 'A quest is pending';
    icon.draggable = false;
    icon.style.cssText = [
      'position:absolute',
      'right:16px',
      'top:10px',
      'width:16px',
      'height:16px',
      'pointer-events:none',
      'z-index:5',
      'image-rendering:pixelated'
    ].join(';');
    return icon;
  }

  function setNpcModalPendingBadge(portraitContainer, isPending) {
    if (!portraitContainer) return;
    const existing = portraitContainer.querySelector(`.${NPC_MODAL_PENDING_BADGE_CLASS}`);
    if (isPending) {
      if (!existing) {
        if (!portraitContainer.style.position) {
          portraitContainer.style.position = 'relative';
        }
        portraitContainer.appendChild(createNpcModalPendingBadge());
      }
    } else if (existing) {
      existing.remove();
    }
  }

  function removeQuestFightIcon(id) {
    document.querySelectorAll(`.${QUEST_FIGHT_ICON_CLASS}[${QUEST_FIGHT_ICON_ATTR}="${id}"]`).forEach((el) => el.remove());
  }

  function removeAllQuestFightIcons() {
    document.querySelectorAll(`.${QUEST_FIGHT_ICON_CLASS}`).forEach((el) => el.remove());
  }

  function placeQuestFightIconOnTile(tileElement, id, alt = 'Quest') {
    if (!tileElement || !id) return;
    removeQuestFightIcon(id);
    if (!areQuestHelpersEnabled()) return;

    const icon = document.createElement('img');
    icon.className = `${QUEST_FIGHT_ICON_CLASS} pixelated`;
    icon.setAttribute(QUEST_FIGHT_ICON_ATTR, id);
    icon.src = getQuestFightIconUrl();
    icon.alt = alt;
    icon.title = QUEST_ACCESS_TILE_TITLE;
    icon.draggable = false;
    icon.style.cssText = [
      'position:absolute',
      'right:2px',
      'top:2px',
      'width:16px',
      'height:16px',
      'pointer-events:none',
      `z-index:${QUEST_FIGHT_ICON_Z_INDEX}`,
      'image-rendering:pixelated'
    ].join(';');
    ensureBoardNpcTileOverflowVisible(tileElement);
    tileElement.appendChild(icon);
    bringQuestTileOverlaysToFront(tileElement);
  }

  function registerQuestFightIconSource(source) {
    questFightIconSources.push(source);
  }

  /** New quest available or a hand-in / talk step is ready at Wyda. */
  function hasWydaQuestAction() {
    const follower = getMissionProgress(FOLLOWER_OF_ZATHROTH_MISSION) || {};
    const mother = getMissionProgress(MOTHER_OF_ALL_SPIDERS_MISSION) || {};
    const jakundaf = getMissionProgress(JAKUNDAF_DESERT_MISSION) || {};
    const taintedSouls = getMissionProgress(TAINTED_SOULS_MISSION) || {};
    const ankhName = COSTELLO_QUEEN_BANSHEES_MISSION.rewardItemName || 'Blessed Ankh';
    if (follower.accepted && !follower.completed && getCachedQuestItemCount(ankhName) > 0) return true;
    if (follower.completed && !mother.accepted) return true;
    if (mother.accepted && !mother.completed && getCachedQuestItemCount('Spider Silk') > 0) return true;
    if (mother.completed && !jakundaf.accepted) return true;
    if (jakundaf.accepted && !jakundaf.completed && jakundaf.pathCleared) return true;
    if (jakundaf.completed && !taintedSouls.accepted) return true;
    if (taintedSouls.accepted && !taintedSouls.completed && taintedSouls.battleCompleted) return true;
    return false;
  }

  /** New quest available or Costello talk / hand-in is needed. */
  function hasCostelloQuestAction() {
    const monks = getMissionProgress(KING_MONKS_STUDY_MISSION) || {};
    if (monks.accepted && !monks.completed) return true;
    const queen = getMissionProgress(COSTELLO_QUEEN_BANSHEES_MISSION) || {};
    if (queen.accepted && !queen.completed) return true;
    if (queen.completed) {
      const follower = getMissionProgress(FOLLOWER_OF_ZATHROTH_MISSION) || {};
      if (!follower.accepted) return true;
    }
    return false;
  }

  /** Stamped letter / axe / rope hand-in, or a new Al Dee quest to accept. */
  function hasAlDeeQuestAction() {
    const items = cachedQuestItems || {};
    if ((items['Stamped Letter'] || 0) > 0) return true;
    if ((items['Small Axe'] || 0) > 0) return true;
    if ((items['Elvenhair Rope'] || 0) > 0) return true;
    const letter = getMissionProgress(KING_LETTER_MISSION) || {};
    const fishing = getMissionProgress(AL_DEE_FISHING_MISSION) || {};
    const rope = getMissionProgress(AL_DEE_GOLDEN_ROPE_MISSION) || {};
    const rookieGuard = getMissionProgress(AL_DEE_ROOKIE_GUARD_MISSION) || {};
    if (letter.completed && !fishing.accepted) return true;
    if (fishing.completed && !rope.accepted) return true;
    if (rope.completed && !rookieGuard.accepted) return true;
    if (rookieGuard.accepted && !rookieGuard.completed && rookieGuard.battleCompleted) return true;
    return false;
  }

  function hasTeshaQuestAction() {
    // Realm of Dreams: startable once the Key to Magic (Book) is in hand, or waiting
    // for the reward hand-back once the fire-path battle is cleared.
    const realm = getMissionProgress(REALM_OF_DREAMS_MISSION) || {};
    if (!realm.completed) {
      if (realm.battleCompleted) return true;
      if (!realm.accepted && getCachedQuestItemCount('Key to Magic (Book)') > 0) return true;
    }
    const scarab = getMissionProgress(KING_SCARAB_COIN_MISSION) || {};
    if (scarab.accepted && !scarab.completed && getCachedQuestItemCount(SCARAB_COIN_CONFIG.productName) > 0) return true;
    if (!scarab.completed) return false;
    const serpentine = getMissionProgress(SERPENTINE_TOWER_MISSION) || {};
    if (serpentine.completed) return false;
    if (!serpentine.accepted) return true;
    return !!serpentine.putridChamberComplete;
  }

  // King Tibianus isn't a board NPC, so unlike hasWydaQuestAction/hasAlDeeQuestAction/hasTeshaQuestAction
  // above, this has to be reachable both from his Quest Log tab (no modal open yet) and from inside his
  // chat modal, so it only relies on top-level helpers/constants rather than the modal's local closures.
  async function hasKingTibianusQuestAction() {
    const DEBUG_TAG = '[Quests Mod][King Tibianus][Pending Badge]';
    try {
      const honeyflowerProgress = getMissionProgress(KING_HONEYFLOWER_MISSION);
      const crossingProgress = getMissionProgress(KING_CROSSING_THE_LINE_MISSION);
      const copperKeyProgress = getMissionProgress(KING_COPPER_KEY_MISSION);
      const scarabProgress = getMissionProgress(KING_SCARAB_COIN_MISSION);
      const monksProgress = getMissionProgress(KING_MONKS_STUDY_MISSION);
      const redDragonProgress = getMissionProgress(KING_RED_DRAGON_MISSION);
      const letterProgress = getMissionProgress(KING_LETTER_MISSION);
      const oracleProgress = getMissionProgress(LOST_ORACLE_MISSION);

      const reasons = [];

      // Any already-accepted King mission ready to hand in / progress — mirrors
      // tryProgressAnyActiveKingMission(), which the King checks first regardless
      // of which mission is currently "focal" in his story sequence.
      if (copperKeyProgress.accepted && !copperKeyProgress.completed && getCachedQuestItemCount(COPPER_KEY_CONFIG.productName) > 0) reasons.push('hand-in:copper-key');
      if (honeyflowerProgress.accepted && !honeyflowerProgress.completed && getCachedQuestItemCount(HONEYFLOWER_CONFIG.productName) > 0) reasons.push('hand-in:honeyflower');
      if (crossingProgress.accepted && !crossingProgress.completed && hasCrossingTheLineObjectiveComplete()) reasons.push('hand-in:crossing-the-line');
      if (redDragonProgress.accepted && !redDragonProgress.completed
        && getCachedQuestItemCount('Red Dragon Scale') >= 30 && getCachedQuestItemCount('Red Dragon Leather') >= 30) reasons.push('hand-in:red-dragon');
      const scarabReady = (scarabProgress.accepted && !scarabProgress.completed) ? await hasScarabCoinInInventory() : false;
      if (scarabReady) reasons.push('hand-in:scarab-coin');
      if (monksProgress.accepted && !monksProgress.completed && kingChatState.costelloVisited) reasons.push('hand-in:monks-study');
      if (letterProgress.accepted && !letterProgress.completed
        && getCachedQuestItemCount('Letter from Al Dee') > 0 && getCachedQuestItemCount('Stamped Letter') === 0) reasons.push('stamp-letter');

      // Lost Oracle: ready to exchange Orb for Luminous Orb
      if (oracleProgress.accepted && !oracleProgress.completed && !oracleProgress.orbExchanged) {
        const hasOrb = getCachedQuestItemCount(ORB_CONFIG.productName) > 0
          || ((await getQuestItems(false))?.[ORB_CONFIG.productName] || 0) > 0;
        if (hasOrb && getCachedQuestItemCount(LUMINOUS_ORB_CONFIG.productName) === 0) reasons.push('hand-in:lost-oracle-orb');
      }

      // New mission offer — the King only ever discusses ONE "focal" mission at a
      // time via generic conversation ("mission"/greeting), following the same
      // honeyflower -> crossing-the-line -> chain sequence as currentMission() /
      // canOfferHoneyflowerMission() inside showKingTibianusModal. A mission further
      // down the chain (e.g. Copper Key) is NOT naturally offerable while an earlier
      // one is still incomplete, even if its own prerequisite (Mine Hub unlocked,
      // Light Shovel held, etc.) is already met.
      let mineHubUnlocked = false;
      let hasLightShovel = false;
      let hasHolyTibleForMonks = false;
      let focalChainMissionId = null;
      if (reasons.length === 0) {
        if (!honeyflowerProgress.completed) {
          if (!honeyflowerProgress.accepted) reasons.push('offer:honeyflower');
        } else if (!crossingProgress.completed) {
          if (!crossingProgress.accepted) reasons.push('offer:crossing-the-line');
        } else {
          hasHolyTibleForMonks = (cachedQuestItems && (cachedQuestItems['The Holy Tible'] || 0) > 0);
          const chain = [
            KING_COPPER_KEY_MISSION,
            KING_RED_DRAGON_MISSION,
            KING_LETTER_MISSION,
            ...(hasHolyTibleForMonks ? [KING_MONKS_STUDY_MISSION] : []),
            KING_SCARAB_COIN_MISSION
          ];
          const focal = chain.find((mission) => !getMissionProgress(mission).completed) || null;
          focalChainMissionId = focal?.id || null;
          if (focal && !getMissionProgress(focal).accepted) {
            if (focal.id === KING_COPPER_KEY_MISSION.id) {
              mineHubUnlocked = isMineHubUnlocked();
              if (mineHubUnlocked) reasons.push('offer:copper-key');
            } else if (focal.id === KING_SCARAB_COIN_MISSION.id) {
              hasLightShovel = await hasLightShovelInInventory();
              if (hasLightShovel) reasons.push('offer:scarab-coin');
            } else {
              reasons.push(`offer:${focal.id}`);
            }
          }
        }
      }

      const isPending = reasons.length > 0;
      console.log(`${DEBUG_TAG} isPending=${isPending}`, {
        reasons,
        honeyflowerProgress, crossingProgress, copperKeyProgress, scarabProgress,
        monksProgress, redDragonProgress, letterProgress, oracleProgress,
        focalChainMissionId, mineHubUnlocked, hasLightShovel, hasHolyTibleForMonks
      });
      return isPending;
    } catch (error) {
      console.error(`${DEBUG_TAG} Error checking pending quest action:`, error);
      return false;
    }
  }

  function shouldShowWydaFightIcon(boardContext = null) {
    return shouldEnableTile83WydaRightClick(boardContext) && hasWydaQuestAction();
  }

  function shouldShowCostelloFightIcon(boardContext = null) {
    return shouldEnableTile53CostelloRightClick(boardContext) && hasCostelloQuestAction();
  }

  function shouldShowAlDeeFightIcon(boardContext = null) {
    return shouldEnableTile79RightClick(boardContext) && hasAlDeeQuestAction();
  }

  function shouldShowTeshaFightIcon(boardContext = null) {
    try {
      if (!isOnRoomByName(DESERT_DIGGING_CONFIG.TARGET_MAP)) return false;
      if (isBoardBattleActive(boardContext) || countAllyPiecesOnBoard(boardContext) > 0) return false;
      return hasTeshaQuestAction();
    } catch (_) {
      return false;
    }
  }

  function updateAllQuestFightIcons(boardContext = null) {
    if (isMapEditorOpen() || !areQuestHelpersEnabled()) {
      removeAllQuestFightIcons();
      return;
    }
    const ctx = boardContext || globalThis.state?.board?.getSnapshot()?.context;
    for (const source of questFightIconSources) {
      try {
        const id = source.id;
        if (!source.isActive(ctx)) {
          removeQuestFightIcon(id);
          continue;
        }
        const tile = typeof source.getTile === 'function' ? source.getTile(ctx) : null;
        if (!tile?.isConnected) {
          removeQuestFightIcon(id);
          continue;
        }
        // Board NPCs already render fight.png on their name tag — skip duplicate tile icons.
        if (tile.querySelector('img[alt="Dialogue"]')) {
          removeQuestFightIcon(id);
          continue;
        }
        if (!tile.querySelector(`.${QUEST_FIGHT_ICON_CLASS}[${QUEST_FIGHT_ICON_ATTR}="${id}"]`)) {
          placeQuestFightIconOnTile(tile, id, source.alt || 'Quest');
        }
      } catch (error) {
        console.error('[Quests Mod][Fight Icon] Error updating source:', error);
      }
    }
  }

  function isMapEditorOpen() {
    try {
      if (typeof window !== 'undefined' && typeof window.MapEditor?.isOpen === 'function') {
        return window.MapEditor.isOpen() === true;
      }
    } catch (_) {
      // ignore
    }
    const panel = document.getElementById('map-editor-panel');
    if (!panel) return false;
    const display = panel.style?.display;
    if (display === 'none') return false;
    if (display === 'flex') return true;
    return panel.offsetParent != null;
  }

  function areQuestHelpersEnabled() {
    if (isMapEditorOpen()) return false;
    return !window.betterUIConfig?.disableQuestHelpers;
  }

  function removeQuestHelperVisuals() {
    if (typeof removeAllTileHighlightEffects === 'function') {
      removeAllTileHighlightEffects();
    } else {
      document.querySelectorAll(`.${TILE_HIGHLIGHT_CLASS}`).forEach((highlight) => highlight.remove());
    }
    document.querySelectorAll(`[${TILE_HIGHLIGHT_TILE_ATTR}="1"]`).forEach((tile) => {
      unmarkQuestAccessTile(tile);
    });
    removeTeshaArrow();
    removeAllQuestFightIcons();
  }

  function refreshQuestHelpersForExternalToggle() {
    removeQuestHelperVisuals();
    const boardContext = globalThis.state?.board?.getSnapshot()?.context;
    refreshQuestTileHighlights(boardContext);
    updateTeshaArrowState(boardContext);
    if (typeof updateAllBoardNpcStates === 'function') {
      updateAllBoardNpcStates(boardContext);
    }
  }

  function canShowQuestTileHighlights(boardContext) {
    return !isBoardBattleActive(boardContext) && countAllyPiecesOnBoard(boardContext) === 0;
  }

  function markQuestAccessTile(tileElement) {
    if (!tileElement) return;
    tileElement.setAttribute(TILE_HIGHLIGHT_TILE_ATTR, '1');
  }

  function unmarkQuestAccessTile(tileElement) {
    if (!tileElement) return;
    tileElement.removeAttribute(TILE_HIGHLIGHT_TILE_ATTR);
  }

  function ensureQuestTileHighlightStyles() {
    if (document.getElementById('quests-tile-highlight-styles')) return;

    const style = document.createElement('style');
    style.id = 'quests-tile-highlight-styles';
    style.textContent = `
      @keyframes quests-tile-highlight-pulse {
        0%, 100% {
          opacity: 0;
          transform: scale(0.96);
        }
        50% {
          opacity: 0.5;
          transform: scale(1);
        }
      }
      .${TILE_HIGHLIGHT_CLASS} {
        opacity: 0;
        animation: quests-tile-highlight-pulse 1.6s ease-in-out infinite;
        cursor: ${QUEST_ACCESS_CURSOR} !important;
      }
      [${TILE_HIGHLIGHT_TILE_ATTR}="1"] {
        cursor: ${QUEST_ACCESS_CURSOR} !important;
      }
      [${TILE_HIGHLIGHT_TILE_ATTR}="1"] *,
      .quests-tile-highlight-hitbox {
        cursor: ${QUEST_ACCESS_CURSOR} !important;
      }
      .${TESHA_ARROW_CLASS} {
        cursor: ${QUEST_ACCESS_CURSOR} !important;
      }
      .${JAKUNDAF_ARROW_CLASS} {
        pointer-events: none;
      }
    `;
    document.head.appendChild(style);
  }

  function getQuestTileOverlayBoxStyle(extraProperties = []) {
    return [
      'position:absolute',
      'right:0',
      'bottom:0',
      'width:calc(32px * var(--zoomFactor))',
      'height:calc(32px * var(--zoomFactor))',
      ...extraProperties
    ].join(';');
  }

  function placeTileHighlightEffect(tileElement, alt = 'Quest access') {
    if (!tileElement) return;

    ensureQuestTileHighlightStyles();

    markQuestAccessTile(tileElement);

    if (!tileElement.querySelector('.quests-tile-highlight-hitbox')) {
      const hitbox = document.createElement('div');
      hitbox.className = 'quests-tile-highlight-hitbox';
      hitbox.style.cssText = getQuestTileOverlayBoxStyle([
        'pointer-events:auto',
        'cursor:' + QUEST_ACCESS_CURSOR,
        'z-index:10001',
        'background:transparent'
      ]);
      tileElement.appendChild(hitbox);
    }

    if (!areQuestHelpersEnabled() || tileElement.querySelector(`.${TILE_HIGHLIGHT_CLASS}`)) {
      bringQuestTileOverlaysToFront(tileElement);
      return;
    }

    const highlight = document.createElement('img');
    highlight.className = `${TILE_HIGHLIGHT_CLASS} pixelated`;
    highlight.src = getQuestItemsAssetUrl('Tile_Highlight_Effect.gif');
    highlight.alt = alt;
    highlight.draggable = false;
    highlight.style.cssText = getQuestTileOverlayBoxStyle([
      'pointer-events:none',
      'z-index:10002',
      'image-rendering:pixelated',
      'object-fit:fill',
      'transform-origin:center center'
    ]);
    tileElement.appendChild(highlight);
    bringQuestTileOverlaysToFront(tileElement);
  }

  function removeAllTileHighlightEffects() {
    document.querySelectorAll(`.${TILE_HIGHLIGHT_CLASS}`).forEach((highlight) => {
      const tile = highlight.parentElement;
      if (tile?.getAttribute(TILE_HIGHLIGHT_TILE_ATTR) === '1') {
        unmarkQuestAccessTile(tile);
      }
      highlight.remove();
    });
    document.querySelectorAll('.quests-tile-highlight-hitbox').forEach((hitbox) => hitbox.remove());
  }

  function registerQuestTileHighlightSource({ getTiles, isAccessActive, alt = 'Quest access', showDuringPlacement = false }) {
    questTileHighlightSources.push({ getTiles, isAccessActive, alt, showDuringPlacement });
  }

  function updateAllQuestTileHighlights(boardContext) {
    removeAllTileHighlightEffects();
    // Map Editor needs a clean board — suppress helper hitboxes and marks too.
    if (isMapEditorOpen()) {
      document.querySelectorAll(`[${TILE_HIGHLIGHT_TILE_ATTR}="1"]`).forEach((tile) => {
        unmarkQuestAccessTile(tile);
      });
      return;
    }
    const emptyBoardOk = canShowQuestTileHighlights(boardContext);
    const battleActive = isBoardBattleActive(boardContext);
    // A custom battle owns this room (any of the quest battles that reskin the Sewers,
    // including the Hellgate Library scene): its board layout is not the overworld, so
    // overworld quest-access helpers like "Visit Al Dee" on tile 79 have no business
    // showing. Sign-reader glows opt back in via showDuringPlacement.
    const currentRoomId = boardContext?.selectedMap?.selectedRoom?.id
      || globalThis.state?.board?.getSnapshot?.()?.context?.selectedMap?.selectedRoom?.id;
    // Also treat the Draconia Tower post-battle talk as "owned" — there's no live battle
    // instance then, but the room is still the dragon-cemetery reskin, not the overworld.
    const customBattleOwnsRoom = (!!currentRoomId && isAnyCustomBattleActiveForRoom(currentRoomId))
      || (playerEnteredDraconiaTower && draconiaTowerPostBattle && isOnRoomByName(DRACONIA_BATTLE_ROOM_NAME));

    for (const source of questTileHighlightSources) {
      try {
        const allowWithCreatures = !!source.showDuringPlacement;
        if (customBattleOwnsRoom && !allowWithCreatures) continue;
        if (!allowWithCreatures && !emptyBoardOk) continue;
        if (allowWithCreatures && battleActive) continue;
        if (!source.isAccessActive(boardContext)) continue;
        const tiles = source.getTiles(boardContext);
        const tileList = Array.isArray(tiles) ? tiles : (tiles ? [...tiles] : []);
        for (const tile of tileList) {
          if (tile?.isConnected) {
            placeTileHighlightEffect(tile, source.alt);
          }
        }
      } catch (error) {
        console.error('[Quests Mod][Tile Highlight] Error updating highlight source:', error);
      }
    }

    updateHoneyflowerTileRightClickHint(boardContext);
    updateCrossingTheLineTileHint(boardContext);
    updateCrossingTheLineOrcSuccessEffects(boardContext);
  }

  function refreshQuestTileHighlights(boardContext = null) {
    if (typeof updateAllQuestTileHighlights !== 'function') return;
    const ctx = boardContext || globalThis.state?.board?.getSnapshot()?.context;
    updateAllQuestTileHighlights(ctx);
    if (typeof updateJakundafDesertArrow === 'function') {
      updateJakundafDesertArrow(ctx);
    }
    if (typeof updateAllQuestFightIcons === 'function') {
      updateAllQuestFightIcons(ctx);
    }
  }

